function asString(v) {
  return typeof v === 'string' ? v.trim() : '';
}

function pickFirst(...vals) {
  for (const v of vals) {
    const s = asString(v);
    if (s) return s;
  }
  return '';
}

function unique(arr) {
  const out = [];
  const seen = new Set();
  for (const v of arr || []) {
    const s = asString(v);
    if (!s) continue;
    const key = s.toUpperCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(s);
  }
  return out;
}

function explicitEntitySnapshot(text) {
  const raw = String(text || '');

  const tags = [];
  const tagPatterns = [
    /\b[A-Z]{1,6}[A-Z0-9_]*\d{2,6}[A-Z0-9_]*(?:\.[A-Z0-9_]+)?\b/g,
    /\b(?:Ecat|Scat|SRcat)[A-Za-z0-9_]*\b/g,
    /\b(?:StackFG|Sample)_[A-Za-z0-9_]+\b/g
  ];
  for (const pattern of tagPatterns) {
    let m;
    while ((m = pattern.exec(raw)) !== null) tags.push(m[0]);
  }

  const numbers = [];
  const numberPattern = /[-+]?\d+(?:\.\d+)?\s*(?:kPa|MPa|bar|psi|℃|°C|t\/h|Nm³\/h|Nm3\/h|%|h|min|s|秒|分钟|小时)?/gi;
  let n;
  while ((n = numberPattern.exec(raw)) !== null) {
    const value = n[0].trim();
    if (value) numbers.push(value);
  }

  const timeWindows = [];
  const timePatterns = [
    /\b20\d{2}[-/年]\d{1,2}[-/月]\d{1,2}(?:日)?(?:\s+\d{1,2}:\d{2}(?::\d{2})?)?\b/g,
    /\b\d{1,2}:\d{2}(?::\d{2})?\b/g,
    /前后\s*\d+\s*(?:个)?小时/g,
    /T\d+\s*(?:那次|时刻|事件)?/gi
  ];
  for (const pattern of timePatterns) {
    let m;
    while ((m = pattern.exec(raw)) !== null) timeWindows.push(m[0]);
  }

  const equipmentMentions = unique([
    ...Array.from(raw.matchAll(/(?:反飞动阀门|防喘振阀|双动滑阀|气压机|主风量|再生器|沉降器|两器压差|SIS|DCS|联锁)/g)).map(m => m[0])
  ]);

  return {
    glossary_version: 'explicit-entity-snapshot-v1',
    entities: [],
    explicit_entities: {
      tags: unique(tags),
      numbers: unique(numbers),
      time_windows: unique(timeWindows),
      equipment_mentions: equipmentMentions
    },
    unresolved: []
  };
}

return $input.all().map((item) => {
  const j = item.json || {};
  const question = pickFirst(
    j.chatInput,
    j.question,
    j['What is your question'],
    j.form?.question,
    j.raw?.chatInput,
    j.user_input?.q
  );

  return {
    json: {
      ...j,
      canonical: explicitEntitySnapshot(question)
    }
  };
});

