const items = $input.all();

function stripCodeFences(s) {
  return s.trim().replace(/```json\s*/gi, "").replace(/```/g, "").trim();
}

function buildFailurePlan(reason, detail) {
  const errors = [reason];
  if (detail) errors.push(detail);
  return {
    intent: "qa",
    valid: false,
    errors,
    steps: [],
    needs_clarification: false,
    clarifying_questions: []
  };
}

function detectSmallTalk(question) {
  const q = String(question || "").trim().toLowerCase();
  if (!q) return null;

  if (/^(hi|hello|hey|hiya|yo|good morning|good afternoon|good evening)[!. ]*$/.test(q)) {
    return "Hi! Ask me a knowledge-base question when you're ready.";
  }

  if (/^(how are you|how are you doing|how's it going|how is it going)[?.! ]*$/.test(q)) {
    return "I'm here and ready to help with knowledge-base questions.";
  }

  if (/^(who are you|what are you|what can you do|what do you do)[?.! ]*$/.test(q)) {
    return "I'm a knowledge-base assistant. Ask me about the documents and data available in this system.";
  }

  if (/^(help|help me|what should i ask|what can i ask|how do i use this)[?.! ]*$/.test(q)) {
    return "Ask a specific question about the knowledge base, documents, process information, or available data sources.";
  }

  if (/^(thanks|thank you|thx|thank u)[!. ]*$/.test(q)) {
    return "You're welcome.";
  }

  if (/^(bye|goodbye|see you|see ya|cya)[!. ]*$/.test(q)) {
    return "Goodbye.";
  }

  return null;
}

function buildDirectResponsePlan(text) {
  return {
    intent: "small_talk",
    valid: true,
    errors: [],
    steps: [
      {
        step: 1,
        tool: "direct_response",
        params: { text },
        depends_on: []
      }
    ],
    needs_clarification: false,
    clarifying_questions: []
  };
}


function nodeJson(name) {
  try {
    return $(name).first().json || {};
  } catch {
    return {};
  }
}

function uniqueStrings(arr) {
  const out = [];
  const seen = new Set();
  for (const v of arr || []) {
    const s = String(v || "").trim();
    if (!s) continue;
    const k = s.toLowerCase();
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(s);
  }
  return out;
}

function normalizeDatasetIds(ids) {
  if (!Array.isArray(ids)) return undefined;
  const cleaned = uniqueStrings(ids).filter(id => id.toLowerCase() !== "test");
  return cleaned.length ? cleaned : undefined;
}

function normalizePlan(plan) {
  const steps = Array.isArray(plan?.steps) ? plan.steps : [];

  for (const step of steps) {
    if (!step || typeof step !== "object") continue;

    if (!step.params || typeof step.params !== "object") {
      step.params = {};
    }

    if (step.tool === "ragflow_retrieval") {
      // RAGFLOW_QUERY_ALIAS_QUESTION_V5
      // Planner outputs may use `query` as the natural retrieval text. The
      // downstream schema expects `question`; normalize the alias structurally.
      if (step.params.question == null && typeof step.params.query === "string" && step.params.query.trim()) {
        step.params.question = step.params.query.trim();
      }
      // IMPORTANT:
      // Do NOT delete dataset_ids chosen upstream.
      // Preserve narrowed retrieval scope to keep references stable.
      const normalizedIds = normalizeDatasetIds(step.params.dataset_ids);
      if (normalizedIds) {
        step.params.dataset_ids = normalizedIds;
      } else {
        delete step.params.dataset_ids;
      }
    }

    if (step.tool === "mongo_find_tags") {
      // keep tag discovery lighter unless explicitly overridden upstream
      if (step.params.top_k == null) step.params.top_k = 8;
    }
  }

  return plan;
}

function planFromMatchedCalls(reason, detail) {
  const matched = nodeJson('Match Tools');
  const raw = typeof matched.output === 'string' ? matched.output : '';
  let parsed = {};
  try {
    parsed = raw.trim() ? JSON.parse(stripCodeFences(raw)) : {};
  } catch {
    parsed = {};
  }
  const calls = Array.isArray(parsed.calls) ? parsed.calls : [];
  if (!calls.length) return buildFailurePlan(reason, detail);
  const intentNode = nodeJson('Parse Intent');
  return {
    intent: String(intentNode.intent || intentNode.output?.intent || 'qa'),
    valid: true,
    errors: [reason].concat(detail ? [detail] : []),
    steps: calls.map((call, index) => ({
      step: Number(call.step_id || call.step || index + 1),
      tool: String(call.tool || '').trim(),
      params: call.params && typeof call.params === 'object' ? call.params : {},
      depends_on: Array.isArray(call.depends_on) ? call.depends_on : [],
      question_part: ALLOWED_QP_FALLBACK.has(call.question_part) ? call.question_part : 'other',
      required_evidence_types: Array.isArray(call.required_evidence_types) ? call.required_evidence_types : [],
      optional_evidence_types: Array.isArray(call.optional_evidence_types) ? call.optional_evidence_types : [],
      purpose: String(call.purpose || '')
    })).filter(step => step.tool),
    needs_clarification: false,
    clarifying_questions: [],
    planner_fallback_source: 'match_tools_calls'
  };
}

const ALLOWED_QP_FALLBACK = new Set([
  'factor_identification', 'target_or_ideal_range', 'period_verification',
  'relationship_lookup', 'structured_lookup', 'other'
]);

return items.map((item) => {
  const j = item.json ?? {};
  const raw = j.output;
  const originalUserMessage = j.originalUserMessage || j.form?.question || "";
  const chatSessionId = j.chatSessionId || j.form?.request_id || "MISSING";
  const redisSessionKey = `chat:anon:${chatSessionId}`;
  const smallTalkResponse = detectSmallTalk(originalUserMessage);
  const capture = nodeJson('Relevant Memory Retriever');
  const conversationState = capture.retrieval_state || j.retrieval_state || {};
  const validationCatalog = nodeJson('Capture context').catalog || j.catalog || {};

  if (smallTalkResponse) {
    return {
      json: {
        redisSessionKey,
        originalUserMessage,
        chatSessionId,
        plan: buildDirectResponsePlan(smallTalkResponse)
      }
    };
  }

  if (typeof raw !== "string" || raw.trim().length === 0) {
    return {
      json: {
        redisSessionKey,
        originalUserMessage,
        chatSessionId,
        plan: planFromMatchedCalls("Planner returned empty output")
      }
    };
  }

  const cleaned = stripCodeFences(raw);
  let plan;
  try {
    plan = JSON.parse(cleaned);
  } catch (e) {
    return {
      json: {
        redisSessionKey,
        originalUserMessage,
        chatSessionId,
        plan: planFromMatchedCalls("Planner returned invalid JSON", e.message)
      }
    };
  }

  const ALLOWED_QP = new Set([
  'factor_identification',
  'target_or_ideal_range',
  'period_verification',
  'relationship_lookup',
  'structured_lookup',
  'other'
]);

for (const step of plan.steps || []) {
  if (!ALLOWED_QP.has(step.question_part)) {
    plan.valid = false;
    plan.errors = Array.isArray(plan.errors) ? plan.errors : [];
    plan.errors.push(`Invalid question_part: ${step.question_part}`);
  }
}

  if (plan?.plan) plan = plan.plan;
  plan = normalizePlan(plan);

  if (!plan || !plan.intent || !Array.isArray(plan.steps)) {
    return {
      json: {
        redisSessionKey,
        originalUserMessage,
        chatSessionId,
        plan: planFromMatchedCalls("Planner output was missing intent or steps")
      }
    };
  }

  return {
    json: {
      redisSessionKey,
      originalUserMessage,
      chatSessionId,
      catalog: validationCatalog,
      plan: {
        intent: plan.intent,
        valid: plan.valid !== false,
        errors: Array.isArray(plan.errors) ? plan.errors : [],
        steps: plan.steps,
        needs_clarification: plan.needs_clarification || false,
        clarifying_questions: Array.isArray(plan.clarifying_questions) ? plan.clarifying_questions : []
      }
    }
  };
});

function safeParseOutput(s) {
  if (s && typeof s === 'object' && !Array.isArray(s)) return s;
  if (typeof s !== 'string') return {};

  const cleaned = s
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  try {
    return JSON.parse(cleaned);
  } catch {}

  const first = cleaned.indexOf('{');
  const last = cleaned.lastIndexOf('}');
  if (first >= 0 && last > first) {
    try {
      return JSON.parse(cleaned.slice(first, last + 1));
    } catch {}
  }

  return {};
}

// MONGODB_FINAL_RENDER_BOUNDARY_V1
// Accept current MongoDB contracts and legacy cached state while keeping the
// renderer's established analysis logic stable. Only MongoDB terminology is
// allowed to leave this node.
const MONGO_TO_INTERNAL_TOOL = Object.freeze({
  mongo_find_tags: 'arctic_find_tags',
  mongo_resolve_factors: 'arctic_resolve_factors',
  mongo_read: 'arctic_read',
  mongo_stats: 'arctic_stats',
  mongo_analyze: 'arctic_analyze',
  mongo_describe: 'arctic_describe'
});
const INTERNAL_TO_MONGO_TOOL = Object.freeze(
  Object.fromEntries(Object.entries(MONGO_TO_INTERNAL_TOOL).map(([mongo, internal]) => [internal, mongo]))
);

function replaceRenderVocabulary(value, direction) {
  let out = String(value == null ? '' : value);
  const replacements = direction === 'internal'
    ? { ...MONGO_TO_INTERNAL_TOOL, MongoDB: 'ArcticDB', mongodb_: 'arctic_', mongodb: 'arcticdb' }
    : { ...INTERNAL_TO_MONGO_TOOL, ArcticDB: 'MongoDB', arctic_: 'mongodb_', arcticdb: 'mongodb' };
  for (const [from, to] of Object.entries(replacements)) {
    out = out.replace(new RegExp(`\\b${from}`, 'g'), to);
  }
  if (direction === 'public') {
    out = out
      .replace(/\blibrary\b/gi, match => match[0] === 'L' ? 'Database' : 'database')
      .replace(/\bsymbol\b/gi, match => match[0] === 'S' ? 'Collection' : 'collection');
  }
  return out;
}

function renderContractKey(key, direction) {
  if (direction === 'internal') {
    if (MONGO_TO_INTERNAL_TOOL[key]) return MONGO_TO_INTERNAL_TOOL[key];
    if (key.startsWith('mongo_analyze_')) return key.replace(/^mongo_analyze_/, 'arctic_analyze_');
    if (key === 'mongodb_target_registry') return 'arctic_target_registry';
    if (key === 'mongodb') return 'arctic';
    return key;
  }
  if (INTERNAL_TO_MONGO_TOOL[key]) return INTERNAL_TO_MONGO_TOOL[key];
  if (key.startsWith('arctic_analyze_')) return key.replace(/^arctic_analyze_/, 'mongo_analyze_');
  if (key === 'arctic_target_registry') return 'mongodb_target_registry';
  if (key === 'arctic') return 'mongodb';
  return key;
}

function translateRenderContract(value, direction) {
  if (Array.isArray(value)) return value.map(v => translateRenderContract(v, direction));
  if (typeof value === 'string') return replaceRenderVocabulary(value, direction);
  if (!value || typeof value !== 'object') return value;

  const out = {};
  for (const [key, child] of Object.entries(value)) {
    out[renderContractKey(key, direction)] = translateRenderContract(child, direction);
  }
  const toInternal = direction === 'internal';
  const historianObject = toInternal
    ? (String(out.tool || '').startsWith('arctic_') ||
      (Object.prototype.hasOwnProperty.call(out, 'database') && Object.prototype.hasOwnProperty.call(out, 'collection')))
    : (String(out.tool || '').startsWith('mongo_') ||
      (Object.prototype.hasOwnProperty.call(out, 'library') && Object.prototype.hasOwnProperty.call(out, 'symbol')));
  if (historianObject && toInternal) {
    if (out.library == null && out.database != null) out.library = out.database;
    if (out.symbol == null && out.collection != null) out.symbol = out.collection;
    delete out.database;
    delete out.collection;
  } else if (historianObject) {
    if (out.database == null && out.library != null) out.database = out.library;
    if (out.collection == null && out.symbol != null) out.collection = out.symbol;
    delete out.library;
    delete out.symbol;
  }
  return out;
}

function toInternalRenderContract(value) {
  return translateRenderContract(value, 'internal');
}

function toPublicMongoRenderContract(value) {
  return translateRenderContract(value, 'public');
}

function detectQuestionLang(q) {
  return /[\u4e00-\u9fff]/.test(String(q || '')) ? 'zh' : 'en';
}

function pickArray() {
  for (const v of arguments) {
    if (Array.isArray(v)) return v;
  }
  return [];
}

function pickObject() {
  for (const v of arguments) {
    if (v && typeof v === 'object' && !Array.isArray(v)) return v;
  }
  return {};
}

function oneLine(s) {
  return String(s || '')
    .replace(/\r/g, ' ')
    .replace(/\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}


// FINAL_DISPLAY_POLICY_V5
// Only an explicitly literal direct response may bypass the Finalizer.
// no_retrieval controls tool use; it does not make an intermediate draft the
// authoritative presentation text.
function directNoRetrievalDisplayText() {
  const sources = [];
  try { sources.push(...pickArray($('Normalize Execution Units').first().json.units).map(toInternalRenderContract)); } catch (e) {}
  try { sources.push(...pickArray($('Unit ordered Splitter').all().map(x => x.json && x.json.unit).filter(Boolean)).map(toInternalRenderContract)); } catch (e) {}
  for (const unit of sources) {
    const params = unit && unit.params && typeof unit.params === 'object' && !Array.isArray(unit.params) ? unit.params : {};
    const text = typeof params.text === 'string' ? params.text.trim() : '';
    const isLiteral = String(params.display_policy || '').toLowerCase() === 'literal';
    if (unit && unit.tool === 'direct_response' && isLiteral && text) return text;
  }
  return '';
}

function firstPresent(obj, keys) {
  if (!obj || typeof obj !== 'object') return null;

  for (const key of keys) {
    if (obj[key] != null && obj[key] !== '') return obj[key];
  }

  return null;
}

function formatChunkReference(ev, idx) {
  if (!ev || typeof ev !== 'object') return '';

  const direct = firstPresent(ev, [
    'chunk_id',
    'chunkId',
    'chunk_idx',
    'chunkIndex',
    'chunk_index',
    'source_chunk_id',
    'sourceChunkId',
    'source_id',
    'retrieval_chunk_id',
    'id'
  ]);

  if (direct != null && direct !== '') return String(direct);

  const rank = firstPresent(ev, ['retrieval_rank', 'rank']) || idx;
  if (ev.unit_id != null && ev.unit_id !== '') {
    return `unit ${ev.unit_id}, retrieved evidence #${rank}`;
  }

  return `retrieved evidence #${rank}`;
}

function splitIntoSentences(text) {
  const s = String(text || '').replace(/\s+/g, ' ').trim();
  if (!s) return [];

  // TAG_SAFE_SENTENCE_SPLITTING_V5
  const decimalToken = '__DECIMAL_POINT__';
  const tagDotToken = '__TAG_SUFFIX_DOT__';
  const protectedText = s
    .replace(/(\d)\.(\d)/g, `$1${decimalToken}$2`)
    .replace(/\b([A-Z][A-Z0-9_]*\d[A-Z0-9_]*)\.(PV|OP|SP|MV|SV|CV)\b/g, `$1${tagDotToken}$2`);
  const matches = protectedText.match(/[^.!?。！？；;]+[.!?。！？；;]+(?:\\s|$)?|[^.!?。！？；;]+$/g);
  return (matches || [protectedText])
    .map(x => x
      .replace(new RegExp(decimalToken, 'g'), '.')
      .replace(new RegExp(tagDotToken, 'g'), '.')
      .trim())
    .filter(Boolean);
}

function formatPageRange(ev, lang) {
  const p1 = ev && ev.page_start;
  const p2 = ev && ev.page_end;

  if (p1 == null && p2 == null) return '';

  if (p1 != null && p2 != null && String(p1) === String(p2)) {
    return lang === 'zh' ? `第 ${p1} 页` : `Page ${p1}`;
  }

  if (p1 != null && p2 != null) {
    return lang === 'zh' ? `第 ${p1}-${p2} 页` : `Pages ${p1}-${p2}`;
  }

  if (p1 != null) return lang === 'zh' ? `第 ${p1} 页` : `Page ${p1}`;
  return lang === 'zh' ? `第 ${p2} 页` : `Page ${p2}`;
}

function labelsFor(lang) {
  if (lang === 'zh') {
    return {
      evidence: '数据依据',
      tags: '相关信号',
      none: '无',
      document: '文档',
      documentId: '文档 ID',
      dataset: '数据集',
      page: '页码',
      section: '章节',
      snippet: '摘录',
      sourceType: '来源类型',
      score: '检索分数',
      rank: '排序',
      selectionQuery: '选择查询',
      whatItMeasures: '测量含义',
      cn: 'CN',
      en: 'EN',
      useInAnswer: '答案用途'
    };
  }

  return {
    evidence: 'Evidence Details',
    tags: 'Sensor Tag Selection',
    none: 'None',
    document: 'Document',
    documentId: 'Document ID',
    dataset: 'Dataset',
    page: 'Page',
    section: 'Section',
    snippet: 'Snippet',
    sourceType: 'Source Type',
    score: 'Retrieval Score',
    rank: 'Rank',
    selectionQuery: 'Selection Query',
    whatItMeasures: 'What It Measures',
    cn: 'CN',
    en: 'EN',
    useInAnswer: 'Use in Answer'
  };
}

function normalizeEvidenceIdToken(v) {
  const s = String(v || '').trim().replace(/[\[\]]/g, '');
  const m = s.match(/E\d+/i);
  return m ? m[0].toUpperCase() : '';
}

function uniqueEvidenceIds(arr) {
  const out = [];
  const seen = new Set();
  for (const v of arr || []) {
    const id = normalizeEvidenceIdToken(v);
    if (!id || seen.has(id)) continue;
    seen.add(id);
    out.push(id);
  }
  return out;
}

function evidenceIdsFromAnswer(text) {
  const out = [];
  const s = String(text || '');
  let m;
  const bracketed = /\[(E\d+)[^\]]*\]/gi;
  while ((m = bracketed.exec(s)) !== null) out.push(m[1].toUpperCase());
  const bare = /(^|[^A-Za-z0-9_\[])(E\d+)(?![A-Za-z0-9_]*)(?!\])/gi;
  while ((m = bare.exec(s)) !== null) out.push(m[2].toUpperCase());
  return uniqueEvidenceIds(out);
}

function buildEvidenceDisplayIdMap(directEids) {
  const map = new Map();
  for (const oldId of uniqueEvidenceIds(directEids)) {
    map.set(oldId, `E${map.size + 1}`);
  }
  return map;
}

function sanitizeEnglishAnswerText(text, lang) {
  const original = String(text || '');
  let out = original;
  if (lang !== 'zh') {
    const stripped = original
      .replace(/\s*[（(][^()（）]*[\u4e00-\u9fff][^()（）]*[）)]/g, '')
      .replace(/[\u4e00-\u9fff]+/g, '')
      .replace(/\s+([,.;:!?])/g, '$1')
      .replace(/[ \t]{2,}/g, ' ')
      .trim();

    // LANGUAGE_SANITIZER_FALLBACK_V443:
    // If the finalizer accidentally produced mostly Chinese for an English
    // question, stripping Han characters can turn a real answer into comma and
    // citation fragments. Preserve the original instead of emitting broken
    // punctuation; the finalizer prompt above is responsible for preventing
    // the mismatch in normal runs.
    const hanCount = (original.match(/[\u4e00-\u9fff]/g) || []).length;
    const latinCount = (stripped.match(/[A-Za-z]/g) || []).length;
    if (hanCount > 40 && latinCount < 80) {
      return original.trim();
    }

    out = stripped;
  }
  return out.trim();
}

function cleanDanglingCitationSpaces(s) {
  return String(s || '')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\(\s*\)/g, '')
    .replace(/\[\s*\]/g, '')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/\n[ \t]+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

