    } else if (contextualCandidate && dataVerified) {
      note = isZh
        ? '本轮用途：查到了历史记录，但目录说明显示其测量对象与所需输入不完全一致，因此未纳入计算。'
        : 'Non-null historical data was verified in this run, but the semantic match is contextual only and cannot replace the requested direct measurement.';
    } else if (contextualCandidate) {
      note = isZh
        ? '本轮用途：仅与相关工艺环节有关，现有目录说明不足以确认它就是所需输入，且本轮未读取其历史记录，因此未纳入计算。'
        : 'This tag is a contextual candidate and non-null historical data was not verified in this run; it is not a direct measured input.';
    } else if (directForThisAnswer && hasSemanticMetadata) {
      note = isZh
        ? '本轮用途：数据库目录说明与所需变量一致，但本轮查询未取得非空历史记录，因此暂未纳入计算。'
        : 'Catalog semantics are a direct match, but non-null historical data was not verified in this run; data availability remains unconfirmed.';
    } else {
      note = isZh
        ? '本轮用途：数据库目录中找到了该位号，但现有说明不足以确认它对应所需变量，因此未纳入计算；如需采用，应先用DCS点表、回路表或P&ID确认测量对象。'
        : 'ArcticDB catalog metadata is a candidate mapping; verify against DCS, P&ID, or loop sheets before treating it as confirmed measurement identity.';
    }
    if (!suppressAvailabilityStatus) {
      lines.push(`  - ${labels.useInAnswer}: ${note}`);
    }
