  return lines.join('\n');
}

function forceParagraphs(answer, lang) {
  let s = String(answer || '')
    .replace(/\r/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n[ \t]+/g, '\n')
    .replace(/\\n\\n/g, '\n\n')
    .replace(/\\n/g, '\n')
    .trim();

  if (!s) return '';

  // PRESENTATION_MERGE_V7（并入 2026-09-24 呈现层改动）：LLM 已输出标题、表格、列表时原样保留。
  const hasMarkdownStructure =
    /^ {0,3}#{1,6}\s+\S/m.test(s) ||
    /^\s*\|.*\|\s*$/m.test(s) ||
    /^\s*\|?\s*:?-{3,}:?\s*\|/m.test(s) ||
    /^\s*(?:[-*+]|\d+[.)])\s+\S/m.test(s);
  if (hasMarkdownStructure) return s;

  // If Finalizer already produced visible paragraph breaks, trust it.
  if (/\n\s*\n/.test(s)) {
    return s
      .split(/\n\s*\n/)
      .map(x => x.trim())
      .filter(Boolean)
      .join('\n\n')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
  }

  const sentences = splitIntoSentences(s.replace(/\n+/g, ' '));
  if (!sentences.length) return s;

  // Do not force paragraphing for short/simple answers.
  if (s.length < 520 && sentences.length <= 4) {
    return s;
  }

  function isLimitationSentence(x) {
    const t = String(x || '').toLowerCase();

    return (
      t.includes('however') ||
      t.includes('therefore') ||
      t.includes('cannot determine') ||
      t.includes('cannot verify') ||
      t.includes('unable to determine') ||
      t.includes('unable to verify') ||
      t.includes('insufficient evidence') ||
      t.includes('does not provide') ||
      t.includes('do not provide') ||
      t.includes('no explicit') ||
      t.includes('not available') ||
      t.includes('missing') ||
      t.includes('limited') ||
      t.includes('workflow cannot') ||
      t.includes('the available evidence does not') ||
      t.includes('the retrieved evidence does not') ||
      t.includes('measured verification was not completed') ||
      t.includes('time-series verification was not completed') ||
      t.includes('但') ||
      t.includes('但是') ||
      t.includes('然而') ||
      t.includes('因此') ||
      t.includes('无法') ||
      t.includes('不能') ||
      t.includes('不足') ||
      t.includes('未提供') ||
      t.includes('没有明确') ||
      t.includes('不可用') ||
      t.includes('缺少') ||
      t.includes('未完成')
    );
  }

  function isTransitionSentence(x) {
    const raw = String(x || '').trim();
    const t = raw.toLowerCase();

    return (
      t.startsWith('regarding ') ||
      t.startsWith('for the ') ||
      t.startsWith('for this ') ||
      t.startsWith('as for ') ||
      t.startsWith('in terms of ') ||
      t.startsWith('with respect to ') ||
      t.startsWith('in practice') ||
      t.startsWith('to maintain ') ||
      t.startsWith('as a safety ') ||
      t.startsWith('for safety') ||
      t.startsWith('the normal operating target') ||
      t.startsWith('the low-differential-pressure') ||
      t.startsWith('when ') ||
      t.startsWith('if ') ||
      raw.startsWith('关于') ||
      raw.startsWith('对于') ||
      raw.startsWith('至于') ||
      (raw.startsWith('在') && (raw.includes('方面') || raw.includes('时')))
    );
  }

  function isContinuationSentence(x) {
    const t = String(x || '').trim().toLowerCase();

    return (
      t.startsWith('additionally') ||
      t.startsWith('also') ||
      t.startsWith('furthermore') ||
      t.startsWith('moreover') ||
      t.startsWith('in addition') ||
      t.startsWith('同时') ||
      t.startsWith('此外') ||
      t.startsWith('另外') ||
      t.startsWith('并且')
    );
  }

  const main = [];
  const later = [];

  for (const sentence of sentences) {
    if (
      main.length > 0 &&
      !isContinuationSentence(sentence) &&
      (isLimitationSentence(sentence) || isTransitionSentence(sentence))
    ) {
      later.push(sentence);
    } else {
      main.push(sentence);
    }
  }

  if (main.length && later.length) {
    const mainText = main.join(' ');
    const laterText = later.join(' ');
    // Use semantic two-part paragraphing only when the split is balanced.
    // Otherwise continue to the generic sentence-count splitter below.
    if (laterText.length >= Math.max(260, mainText.length * 0.25)) {
      return [
        mainText,
        laterText
      ]
        .filter(Boolean)
        .join('\n\n')
        .replace(/\n{3,}/g, '\n\n')
        .trim();
    }
  }

  // Generic fallback for very long answers only.
  if (sentences.length >= 6) {
    const n = sentences.length;
    const cut1 = Math.max(2, Math.ceil(n * 0.55));
    const cut2 = Math.max(cut1 + 1, Math.ceil(n * 0.8));

    return [
      sentences.slice(0, cut1).join(' '),
      sentences.slice(cut1, cut2).join(' '),
      sentences.slice(cut2).join(' ')
    ]
      .filter(Boolean)
      .join('\n\n')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
  }

  return s;
}

function decodeJsonStringLoose(value) {
  return String(value || '')
    .replace(/\\n/g, '\n')
    .replace(/\\r/g, '\r')
    .replace(/\\t/g, '\t')
    .replace(/\\\"/g, '\"')
    .trim();
}

function extractJsonStringField(raw, field) {
  const s = String(raw || '');
  const key = `\"${field}\"`;
  const start = s.indexOf(key);
  if (start < 0) return '';

  const colon = s.indexOf(':', start + key.length);
  if (colon < 0) return '';

  const firstQuote = s.indexOf('\"', colon + 1);
  if (firstQuote < 0) return '';

  const boundary = new RegExp('\\",\\s*\\n?\\s*\\"[A-Za-z0-9_]+\\"\\s*:','g');
  boundary.lastIndex = firstQuote + 1;
  const b = boundary.exec(s);
  if (b && b.index > firstQuote) {
    return decodeJsonStringLoose(s.slice(firstQuote + 1, b.index));
  }

  let out = '';
  let escaped = false;

  for (let i = firstQuote + 1; i < s.length; i++) {
    const ch = s[i];

    if (escaped) {
      if (ch === 'n') out += '\n';
      else if (ch === 'r') out += '\r';
      else if (ch === 't') out += '\t';
      else out += ch;
      escaped = false;
    } else if (ch === '\\') {
      escaped = true;
    } else if (ch === '\"') {
      return out.trim();
    } else {
      out += ch;
    }
  }

  return '';
}

