      .replace(/（\s*(E\d+(?:\s*[,，、]\s*E\d+)*)\s*）/gi, (m, ids) => toCite(ids) ?? m)
      .replace(/\(\s*(E\d+(?:\s*[,，、]\s*E\d+)*)\s*\)/gi, (m, ids) => toCite(ids) ?? m)
      .replace(/(?<![\[A-Za-z0-9_-])\bE\d+\b(?!\])/gi, (m) => toCite(m) ?? m)
  );
}



