function normalizeEnglishAbbreviationSpacing(text) {
  // CONCEPT_ABBREVIATION_LINEBREAK_V424_PATCH: prevent formatter from turning abbreviations into broken paragraphs.
  return String(text || '')
    .replace(/\be\s*\.\s*g\s*\.\s*,?/gi, 'e.g.,')
    .replace(/\bi\s*\.\s*e\s*\.\s*,?/gi, 'i.e.,')
