    .replace(/\b([A-Za-z0-9_]+\d[A-Za-z0-9_]*)\.\s*((?:\[[Ee]\d+\]\s*){1,8})\n+\s*(PV|OP|SP|MV|SV|CV)\b/g, '$1.$3 $2')
    .replace(/\b([A-Za-z0-9_]+\d[A-Za-z0-9_]*)\.\s+((?:\[[Ee]\d+\]\s*){1,8})(PV|OP|SP|MV|SV|CV)\b/g, '$1.$3 $2')
    .replace(/\b([A-Z][A-Z0-9_]{1,20}\d[A-Z0-9_]*)\.\s+(PV|OP|SP|MV|SV|CV)\b/g, '$1.$2')
    .replace(/\b([A-Z][A-Z0-9_]{1,20}\d[A-Z0-9_]*)\.\s*\n+\s*(PV|OP|SP|MV|SV|CV)\b/g, '$1.$2');
