// DETERMINISTIC_FACTOR_COVERAGE_DISPLAY_V5
function verticalCoverageFromCompletedUnits() {
  const completed = pickArray(aggregatorJson.completed_units, outerPayload.completed_units);
  const factors = new Map();
  const selectedTags = new Set();
  const verifiedTags = new Set();
  const statsByTag = new Map();
  const descriptions = new Map();
  const candidatesByFactor = new Map();
  const statsFailures = [];
  let nonHistorianInputs = [];
  let statsScope = {};

  try {
    const splitterItems = $('Unit ordered Splitter').all();
    for (const item of splitterItems) {
      const debug = pickObject(item?.json?.unit?.presence_contract_debug);
      const names = pickArray(debug.structured_non_historian_inputs)
        .map(String).map(value => value.trim()).filter(Boolean);
      if (names.length) nonHistorianInputs = Array.from(new Set(names));
    }
  } catch (e) {}

  for (const unit of completed) {
    const raw = pickObject(unit?.raw_result, unit?.normalized_result?.raw_result);
    if (unit?.tool === 'arctic_find_tags') {
      for (const trace of pickArray(unit?.tag_selection_trace)) {
        const tag = String(trace?.tag || trace?.name || '').trim();
        const factorId = String(trace?.process_factor_id || trace?.process_factor || '').trim();
        if (tag) {
          descriptions.set(tag.toUpperCase(), {
            cn: String(trace?.desc_cn || trace?.description_cn || '').trim(),
            en: String(trace?.desc_en || trace?.description_en || '').trim()
          });
        }
        if (factorId && tag && trace?.selected !== true) {
          const rows = candidatesByFactor.get(factorId) || [];
          if (!rows.some(row => row.tag.toUpperCase() === tag.toUpperCase())) {
            rows.push({
              tag,
              desc: String(trace?.desc_cn || trace?.desc_en || '').trim(),
              reason: String(trace?.physical_quantity_check?.reason || '').trim()
            });
          }
          candidatesByFactor.set(factorId, rows);
        }
      }
      for (const entry of pickArray(raw.factor_resolution)) {
        const id = String(entry?.factor_id || entry?.factor || '').trim();
        if (!id) continue;
        const previous = factors.get(id) || {};
        const merged = {
          ...previous,
          ...entry,
          factor_id: id,
          factor: String(entry?.factor || previous?.factor || id).trim(),
          selected_tags: Array.from(new Set([
            ...pickArray(previous?.selected_tags),
            ...pickArray(entry?.selected_tags)
          ].map(value => String(value || '').trim()).filter(Boolean)))
        };
        merged.resolution = merged.selected_tags.length ? 'direct_match' : 'unresolved';
        factors.set(id, merged);
        for (const tag of merged.selected_tags) selectedTags.add(tag.toUpperCase());
      }
    }
    if (unit?.tool === 'arctic_stats') {
      const stats = pickObject(raw.column_stats, raw.stats);
      if (String(unit?.execution_status || '').toUpperCase() !== 'SUCCESS') {
        const failedRequested = Array.from(new Set([
          ...pickArray(raw.requested_columns),
          ...pickArray(unit?.params?.columns)
        ].map(String).filter(value => value && !/^\$ref:/i.test(value)))).slice(0, 80);
        if (failedRequested.length) statsFailures.push({
          status: String(unit?.execution_status || 'unknown'),
          message: String(unit?.answer || raw.error_message || '').trim().slice(0, 1200),
          requested_columns: failedRequested
        });
      }
      const missing = new Set(pickArray(raw.missing_columns).map(x => String(x).toUpperCase()));
      const allNull = new Set(pickArray(raw.all_null_columns).map(x => String(x).toUpperCase()));
      statsScope = {
        library: String(raw.library || statsScope.library || '').trim(),
        symbol: String(raw.symbol || statsScope.symbol || '').trim(),
        timeRange: pickArray(raw.time_range).length ? pickArray(raw.time_range) : statsScope.timeRange,
        rowCount: Number(raw.row_count) || statsScope.rowCount || 0,
        dataScope: String(raw.data_scope || statsScope.dataScope || '').trim()
      };
      for (const [column, values] of Object.entries(stats)) {
        const key = String(column || '').trim().toUpperCase();
        if (!key) continue;
        statsByTag.set(key, values || {});
        if (Number(values?.count) > 0 && !missing.has(key) && !allNull.has(key)) {
          verifiedTags.add(key);
        }
      }
    }
    if (unit?.tool === 'arctic_read') {
      const nonNull = new Set(pickArray(raw.non_null_columns).map(x => String(x).toUpperCase()));
      const requested = pickArray(raw.columns, raw.requested_columns, unit?.params?.columns)
        .map(value => String(value || '').trim())
        .filter(Boolean);
      statsScope = {
        library: String(raw.library || unit?.params?.library || statsScope.library || '').trim(),
        symbol: String(raw.symbol || unit?.params?.symbol || statsScope.symbol || '').trim(),
        timeRange: pickArray(raw.time_range).length ? pickArray(raw.time_range) : statsScope.timeRange,
        rowCount: Number(raw.row_count) || statsScope.rowCount || 0,
        dataScope: String(raw.data_scope || statsScope.dataScope || '').trim()
      };
      for (const tag of requested) {
        const key = tag.toUpperCase();
        if (!nonNull.has(key)) continue;
        verifiedTags.add(key);
        if (!statsByTag.has(key)) {
          statsByTag.set(key, { existence_confirmed: true });
        }
      }
    }
  }

  // CROSS_FACTOR_METADATA_RECONCILIATION_V5
  // Factor discovery is split into bounded batches. A broad factor in one
  // batch can therefore select a tag whose catalog description also directly
  // answers a narrower factor in another batch. Reconcile those results only
  // from tags that were both selected and verified as non-null in this run.
  // The matcher uses language-independent token and CJK n-gram overlap; it has
  // no test-question, factor-name, or tag dictionary.
  function semanticFeatures(value) {
    const normalized = String(value || '')
      .normalize('NFKC')
      .toLowerCase()
      .replace(/[._/\\|()[\]{}:;,，。；：、\-]+/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    const words = new Set(normalized.match(/[a-z][a-z0-9]{1,}/g) || []);
    const cjk = (normalized.match(/[\u3400-\u9fff]/g) || []).join('');
    const grams = new Set();
    for (const size of [2, 3]) {
      for (let index = 0; index + size <= cjk.length; index += 1) {
        grams.add(cjk.slice(index, index + size));
      }
    }
    return { words, grams };
  }

  function overlapCount(left, right) {
    let count = 0;
    for (const value of left) if (right.has(value)) count += 1;
    return count;
  }

  function metadataCoverageScore(factorName, description) {
    const factor = semanticFeatures(factorName);
    const desc = semanticFeatures(description);
    const sharedWords = overlapCount(factor.words, desc.words);
    const sharedGrams = overlapCount(factor.grams, desc.grams);
    const wordBase = Math.max(1, Math.min(factor.words.size, desc.words.size));
    const gramBase = Math.max(1, Math.min(factor.grams.size, desc.grams.size));
    return {
      sharedWords,
      sharedGrams,
      score: Math.max(sharedWords / wordBase, sharedGrams / gramBase)
    };
  }

  // DISTINCTIVE_METADATA_RECONCILIATION_V5
  // Generic quantity fragments often occur in many catalog descriptions. They
  // cannot by themselves identify equipment or measurement location. Require
  // every promoted match to share at least one feature that is uncommon among
  // the selected descriptions from this run.
  const descriptorFeatures = new Map();
  const gramFrequency = new Map();
  const wordFrequency = new Map();
  for (const tagKey of selectedTags) {
    if (!verifiedTags.has(tagKey)) continue;
    const description = descriptions.get(tagKey) || {};
    const combined = `${description.cn || ''} ${description.en || ''}`.trim();
    if (!combined) continue;
    const features = semanticFeatures(combined);
    descriptorFeatures.set(tagKey, features);
    for (const gram of features.grams) gramFrequency.set(gram, (gramFrequency.get(gram) || 0) + 1);
    for (const word of features.words) wordFrequency.set(word, (wordFrequency.get(word) || 0) + 1);
  }
  const distinctiveLimit = Math.max(1, Math.floor(descriptorFeatures.size * 0.25));

  for (const entry of factors.values()) {
    if (entry?.resolution === 'direct_match' || pickArray(entry?.selected_tags).length) continue;
    const matches = [];
    const factorFeatures = semanticFeatures(entry.factor);
    for (const [tagKey, descFeatures] of descriptorFeatures.entries()) {
      const description = descriptions.get(tagKey) || {};
      const combined = `${description.cn || ''} ${description.en || ''}`.trim();
      const coverage = metadataCoverageScore(entry.factor, combined);
      const distinctiveGrams = Array.from(factorFeatures.grams)
        .filter(gram => descFeatures.grams.has(gram) && (gramFrequency.get(gram) || 0) <= distinctiveLimit)
        .length;
      const distinctiveWords = Array.from(factorFeatures.words)
        .filter(word => descFeatures.words.has(word) && (wordFrequency.get(word) || 0) <= distinctiveLimit)
        .length;
      const sufficientlySpecific =
        (coverage.sharedGrams >= 4 && distinctiveGrams >= 1 && coverage.score >= 0.25) ||
        (coverage.sharedWords >= 2 && distinctiveWords >= 1 && coverage.score >= 0.5);
      if (sufficientlySpecific) matches.push({
        tag: tagKey,
        ...coverage,
        distinctiveGrams,
        distinctiveWords
      });
    }
    if (!matches.length) continue;
    matches.sort((a, b) => b.score - a.score || b.sharedGrams - a.sharedGrams || b.sharedWords - a.sharedWords);
    const bestScore = matches[0].score;
    entry.selected_tags = matches
      .filter(match => match.score >= bestScore - 0.08)
      .map(match => match.tag);
    entry.resolution = 'direct_match';
    entry.resolution_source = 'cross_factor_metadata_reconciliation';
    entry.reconciliation_score = Number(bestScore.toFixed(4));
  }

  // Rebuild the selected set because reconciliation can add direct mappings.
  selectedTags.clear();
  for (const entry of factors.values()) {
    for (const tag of pickArray(entry?.selected_tags)) selectedTags.add(String(tag).toUpperCase());
  }

  const rows = Array.from(factors.values());
  const resolvedRows = rows.filter(row => row?.resolution === 'direct_match');
  const unresolvedRows = rows.filter(row => row?.resolution !== 'direct_match');
  return {
    requested: rows.length + nonHistorianInputs.length,
    historianRequested: rows.length,
    nonHistorianInputs,
    resolved: resolvedRows.length,
    unresolved: unresolvedRows.length,
    selectedTagCount: selectedTags.size,
    verifiedTagCount: Array.from(selectedTags).filter(tag => verifiedTags.has(tag)).length,
    resolvedRows,
    unresolvedRows,
    selectedTags,
    verifiedTags,
    statsByTag,
    statsScope,
    descriptions,
    candidatesByFactor,
    statsFailures
  };
}

function removeCoverageOverclaims(text, coverage) {
  if (!coverage || coverage.unresolved <= 0) return text;
  return splitIntoSentences(text)
    .filter(sentence => {
      const value = String(sentence || '');
      if (lang === 'zh') {
        const totalClaim = /(?:全部|所有|均已|不存在缺失|没有缺失|无缺失)/.test(value);
        const inputScope = /(?:请求|计算)?(?:输入|因子|测点)/.test(value);
        return !(totalClaim && inputScope);
      }
      return !(/\b(?:all|every|no missing|none missing)\b/i.test(value) &&
        /\b(?:requested|calculation)?\s*(?:inputs?|factors?|tags?|measurements?)\b/i.test(value));
    })
    .join(' ')
    .trim();
}

function isHistorianInputAvailabilityQuestion(question) {
  const value = String(question || '');
  const asksHistorian = /历史实时数据库|历史数据库|历史库|historian|historical database/i.test(value);
  const asksAvailability = /有效数据|存在.*数据|可以直接使用|缺失|候选|available|availability|usable|missing|candidate/i.test(value);
  return asksHistorian && asksAvailability;
}

function compactDate(value) {
  return String(value || '').replace('T', ' ').replace(/\s+\d{2}:\d{2}:\d{2}.*$/, '');
}

function percent(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return '';
  return `${(number * 100).toFixed(number >= 0.1 ? 1 : 2)}%`;
}

// NATURAL_FACTOR_AVAILABILITY_ANSWER_V5
// Availability answers are reconstructed from factor mappings and historian
// statistics. Internal enums and raw key=value dumps remain in the audit data,
// not in the prose shown to the user.
function naturalAvailabilityAnswer(coverage, readEvidenceId) {
  // STATS_FAILURE_AVAILABILITY_STATE_V5
  // A failed historian read is neither evidence of missing data nor evidence
  // that a catalog mapping is usable. Keep mapping and data availability as
  // separate states so a transient backend error cannot become a false zero.
  if (pickArray(coverage.statsFailures).length && coverage.verifiedTagCount === 0) {
    const mapped = coverage.resolvedRows
      .map(row => {
        const tags = pickArray(row.selected_tags).map(tag => String(tag || '').trim()).filter(Boolean);
        if (!tags.length) return '';
        const tagText = tags.map(tag => {
          const desc = coverage.descriptions.get(tag.toUpperCase()) || {};
          return desc.cn ? `${tag}（${desc.cn}）` : tag;
        }).join('、');
        return `- ${row.factor}：${tagText}`;
      })
      .filter(Boolean);
    const unresolved = coverage.unresolvedRows.map(row => row.factor).filter(Boolean);
    const failedColumns = Array.from(new Set(
      coverage.statsFailures.flatMap(failure => pickArray(failure.requested_columns)).map(String).filter(Boolean)
    ));
    const sections = [
      `此次历史数据读取没有完成，因此目前只能列出已经识别到的相关信号，不能判断这些信号是否具有可用的非空历史记录。`
    ];
    if (mapped.length) sections.push(`已经识别到的相关信号：
${mapped.join('\n')}`);
    if (unresolved.length) sections.push(
      `目前还缺少明确对应信号或必要设计资料的计算条件：
${unresolved.join('、')}。` +
      `其中计算量和设计条件可能需要由多个实测量组合计算，不能按单个信号名称判断。`
    );
    sections.push(
      `需要重新读取上述相关信号的历史记录，确认数据覆盖时间和有效样本后，才能判断哪些输入能够直接用于计算。`
    );
    return sections.join('\n\n');
  }

  // GROUPED_AVAILABILITY_DATA_QUALITY_V5
  // List each factor/tag mapping once. Data quality belongs to the result set
  // as a whole, so it is summarized once after the list instead of repeated
  // mechanically for every factor.
  const directlyUsable = coverage.resolvedRows
    .map(row => {
      const verified = pickArray(row.selected_tags)
        .map(tag => String(tag || '').trim())
        .filter(tag => coverage.verifiedTags.has(tag.toUpperCase()));
      if (!verified.length) return '';
      const tagText = verified.map(tag => {
        const desc = coverage.descriptions.get(tag.toUpperCase()) || {};
        return desc.cn ? `${tag}（${desc.cn}）` : tag;
      }).join('、');
      return `- ${row.factor}：${tagText}`;
    })
    .filter(Boolean);

  const verifiedStats = Array.from(coverage.selectedTags)
    .filter(tag => coverage.verifiedTags.has(String(tag || '').toUpperCase()))
    .map(tag => coverage.statsByTag.get(String(tag || '').toUpperCase()) || {});
  const nullRates = verifiedStats
    .map(stats => Number(stats?.null_rate))
    .filter(Number.isFinite);
  const groupedQuality =
    `以上共 ${coverage.verifiedTagCount} 个直接测点，均在本轮查询范围内读取到非空历史记录` +
    `${nullRates.length ? `；其中最高空值比例约为 ${percent(Math.max(...nullRates))}` : ''}。`;

  const candidateLines = [];
  const missingNames = [];
  for (const row of coverage.unresolvedRows) {
    const candidates = pickArray(coverage.candidatesByFactor.get(row.factor_id)).slice(0, 8);
    if (!candidates.length) {
      missingNames.push(row.factor);
      continue;
    }
    const candidateText = candidates.map(candidate => {
      const tag = String(candidate.tag || '').trim();
      const label = candidate.desc ? `${tag}（${candidate.desc}）` : tag;
      return coverage.verifiedTags.has(tag.toUpperCase())
        ? `${label}，已确认存在非空历史记录`
        : `${label}，本轮尚未确认非空历史记录`;
    }).join('；');
    candidateLines.push(
      `- ${row.factor}：检索到了 ${candidateText}。这些候选的测量对象或物理量尚未与所需输入建立直接对应关系，因此即使已有数据，也不能直接代入公式。`
    );
  }

  const scope = coverage.statsScope || {};
  const range = pickArray(scope.timeRange);
  const rangeText = range.length === 2
    ? `${compactDate(range[0])} 至 ${compactDate(range[1])}`
    : '本轮实际查询范围';
  const conclusion =
    `核对结果：前序回答涉及 ${coverage.requested} 项计算输入，其中 ${directlyUsable.length} 项在历史实时数据库中` +
    `找到了可直接使用的测点，另外 ${coverage.requested - directlyUsable.length} 项目前还不能直接用于计算。`;

  const sections = [conclusion];
  if (directlyUsable.length) {
    sections.push(`可直接使用的输入：\n${directlyUsable.join('\n')}\n\n${groupedQuality}`);
  }
  if (candidateLines.length) {
    sections.push(`暂时只能作为候选：\n${candidateLines.join('\n')}`);
  }
  if (missingNames.length) {
    sections.push(
      `尚未找到可直接使用测点的输入：\n${missingNames.join('、')}。` +
      `这表示本次查询没有找到满足条件的直接测量，并不等同于证明数据库中绝对不存在相关信息。`
    );
  }
  if (pickArray(coverage.nonHistorianInputs).length) {
    sections.push(
      `不属于历史实时数据库测点的输入：\n${coverage.nonHistorianInputs.join('、')}。` +
      '这些项目属于设备布置、标高、结构或计算模型，应从 P&ID、设备布置图、仪表回路表或设计计算书确认，不能把本轮未检索到传感器标签解释为数据缺失。'
    );
  }
  if (pickArray(coverage.statsFailures).length) {
    const failedColumns = Array.from(new Set(
      coverage.statsFailures
        .flatMap(failure => pickArray(failure.requested_columns))
        .map(String)
        .filter(Boolean)
    ));
    sections.push(
      `部分历史数据读取批次未完成${failedColumns.length ? `，涉及 ${failedColumns.join('、')}` : ''}。` +
      '已成功返回的测点仍按实际结果报告；失败批次对应测点的数据存在性保持未确认，不能按缺失或全空处理。'
    );
  }
  sections.push(
    `数据范围与边界：本轮历史数据来自 ${scope.library || '所选历史库'}` +
    `，覆盖 ${rangeText}${scope.rowCount ? `，库内时间轴共 ${scope.rowCount.toLocaleString('en-US')} 行` : ''}。${readEvidenceId ? `[${readEvidenceId}]` : '[E1]'} ` +
    `这里确认的是相关信号是否存在非空历史记录；工程单位、量程及是否满足具体计算公式的采样要求，仍需结合设计资料或计算定义确认。`
  );
  return sections.join('\n\n');
}

