    return pickArray(raw.non_null_columns).length > 0;
  });
  if (!reads.length) return '';
  const columns = Array.from(new Set(reads.flatMap(unit => {
    const raw = pickObject(unit?.raw_result, unit?.normalized_result?.raw_result);
    return pickArray(raw.non_null_columns).map(String);
  }).filter(Boolean)));
  const ranges = reads
    .map(unit => pickArray(pickObject(unit?.raw_result, unit?.normalized_result?.raw_result).time_range))
    .filter(range => range.length === 2);
  const existingNumbers = evidence.map(item => {
    const match = String(item?.evidence_id || '').match(/^E(\d+)$/i);
    return match ? Number(match[1]) : 0;
  });
  const evidenceId = `E${Math.max(0, ...existingNumbers) + 1}`;
  const requestedColumns = Array.from(new Set(reads.flatMap(unit => {
    const raw = pickObject(unit?.raw_result, unit?.normalized_result?.raw_result);
    return pickArray(raw.requested_columns, raw.columns, unit?.params?.columns).map(String);
  }).filter(value => value && !/^\$ref:/i.test(value))));
  const libraries = Array.from(new Set(reads.map(unit => {
    const raw = pickObject(unit?.raw_result, unit?.normalized_result?.raw_result);
    return String(raw.library || unit?.params?.library || '').trim();
  }).filter(Boolean)));
  const symbols = Array.from(new Set(reads.map(unit => {
    const raw = pickObject(unit?.raw_result, unit?.normalized_result?.raw_result);
    return String(raw.symbol || unit?.params?.symbol || '').trim();
  }).filter(Boolean)));
  const rangeText = ranges.length
    ? `${ranges[0][0]} 至 ${ranges[ranges.length - 1][1]}`
    : '本轮返回结果未提供时间边界';
  const evidenceItem = {
    evidence_id: evidenceId,
    document_id: null,
    document_name: null,
    dataset_name: [...libraries, ...symbols].filter((value, index, all) => all.indexOf(value) === index).join(' / ') || null,
    section_title: 'ArcticDB 实际读取结果（非空历史数据核查）',
    source_type: 'arctic_sensor_data',
    retrieval_score: null,
    snippet: `本轮通过 ${reads.length} 个 ArcticDB 读取单元核查历史数据。` +
      `${requestedColumns.length ? `共请求 ${requestedColumns.length} 个测点；` : ''}` +
      `其中 ${columns.length} 个测点返回非空历史记录：${columns.join('、')}。` +
      `实际返回数据的时间边界为 ${rangeText}。` +
      '该证据可确认这些测点在本轮读取范围内存在非空记录，但不能单独证明整个期间连续无缺口，也不能替代工程单位和测量含义核对。',
    unit_id: reads.map(unit => unit.unit_id).filter(Boolean).join(',')
  };
  evidence.push(evidenceItem);
  evidenceById.set(evidenceId.toUpperCase(), evidenceItem);
  const displayNumbers = Array.from(evidenceDisplayIdMap.values()).map(value => {
    const match = String(value || '').match(/^E(\d+)$/i);
    return match ? Number(match[1]) : 0;
  });
  const displayEvidenceId = `E${Math.max(0, ...displayNumbers) + 1}`;
  evidenceDisplayIdMap.set(evidenceId.toUpperCase(), displayEvidenceId);
  if (!originalDirectEids.includes(evidenceId.toUpperCase())) {
    originalDirectEids.push(evidenceId.toUpperCase());
  }
  return displayEvidenceId;
}

