      )
      .replace(/\bcontextual_match\b/gi, '仅与相关工艺环节有关的候选测点')
      .replace(/\bdirect_match\b/gi, '与所需计算输入直接对应')
      .replace(/\bunresolved\b/gi, '尚未找到可直接使用的对应测点')
      .replace(
        /数据状态未经验证/g,
        '本轮未读取该候选测点在指定范围内的历史数据'
      )
      .replace(
        /通过统计验证具有大量非空样本/g,
        '在本轮查询范围内读取到了大量非空历史记录'
      )
      .replace(
        /已由非空统计数据验证/g,
        '在本轮查询范围内已读取到非空历史记录'
      )
      .replace(
        /语义均已通过元数据直接匹配确认/g,
        '数据库目录中的测点说明与所需变量一致'
      )
      .replace(
        /在标签目录中存在且语义匹配[“"]([^”"]+)[”"]/g,
        '在数据库目录中存在，目录说明为“$1”'
      )
      .replace(
        /需重新查询或通过DCS\/SIS点表、回路图确认其数据可用性/g,
        '需重新查询历史数据；DCS/SIS点表或回路图只能用于确认测量对象、单位和量程，不能证明历史数据是否存在'
      )
      .replace(/语义匹配未通过/g, '目录说明显示其测量对象与所需输入不同')
      .replace(/语义未确认/g, '现有目录说明不足以确认它就是所需输入')
      .replace(/仍属未解析状态/g, '尚未找到可直接使用的对应测点')
      .replace(/未解析状态/g, '尚未找到可直接使用的对应测点')
      // Public answers describe the consequence of machine states; enum and
      // object names remain available in execution traces for auditing.
      .replace(/[（(][^（）()\n]{0,100}(?:current_calculation_status|formula_subset_terms|requires_explicit_formula_dependency_and_unit_mapping)[^（）()\n]{0,100}[)）]/gi, '')
      .replace(/[（(]\s*full_formula_closure\s*[)）]/gi, '')
      .replace(/\bfull_formula_closure\b/gi, '完整公式闭合计算')
      .replace(/统计验证步骤/g, '历史数据查询')
      .replace(/因上游依赖未满足而被阻塞/g, '由于没有确定可查询的测点而未执行');
  } else {
    value = value
      .replace(/\bcontextual_match\b/gi, 'related candidate, not the requested measurement')
      .replace(/\bdirect_match\b/gi, 'directly corresponds to the requested input')
      .replace(/\bunresolved\b/gi, 'no directly usable measurement was found')
      .replace(
        /\bunverified data status\b/gi,
        'historical records for this candidate were not read in the queried scope'
      );
  }
  return value;
}

