// INHERITED_EVENT_DISPLAY_CONSISTENCY_V5
function priorConfirmedEvent() {
  try {
    const state = pickObject(toInternalRenderContract($('Capture context').first().json.conversation_state));
    const top = pickObject(state.event_status);
    const topStatistical = pickObject(top.statistical_anomaly);
    if (
      String(top.status || '').toLowerCase() === 'confirmed' &&
      String(topStatistical.status || '').toLowerCase() === 'confirmed'
    ) return top;

    // EVENT_CARD_RECOVERY_V5
    // Recover a structured anchor from the most recent confirmed analysis card
    // only when an older workflow version already corrupted the top-level
    // event state. This is generic extraction from saved question evidence.
    let resolvedQuestion = '';
    try {
      const decomposed = toInternalRenderContract(safeParseOutput($('Decompose Question').first().json.output));
      resolvedQuestion = String(decomposed.resolved_question || '');
    } catch (e) {}
    const requestedDates = new Set(
      resolvedQuestion.match(/\d{4}-\d{2}-\d{2}/g) || []
    );

    const cards = pickArray(state.question_memory_cards).slice().reverse();
    for (const card of cards) {
      if (String(card?.status || '').toLowerCase() !== 'confirmed') continue;
      const text = String(card?.current_answer_summary || '');
      const matches = [];
      const pattern = /(\d{4}-\d{2}-\d{2})[^。；]{0,120}?z\s*=\s*(-?\d+(?:\.\d+)?)/gi;
      let match;
      while ((match = pattern.exec(text)) !== null) {
        const prefix = text.slice(Math.max(0, match.index - 220), match.index);
        const tags = prefix.match(/[A-Z][A-Z0-9_]*\d[A-Z0-9_]*\.PV/gi) || [];
        matches.push({
          column: tags.length ? tags[tags.length - 1] : '',
          timestamp: match[1],
          zscore: Number(match[2])
        });
      }
      const scopedMatches = requestedDates.size
        ? matches.filter(entry => requestedDates.has(entry.timestamp))
        : matches;
      if (!scopedMatches.length) continue;
      scopedMatches.sort((a, b) => Math.abs(b.zscore) - Math.abs(a.zscore));
      const strongest = scopedMatches[0];
      return {
        status: 'confirmed',
        event_type: 'statistical_anomaly',
        event_window: {
          status: 'anchor_available',
          anchor_timestamp: strongest.timestamp,
          source: 'confirmed_question_memory_card'
        },
        statistical_anomaly: {
          status: 'confirmed',
          strongest_event: strongest
        },
        recovery_source: 'confirmed_question_memory_card'
      };
    }
    return top;
  } catch (e) {
    return {};
  }
}

