// STRUCTURED_ANALYSIS_INTEGRITY_V5
// A ranked anomaly list can mention only the windows containing top events.
// Scope statements must come from the executed target windows, not from the
// subset represented in the ranking.
function enforceExecutedWindowScope(answerText, result, lang) {
  const targets = pickArray(result && result.targets)
    .filter(target => pickArray(target && target.time_range).length === 2);
  if (targets.length <= 1) return String(answerText || '');
  const firstRange = pickArray(targets[0].time_range);
  const lastRange = pickArray(targets[targets.length - 1].time_range);
  let value = String(answerText || '');
  if (lang === 'zh') {
    value = value.replace(/本次分析采用了\s*\d+\s*个分析窗口[^。！？]*[。！？]?/g, '');
    const scope = `本次实际执行了 ${targets.length} 个连续历史窗口，覆盖 ${firstRange[0]} 至 ${lastRange[1]}；异常列表只展示评分最高的结果，某个窗口未出现在列表中不表示该窗口未执行。`;
    if (value.includes(scope)) return value.trim(); // ANSWER_EDIT_ROUND_V8：已有同一句则不重复追加
    return `${value.trim()}\n\n${scope}`.trim();
  }
  value = value.replace(/This analysis used\s+\d+\s+(?:analysis\s+)?windows?[^.?!]*[.?!]?/gi, '');
  const scope = `The analysis executed ${targets.length} consecutive historical windows covering ${firstRange[0]} to ${lastRange[1]}; the anomaly list shows only the highest-ranked results, so an unlisted window was still executed.`;
  if (value.includes(scope)) return value.trim();
  return `${value.trim()}\n\n${scope}`.trim();
}

