// DATA_QUALITY_COUNT_SEMANTICS_V5
// Non-null existence and zero-missing completeness are different counts.
// Reconcile visible totals with structured data_quality before display.
function reconcileDataQualityCounts(answerText, result, lang) {
  const rows = pickArray(result && result.data_quality)
    .filter(row => String(row?.column || row?.column_id || '').trim());
  if (!rows.length) return String(answerText || '');
  const nonNull = rows.filter(row =>
    row?.all_null !== true &&
    (
      Number(row?.count) > 0 ||
      Number(row?.null_fraction) < 1
    )
  ).length;
  const zeroMissing = rows.filter(row =>
    row?.all_null !== true &&
    (
      Number(row?.null_count) === 0 ||
      Number(row?.null_fraction) === 0
    )
  ).length;
  let value = String(answerText || '');
  if (lang === 'zh') {
    value = value.replace(
      /在已分析的\s*\d+\s*个(?:标签|变量|测点)中，?有\s*\d+\s*个变量在窗口内实际有非空数据[，,:：]?/g,
      `本轮分析的 ${rows.length} 个变量均有非空数据，其中 ${zeroMissing} 个变量零缺失；`
    );
    return value;
  }
  value = value.replace(
    /Of the\s+\d+\s+analy[sz]ed\s+(?:tags|variables|columns),?\s+\d+\s+had non-null data[:,]?/gi,
    `All ${nonNull} of ${rows.length} analyzed variables had non-null data; ${zeroMissing} had zero missing observations:`
  );
  return value;
}

