function limitTagsForDisplay(tags, answerText, maxItems) {
  const text = String(answerText || '').toLowerCase();
  const selected = [];
  const seen = new Set();

  for (const tag of tags || []) {
    const name = String(tag && tag.tag || '').trim();
    if (!name || seen.has(name)) continue;
    if (text && !text.includes(name.toLowerCase())) continue;
    seen.add(name);
    selected.push(tag);
    if (selected.length >= maxItems) break;
  }

  return selected;
}

