function analysisColumnName(row) {
  const value = String(row?.column || row?.column_id || '').trim();
  return value.includes('.') && !/\.(?:PV|SP|OP|MV|SV|CV)$/i.test(value)
    ? value.slice(value.indexOf('.') + 1)
