}

function measuredTagSets(completedUnits) {
  const verified = new Set();
  const used = new Set();
  for (const unit of (Array.isArray(completedUnits) ? completedUnits : [])) {
    if (!unit || !['arctic_stats', 'arctic_analyze'].includes(unit.tool)) continue;
    const raw = unit.raw_result && typeof unit.raw_result === 'object'
      ? unit.raw_result
      : {};
    if (unit.tool === 'arctic_analyze') {
      // The analyzer's returned_columns are the authoritative execution
      // provenance even when merged window profiles are keyed objects rather
      // than row arrays.
      for (const target of pickArray(raw.targets)) {
        const missing = new Set(pickArray(target?.missing_columns).map(value => String(value || '').trim().toUpperCase()));
        const nonNumeric = new Set(pickArray(target?.non_numeric_columns).map(value => String(value || '').trim().toUpperCase()));
        for (const column of pickArray(target?.returned_columns)) {
          const key = analysisColumnName({ column }).toUpperCase();
          if (!key) continue;
          used.add(key);
          if (!missing.has(key) && !nonNumeric.has(key)) verified.add(key);
        }
      }
    }
    if (unit.tool === 'arctic_stats') {
      const stats = raw.column_stats && typeof raw.column_stats === 'object'
        ? raw.column_stats
        : (raw.stats && typeof raw.stats === 'object' ? raw.stats : {});
      const missing = new Set((Array.isArray(raw.missing_columns) ? raw.missing_columns : []).map(value => String(value || '').trim().toUpperCase()));
      const allNull = new Set((Array.isArray(raw.all_null_columns) ? raw.all_null_columns : []).map(value => String(value || '').trim().toUpperCase()));
      for (const [column, values] of Object.entries(stats)) {
        const key = String(column || '').trim().toUpperCase();
        const count = Number(values && values.count);
        if (key && Number.isFinite(count) && count > 0 && !missing.has(key) && !allNull.has(key)) {
          verified.add(key);
          used.add(key);
        }
      }
      continue;
    }

    for (const row of [
      ...pickArray(raw.period_profile),
      ...pickArray(raw.data_quality),
      ...pickArray(raw.baseline_comparison)
    ]) {
      const key = analysisColumnName(row).toUpperCase();
      const count = Number(row?.count);
      const allNull = row?.all_null === true || Number(row?.null_fraction) >= 1;
      if (!key) continue;
      used.add(key);
      if ((!Number.isFinite(count) || count > 0) && !allNull) verified.add(key);
    }
  }
  return { verified, used };
}

