// CONFIGURED_TARGET_NAME_INTEGRITY_V5
// Preserve library and symbol identities from workflow configuration. A final
// prose model may introduce a one-character typo; near-identical identifiers
// are restored to the configured value without encoding any fixed target.
function editDistance(leftValue, rightValue) {
  const left = String(leftValue || '').toLowerCase();
  const right = String(rightValue || '').toLowerCase();
  const row = Array.from({ length: right.length + 1 }, (_, index) => index);
  for (let i = 1; i <= left.length; i += 1) {
    let previous = row[0];
    row[0] = i;
    for (let j = 1; j <= right.length; j += 1) {
      const saved = row[j];
      row[j] = Math.min(
        row[j] + 1,
        row[j - 1] + 1,
        previous + (left[i - 1] === right[j - 1] ? 0 : 1)
      );
      previous = saved;
    }
  }
  return row[right.length];
}

function configuredHistorianTargetNames() {
