function pickFirst(...vals) {
  for (const v of vals) {
    if (typeof v === "string" && v.trim().length > 0) return v.trim();
    if (typeof v === "number" && Number.isFinite(v)) return String(v);
  }
  return "";
}

function asArray(x) {
  return Array.isArray(x) ? x : [];
}

function asString(x) {
  return typeof x === "string" ? x.trim() : "";
}

function nodeJson(name) {
  try {
    return $(name).first().json || {};
  } catch {
    return {};
  }
}

function safeParse(x) {
  if (x && typeof x === "object" && !Array.isArray(x)) return x;
  if (typeof x !== "string") return {};
  const s = x.trim();
  if (!s) return {};
  try { return JSON.parse(s); } catch {}
  return {};
}

// ARCTIC_TARGET_REGISTRY_PROPAGATION_V5
function normalizeArcticTargetRegistry(value) {
  const out = [];
  const seen = new Set();
  for (const raw of asArray(value)) {
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) continue;
    const tag = asString(raw.tag || raw.name);
    const library = asString(raw.library);
    const symbol = asString(raw.symbol);
    if (!tag || !library || !symbol) continue;
    const key = `${tag.toUpperCase()}|${library}|${symbol}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({
      tag,
      library,
      symbol,
      count: raw.count !== null && raw.count !== '' && Number.isFinite(Number(raw.count)) ? Number(raw.count) : null,
      data_status: asString(raw.data_status || raw.status),
      time_range: asArray(raw.time_range).slice(0, 2),
      desc_cn: asString(raw.desc_cn),
      desc_en: asString(raw.desc_en),
      process_factor: asString(raw.process_factor || raw.factor),
      source_turn: asString(raw.source_turn)
    });
  }
  return out.slice(-240);
}

