function trimTurnsToMemoryBudget(turns) {
  const wf = nodeJson('Workflow Configuration');
  const rp = safeParse(wf.run_params) || {};
  const maxChars = Math.max(4000, Math.min(Number(rp?.memory?.recent_turn_char_budget || 14000), 30000));
  const source = asArray(turns).slice(-getRecentTurnLimit());
  const kept = [];
  let used = 0;
  for (let i = source.length - 1; i >= 0; i -= 1) {
    const size = JSON.stringify(source[i] || {}).length;
    if (kept.length >= 4 && used + size > maxChars) break;
    kept.unshift(source[i]);
    used += size;
  }
  return kept;
}

function buildConversationStateForLLM(state) {
  // RELEVANCE_MEMORY_PLANNING_V5
  // Preserve recent context plus turn references already selected by the
  // question-memory relevance graph. No domain term, tag, threshold, test ID,
  // or fixed question is used to choose history.
  // CONVERSATION_ARCHIVE_V7：关联轮次从完整存档里挑（挑选规则与上限不变）
  const allTurns = (asArray(state.turn_archive).length ? asArray(state.turn_archive) : asArray(state.turns));
  const allQuestionCards = normalizeQuestionMemoryCards(state.question_memory_cards);
  // DIRECT_QUESTION_EDGE_MEMORY_V5
  // Follow only the latest card's explicit relevance edges. Expanding edges
  // from several recent cards reintroduced the entire conversation graph.
  const recentQuestionCards = allQuestionCards.slice(-1);
  const relevantTurnRefs = new Set(
    allTurns.slice(-2).map(turn => String(turn?.turn_ref || '')).filter(Boolean)
  );
  for (const card of recentQuestionCards) {
    const ownTurnRef = String(card?.internal?.turn_ref || card?.turn_ref || '').trim();
    if (ownTurnRef) relevantTurnRefs.add(ownTurnRef);
    for (const edge of asArray(card?.related_questions).slice(0, 6)) {
      const turnRef = String(edge?.internal?.turn_ref || edge?.turn_ref || '').trim();
      if (turnRef) relevantTurnRefs.add(turnRef);
    }
  }

  const selectedTurns = allTurns
    .filter(turn => relevantTurnRefs.has(String(turn?.turn_ref || '')))
    .slice(-6);
  const turns = selectedTurns.map(t => ({
    turn_ref: t.turn_ref || null,
    ts: t.ts || null,
    user_question: String(t.user_question || '').slice(0, 400),
    resolved_question: String(t.resolved_question || '').slice(0, 600),
    assistant_answer: String(t.assistant_answer || '').slice(0, 650),
    answer_mode: t.answer_mode || '',
    evidence_count: Number(t.evidence_count || 0)
  }));

  const selectedQuestionCards = allQuestionCards
    .filter(card => {
      const turnRef = String(card?.internal?.turn_ref || card?.turn_ref || '');
      return relevantTurnRefs.has(turnRef);
    })
    .slice(-6);
  const questionCards = selectedQuestionCards.map(card => ({
    current_question: card.current_question,
    resolved_question: card.resolved_question,
    current_answer_summary: String(card.current_answer_summary || '').slice(0, 350),
    status: card.status,
    entities: asArray(card.entities).slice(0, 16),
    missing_requirements: asArray(card.missing_requirements).slice(0, 8),
    data_analysis_results: asArray(card.data_analysis_results).slice(0, 6),
    related_questions: asArray(card.related_questions).slice(0, 4).map(edge => ({
      question: edge?.question,
      relation: edge?.relation,
      relevance: edge?.relevance,
      internal: edge?.internal || {}
    })),
    internal: card.internal || {}
  }));

  const factCards = asArray(state.fact_cards)
    .filter(card => {
      const sourceTurn = String(card?.source_turn || '');
      const confirmedEvent =
        String(card?.status || '').toLowerCase() === 'confirmed' &&
        String(card?.entity_type || '').toLowerCase() === 'event';
      return relevantTurnRefs.has(sourceTurn) || confirmedEvent;
    })
    .slice(-22)
    .map(card => ({
      fact_id: card.fact_id,
      source_turn: card.source_turn,
      subject: card.subject,
      relation: card.relation,
      value: card.value,
      status: card.status,
      entity_type: card.entity_type,
      entities: asArray(card.entities).slice(0, 10),
      numbers: asArray(card.numbers).slice(0, 10),
      evidence_ids: asArray(card.evidence_ids).slice(0, 8),
      note: String(card.note || '').slice(0, 240)
    }));

  const topics = normalizeTopicSummaries(state.topic_summaries);
  return {
    turns,
    fact_cards: factCards,
    topic_summaries: Object.fromEntries(Object.entries(topics).slice(-6)),
    question_memory_cards: questionCards,
    // ARCTIC_REGISTRY_IN_LLM_MEMORY_V5
    arctic_target_registry: normalizeArcticTargetRegistry(state.arctic_target_registry)
      .slice(-80)
      .map(item => ({
        tag: item.tag,
        library: item.library,
        symbol: item.symbol,
        count: item.count,
        data_status: item.data_status,
        time_range: item.time_range,
        desc_cn: item.desc_cn,
        desc_en: item.desc_en,
        process_factor: item.process_factor,
        source_turn: item.source_turn
      })),
    event_status: state.event_status || null,
    latest_topic: state.latest_topic || '',
    latest_resolved_question: state.latest_resolved_question || '',
    compression: {
      strategy: 'recent_plus_question_graph',
      full_turn_count: allTurns.length,
      supplied_turn_count: turns.length,
      full_fact_count: asArray(state.fact_cards).length,
      supplied_fact_count: factCards.length,
      full_question_card_count: allQuestionCards.length,
      supplied_question_card_count: questionCards.length
    }
  };
}

function normalizeConversationState(raw) {
  const base = defaultConversationState();
  const obj = raw && typeof raw === "object" && !Array.isArray(raw) ? raw : base;

  return {
    turns: trimTurnsToMemoryBudget(asArray(obj.turns)
      .filter(t => t && typeof t === "object" && !Array.isArray(t))),
    turn_archive: asArray(obj.turn_archive).filter(t => t && typeof t === "object" && !Array.isArray(t)), // CONVERSATION_ARCHIVE_V7
    answer_fact_index: normalizeFactIndex(obj.answer_fact_index),
    fact_cards: normalizeFactCards(obj.fact_cards),
    topic_summaries: normalizeTopicSummaries(obj.topic_summaries),
    entity_index: normalizeEntityIndex(obj.entity_index),
    question_memory_cards: normalizeQuestionMemoryCards(obj.question_memory_cards),
    arctic_target_registry: normalizeArcticTargetRegistry(obj.arctic_target_registry),
    threshold_registry: (obj.threshold_registry && typeof obj.threshold_registry === 'object' && !Array.isArray(obj.threshold_registry)) ? obj.threshold_registry : {}, // THRESHOLD_REGISTRY_V7
    alarm_table_majority: (obj.alarm_table_majority && typeof obj.alarm_table_majority === 'object' && !Array.isArray(obj.alarm_table_majority)) ? obj.alarm_table_majority : {}, // ALARM_TABLE_MAJORITY_V7
    exceedance_episodes: Array.isArray(obj.exceedance_episodes) ? obj.exceedance_episodes : [], // EXCEEDANCE_EPISODES_STATE_V7：越限时段随状态透传，供后续轮次做关联变量扫描
    turn_counter: Number(obj.turn_counter) || 0, // TURN_COUNTER_V7
    event_status: obj.event_status && typeof obj.event_status === 'object' && !Array.isArray(obj.event_status) ? obj.event_status : null,
    latest_topic: asString(obj.latest_topic),
    latest_resolved_question: asString(obj.latest_resolved_question),
    latest_device_context: asObject(obj.latest_device_context),
    updated_at: obj.updated_at || null
  };
}

// STAGE_CONTEXT_AND_TIMESERIES_ANALYSIS_V5
// Decomposition and planning need semantic memory, not every stored field.
// Apply a character budget while preserving newest graph-linked items. This is
// adaptive to content size and does not encode a fixed number of turns.
function stageConversationState(memory, maxChars) {
  const source = memory && typeof memory === 'object' ? memory : {};
  const compact = {
    latest_topic: source.latest_topic || '',
    latest_resolved_question: source.latest_resolved_question || '',
    event_status: source.event_status || null,
    topic_summaries: source.topic_summaries || {},
    question_memory_cards: [],
    fact_cards: [],
    turns: [],
    arctic_target_registry: [],
    compression: {
      strategy: 'stage_character_budget',
      max_chars: maxChars
    }
  };

  function addNewest(field, values) {
    const rows = Array.isArray(values) ? values.slice().reverse() : [];
    for (const row of rows) {
      const candidate = [row, ...compact[field]];
      const next = { ...compact, [field]: candidate };
      if (JSON.stringify(next).length > maxChars) continue;
      compact[field] = candidate;
    }
  }

  // REGISTRY_BUDGET_AND_ANAPHORIC_REUSE_V5
  // Reserve a proportional character budget for dynamic historian mappings.
  // This remains content-budgeted rather than round-count-limited.
  const registryBudget = Math.max(1800, Math.floor(maxChars * 0.32));
  let registryChars = 2;
  const reservedRegistry = [];
  for (const row of (Array.isArray(source.arctic_target_registry)
    ? source.arctic_target_registry.slice().reverse()
    : [])) {
    const size = JSON.stringify(row).length + 1;
    if (registryChars + size > registryBudget) continue;
    reservedRegistry.unshift(row);
    registryChars += size;
  }
  compact.arctic_target_registry = reservedRegistry;
  addNewest('question_memory_cards', source.question_memory_cards);
  addNewest('fact_cards', source.fact_cards);
  addNewest('turns', source.turns);
  compact.compression.supplied_chars = JSON.stringify(compact).length;
  return compact;
}

function compactCatalogForLLM(catalog) {
  const source = catalog && typeof catalog === 'object' ? catalog : {};
  const mongo = source.mongodb && typeof source.mongodb === 'object'
  ? source.mongodb
  : {};
  const ragflow = source.ragflow && typeof source.ragflow === 'object'
    ? source.ragflow
    : {};
  const postgres = source.postgres && typeof source.postgres === 'object'
    ? source.postgres
    : {};
  const neo4j = source.neo4j && typeof source.neo4j === 'object'
    ? source.neo4j
    : {};
  return {
    updated_at: source.updated_at || null,
    ragflow: {
      available: ragflow.available === true,
      datasets: asArray(ragflow.datasets).map(dataset => ({
        id: dataset?.id,
        name: dataset?.name,
        language: dataset?.language,
        is_searchable: dataset?.is_searchable !== false
      }))
    },
mongodb: {
  available: mongo.available === true,
  default_target: mongo.default_target || null,
  databases_of_interest: asArray(mongo.databases_of_interest),
  all_databases: asArray(mongo.all_databases),
  catalog: mongo.catalog || {},
  tools: asArray(mongo.tools)
    .filter(tool => typeof tool === 'string' || tool?.deprecated !== true)
    .map(tool =>
      typeof tool === 'string' ? tool : (tool?.name || tool?.tool)
    )
    .filter(Boolean),
  target_resolution_source: mongo.target_resolution_source || null
},
    postgres: {
      available: postgres.available === true,
      has_tables: postgres.has_tables === true,
      tables: asArray(postgres.tables)
    },
    neo4j: {
      available: neo4j.available === true,
      schema_raw: neo4j.available === true
        ? String(neo4j.schema_raw || '').slice(0, 12000)
        : null
    },
    computation_tools: {
      available: source.computation_tools?.available === true,
      tools: asArray(source.computation_tools?.tools).map(tool =>
        typeof tool === 'string' ? tool : tool?.name
      ).filter(Boolean)
    },
    tools: source.tools || {}
  };
}

function getLoadedConversationState() {
  const loaded = nodeJson('Load Conversation State');
  const candidates = [
    loaded.propertyName,
    loaded.value,
    loaded.data,
    loaded.result,
    loaded.output,
    loaded.conversation_state,
    $json.propertyName,
    $json.value,
    $json.data,
    $json.result,
    $json.output,
    $json.conversation_state
  ];

  for (const candidate of candidates) {
    const parsed = safeParse(candidate);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed) && (Array.isArray(parsed.turns) || parsed.latest_topic || parsed.latest_resolved_question)) {
      return parsed;
    }
  }

  return defaultConversationState();
}

return items.map((item) => {
  const j = item.json ?? {};
  const wf = nodeJson('Workflow Configuration');
  const chat = nodeJson('When chat message received');
  const catalogNode = nodeJson('Catalog');

  const originalUserMessage = pickFirst(
    wf.chatInput,
    chat.chatInput,
    j.chatInput,
    j.question,
    j.form?.question,
    j.raw?.chatInput,
    wf["What is your question"],
    j["What is your question"]
  );

  const chatSessionId = pickFirst(
    wf.sessionId,
    wf.request_id,
    chat.sessionId,
    j.sessionId,
    j.request_id,
    j.raw?.sessionId,
    j.form?.request_id
  );

  const sessionKey = chatSessionId || "default";
  const convKey = `conversation_state:${sessionKey}`;
  const conversationState = normalizeConversationState(getLoadedConversationState());
  const targetLanguage = /[\u4e00-\u9fff]/.test(originalUserMessage) ? 'zh' : 'en';
  const conversationStateForLLM = buildConversationStateForLLM(conversationState);
  const catalog = catalogNode.catalog || j.catalog || {};
  const stageMemory = stageConversationState(conversationStateForLLM, 14000);

  return {
    json: {
      ...j,
      catalog,
      latest_device_context: asObject(conversationState.latest_device_context),
      catalog_for_llm: compactCatalogForLLM(catalog),
      originalUserMessage,
      chatSessionId,
      target_language: targetLanguage,
      health: catalogNode.health || j.health || {},
      catalog_status: catalogNode.catalog_status || j.catalog_status || {},
      conversation_state_key: convKey,
      conversation_state: conversationState,
      conversation_state_for_llm: conversationStateForLLM,
      conversation_state_for_decompose: stageMemory,
      conversation_state_for_planner: stageConversationState(conversationStateForLLM, 12000),
      conversation_state_debug: {
        source: 'redis',
        key: convKey,
        turn_count: conversationState.turns.length,
        latest_topic: conversationState.latest_topic,
        latest_resolved_question: conversationState.latest_resolved_question,
        fact_card_count: conversationState.fact_cards.length,
        topic_count: Object.keys(conversationState.topic_summaries).length,
        arctic_target_count: conversationState.arctic_target_registry.length,
        latest_arctic_targets: conversationState.arctic_target_registry.slice(-12).map(x => ({
          tag: x.tag,
          library: x.library,
          symbol: x.symbol,
          count: x.count,
          data_status: x.data_status
        }))
      }
    },
  };
});

