// MONGODB_CATALOG_PUBLIC_CONTRACT_V1
// Accept legacy MCP/cache shapes during rollout, but publish only the canonical
// MongoDB catalog contract to planners, executors, health checks, and caches.
const MONGO_TO_INTERNAL_TOOL = Object.freeze({
  mongo_find_tags: 'arctic_find_tags',
  mongo_resolve_factors: 'arctic_resolve_factors',
  mongo_read: 'arctic_read',
  mongo_stats: 'arctic_stats',
  mongo_analyze: 'arctic_analyze',
  mongo_describe: 'arctic_describe'
});
const INTERNAL_TO_MONGO_TOOL = Object.freeze(
  Object.fromEntries(Object.entries(MONGO_TO_INTERNAL_TOOL).map(([mongo, internal]) => [internal, mongo]))
);

function catalogContractKey(key, direction) {
  if (direction === 'internal') {
    if (MONGO_TO_INTERNAL_TOOL[key]) return MONGO_TO_INTERNAL_TOOL[key];
    const aliases = {
      mongodb: 'arcticdb',
      mongodb_tools: 'arctic_tools',
      database: 'library',
      collection: 'symbol',
      databases: 'libraries',
      collections: 'symbols',
      all_databases: 'all_libraries',
      databases_of_interest: 'libraries_of_interest',
      collection_glossary: 'symbol_glossary',
      database_count: 'library_count'
    };
    return aliases[key] || key;
  }
  if (INTERNAL_TO_MONGO_TOOL[key]) return INTERNAL_TO_MONGO_TOOL[key];
  const aliases = {
    arcticdb: 'mongodb',
    arctic_tools: 'mongodb_tools',
    library: 'database',
    symbol: 'collection',
    libraries: 'databases',
    symbols: 'collections',
    all_libraries: 'all_databases',
    libraries_of_interest: 'databases_of_interest',
    symbol_glossary: 'collection_glossary',
    library_count: 'database_count'
  };
  return aliases[key] || key;
}

function replaceCatalogVocabulary(value, direction) {
  let out = String(value == null ? '' : value);
  const replacements = direction === 'internal'
    ? { ...MONGO_TO_INTERNAL_TOOL, 'MongoDB Time-Series API': 'ArcticDB API', MongoDB: 'ArcticDB', mongodb_: 'arctic_', mongodb: 'arcticdb' }
    : { ...INTERNAL_TO_MONGO_TOOL, 'ArcticDB API': 'MongoDB Time-Series API', ArcticDB: 'MongoDB', arctic_: 'mongodb_', arcticdb: 'mongodb' };
  for (const [from, to] of Object.entries(replacements)) {
    out = out.replace(new RegExp(`\\b${from}`, 'g'), to);
  }
  return out;
}

function translateCatalogContract(value, direction) {
  if (Array.isArray(value)) return value.map(v => translateCatalogContract(v, direction));
  if (typeof value === 'string') return replaceCatalogVocabulary(value, direction);
  if (!value || typeof value !== 'object') return value;
  const out = {};
  for (const [key, child] of Object.entries(value)) {
    out[catalogContractKey(key, direction)] = translateCatalogContract(child, direction);
  }
  return out;
}

function toInternalCatalogContract(value) {
  return translateCatalogContract(value, 'internal');
}

function toPublicMongoCatalogContract(value) {
  return translateCatalogContract(value, 'public');
}

const inputItems = $input.all().map(i => toInternalCatalogContract(i.json ?? {}));

// SHARED_CATALOG_CACHE_V5
let sharedCatalogCacheRecord = inputItems.find(x => x?.__catalog_cache_hit === true)?.catalog_cache_record || null;
if (!sharedCatalogCacheRecord) {
  try {
    const probe = toInternalCatalogContract($('Validate Shared Catalog Cache').first().json || {});
    sharedCatalogCacheRecord = probe.__catalog_cache_usable ? probe.catalog_cache_record : null;
  } catch {}
}

// 鈥斺€?small helpers 鈥斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€擻n
function isPlainObject(v) {
  return !!v && typeof v === "object" && !Array.isArray(v);
}

function asString(v) {
  return typeof v === "string" ? v.trim() : "";
}

function dedupeStrings(arr) {
  return Array.from(
    new Set(
      (Array.isArray(arr) ? arr : [])
        .map(v => (typeof v === "string" ? v.trim() : ""))
        .filter(Boolean)
    )
  );
}

// 鈥斺€?Unwrappers 鈥斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€擻n
function isTimeSeriesToolingPayload(obj) {
  if (!obj || typeof obj !== "object" || Array.isArray(obj)) return false;

  const serviceName = obj?.service?.name ?? obj?.service;
  const backend = typeof obj?.service?.backend === "string"
    ? obj.service.backend.toLowerCase()
    : "";

  const hasReadTool =
    Array.isArray(obj?.tools) &&
    obj.tools.some(
      (t) =>
        t?.path === "/read" ||
        t?.name === "arctic_read" ||
        t?.name === "mongo_read"
    );

  return (
    Array.isArray(obj?.tools) &&
    (
      serviceName === "ArcticDB API" ||
      serviceName === "MongoDB Time-Series API" ||
      backend === "mongodb" ||
      (isPlainObject(obj?.catalog) && hasReadTool)
    )
  );
}

function unwrapArcticContent(obj) {
  // Support direct payloads and n8n MCP wrappers using structuredContent.
  const directCandidates = [obj?.structuredContent, obj];

  for (const candidate of directCandidates) {
    if (!candidate || typeof candidate !== "object" || Array.isArray(candidate)) continue;
    if (Array.isArray(candidate.libraries)) return candidate;
    if (isTimeSeriesToolingPayload(candidate)) return candidate;
  }

  const content = obj?.content;
  if (!Array.isArray(content)) return null;

  for (const c of content) {
    let t = c?.text;
    // text may arrive as a JSON string; parse it.
    if (typeof t === "string") {
      try { t = JSON.parse(t); } catch { t = null; }
    }
    if (!t || typeof t !== "object" || Array.isArray(t)) continue;
    if (Array.isArray(t.libraries)) return t;
    if (isTimeSeriesToolingPayload(t)) return t;
  }

  return null;
}

function unwrapComputationTools(obj) {
  const candidates = [];

  if (obj?.structuredContent) candidates.push(obj.structuredContent);

  const content = obj?.content;
  if (Array.isArray(content)) {
    for (const c of content) {
      let t = c?.text;
      if (typeof t === "string") {
        try { t = JSON.parse(t); } catch { t = null; }
      }
      if (t) candidates.push(t);
    }
  }

  for (const candidate of candidates) {
    if (!candidate || typeof candidate !== "object" || Array.isArray(candidate)) continue;
    if (!Array.isArray(candidate.tools)) continue;

    // Time-series tooling belongs to arcticdb/MongoDB, not computation_tools.
    if (isTimeSeriesToolingPayload(candidate)) continue;

    return candidate.tools;
  }

  return null;
}

function pickNeo4j(obj) {
  if (hasNodeError(obj)) return false;
  const content = obj?.content;
  if (!Array.isArray(content)) return false;

  return content.some((c) => {
    const t = c?.text;
    if (!Array.isArray(t) || t.length === 0) return false;
    const first = t[0];
    return (
      typeof first?.key === "string" &&
      (first?.value?.type === "node" || first?.value?.type === "relationship")
    );
  });
}

function hasNodeError(obj) {
  if (!obj || typeof obj !== "object") return false;
  if (obj.error) return true;
  if (obj.message && /could not connect|connection|timeout|mcp server/i.test(String(obj.message))) return true;
  const content = obj?.content;
  if (!Array.isArray(content)) return false;
  return content.some((c) => {
    const t = typeof c?.text === "string" ? c.text : "";
    return /could not connect|connection|timeout|mcp server/i.test(t);
  });
}

function pickPostgres(obj) {
  if (hasNodeError(obj)) return false;
  const content = obj?.content;
  if (!Array.isArray(content)) return false;

  return content.some(
    (c) =>
      typeof c?.text === "string" &&
      c.text.toLowerCase().includes("list of tables")
  );
}

function pickRagflowDatasets(obj) {
  return Array.isArray(obj?.datasets) && Array.isArray(obj?.dataset_names);
}

function pickArcticTooling(obj) {
  return unwrapArcticContent(obj) !== null;
}

function pickComputationTools(obj) {
  return unwrapComputationTools(obj) !== null;
}

// 鈥斺€?ArcticDB helpers 鈥斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€斺€擻n
function getArcticBaseUrl(arctic) {
  const base = arctic?.service?.base_url ?? arctic?.base_url ?? null;
  return typeof base === "string" && base.length ? base.replace(/\/$/, "") : null;
}

function getArcticLibrariesOfInterest(arctic) {
  // 鍙俊鏄惧紡鎻愪緵鐨?libraries_of_interest锛涗笉瑕佸啀榛樿 OPC / Office
  const loi = dedupeStrings(arctic?.libraries_of_interest);
  if (loi.length) return loi;

  const singleLib = asString(arctic?.library);
  if (singleLib) return [singleLib];

  return [];
}

function getArcticTools(arctic) {
  if (Array.isArray(arctic?.tools)) return arctic.tools;

  const endpoints = arctic?.endpoints ?? null;
  if (!endpoints || typeof endpoints !== "object") return [];

  return Object.entries(endpoints).map(([key, val]) => ({
    name: `arctic_${key}`,
    method: val?.method,
    path: val?.path,
    description: val?.description,
    inputs: val?.body_schema ?? {},
  }));
}

function getArcticGlossary(arctic) {
  return arctic?.Glossary ?? arctic?.symbol_glossary ?? null;
}

function getArcticAllLibraries(arctic) {
  const fromLibraries = dedupeStrings(arctic?.libraries);
  const fromCatalogKeys =
    isPlainObject(arctic?.catalog) ? Object.keys(arctic.catalog).map(s => s.trim()).filter(Boolean) : [];
  const singleLib = asString(arctic?.library);

  return dedupeStrings([
    ...fromLibraries,
    ...fromCatalogKeys,
    ...(singleLib ? [singleLib] : []),
  ]);
}

function normalizeArcticCatalogEntry(entry) {
  // 鏀寔:
  // 1) ["sym1", "sym2"]
  // 2) { symbols: ["sym1", "sym2"], ... }
  // 3) 鍏朵粬 object 鍘熸牱淇濈暀锛屼絾灏介噺琛?symbols
  if (Array.isArray(entry)) {
    return {
      symbols: dedupeStrings(entry),
    };
  }

  if (isPlainObject(entry)) {
    const out = { ...entry };
    if (Array.isArray(out.symbols)) {
      out.symbols = dedupeStrings(out.symbols);
    } else {
      out.symbols = [];
    }
    return out;
  }

  return { symbols: [] };
}

function buildNormalizedArcticCatalog(arctic) {
  const normalized = {};

  // 1) 鍏堝惛鏀跺師濮?catalog
  const rawCatalog = isPlainObject(arctic?.catalog) ? arctic.catalog : {};
  for (const [lib, entry] of Object.entries(rawCatalog)) {
    const libName = asString(lib);
    if (!libName) continue;
    normalized[libName] = normalizeArcticCatalogEntry(entry);
  }

  // 2) 鐢?all_libraries / libraries / single library 琛ラ綈缂哄け鐨?library key
  for (const lib of getArcticAllLibraries(arctic)) {
    if (!normalized[lib]) normalized[lib] = { symbols: [] };
  }

  // 3) 濡傛灉 payload 閲屾湁鏄庣‘鐨?library + symbol锛岃ˉ杩涘幓
  const singleLib = asString(arctic?.library);
  const singleSym = asString(arctic?.symbol);

  if (singleLib) {
    if (!normalized[singleLib]) normalized[singleLib] = { symbols: [] };
    if (singleSym) {
      normalized[singleLib].symbols = dedupeStrings([
        ...(normalized[singleLib].symbols || []),
        singleSym,
      ]);
    }
  }

  return normalized;
}

function getArcticCatalogFocused(arctic) {
  const normalizedCatalog = buildNormalizedArcticCatalog(arctic);
  const libs = getArcticLibrariesOfInterest(arctic);

  // 娌℃湁鏄惧紡 LOI锛屽氨鐩存帴杩斿洖瀹屾暣 catalog
  if (!libs.length) return normalizedCatalog;

  const focused = {};
  for (const lib of libs) {
    if (normalizedCatalog[lib]) {
      focused[lib] = normalizedCatalog[lib];
    }
  }

  // 濡傛灉鎸?LOI 杩囨护鍚庝负绌猴紝灏卞洖閫€鍒板畬鏁?catalog
  return Object.keys(focused).length ? focused : normalizedCatalog;
}

