function extractPostgresTables(pgJson) {
  if (!pgJson) return [];
  if (Array.isArray(pgJson.tables)) return pgJson.tables;

  const content = pgJson?.content ?? [];
  for (const entry of content) {
    const t = entry?.text;
    if (typeof t === "string" && t.trimStart().startsWith("[")) {
      try {
        return JSON.parse(t);
      } catch {}
    }
  }

  return [];
}

const pgTables = extractPostgresTables(pgRaw);


