// CONFIGURED_ARCTIC_TARGET_ROUTING_V5
function configuredArcticTarget() {
  const target = workflowRunParams()?.arcticdb?.default_target;
  const library = asString(target?.library);
  const symbol = asString(target?.symbol);
  return library && symbol ? { library, symbol } : null;
}

function arcticTargetExists(arctic, target) {
  if (!target || !isPlainObject(arctic)) return false;
  const libraries = dedupeStrings([
    ...(Array.isArray(arctic.all_libraries) ? arctic.all_libraries : []),
    ...(Array.isArray(arctic.libraries_of_interest) ? arctic.libraries_of_interest : []),
    ...Object.keys(isPlainObject(arctic.catalog) ? arctic.catalog : {})
  ]);
  if (!libraries.includes(target.library)) return false;
  const entry = isPlainObject(arctic.catalog) ? arctic.catalog[target.library] : null;
  const symbols = Array.isArray(entry)
    ? dedupeStrings(entry)
    : dedupeStrings(Array.isArray(entry?.symbols) ? entry.symbols : []);
  return symbols.length === 0 || symbols.includes(target.symbol);
}

function applyConfiguredArcticTarget(catalogObject) {
  const configured = configuredArcticTarget();
  const arctic = catalogObject?.arcticdb;
  if (!configured || !arcticTargetExists(arctic, configured)) return catalogObject;
  arctic.default_target = configured;
  arctic.target_resolution_source = "workflow_configuration_catalog_validated";
  arctic.libraries_of_interest = dedupeStrings([
    configured.library,
    ...(Array.isArray(arctic.libraries_of_interest) ? arctic.libraries_of_interest : [])
  ]);
  return catalogObject;
}

