    return {
      available: true,
      base_url: getArcticBaseUrl(arctic),
      libraries_of_interest: librariesOfInterest,
      all_libraries: allLibraries,
      catalog: Object.keys(focusedCatalog).length ? focusedCatalog : normalizedCatalog,
