};

if (Object.values(health.sources).some(s => s.status === "unavailable")) {
  health.overall = Object.values(health.sources).some(s => s.status === "ok") ? "degraded" : "failed";
}

let catalog_status = {
  cache: "disabled",
  cache_key: cacheKey,
  age_sec: null,
  ttl_sec: cacheTtlSec,
  stale_used: false
};

if (cacheEnabled) {
  const usable = catalogLooksUsable(catalog);
  const cacheAgeSec = cached?.cached_at ? Math.round((nowMs - Number(cached.cached_at)) / 1000) : null;
  const cacheFresh = cached?.catalog && cacheAgeSec != null && cacheAgeSec <= cacheTtlSec;

  if (usable) {
    sd[cacheKey] = {
      cached_at: nowMs,
      catalog,
      health
    };
    catalog_status = {
      ...catalog_status,
      cache: cached ? "refresh" : "miss",
      age_sec: 0
    };
  } else if (cached?.catalog && (cacheFresh || cacheCfg.allow_stale !== false)) {
    catalog = cached.catalog;
    health.overall = "degraded";
    health.cache_fallback = true;
    catalog_status = {
      ...catalog_status,
      cache: cacheFresh ? "hit_after_refresh_failed" : "refresh_failed_using_stale",
      age_sec: cacheAgeSec,
      stale_used: !cacheFresh
    };
  } else {
    catalog_status = {
      ...catalog_status,
      cache: "miss_unusable",
      age_sec: cacheAgeSec
    };
  }
}

