// SHARED_CATALOG_CACHE_V5: expose one portable Redis record without changing the catalog payload.
const sharedCachedAt = sharedCatalogCacheHit
  ? Number(sharedCatalogCacheRecord?.cached_at || Date.now())
  : Date.now();
const sharedCatalogStatus = {
  cache: sharedCatalogCacheHit ? 'hit' : 'refresh',
  age_sec: sharedCatalogCacheHit ? Math.max(0, Math.round((Date.now() - sharedCachedAt) / 1000)) : 0,
  ttl_sec: cacheTtlSec,
  key: 'fcc:catalog_cache:v5'
};
catalog_status.shared = sharedCatalogStatus;
// NO_EMPTY_CATALOG_WRITEBACK_V6
// A refresh where every source came back unavailable must not overwrite a good
// cached catalog: that single bad write poisons every later turn for the whole
// TTL (0 dataset ids -> Match Tools NO_MATCH -> direct_response -> no retrieval).
function __catalogResourceIdCount(node) {
  const ids = JSON.stringify(node || {}).match(/[0-9a-f]{24,34}/g) || [];
  return new Set(ids).size;
}
const __freshCatalogIds = __catalogResourceIdCount(catalog);
const __priorCatalogIds = __catalogResourceIdCount(
  sharedCatalogCacheRecord && sharedCatalogCacheRecord.catalog);
// STALE_PRESERVE_REFRESHES_TIMESTAMP_V6b
// Preserving the prior catalog is right, but keeping its ORIGINAL cached_at made
// the record permanently stale: every turn then failed the freshness check and
// forced another full refresh, which piled load onto the very MCP servers whose
// failure caused the empty catalog. Keep the content, restamp the time.
const catalog_cache_record = (__freshCatalogIds === 0 && __priorCatalogIds > 0)
  ? { ...sharedCatalogCacheRecord, cached_at: sharedCachedAt, stale_preserved: true }
  : { cached_at: sharedCachedAt, catalog, health };
return [{
  json: toPublicMongoCatalogContract({
    form,
    catalog,
    health,
    catalog_status,
    catalog_cache_record
  })
}];

// n8n Code node: preserve dataset metadata for downstream routing
// Input: RagFlow /api/v1/datasets response { code: 0, data: [...] }
// Output:
// {
//   datasets: [
//     { id, name, language, chunk_count, document_count, token_num, is_searchable }
//   ],
//   dataset_names: [...],
//   dataset_ids: [...],
//   searchable_dataset_ids: [...],
//   searchable_dataset_names: [...]
// }

const data = Array.isArray($json?.data) ? $json.data : [];

function toInt(v, fallback = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

const datasets = data
  .map(d => {
    const id = d?.id ?? null;
    const name = d?.name ?? null;
    const language = d?.language ?? null;
    const chunk_count = toInt(d?.chunk_count, 0);
    const document_count = toInt(d?.document_count, 0);
    const token_num = toInt(d?.token_num, 0);

    const is_searchable =
      !!id &&
      !!name &&
      name !== 'Test' &&
      chunk_count > 0 &&
      token_num > 0;

    return {
      id,
      name,
      language,
      chunk_count,
      document_count,
      token_num,
      is_searchable,
    };
  })
  .filter(d => d.id && d.name);

const dataset_names = datasets.map(d => d.name);
const dataset_ids = datasets.map(d => d.id);

const searchable = datasets.filter(d => d.is_searchable);
const searchable_dataset_ids = searchable.map(d => d.id);
const searchable_dataset_names = searchable.map(d => d.name);

return [
  {
    json: {
      datasets,
      dataset_names,
      dataset_ids,
      searchable_dataset_ids,
      searchable_dataset_names,
    },
  },
];

