function asArray(x) {
  return Array.isArray(x) ? x : [];
}

function asObject(x) {
  return x && typeof x === 'object' && !Array.isArray(x) ? x : {};
}

function isRuntimeRef(x) {
  return typeof x === 'string' && /^\$ref:step_?\d+\.[A-Za-z0-9_]+$/.test(x.trim());
}

function extractKnownArcticLibraries(arcticdb) {
  const out = new Set();

  const allLibraries = asArray(arcticdb?.all_libraries);
  for (const lib of allLibraries) {
    if (typeof lib === 'string' && lib.trim()) out.add(lib.trim());
  }

  const arcCat = asObject(arcticdb?.catalog);
  for (const lib of Object.keys(arcCat)) {
    if (typeof lib === 'string' && lib.trim()) out.add(lib.trim());
  }

  return out;
}

function extractKnownArcticSymbolsForLibrary(arcticdb, library) {
  const arcCat = asObject(arcticdb?.catalog);
  const entry = arcCat?.[library];

  if (!entry) return [];

