function extractJsonObject(s) {
  if (s && typeof s === 'object' && !Array.isArray(s)) return s;
  if (typeof s !== 'string') return {};

  const cleaned = s.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  try { return JSON.parse(cleaned); } catch {}

  // STRUCTURED_ANALYSIS_INTEGRITY_V5
  // Tool agents can serialize a valid structured result while leaving literal
  // line breaks inside a JSON string field such as `answer`. Escape only
  // control characters encountered inside quoted strings, then parse the full
  // object. This preserves every computed array instead of falling back to a
  // prose-only recovery.
  function escapeControlCharactersInsideStrings(text) {
    let out = '';
    let quoted = false;
    let escaped = false;
    for (let i = 0; i < text.length; i += 1) {
      const ch = text[i];
      if (!quoted) {
        out += ch;
        if (ch === '"') quoted = true;
        continue;
      }
      if (escaped) {
        out += ch;
        escaped = false;
        continue;
      }
      if (ch === '\\') {
        out += ch;
        escaped = true;
        continue;
      }
      if (ch === '"') {
        out += ch;
        quoted = false;
        continue;
      }
      if (ch === '\n') {
        out += '\\n';
        continue;
      }
      if (ch === '\r') {
        out += '\\r';
        continue;
      }
      if (ch === '\t') {
        out += '\\t';
        continue;
      }
      out += ch;
    }
    return out;
  }

  try { return JSON.parse(escapeControlCharactersInsideStrings(cleaned)); } catch {}

  function repairBareQuotes(text) {
    let out = '';
    let quoted = false;
    let escaped = false;
    for (let i = 0; i < text.length; i += 1) {
      const ch = text[i];
      if (!quoted) {
        out += ch;
        if (ch === '"') quoted = true;
        continue;
      }
      if (escaped) { out += ch; escaped = false; continue; }
      if (ch === '\\') { out += ch; escaped = true; continue; }
      if (ch !== '"') { out += ch; continue; }
      let j = i + 1;
      while (j < text.length && /\s/.test(text[j])) j += 1;
      if (!text[j] || /[,}\]:]/.test(text[j])) { out += ch; quoted = false; }
      else out += '\\"';
    }
    return out;
  }

  const fenced = /```(?:json)?\s*([\s\S]*?)```/i.exec(cleaned);
  const candidates = [];
  if (fenced?.[1]) candidates.push(fenced[1].trim());
  const first = cleaned.indexOf('{');
  const last = cleaned.lastIndexOf('}');
  if (first >= 0 && last > first) candidates.push(cleaned.slice(first, last + 1));
  for (const candidate of candidates.sort((a, b) => b.length - a.length)) {
    try { return JSON.parse(candidate); } catch {}
    try { return JSON.parse(repairBareQuotes(candidate)); } catch {}
  }
  return {};
}

// MONGODB_RESULT_NORMALIZER_BOUNDARY_V1
// Keep the mature normalization/recovery implementation stable internally,
// but accept and emit only the public MongoDB historian contract.
const MONGO_TO_INTERNAL_TOOL = Object.freeze({
  mongo_find_tags: 'arctic_find_tags',
  mongo_resolve_factors: 'arctic_resolve_factors',
  mongo_read: 'arctic_read',
  mongo_stats: 'arctic_stats',
  mongo_analyze: 'arctic_analyze',
  mongo_describe: 'arctic_describe'
});
const INTERNAL_TO_MONGO_TOOL = Object.freeze(
  Object.fromEntries(Object.entries(MONGO_TO_INTERNAL_TOOL).map(([mongo, internal]) => [internal, mongo]))
);

function replaceContractVocabulary(value, replacements) {
  let out = String(value == null ? '' : value);
  for (const [from, to] of Object.entries(replacements)) {
    out = out.replace(new RegExp(`\\b${from}\\b`, 'g'), to);
  }
  return out;
}

function toInternalContractKey(key) {
  if (MONGO_TO_INTERNAL_TOOL[key]) return MONGO_TO_INTERNAL_TOOL[key];
  if (key.startsWith('mongo_analyze_')) return key.replace(/^mongo_analyze_/, 'arctic_analyze_');
  if (key === 'mongodb_target_registry') return 'arctic_target_registry';
  if (key === 'mongodb') return 'arcticdb';
  return key;
}

function toPublicMongoContractKey(key) {
  if (INTERNAL_TO_MONGO_TOOL[key]) return INTERNAL_TO_MONGO_TOOL[key];
  if (key.startsWith('arctic_analyze_')) return key.replace(/^arctic_analyze_/, 'mongo_analyze_');
  if (key === 'arctic_target_registry') return 'mongodb_target_registry';
  if (key === 'arcticdb') return 'mongodb';
  return key;
}

function toInternalContractDeep(value) {
  if (Array.isArray(value)) return value.map(toInternalContractDeep);
  if (typeof value === 'string') {
    return replaceContractVocabulary(value, {
      ...MONGO_TO_INTERNAL_TOOL,
      MongoDB: 'ArcticDB',
      mongodb: 'arcticdb'
    });
  }
  if (!value || typeof value !== 'object') return value;

  const out = {};
  for (const [key, child] of Object.entries(value)) {
    out[toInternalContractKey(key)] = toInternalContractDeep(child);
  }
  const historianObject =
    String(out.tool || '').startsWith('arctic_') ||
    (Object.prototype.hasOwnProperty.call(out, 'database') &&
      Object.prototype.hasOwnProperty.call(out, 'collection'));
  if (historianObject) {
    if (out.library == null && out.database != null) out.library = out.database;
    if (out.symbol == null && out.collection != null) out.symbol = out.collection;
    delete out.database;
    delete out.collection;
  }
  return out;
}

function toPublicMongoContractDeep(value) {
  if (Array.isArray(value)) return value.map(toPublicMongoContractDeep);
  if (typeof value === 'string') {
    return replaceContractVocabulary(value, {
      ...INTERNAL_TO_MONGO_TOOL,
      ArcticDB: 'MongoDB',
      arcticdb: 'mongodb'
    });
  }
  if (!value || typeof value !== 'object') return value;

  const out = {};
  for (const [key, child] of Object.entries(value)) {
    out[toPublicMongoContractKey(key)] = toPublicMongoContractDeep(child);
  }
  const historianObject =
    String(out.tool || '').startsWith('mongo_') ||
    (Object.prototype.hasOwnProperty.call(out, 'library') &&
      Object.prototype.hasOwnProperty.call(out, 'symbol'));
  if (historianObject) {
    if (out.database == null && out.library != null) out.database = out.library;
    if (out.collection == null && out.symbol != null) out.collection = out.symbol;
    delete out.library;
    delete out.symbol;
  }
  return out;
}

