function normalizeStringArray(value, limit = 12) {
  const raw = Array.isArray(value)
    ? value
    : (typeof value === 'string' ? value.split(/[|;,\uFF0C\u3001]+/) : []);
  const out = [];
  const seen = new Set();
  for (const v of raw) {
    const s = asString(v).replace(/\s+/g, ' ').trim();
    if (!s) continue;
    const key = s.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(s.length > 180 ? s.slice(0, 180).trim() : s);
