// ARCTIC_ANALYZE_RECOVERY_AND_DISPLAY_SPACING_V5
function detectToolFromRawOutput(raw) {
  const s = String(raw || '');
  const m = s.match(/"tool"\s*:\s*"(arctic_[A-Za-z0-9_]+)"/);
  return m ? m[1] : '';
}

function decodeJsonStringLoose(value) {
  return String(value || '')
    .replace(/\\n/g, '\n')
    .replace(/\\r/g, '\r')
    .replace(/\\t/g, '\t')
    .replace(/\\"/g, '"')
    .trim();
}

function extractJsonStringField(raw, field) {
  const s = String(raw || '');
  const key = `"${field}"`;
  const start = s.indexOf(key);
  if (start < 0) return '';
  const colon = s.indexOf(':', start + key.length);
  if (colon < 0) return '';
  const firstQuote = s.indexOf('"', colon + 1);
  if (firstQuote < 0) return '';
  let out = '';
  let escaped = false;
  for (let i = firstQuote + 1; i < s.length; i++) {
    const ch = s[i];
    if (escaped) {
      out += '\\' + ch;
      escaped = false;
      continue;
    }
    if (ch === '\\') {
      escaped = true;
      continue;
    }
    if (ch === '"') return decodeJsonStringLoose(out);
    out += ch;
  }
  return '';
}

