// TRUNCATED_VERTICAL_TRACE_RECOVERY_V5
// A vertical metadata result can exceed the model output limit after its tool
// calls succeed. Recover only complete flat trace objects; prose and candidate
// lists are never promoted to selected tags.
function recoverFlatTagTrace(raw) {
  const out = [];
  const seen = new Set();
  const matches = String(raw || '').match(/\{[^{}]{20,5000}\}/g) || [];
  for (const candidate of matches) {
    let value = null;
    try { value = JSON.parse(candidate); } catch (e) { continue; }
    if (!value || typeof value !== 'object' || Array.isArray(value)) continue;
    const tag = asString(value.tag || value.name);
    const matchType = asString(value.match_type);
    if (!tag || !matchType || typeof value.selected !== 'boolean') continue;
    const factor = asString(value.process_factor || value.process_factor_id);
    const key = [tag.toUpperCase(), factor.toLowerCase(), matchType.toLowerCase()].join('|');
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({
      ...value,
      tag,
      selected: value.selected === true,
      recovery_source: 'complete_trace_object_from_truncated_output'
    });
    if (out.length >= 240) break;
  }
  return out;
}

