// STRUCTURED_EVENT_RETENTION_AND_ANCHOR_V5
// A long tool-agent envelope can remain readable while its outer JSON is
// truncated or malformed. Recover only bounded structured analysis arrays
// from that envelope. This preserves event identity for later turns without
// retaining an unbounded raw payload or deriving facts from prose.
function recoverJsonArrayField(raw, field, limit) {
  const text = String(raw || '');
  const key = `"${field}"`;
  let keyIndex = -1;
  let colon = -1;
  let searchFrom = 0;
  while (searchFrom < text.length) {
    keyIndex = text.indexOf(key, searchFrom);
    if (keyIndex < 0) return [];
    let cursor = keyIndex + key.length;
    while (cursor < text.length && /\s/.test(text[cursor])) cursor += 1;
    if (text[cursor] === ':') {
      colon = cursor;
      break;
    }
    searchFrom = keyIndex + key.length;
  }
  if (colon < 0) return [];
  let start = colon + 1;
  while (start < text.length && /\s/.test(text[start])) start += 1;
  if (text[start] !== '[') return [];

  let depth = 0;
  let quoted = false;
  let escaped = false;
  for (let index = start; index < text.length; index += 1) {
    const ch = text[index];
    if (quoted) {
      if (escaped) {
        escaped = false;
      } else if (ch === '\\') {
        escaped = true;
      } else if (ch === '"') {
        quoted = false;
      }
      continue;
    }
    if (ch === '"') {
      quoted = true;
      continue;
    }
    if (ch === '[') depth += 1;
    if (ch === ']') {
      depth -= 1;
      if (depth === 0) {
        try {
          const value = JSON.parse(text.slice(start, index + 1));
          return Array.isArray(value) ? value.slice(0, limit) : [];
        } catch (e) {
          return [];
        }
      }
    }
  }
  return [];
}

