// ARCTIC_UTC_QUERY_CONTRACT_V5
// arctic_analyze returns timezone-naive UTC ranges. Preserve UTC explicitly
// and derive a separate configured-local display range. Query scope and display
// scope must never overwrite one another.
function configuredDisplayTimezone() {
  try {
    const wf = $('Workflow Configuration').first().json || {};
    const runParams = wf.run_params && typeof wf.run_params === 'object'
      ? wf.run_params
      : JSON.parse(wf.run_params || '{}');
    const value = String(runParams?.arcticdb?.default_timezone || '').trim();
    return /^[+-]\d{2}:\d{2}$/.test(value) ? value : '';
  } catch (e) {
    return '';
  }
}

function markNaiveRangeUtc(range) {
  if (!Array.isArray(range) || range.length !== 2) return range;
  return range.map(value => {
    const text = String(value || '').trim();
    if (!text || /(?:Z|[+-]\d{2}:?\d{2})$/i.test(text)) return text;
    return `${text}Z`;
  });
}

function displayOffsetMinutes(value) {
  const match = /^([+-])(\d{2}):(\d{2})$/.exec(String(value || ''));
  if (!match) return null;
  const minutes = Number(match[2]) * 60 + Number(match[3]);
  return match[1] === '-' ? -minutes : minutes;
}

function utcRangeToDisplay(range, timezone) {
  const offsetMinutes = displayOffsetMinutes(timezone);
  if (!Array.isArray(range) || range.length !== 2 || !Number.isFinite(offsetMinutes)) return [];
  return range.map(value => {
    const text = String(value || '').trim();
    const utcText = /Z$/i.test(text) ? text : `${text}Z`;
    const ms = Date.parse(utcText);
    if (!Number.isFinite(ms)) return text;
    return `${new Date(ms + offsetMinutes * 60000).toISOString().slice(0, 19)}${timezone}`;
  });
}

