function analysisColumnIdentity(value) {
  const text = String(value || '').trim();
  const parts = text.split('.').filter(Boolean);
  // Computed analysis IDs use targetName.TAG.FIELD. Raw tags use TAG.FIELD.
  return (parts.length >= 3 ? parts.slice(1).join('.') : text).toUpperCase();
}

// IMPLICIT_CORRELATION_TARGET_V5
function sanitizeRelationshipRows(rows, implicitTargetRaw) {
  const kept = [];
  const removed = [];
  const seenPairs = new Set();

  for (const raw of Array.isArray(rows) ? rows : []) {
    if (!raw || typeof raw !== 'object') continue;
    const targetRaw =
      raw.target_column_id || raw.target_column || raw.target || implicitTargetRaw || '';
    const candidateRaw =
      raw.candidate_column_id || raw.candidate_column || raw.candidate || '';
    const target = analysisColumnIdentity(targetRaw);
    const candidate = analysisColumnIdentity(candidateRaw);
    if (!target || !candidate) {
      removed.push({ ...raw, validation_reason: 'missing_column_identity' });
      continue;
    }
    if (target === candidate) {
      removed.push({ ...raw, validation_reason: 'same_physical_column' });
      continue;
    }

    const pair = [target, candidate].sort().join('|');
    if (seenPairs.has(pair)) {
      removed.push({ ...raw, validation_reason: 'reciprocal_or_duplicate_pair' });
      continue;
    }
    seenPairs.add(pair);
    kept.push({ ...raw, relationship_validation: 'distinct_columns' });
  }

  return { kept, removed };
}

