  };
}

// GENERIC_METADATA_IDENTIFIER_MATCHING_V6
function compactMatchText(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9\u4e00-\u9fff]+/g, '');
}

function stripFieldSuffix(value) {
  return compactMatchText(value).replace(/(?:pv|sp|op|mv|sv|cv)$/, '');
}

function queryInstrumentIdentifiers(value) {
  const matches = String(value || '').match(/[a-z][a-z0-9]*(?:[-_.][a-z0-9]+)*/gi) || [];
  return Array.from(new Set(
    matches
      .filter(token => /\d/.test(token))
      .map(stripFieldSuffix)
      .filter(token => token.length >= 4)
  ));
}

function identifierMatches(candidateTag, queryIdentifier) {
  const candidate = stripFieldSuffix(candidateTag);
  const requested = stripFieldSuffix(queryIdentifier);
  if (!candidate || !requested) return false;
  if (candidate === requested) return true;

  // A query may name the loop while the catalog stores explicit A/B channels.
  const candidateTail = candidate.slice(requested.length);
  if (
    requested.length >= 5 &&
    candidate.startsWith(requested) &&
    /^[a-z]$/.test(candidateTail)
  ) return true;

  return false;
}

function semanticSegments(value) {
  return Array.from(new Set(
    String(value || '')
      .split(/[\s,;:，；：、/|()[\]{}]+/)
      .map(compactMatchText)
      .filter(segment => segment.length >= 4)
  ));
}

function wordTokens(value) {
  return Array.from(new Set(
    String(value || '')
      .toLowerCase()
      .match(/[a-z][a-z0-9]{2,}|[\u4e00-\u9fff]{2,}/g) || []
  ));
}

function metadataDirectlyMatchesQuery(candidate, query) {
  if (!candidate || typeof candidate !== 'object') return false;
  const tag = asString(candidate.tag || candidate.name);
  const descCn = asString(candidate.desc_cn || candidate.description_cn);
  const descEn = asString(candidate.desc_en || candidate.description_en);
  const identifiers = queryInstrumentIdentifiers(query);

  if (identifiers.some(identifier => identifierMatches(tag, identifier))) return true;

  const segments = semanticSegments(query);
  for (const desc of [descCn, descEn]) {
    const descCompact = compactMatchText(desc);
    if (
      descCompact.length >= 4 &&
      segments.some(segment =>
        segment.includes(descCompact) || descCompact.includes(segment)
      )
    ) return true;

    const queryTokens = wordTokens(query);
    const descTokens = wordTokens(desc);
    if (!queryTokens.length || !descTokens.length) continue;
    const overlap = descTokens.filter(token =>
      queryTokens.some(qt => qt === token || qt.includes(token) || token.includes(qt))
    );
    if (overlap.length >= Math.max(1, Math.ceil(descTokens.length * 0.6))) return true;
  }

  return false;
}

let tag_selection_trace = Array.isArray(parsed.tag_selection_trace) && parsed.tag_selection_trace.length
