// EMPTY_CATALOG_DIRECT_VERIFY_V7
// MongoDB Executor（LLM 代理）常不调用工具就写出「0 条候选」：MT25 T7 exec 147321 给出 2 条目录查询结果、实际工具调用 0 次；
// 真实工具是确定性词法检索，「两器压差 差压」返回 PDRA3125.PV / PDRA3125B.PV 居前（exec 143060）。
// 目录查询原始结果与候选均为空时，按执行器真实调用的参数形态直接调一次核实（总预算 15 秒）。
await (async function () {
  try {
    const isFind = recoveredToolFromRaw === 'arctic_find_tags' || /find_tags$/.test(asString(unit && unit.tool));
    if (!isFind) return;
    const rawTags = Array.isArray(raw_result && raw_result.tags) ? raw_result.tags : [];
    if (rawTags.length || (Array.isArray(tag_selection_trace) && tag_selection_trace.length)) return;
    const p = (unit && unit.params) || {};
    // Param Injector 把查询改写为 primary_query + fallback_queries（exec 147321），也兼容原始的 params.query。
    const querySpecs = []
      .concat(p.primary_query && typeof p.primary_query === 'object' ? [p.primary_query] : [])
      .concat(Array.isArray(p.fallback_queries) ? p.fallback_queries : [])
      .concat(p.query ? [{ query: p.query, top_k: p.top_k }] : [])
      .filter(q => q && asString(q.query));
    if (!querySpecs.length) return;
    const query = asString(querySpecs[0].query);
    const database = asString(p.database || p.library);
    const collection = asString(p.collection || p.symbol);
    const ctx = this && this.helpers && this.helpers.httpRequest ? this : null;
    const verification = { policy: 'EMPTY_CATALOG_DIRECT_VERIFY_V7', query };
    if (raw_result && typeof raw_result === 'object') raw_result.direct_verification = verification;
    if (!ctx) { verification.skipped = 'no_http_helper'; return; }
    const deadline = Date.now() + 15000;
    // NO_HARDCODE_V7：地址取自 Workflow Configuration.run_params.mongodb.mcp_endpoint，代码里不保留。
    const url = (function () {
      try {
        const wc = $('Workflow Configuration').first().json || {};
        const rp = typeof wc.run_params === 'string' ? JSON.parse(wc.run_params) : (wc.run_params || {});
        return String((rp.mongodb && rp.mongodb.mcp_endpoint) || '');
      } catch (e) { return ''; }
    })();
    if (!url) { verification.skipped = 'mcp_endpoint_not_configured'; return; }
    const parseBody = body => {
      if (body && typeof body === 'object' && !(typeof Buffer !== 'undefined' && Buffer.isBuffer(body))) return body;
      const text = String(body || '');
      const datas = text.split(/\r?\n/).filter(l => l.startsWith('data:')).map(l => l.slice(5).trim()).filter(Boolean);
      for (let i = datas.length - 1; i >= 0; i--) { try { return JSON.parse(datas[i]); } catch (e) {} }
      try { return JSON.parse(text); } catch (e) { return {}; }
    };
    const post = async (payload, sid) => {
      if (Date.now() > deadline - 500) throw new Error('direct verify time budget exhausted');
      const headers = { 'Content-Type': 'application/json', Accept: 'application/json, text/event-stream' };
      if (sid) headers['Mcp-Session-Id'] = sid;
      const res = await ctx.helpers.httpRequest({
        method: 'POST', url, headers, body: JSON.stringify(payload), json: false,
        returnFullResponse: true, timeout: Math.max(1000, Math.min(8000, deadline - Date.now()))
      });
      const h = (res && res.headers) || {};
      return { sid: h['mcp-session-id'] || h['Mcp-Session-Id'] || sid || '', msg: parseBody(res && res.body) };
    };
    const init = await post({ jsonrpc: '2.0', id: 1, method: 'initialize',
      params: { protocolVersion: '2025-03-26', capabilities: {}, clientInfo: { name: 'result-normalizer', version: '1' } } }, '');
    try { await post({ jsonrpc: '2.0', method: 'notifications/initialized' }, init.sid); } catch (e) {}
    let matches = [];
    let out = {};
    verification.tried = [];
    for (let qi = 0; qi < querySpecs.length && !matches.length; qi++) {
      if (Date.now() > deadline - 2000) break;
      const spec = querySpecs[qi];
      // NO_HARDCODE_V7：沿用本单元已注入的查询参数（Param Injector 写好的 primary_query / fallback_queries），不另设取值。
      const args = { ...spec };
      if (database) args.database = database;
      if (collection) args.collection = collection;
      const call = await post({ jsonrpc: '2.0', id: 2 + qi, method: 'tools/call', params: { name: 'mongo_find_tags', arguments: args } }, init.sid);
      const content = (((call.msg || {}).result || {}).content) || [];
      const text = content.filter(c => c && c.type === 'text').map(c => c.text).join('\n');
      out = {};
      try { out = JSON.parse(text); } catch (e) { verification.raw = text.slice(0, 300); }
      matches = Array.isArray(out.matches) ? out.matches : (Array.isArray(out.tags) ? out.tags : []);
      verification.tried.push({ query: args.query, returned: matches.length });
    }
    verification.total_matches = Number(out.total_matches) || matches.length;
    verification.returned = matches.length;
    if (!matches.length) return;

    // 主体名称：设备上下文规范名/别名（括号内外分开），缺省用会话主体。
    const cjk = x => Array.from(new Set(Array.from(String(x || '').replace(/[^\u4e00-\u9fff]/g, ''))));
    const names = (function () {
      const out2 = [];
      try {
        const d = ((($('Parse Device Context').first().json || {}).device_context) || {}).device || {};
        for (const n of [d.canonical_name].concat(Array.isArray(d.aliases) ? d.aliases : [])) {
          const v = String(n || '');
          if (!v) continue;
          out2.push(v.replace(/[（(][^）)]*[）)]/g, ''));
          for (const m of v.matchAll(/[（(]([^）)]*)[）)]/g)) out2.push(m[1]);
        }
      } catch (e) {}
      try {
        const st = (($('Capture context').first() || {}).json || {}).conversation_state || {};
        if (st.latest_topic) out2.push(String(st.latest_topic));
      } catch (e) {}
      return out2.map(cjk).filter(chars => chars.length >= 3);
    })();
    const descOf = m => asString(m.desc_cn || m.desc_en || m.description);
    const ratioOf = m => {
      const d = new Set(cjk(descOf(m)));
      let best = 0;
      for (const chars of names) {
        const hit = chars.filter(ch => d.has(ch)).length;
        if (hit >= 3) best = Math.max(best, hit / chars.length);
      }
      return best;
    };
    const scored = matches.map((m, i) => ({ m, i, r: ratioOf(m) }));
    // 优先：前序轮次 fact_cards 里 status=confirmed 的位号（exec 147321：T6 记 PDRA3125/B confirmed，
    // PDIA203A、PDI36413C 等 unconfirmed；只看「回答里提到过」会把后者一并收回）。
    const confirmedTags = (function () {
      const set = new Set();
      try {
        const st = (($('Capture context').first() || {}).json || {}).conversation_state || {};
        for (const c of (Array.isArray(st.fact_cards) ? st.fact_cards : [])) {
          if (c && c.entity_type === 'tag' && String(c.status || '').toLowerCase() === 'confirmed') {
            set.add(String(c.subject || '').toUpperCase());
          }
        }
      } catch (e) {}
      return set;
    })();
    const byFact = scored.filter(x => confirmedTags.has(asString(x.m.tag).toUpperCase()));
    // NO_HARDCODE_V7：只以前序轮次已确认为依据；没有依据不自动选，交给会话收回逻辑。
    const chosenGroup = byFact;
    const autoSelect = chosenGroup.length > 0;
    verification.subject_names = names.map(chars => chars.join(''));
    verification.selection_basis = byFact.length ? 'conversation_confirmed_fact_cards' : 'none';
    verification.auto_selected = chosenGroup.map(x => asString(x.m.tag));

    raw_result.tags = matches.map(m => ({ tag: asString(m.tag || m.name), desc_cn: asString(m.desc_cn), desc_en: asString(m.desc_en), score: m.score }));
    raw_result.count = matches.length;
    tag_selection_trace = scored.map(x => {
      const chosen = autoSelect && chosenGroup.includes(x);
      return {
        tag: asString(x.m.tag || x.m.name),
        desc_cn: asString(x.m.desc_cn),
        desc_en: asString(x.m.desc_en),
        rank: x.i + 1,
        query,
        selected: chosen,
        match_type: chosen ? 'direct_match' : 'unconfirmed_metadata_candidate',
        subject_coverage: Math.round(x.r * 100) / 100,
        selection_reason: chosen
          ? '执行器未调用工具；代码直接核实目录，该位号在本对话前序轮次已确认'
          : '执行器未调用工具；代码直接核实目录所得候选，未自动选中'
      };
    }).filter(e => e.tag);
  } catch (e) {
    try { if (raw_result && typeof raw_result === 'object') raw_result.direct_verification = { policy: 'EMPTY_CATALOG_DIRECT_VERIFY_V7', error: String((e && e.message) || e).slice(0, 300) }; } catch (e2) {}
  }
}).call(this);

if (
  recoveredToolFromRaw === 'arctic_find_tags' &&
  Array.isArray(raw_result && raw_result.tags) &&
  raw_result.tags.length &&
  !(Array.isArray(parsed.tag_selection_trace) && parsed.tag_selection_trace.length)
) {
  const query = asString(unit?.params?.query);
  const globalMetadataDiscovery =
    !asString(unit?.params?.library) &&
    !asString(unit?.params?.symbol);

  if (globalMetadataDiscovery && query) {
    tag_selection_trace = raw_result.tags
      .map((candidate, index) => {
        const obj = candidate && typeof candidate === 'object'
          ? candidate
          : { tag: String(candidate || '') };
        const selected = metadataDirectlyMatchesQuery(obj, query);
        return {
          tag: asString(obj.tag || obj.name),
          desc_cn: asString(obj.desc_cn || obj.description_cn),
          desc_en: asString(obj.desc_en || obj.description_en),
          rank: index + 1,
          query,
          selected,
          match_type: selected ? 'direct_metadata_match' : 'unconfirmed_metadata_candidate',
          selection_reason: selected
            ? 'Exact tag or metadata description matched the factor query.'
            : 'Catalog candidate was retained as evidence but not selected for target-library statistics.'
        };
      })
      .filter(entry => entry.tag);
  }
}

if (
  recoveredToolFromRaw === 'arctic_find_tags' &&
  recoveredTruncatedTrace.length &&
  raw_result &&
  typeof raw_result === 'object'
) {
  const selected = recoveredTruncatedTrace
    .filter(entry => entry.selected === true && /direct/i.test(asString(entry.match_type)))
    .map(entry => ({
      tag: entry.tag,
      desc_cn: asString(entry.desc_cn),
      desc_en: asString(entry.desc_en)
    }));
  raw_result.tags = selected;
  raw_result.count = selected.length;
  raw_result.output_truncated_recovered = true;
  raw_result.trace_object_count = recoveredTruncatedTrace.length;
}

// PHYSICAL_QUANTITY_COMPATIBILITY_V5
// A catalog candidate is directly usable only when it measures the same
// physical quantity as the requested factor. This is a generic metadata rule:
// it does not contain workflow-test questions or plant-specific tag names.
function measurementClass(value, tag) {
  const text = `${asString(value)} ${asString(tag)}`.toLowerCase();
  const classes = [];
  const add = name => {
    if (!classes.includes(name)) classes.push(name);
  };

  if (/(?:差压|压差|压降|differential\s*pressure|pressure\s*drop|delta\s*p|Δp|\bdp\b)/i.test(text) ||
      /^(?:pdi|pdr|pdra|pdrc)/i.test(asString(tag))) add('differential_pressure');
  if (/(?:密度|density|specific\s*gravity)/i.test(text) ||
      /^(?:dr|dra|drc)/i.test(asString(tag))) add('density');
  if (/(?:流量|流率|流速|循环量|通量|flow|throughput|circulation\s*rate)/i.test(text) ||
      /^(?:fi|fr|frc|fica)/i.test(asString(tag))) add('flow');
  if (/(?:温度|temperature|\btemp\b)/i.test(text) ||
      /^(?:ti|tr|trc)/i.test(asString(tag))) add('temperature');
  if (/(?:料位|液位|床层高度|level)/i.test(text) ||
      /^(?:li|lr|lrc)/i.test(asString(tag))) add('level');
  if (/(?:藏量|存量|库存|持有量|inventory|holdup|hold-up)/i.test(text)) add('inventory');
  if (/(?:开度|阀位|位置|opening|valve\s*position|position)/i.test(text) ||
      /^(?:zi|zr|zrc)/i.test(asString(tag))) add('position');
  if (/(?:负荷|功率|电流|load|power|current)/i.test(text)) add('load');

  const hasDifferential = classes.includes('differential_pressure');
  if (!hasDifferential &&
      (/(?:压力|顶压|背压|pressure)/i.test(text) ||
       /^(?:pi|pr|pra|prc)/i.test(asString(tag)))) add('pressure');
  return classes;
}

function physicalQuantityCompatibility(entry, factor) {
  // FACTOR_LOCAL_QUANTITY_CLASSIFICATION_V5
  // Batch process_context can mention several neighbouring quantities. Use
  // the factor-local name first; consult factor-local description/query only
  // when the name itself does not identify a physical quantity.
  const factorName = asString(factor?.name);
  const nameClasses = measurementClass(factorName, '');
  const factorText = nameClasses.length
    ? factorName
    : [
        factorName,
        factor?.description,
        factor?.query
      ].map(asString).filter(Boolean).join(' ');
  const candidateText = [
    entry?.desc_cn,
    entry?.desc_en,
    entry?.description_cn,
    entry?.description_en,
    entry?.what_it_measures
  ].map(asString).filter(Boolean).join(' ');
  const tag = asString(entry?.tag || entry?.name);
  const requested = measurementClass(factorText, '');
  const measured = measurementClass(candidateText, tag);

  // Phase qualifiers are part of the measured quantity. A dense-phase
  // density must not satisfy a dilute-phase request merely because both are
  // densities. This remains metadata-driven and independent of tag identity.
  const phaseClasses = value => {
    const text = asString(value).toLowerCase();
    const phases = [];
    if (/(?:稀相|dilute\s*phase)/i.test(text)) phases.push('dilute');
    if (/(?:密相|dense\s*phase)/i.test(text)) phases.push('dense');
    return phases;
  };
  const requestedPhases = phaseClasses(factorText);
  const measuredPhases = phaseClasses(candidateText);

  // When neither side identifies a physical quantity, retain the executor's
  // semantic decision. When only one side is known, direct use is not proven.
  if (!requested.length && !measured.length) {
    return { compatible: true, requested, measured, reason: 'no_quantity_metadata' };
  }
  if (!requested.length || !measured.length) {
    return { compatible: false, requested, measured, reason: 'quantity_metadata_incomplete' };
  }
  const quantityCompatible = requested.some(name => measured.includes(name));
  const phaseCompatible = !requestedPhases.length ||
    requestedPhases.some(name => measuredPhases.includes(name));
  const compatible = quantityCompatible && phaseCompatible;
  return {
    compatible,
    requested,
    measured,
    requested_phases: requestedPhases,
    measured_phases: measuredPhases,
    reason: compatible
      ? 'same_physical_quantity'
      : (quantityCompatible ? 'phase_qualifier_mismatch' : 'physical_quantity_mismatch')
  };
}

// DETERMINISTIC_VERTICAL_COVERAGE_V5
// Reconstruct factor coverage from the execution envelope and complete trace
// objects. This remains valid when the model response is cut after tool calls.
const isVerticalFind =
  recoveredToolFromRaw === 'arctic_find_tags' &&
  asString(unit?.tag_selection_mode) === 'vertical_multi_query';
let verticalCoverage = null;
if (isVerticalFind && raw_result && typeof raw_result === 'object') {
  const factors = Array.isArray(unit.factor_context) ? unit.factor_context : [];
  const factorsById = new Map(
    factors.map((factor, index) => [
      asString(factor?.factor_id) || `factor_${index + 1}`,
      factor
    ])
  );
  const factorsByName = new Map(
    factors.map(factor => [asString(factor?.name), factor]).filter(([name]) => name)
  );

  // CROSS_FACTOR_METADATA_REBINDING_V5
  // The retrieval model may discover a valid candidate under a neighbouring
  // query. Rebind by explicit metadata object/location overlap, then apply the
  // physical-quantity gate. This uses no plant-specific tag identities.
  function objectCore(value) {
    return String(value || '')
      .toLowerCase()
      .replace(/差压|压差|压降|压力|密度|流量|流率|流速|温度|料位|液位|开度|阀位/g, ' ')
      .replace(/differential\s*pressure|pressure\s*drop|pressure|density|flow|rate|velocity|temperature|level|opening|position/gi, ' ')
      .replace(/测点|仪表|控制|回路|各部位|measurement|control|controller|indicator/gi, ' ')
      .replace(/[^\p{L}\p{N}]+/gu, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  }

  function objectFeatures(value) {
    const core = objectCore(value);
    const features = new Set();
    for (const word of core.split(/\s+/).filter(Boolean)) {
      if (/[\u3400-\u9fff]/.test(word)) {
        if (word.length <= 2) features.add(word);
        for (let index = 0; index < word.length - 1; index += 1) {
          features.add(word.slice(index, index + 2));
        }
      } else if (word.length >= 3) {
        features.add(word);
      }
    }
    return { core: core.replace(/\s+/g, ''), features };
  }

  // CROSSLINGUAL_EQUIPMENT_OBJECT_MATCH_V5
  // Metadata commonly contains a Chinese label and an English description.
  // Normalize broad equipment classes before comparing object/location text.
  // These are semantic classes only; no plant tag identity is encoded here.
  function equipmentConcepts(value) {
    const text = String(value || '').toLowerCase();
    const concepts = new Set();
    const classes = [
      ['regenerator', /再生器|一再|二再|regenerator/],
      ['settler', /沉降器|settler|disengager/],
      ['riser', /提升管|riser/],
      ['standpipe', /立管|standpipe/],
      ['slide_valve', /滑阀|slide\s*valve/],
      ['distributor', /分布板|分布管|分布器|grid|distribut(?:or|ion)/],
      ['compressor', /压缩机|气压机|compressor/],
      ['fractionator', /分馏塔|分馏器|fractionator/],
      ['cyclone', /旋风分离器|旋分器|旋分|cyclone/],
      ['catalyst', /催化剂|catalyst/]
    ];
    for (const [name, pattern] of classes) {
      if (pattern.test(text)) concepts.add(name);
    }
    return concepts;
  }

  function factorObjectScore(entry, factor) {
    const factorText = [
      factor?.name,
      ...(Array.isArray(factor?.aliases) ? factor.aliases : []),
      factor?.process_context,
      factor?.measurement_type
    ].map(asString).filter(Boolean).join(' ');
    const candidateText = [
      entry?.desc_cn,
      entry?.desc_en,
      entry?.description_cn,
      entry?.description_en,
      entry?.what_it_measures
    ].map(asString).filter(Boolean).join(' ');
    const left = objectFeatures(factorText);
    const right = objectFeatures(candidateText);
    if (!left.core || !right.core) return 0;
    let score = 0;
    if (right.core.includes(left.core) || left.core.includes(right.core)) score += 8;
    for (const feature of left.features) {
      if (right.features.has(feature)) score += feature.length >= 3 ? 3 : 2;
    }
    const leftConcepts = equipmentConcepts(factorText);
    const rightConcepts = equipmentConcepts(candidateText);
    for (const concept of leftConcepts) {
      if (rightConcepts.has(concept)) score += 6;
    }
    // RELATIONAL_EQUIPMENT_MATCH_V5
    // A factor may name a relationship (for example, pressure difference
    // between two vessels) while metadata names both endpoints explicitly.
    // Match the relationship shape without encoding any plant-specific tag.
    const factorIsInterEquipment = /(?:\u4e24\u5668|\u4e24\u8bbe\u5907|between\s+.+\s+and\s+.+)/i.test(factorText);
    const candidateIsInterEquipment = /(?:[\u3400-\u9fffA-Za-z0-9]+\s*[\u4e0e\-]\s*[\u3400-\u9fffA-Za-z0-9]+.*(?:\u5dee\u538b|\u538b\u5dee)|between\s+.+\s+(?:and|&)\s+.+)/i.test(candidateText);
    if (factorIsInterEquipment && candidateIsInterEquipment) score += 8;
    return score;
  }

  function factorHasExplicitObjectConstraint(factor) {
    const factorText = [
      factor?.name,
      ...(Array.isArray(factor?.aliases) ? factor.aliases : [])
    ].map(asString).filter(Boolean).join(' ');
    const equipment = [...equipmentConcepts(factorText)]
      .filter(concept => concept !== 'catalyst');
    const explicitEquipmentCode = /\b[A-Z]{1,8}[-_]?\d{2,6}[A-Z0-9_-]*\b/i.test(factorText);
    const relationalObject = /(?:两器|两设备|between\s+.+\s+and\s+.+)/i.test(factorText);
    return equipment.length > 0 || explicitEquipmentCode || relationalObject;
  }

  // COMPOUND_FACTOR_COVERAGE_GUARD_V5
  // A candidate that covers only one half of "A and B" cannot establish the
  // whole compound input. Each semantic component must independently match
  // the candidate's quantity and object metadata.
  function compoundFactorCovered(entry, factor) {
    const name = asString(factor?.name);
    const parts = name
      .split(/(?:与|和|及|以及|\/|／|\band\b)/i)
      .map(value => value.trim())
      .filter(Boolean);
    if (parts.length < 2) return true;
    return parts.every(part => {
      const component = { ...factor, name: part, aliases: [] };
      const quantity = physicalQuantityCompatibility(entry, component);
      return quantity.compatible && factorObjectScore(entry, component) >= 4;
    });
  }

  tag_selection_trace = tag_selection_trace.map(entry => {
    if (!entry) return entry;
    const compatibleFactors = factors
      .map(factor => ({
        factor,
        check: physicalQuantityCompatibility(entry, factor),
        score: factorObjectScore(entry, factor)
      }))
      .filter(candidate => candidate.check.compatible)
      .sort((left, right) => right.score - left.score);
    const best = compatibleFactors[0];
    const second = compatibleFactors[1];
    const uniquelyExplicit =
      best && best.score >= 4 && (!second || best.score > second.score);
    const originalFactor =
      factorsById.get(asString(entry.process_factor_id)) ||
      factorsByName.get(asString(entry.process_factor));
    const chosen = uniquelyExplicit ? best.factor : originalFactor;
    const check = physicalQuantityCompatibility(entry, chosen);
    const compoundCovered = compoundFactorCovered(entry, chosen);
    const factorRequiresObject = factorHasExplicitObjectConstraint(chosen);
    const chosenObjectScore = factorObjectScore(entry, chosen);
    const objectConfirmed = !factorRequiresObject || chosenObjectScore >= 4;
    const executorDirect =
      entry.selected === true && /direct/i.test(asString(entry.match_type)) && compoundCovered && objectConfirmed;
    const metadataDirect = uniquelyExplicit && check.compatible && compoundCovered && objectConfirmed;

    if (check.compatible && compoundCovered && (executorDirect || metadataDirect)) {
      return {
        ...entry,
        process_factor_id: asString(chosen?.factor_id) || asString(entry.process_factor_id),
        process_factor: asString(chosen?.name) || asString(entry.process_factor),
        selected: true,
        match_type: 'direct_match',
        physical_quantity_check: check,
        binding_source: metadataDirect ? 'metadata_object_rebind' : 'executor_direct'
      };
    }
    return {
      ...entry,
      process_factor_id: asString(chosen?.factor_id) || asString(entry.process_factor_id),
      process_factor: asString(chosen?.name) || asString(entry.process_factor),
      selected: false,
      match_type: 'contextual_match',
      physical_quantity_check: check,
      selection_reason: check.compatible
        ? (compoundCovered
          ? 'Catalog metadata does not explicitly identify the same equipment or location.'
          : 'Catalog metadata covers only part of the compound factor.')
        : 'Catalog candidate measures a different physical quantity and cannot be used as a direct input.'
    };
  });

  const directTrace = tag_selection_trace.filter(entry =>
    entry &&
    entry.selected === true &&
    /direct/i.test(asString(entry.match_type)) &&
    asString(entry.tag || entry.name)
  );
  const directTags = [];
  const seenDirectTags = new Set();
  for (const entry of directTrace) {
    const tag = asString(entry.tag || entry.name);
    const key = tag.toUpperCase();
    if (seenDirectTags.has(key)) continue;
    seenDirectTags.add(key);
    directTags.push({
      tag,
      desc_cn: asString(entry.desc_cn),
      desc_en: asString(entry.desc_en)
    });
  }
  const factorResolution = factors.map((factor, index) => {
    const factorId = asString(factor?.factor_id) || `factor_${index + 1}`;
    const factorName = asString(factor?.name) || factorId;
    const matches = directTrace.filter(entry =>
      asString(entry.process_factor_id) === factorId ||
      asString(entry.process_factor) === factorName
    );
    const contextualMatches = tag_selection_trace.filter(entry =>
      entry &&
      entry.selected !== true &&
      /contextual/i.test(asString(entry.match_type)) &&
      (asString(entry.process_factor_id) === factorId ||
       asString(entry.process_factor) === factorName)
    );
    return {
      factor_id: factorId,
      factor: factorName,
      resolution: matches.length ? 'direct_match' : 'unresolved',
      selected_tags: Array.from(new Set(matches.map(entry => asString(entry.tag)).filter(Boolean))),
      candidate_tags: Array.from(new Set(contextualMatches.map(entry => asString(entry.tag || entry.name)).filter(Boolean)))
    };
  });
  const contextualCandidateTags = Array.from(new Set(
    factorResolution.flatMap(entry => entry.candidate_tags || []).filter(Boolean)
  ));
  const resolvedFactors = factorResolution.filter(entry => entry.resolution === 'direct_match');
  const unresolvedFactors = factorResolution.filter(entry => entry.resolution === 'unresolved');
  raw_result.tags = directTags;
  raw_result.candidate_tags = contextualCandidateTags;
  raw_result.probe_tags = Array.from(new Set(
    directTags.map(entry => asString(entry.tag)).concat(contextualCandidateTags).filter(Boolean)
  ));
  raw_result.count = directTags.length;
  raw_result.factor_resolution = factorResolution;
  raw_result.requested_factor_count = factorResolution.length;
  raw_result.resolved_factor_count = resolvedFactors.length;
  raw_result.unresolved_factor_count = unresolvedFactors.length;
  raw_result.unresolved_factors = unresolvedFactors.map(entry => entry.factor);
  raw_result.factor_batch = unit.factor_batch || null;
  raw_result.output_recovery = recoveredTruncatedTrace.length
    ? 'complete_trace_recovery'
    : 'structured_response';
  verticalCoverage = {
    requested: factorResolution.length,
    resolved: resolvedFactors.length,
    unresolved: unresolvedFactors.length,
    selected_tags: directTags.length
  };
}

let answer =
  asString(parsed.answer) ||
  asString(recoveredAnswerFromRaw) ||
  asString(item.answer) ||
  asString(item.tool_answer);

if (verticalCoverage) {
  const chinese = /[\u4e00-\u9fff]/.test(asString(item.originalUserMessage || _pi.originalUserMessage));
  answer = chinese
    ? `本批请求因子 ${verticalCoverage.requested} 个，直接命中 ${verticalCoverage.resolved} 个，未解析 ${verticalCoverage.unresolved} 个，选中直接标签 ${verticalCoverage.selected_tags} 个。`
    : `Batch factors: ${verticalCoverage.requested}; directly resolved: ${verticalCoverage.resolved}; unresolved: ${verticalCoverage.unresolved}; selected direct tags: ${verticalCoverage.selected_tags}.`;
}

const chunkCount = Number(raw_result && raw_result.chunk_count);

// AUTHORITATIVE_TOOL_STATUS_V5
// A structured zero-match catalog response is a completed lookup, even when
// an executor labels the empty result as status:error.
// STRUCTURED_RESULT_TOOL_IDENTITY_V5
// The runtime injector can change a planned stats unit into a read-only
// existence result. Prefer unambiguous result structure over a stale tool
// label copied by the Agent envelope.
const structuredResultTool =
  raw_result?.presence_probe === true ||
  Array.isArray(raw_result?.non_null_columns)
    ? 'arctic_read'
    : (raw_result?.column_stats && typeof raw_result.column_stats === 'object')
      ? 'arctic_stats'
      : '';
const normalizedToolName = asString(
  structuredResultTool ||
  (_pi.unit && _pi.unit.tool) ||
  (unit && unit.tool) ||
  parsed.tool ||
  recoveredToolFromRaw ||
  item.tool
);

// CONVERTED_TOOL_UNIT_IDENTITY_V5
// Runtime policy may convert a planned raw read into compact statistics. Item
// linking can still point at a neighbouring loop item, so recover the planned
// unit whose time scope overlaps the returned result and preserve its unit ID.
if (
  structuredResultTool === 'arctic_stats' &&
  (!unit || unit.tool !== 'arctic_stats')
) {
  const resultRange = Array.isArray(raw_result?.time_range) ? raw_result.time_range : [];
  const compatible = plannedUnits().filter(candidate =>
    candidate && ['arctic_read', 'arctic_stats'].includes(candidate.tool)
  );
  const overlapping = compatible.filter(candidate =>
    arcticRangesOverlap(candidate?.params?.date_range, resultRange)
  );
  const sourceUnit = overlapping.length === 1
    ? overlapping[0]
    : (compatible.length === 1 ? compatible[0] : null);
  if (sourceUnit) {
    unit = {
      ...sourceUnit,
      tool: 'arctic_stats',
      params: {
        ...(sourceUnit.params || {}),
        columns: firstArray(
          raw_result?.requested_columns,
          raw_result?.columns_analyzed,
          raw_result?.returned_columns,
          sourceUnit?.params?.columns
        )
      },
      runtime_tool_conversion: {
        from: sourceUnit.tool,
        to: 'arctic_stats',
        identity_source: 'planned_time_scope_match'
      }
    };
  }
}

// ARCTIC_READ_RANGE_INTEGRITY_V5
// The preview MCP can return head rows from another period when a large or
// empty bounded read does not match. Such rows are diagnostic output, never
// evidence for the requested period.
function parseArcticRangeMs(value, naiveIsUtc) {
  const text = String(value || '').trim().replace(' ', 'T');
  if (!text) return null;
  const normalized =
    naiveIsUtc && !/(?:Z|[-+]\d{2}:?\d{2})$/i.test(text)
      ? `${text}Z`
      : text;
  const ms = Date.parse(normalized);
  return Number.isFinite(ms) ? ms : null;
}

function arcticRangesOverlap(requested, observed) {
  if (!Array.isArray(requested) || requested.length !== 2) return true;
  if (!Array.isArray(observed) || observed.length !== 2) return true;
  const reqStart = parseArcticRangeMs(requested[0], true);
  const reqEnd = parseArcticRangeMs(requested[1], true);
  const obsStart = parseArcticRangeMs(observed[0], false);
  const obsEnd = parseArcticRangeMs(observed[1], false);
  if ([reqStart, reqEnd, obsStart, obsEnd].some(value => value == null)) return false;
  return obsEnd >= reqStart && obsStart <= reqEnd;
}

const requestedReadRange = Array.isArray(unit?.params?.date_range)
  ? unit.params.date_range
  : [];
const observedReadRange = Array.isArray(raw_result?.time_range)
  ? raw_result.time_range
  : [];
const readRangeMismatch =
  normalizedToolName === 'arctic_read' &&
  requestedReadRange.length === 2 &&
  observedReadRange.length === 2 &&
  !arcticRangesOverlap(requestedReadRange, observedReadRange);

if (readRangeMismatch) {
  const rejectedRowCount = Number(raw_result.row_count || raw_result.count || 0);
  for (const key of Object.keys(raw_result)) delete raw_result[key];
  Object.assign(raw_result, {
    row_count: 0,
    data_scope: 'range_mismatch_rejected',
    range_match: false,
    date_range_requested: requestedReadRange,
    rejected_observed_time_range: observedReadRange,
    rejected_row_count: Number.isFinite(rejectedRowCount) ? rejectedRowCount : null,
    note: 'Historian rows outside the requested UTC interval were rejected before synthesis.'
  });
  evidence_summary.splice(0, evidence_summary.length);
  evidence_digest.splice(0, evidence_digest.length);
  parsed.claims = [];
  parsed.analysis_notes = [];
  answer = 'NO_EVIDENCE';
}

// RELATIONSHIP_QUALITY_SEMANTICS_V5
// Rebuild correlation/lag summaries from structured values. Raw historian
// coverage, relationship computability, and inferential confidence are
// separate properties and must not be collapsed into one "data quality" claim.
function structuredRelationshipSummary(result, plannedUnit) {
  if (!result || typeof result !== 'object') return '';
  const correlations = Array.isArray(result.ranked_correlations) ? result.ranked_correlations : [];
  const lags = Array.isArray(result.lag_findings) ? result.lag_findings : [];
  if (!correlations.length && !lags.length) return '';

  const quality = Array.isArray(result.data_quality) ? result.data_quality : [];
  const targetRaw = firstArray(
    plannedUnit?.params?.target_columns,
    result.target_columns
  )[0] || (correlations[0] && correlations[0].target_column_id) || '';
  const target = analysisColumnIdentity(targetRaw);
  const fmt = value => {
    const number = Number(value);
    return Number.isFinite(number) ? number.toFixed(4).replace(/0+$/, '').replace(/\.$/, '') : 'n/a';
  };
  const rowLabel = row => analysisColumnIdentity(
    row?.candidate_column_id || row?.candidate_column || row?.candidate || ''
  );
  const relationshipColumns = new Set(
    [...correlations, ...lags]
      .flatMap(row => [
        analysisColumnIdentity(
          row?.target_column_id || row?.target_column || row?.target || ''
        ),
        rowLabel(row)
      ])
      .filter(Boolean)
  );
  const availableCandidates = quality
    .map(row => analysisColumnIdentity(row?.column))
    .filter(column => column && column !== target);
  const omitted = availableCandidates.filter(column => !relationshipColumns.has(column));
  const completeColumns = quality.filter(
    row => Number(row?.count) > 0 && Number(row?.null_fraction) === 0
  );
  const confidenceValues = [...correlations, ...lags]
    .map(row => String(row?.confidence || '').trim().toLowerCase())
    .filter(Boolean);
  const allLowConfidence =
    confidenceValues.length > 0 && confidenceValues.every(value => value === 'low');
  const correlationSamples = Array.from(new Set(
    correlations.map(row => Number(row?.sample_count)).filter(Number.isFinite)
  ));
  const lagSamples = Array.from(new Set(
    lags.map(row => Number(row?.sample_count)).filter(Number.isFinite)
  ));

  const lines = [];
  const range = Array.isArray(result.date_range) ? result.date_range.join(' to ') : '';
  lines.push(
    `Structured relationship analysis${range ? ` for ${range}` : ''}` +
    `${target ? ` with target ${target}` : ''}.`
  );
  if (quality.length) {
    lines.push(
      `Raw coverage: ${completeColumns.length}/${quality.length} columns have non-null observations with zero reported null fraction.` +
      ` This establishes source-data completeness for the window, not statistical reliability.`
    );
  }
  if (correlations.length) {
    lines.push(
      `Zero-lag results: ${correlations.map(row =>
        `${rowLabel(row)} r=${fmt(row.correlation)} (n=${Number(row.sample_count) || 0}, confidence=${row.confidence || 'unreported'})`
      ).join('; ')}.`
    );
  }
  if (lags.length) {
    lines.push(
      `Lag results: ${lags.map(row =>
        `${rowLabel(row)} ${row.interpretation || `lag_periods=${row.lag_periods}`} with r=${fmt(row.correlation)}` +
        ` (n=${Number(row.sample_count) || 0}, confidence=${row.confidence || 'unreported'})`
      ).join('; ')}.`
    );
  }
  if (omitted.length) {
    lines.push(
      `No correlation/lag row was returned for ${omitted.join(', ')}, although historian coverage exists.` +
      ` The structured result does not state why; constant values, insufficient variance, or an analysis filter are possibilities, not confirmed explanations.`
    );
  }
  if (allLowConfidence) {
    lines.push(
      `Inferential assessment: all returned relationships are low confidence` +
      `${correlationSamples.length ? ` (zero-lag n=${correlationSamples.join('/')})` : ''}` +
      `${lagSamples.length ? ` (lag n=${lagSamples.join('/')})` : ''}.` +
      ` The window supports exploratory association screening only and is insufficient for a reliable leading, synchronous, lagging, or causal conclusion.`
    );
  }

  result.relationship_quality_summary = {
    target_column: target,
    raw_coverage_column_count: quality.length,
    complete_raw_coverage_column_count: completeColumns.length,
    computed_relationship_columns: Array.from(relationshipColumns),
    columns_without_relationship_result: omitted,
    all_returned_relationships_low_confidence: allLowConfidence,
    zero_lag_sample_counts: correlationSamples,
    lag_sample_counts: lagSamples,
    interpretation_rule:
      'Raw coverage does not imply inferential sufficiency; absent relationship rows do not prove absent overlap.'
  };
  return lines.join('\n\n');
}

// ANALYSIS_COLUMN_SCALAR_NORMALIZATION_V6
// The analyzer may return a structured source identity in row.column. Keep the
// qualified column_id separately and expose the physical column as a scalar.
function scalarAnalysisColumn(row) {
  if (!row || typeof row !== 'object') return row;
  const source = row.column;
  const scalar = source && typeof source === 'object'
    ? asString(source.column || source.name || source.column_id)
    : asString(source);
  if (!scalar) return row;
  return { ...row, column: scalar };
}

if (normalizedToolName === 'arctic_analyze' && raw_result && typeof raw_result === 'object') {
  for (const key of [
    'period_profile',
    'data_quality',
    'baseline_comparison',
    'baseline_data_quality',
    'anomaly_windows',
    'ranked_correlations',
    'lag_findings'
  ]) {
    if (Array.isArray(raw_result[key])) {
      raw_result[key] = raw_result[key].map(scalarAnalysisColumn);
    }
  }
}

if (normalizedToolName === 'arctic_analyze') {
  const structuredSummary = structuredRelationshipSummary(raw_result, unit);
  if (structuredSummary) answer = structuredSummary;
}
// DIRECT_CANDIDATE_SEPARATION_V5
// "selected" describes direct semantic usability. Contextual candidates may
// still be validated by stats, but must remain candidates in final synthesis.
if (normalizedToolName === 'arctic_find_tags' && Array.isArray(tag_selection_trace)) {
  tag_selection_trace = tag_selection_trace.map(entry => {
    if (!entry || typeof entry !== 'object') return entry;
    const matchType = asString(entry.match_type).toLowerCase();
    if (matchType === 'contextual_match') return { ...entry, selected: false };
    if (matchType === 'direct_match') return { ...entry, selected: true };
    return { ...entry, selected: false };
  });
}

// STRUCTURED_MEMORY_SAFE_RESPONSE_AUTHORITY_V5
// The memory resolver has already determined whether the requested operation
// is supported by prior evidence. Preserve its explicit safe response instead
// of asking an executor model to paraphrase or synthesize a placeholder.
const structuredMemoryParams = unit && unit.params && typeof unit.params === 'object'
  ? unit.params
  : {};
const structuredMemorySafeResponse =
  unit && unit.tool === 'direct_response' &&
  String(structuredMemoryParams.mode || '').toLowerCase() === 'structured_memory_resolution' &&
  typeof structuredMemoryParams.safe_response === 'string' &&
  /[A-Za-z0-9\u3400-\u9fff]/.test(structuredMemoryParams.safe_response)
    ? structuredMemoryParams.safe_response.trim()
    : '';
if (structuredMemorySafeResponse) {
  answer = structuredMemorySafeResponse;
  parsed.claims = [];
  parsed.analysis_notes = [{
    note_type: 'conversation_memory',
    text: 'Used the structured memory resolver response without new retrieval.',
    related_evidence_indices: [],
    related_claim_indices: []
  }];
}

const completedEmptyLookup =
  normalizedToolName === 'arctic_find_tags' &&
  (!Array.isArray(tag_selection_trace) || tag_selection_trace.length === 0) &&
  raw_result &&
  typeof raw_result === 'object' &&
  Array.isArray(raw_result.tags) &&
  Number.isFinite(Number(raw_result.count)) &&
  Number(raw_result.count) === 0 &&
  !raw_result.error;
if (completedEmptyLookup) {
  raw_result.catalog_lookup_status = 'completed_zero_match';
  raw_result.existence_conclusion_allowed = false;
  raw_result.scope_limitation =
    'No metadata candidate was located by this query. Column or historian data absence was not tested.';
  answer =
    'No metadata candidate was located by the current catalog query. This result leaves the factor unresolved and does not prove that the historian lacks a corresponding column or non-null data.';
  parsed.claims = [];
}

const explicitToolError =
  !completedEmptyLookup && (
    /^error$/i.test(asString(parsed.status)) ||
    /^error$/i.test(asString(item.status)) ||
    Boolean(raw_result && raw_result.error) ||
    /^TOOL_(?:RUNTIME_)?ERROR$/i.test(asString(item.execution_status))
  );
let execution_status = explicitToolError
  ? 'TOOL_RUNTIME_ERROR'
  : (item.execution_status || 'SUCCESS');

if (!explicitToolError &&
  isNoEvidenceAnswer(answer) &&
  evidence_summary.length === 0 &&
  (!Number.isFinite(chunkCount) || chunkCount === 0)
) {
  answer = 'NO_EVIDENCE';
  execution_status = 'NO_EVIDENCE';
} else if (!explicitToolError) {
  if (!answer && evidence_summary.length) {
    answer = 'Retrieved evidence is available for downstream synthesis.';
  }
  execution_status = 'SUCCESS';
}

// SELECTED_TAG_PRECEDENCE_V5
const resolved_tags = (() => {
  const explicit = Array.isArray(parsed.resolved_tags) ? parsed.resolved_tags : [];
  if (explicit.length) return normalizeStringArray(explicit, 100);
  if (normalizedToolName === 'arctic_find_tags') {
    const vertical =
      asString(unit?.tag_selection_mode) === 'vertical_multi_query' ||
      Array.isArray(unit?.params?.queries);
    const picked = normalizeStringArray(
      (Array.isArray(tag_selection_trace) ? tag_selection_trace : [])
        .filter(entry => {
          if (!entry || entry.selected === false) return false;
          const matchType = asString(entry.match_type).toLowerCase();
          if (vertical) return entry.selected === true && matchType === 'direct_match';
          return matchType === 'direct_match' || matchType === 'contextual_match';
        })
        .map(entry => entry.tag || entry.name),
      100
    );
    if (picked.length) return picked;

    // CONVERSATION_CONFIRMED_TAG_READMISSION_V7
    // 执行器对同一批目录行会给出不一致的裁决：T6（exec 136067）把
    // PDRA3125.PV/PDRA3125B.PV 判为 direct_match，T7（exec 136068）同样的
    // desc_en「沉降器与二再差压」却判成 reject，resolved_tags 变空，
    // 于是 arctic_stats 因依赖未满足被分流、从不执行，整轮拿不到任何统计量。
    // 已在本对话里确认过的位号，不该被后一轮的一次翻脸作废。
    // 两个条件必须同时成立才收回：该位号在此前轮次的回答正文里出现过，
    // 且它确实在本轮目录候选中——既不凭空造位号，也不推翻已确认事实。
    const readmitted = (function () {
      try {
        const candidates = (Array.isArray(tag_selection_trace) ? tag_selection_trace : [])
          .map(e => asString(e && (e.tag || e.name)))
          .filter(Boolean);
        if (!candidates.length) return [];

        const state = (($('Capture context').first() || {}).json || {}).conversation_state || {};
        const priorText = []
          .concat(Array.isArray(state.turns) ? state.turns : [])
          .map(t => asString(t && t.assistant_answer))
          .concat((Array.isArray(state.question_memory_cards) ? state.question_memory_cards : [])
            .map(c => asString(c && c.current_answer_summary)))
          .concat((Array.isArray(state.arctic_target_registry) ? state.arctic_target_registry : [])
            .map(x => asString(x && x.tag)))
          .filter(Boolean)
          .join(' ')
          .toUpperCase();
        if (!priorText) return [];

        // 位号形状：字母前缀 + 数字 +（可选字母后缀/点后缀），纯结构判断
        const TAG_SHAPE = /^[A-Z]{2,6}\d{3,5}[A-Z]?(?:\.[A-Z]{2,4})?$/;
        const out = [];
        const seen = new Set();
        for (const tag of candidates) {
          const up = tag.toUpperCase();
          if (seen.has(up) || !TAG_SHAPE.test(up)) continue;
          // 去掉 .PV 之类后缀再找，前一轮可能只写了裸位号
          const bare = up.split('.')[0];
          if (priorText.indexOf(up) < 0 && priorText.indexOf(bare) < 0) continue;
          // EMPTY_CATALOG_DIRECT_VERIFY_V7：前序 fact_cards 对该位号只有未确认记录时不收回
          //（exec 147321：T6 回答把 PDIA203A、PDI36413C 列为不相关候选，fact_cards 记为 unconfirmed，原规则仍会收回）。
          const __facts = (Array.isArray(state.fact_cards) ? state.fact_cards : [])
            .filter(c => c && c.entity_type === 'tag' && asString(c.subject).toUpperCase().split('.')[0] === bare);
          if (__facts.length && !__facts.some(c => asString(c.status).toLowerCase() === 'confirmed')) continue;
          seen.add(up);
          out.push(tag);
          for (const entry of tag_selection_trace) {
            if (entry && asString(entry.tag || entry.name).toUpperCase() === up) {
              entry.selected = true;
              entry.match_type = 'readmitted_from_conversation';
              entry.selection_reason = '本对话此前轮次已确认该位号，且本轮目录候选中存在';
            }
          }
        }
        return normalizeStringArray(out, 100);
      } catch (e) {
        return [];
      }
    })();

    return readmitted;
  }
  if (normalizedToolName === 'arctic_read') {
    const nonNull = normalizeStringArray(raw_result?.non_null_columns || [], 100);
    const positiveExistence =
      raw_result?.existence_conclusion_allowed === true ||
      (raw_result?.presence_probe === true && nonNull.length > 0);
    return positiveExistence ? nonNull : [];
  }
  if (normalizedToolName !== 'arctic_stats') return [];

  const missing = new Set(normalizeStringArray(raw_result?.missing_columns || [], 100).map(x => x.toLowerCase()));
  const allNull = new Set(normalizeStringArray(raw_result?.all_null_columns || [], 100).map(x => x.toLowerCase()));
  const fromStats = raw_result?.column_stats && typeof raw_result.column_stats === 'object'
    ? Object.keys(raw_result.column_stats)
    : [];
  const returned = firstArray(
    fromStats,
    raw_result?.columns_analyzed,
    raw_result?.returned_columns,
    raw_result?.requested_columns
  );
  return normalizeStringArray(returned, 100)
    .filter(tag => !missing.has(tag.toLowerCase()) && !allNull.has(tag.toLowerCase()));
})();



// ===== DETERMINISTIC_FALLBACK_LAYER_V6 (ported from the merged branch) =====
// These only fire when the executor produced no claims/answer_items/analysis_notes,
// so they never override 5.0's tag-arbitration output.
function compactText(value, maxLen = 700) {
  const s = String(value || '').replace(/\s+/g, ' ').trim();
  return s.length <= maxLen ? s : s.slice(0, maxLen - 3).trim() + '...';
}

function stringArray(value, maxItems = 8) {
  if (!Array.isArray(value)) return [];
  const out = [];
  const seen = new Set();
  for (const item of value) {
    const text = compactText(item, 300);
    const key = text.toLowerCase();
    if (!text || seen.has(key)) continue;
    seen.add(key);
    out.push(text);
    if (out.length >= maxItems) break;
  }
  return out;
}

function extractValuePhrases(text, maxItems = 8) {
  const out = [];
  const seen = new Set();
  const patterns = [
    /\b\d{4}[-/]\d{1,2}[-/]\d{1,2}\b/g,
    /\b\d{1,2}:\d{2}\b/g,
    /[<>]=?\s*\d+(?:\.\d+)?\s*(?:C\b|t\/h|%|kPa|KPa|MPa|ppm|g\/l|kg\/h|m3\/h|m3\/hr|min|minutes?|s\b|vol%|wt%)/gi,
    /\b\d+(?:\.\d+)?\s*(?:C\b|t\/h|%|kPa|KPa|MPa|ppm|g\/l|kg\/h|m3\/h|m3\/hr|min|minutes?|s\b|vol%|wt%)\b/gi,
    /\b\d+(?:\.\d+)?\s*[-~]\s*\d+(?:\.\d+)?\s*(?:C\b|t\/h|%|kPa|KPa|MPa|ppm|g\/l|kg\/h|m3\/h|m3\/hr|min|minutes?|s\b|vol%|wt%)?/gi
  ];

  for (const pattern of patterns) {
    let match;
    while ((match = pattern.exec(String(text || ''))) !== null) {
      const value = compactText(match[0], 120);
      const key = value.toLowerCase();
      if (!value || seen.has(key)) continue;
      seen.add(key);
      out.push(value);
      if (out.length >= maxItems) return out;
    }
  }
  return out;
}

function inferDeterministicItemType(questionPart, text) {
  const qp = String(questionPart || '').toLowerCase();
  const s = String(text || '').toLowerCase();

  if (qp.includes('target') || qp.includes('range') || /target|range|limit|setpoint|recommended|ideal|optimum|benchmark/.test(s)) return 'range';
  if (qp.includes('period') || qp.includes('trend') || qp.includes('comparison') || /mean|min|max|average|latest|sample|observed|during|period|monthly|202\d/.test(s)) return 'period_observation';
  if (qp.includes('event') || qp.includes('anomaly') || qp.includes('cause') || /incident|event|failure|fault|trip|alarm|upset|abnormal|shutdown/.test(s)) return 'data_finding';
  if (qp.includes('procedure') || qp.includes('action') || /procedure|action|adjust|increase|decrease|maintain|control|check/.test(s)) return 'action';
  if (qp.includes('factor') || qp.includes('correlation') || qp.includes('dependency') || /affect|impact|cause|lead to|result in|increase|decrease|improve|worsen|correlat|depend/.test(s)) return 'factor';
  if (qp.includes('definition') || qp.includes('explanation') || /definition|means|refers to|is defined/.test(s)) return 'mechanism';
  return 'context';
}

function inferDeterministicScope(questionPart, text) {
  const qp = String(questionPart || '').toLowerCase();
  const s = String(text || '').toLowerCase();

  if (qp.includes('period') || /\b202\d[-/]\d{1,2}|\b202\d\b|monthly|observed|sample|mean|min|max|latest/.test(s)) return 'measured_period_verification';
  if (qp.includes('target') || qp.includes('range') || /target|range|recommended|ideal|optimum|setpoint|limit/.test(s)) return 'recommended_range';
  if (qp.includes('event') || /incident|event|failure|fault|trip|alarm|upset|abnormal/.test(s)) return 'historical_monthly_observation';
  if (qp.includes('definition') || qp.includes('factor') || qp.includes('cause') || qp.includes('relationship')) return 'general_knowledge';
  return 'other';
}

function evidenceIdForIndex(evidenceSummary, evidenceDigest, index) {
  const fromDigest = evidenceDigest[index] && evidenceDigest[index].evidence_id;
  const fromSummary = evidenceSummary[index] && evidenceSummary[index].evidence_id;
  return asString(fromDigest) || asString(fromSummary) || ('E' + (index + 1));
}

function evidenceTextForDeterministicItem(digest, summary) {
  return compactText([
    digest && digest.document_name,
    digest && digest.dataset_name,
    digest && digest.section_title,
    digest && digest.content_summary,
    digest && stringArray(digest.key_points).join(' '),
    digest && stringArray(digest.key_values).join(' '),
    digest && stringArray(digest.operational_actions).join(' '),
    digest && stringArray(digest.limitations).join(' '),
    digest && digest.relevance_to_question,
    digest && digest.snippet,
    summary && summary.snippet
  ].filter(Boolean).join(' '), 1400);
}

function buildDeterministicAnswerItems(evidenceDigest, evidenceSummary, unit) {
  const params = unit && unit.params && typeof unit.params === 'object' ? unit.params : {};
  const requestedLimit = Number(params.deterministic_answer_item_limit ?? params.post_rag_answer_item_limit ?? 24);
  const maxItems = Number.isFinite(requestedLimit) && requestedLimit > 0 ? Math.min(40, requestedLimit) : 24;
  const qp = unit && unit.question_part || 'other';
  const out = [];
  const seen = new Set();
  const digest = Array.isArray(evidenceDigest) ? evidenceDigest : [];
  const summary = Array.isArray(evidenceSummary) ? evidenceSummary : [];

  for (let i = 0; i < Math.max(digest.length, summary.length); i += 1) {
    if (out.length >= maxItems) break;
    const d = digest[i] && typeof digest[i] === 'object' ? digest[i] : {};
    const s = summary[i] && typeof summary[i] === 'object' ? summary[i] : {};
    const text = evidenceTextForDeterministicItem(d, s);
    if (!text) continue;

    const evidenceId = evidenceIdForIndex(summary, digest, i);
    const key = [
      evidenceId,
      compactText(d.section_title || s.section_title || '', 120).toLowerCase(),
      compactText(d.content_summary || d.snippet || s.snippet || '', 220).toLowerCase()
    ].join('|');
    if (seen.has(key)) continue;
    seen.add(key);

    const values = stringArray(d.key_values, 6);
    const extractedValues = extractValuePhrases(text, 6);
    const actions = stringArray(d.operational_actions, 4);
    const limitations = stringArray(d.limitations, 3);
    const itemType = inferDeterministicItemType(qp, text);

    out.push({
      answer_item_id: 'deterministic_evidence_item_' + (out.length + 1),
      item_type: itemType,
      subject: compactText(d.section_title || s.section_title || d.document_name || s.document_name || ('Retrieved evidence ' + (i + 1)), 300),
      relationship: compactText(d.content_summary || d.snippet || s.snippet || text, 700),
      direction_or_condition: compactText(d.relevance_to_question || actions.join('; ') || '', 350),
      value_or_range: compactText([].concat(values, extractedValues).join(', '), 300),
      scope: inferDeterministicScope(qp, text),
      evidence_indices: [i + 1],
      evidence_ids: [evidenceId],
      importance: out.length < 16 ? 'primary' : 'secondary',
      confidence: Number(s.retrieval_score) >= 0.5 || Number(d.post_rag_rank_score) >= 0.35 ? 'high' : 'medium',
      notes: compactText([
        d.document_name || s.document_name,
        d.dataset_name || s.dataset_name,
        d.page_start || s.page_start ? 'page ' + (d.page_start || s.page_start) : '',
        limitations.length ? 'Limitations: ' + limitations.join('; ') : ''
      ].filter(Boolean).join('; '), 500)
    });
  }

  return out;
}

function buildDeterministicClaims(answerItems) {
  const out = [];
  const maxClaims = 16;
  for (const item of answerItems || []) {
    if (out.length >= maxClaims) break;
    const claimText = compactText([item.subject, item.relationship].filter(Boolean).join(': '), 900);
    if (!claimText) continue;

    const itemType = String(item.item_type || '').toLowerCase();
    const evidenceType =
      itemType === 'range' ? 'recommended_or_target_range' :
      itemType === 'period_observation' || itemType === 'data_finding' ? 'historical_observation' :
      itemType === 'factor' || itemType === 'mechanism' ? 'directional_effect' :
      'other';

    out.push({
      claim_text: claimText,
      evidence_type: evidenceType,
      scope: item.scope || 'other',
      supports_question_part: unit && unit.question_part || 'other',
      inferential_use: item.importance === 'primary' ? 'main_effect' : 'secondary_context',
      analysis_note: compactText(item.direction_or_condition || item.notes || '', 400),
      supported_by_evidence_indices: Array.isArray(item.evidence_indices) ? item.evidence_indices : []
    });
  }
  return out;
}

function buildDeterministicAnalysisNotes(evidenceSummary, evidenceDigest, rawResult) {
  const notes = [{
    note_type: 'deterministic_unit_summary',
    text: 'Skipped the unit-level Answer Synthesizer LLM. The workflow preserved ranked RAG evidence directly as deterministic claims and answer_items for the final answer pass.',
    related_evidence_indices: [],
    related_claim_indices: []
  }];

  const variantFailures = rawResult && Array.isArray(rawResult.variant_failures) ? rawResult.variant_failures : [];
  if (variantFailures.length) {
    notes.push({
      note_type: 'retrieval_warning',
      text: 'Some RAGFlow query variants failed or timed out: ' + variantFailures.map(x => compactText((x.variant_id || 'variant') + ': ' + (x.error || 'failed'), 180)).join(' | '),
      related_evidence_indices: [],
      related_claim_indices: []
    });
  }

  return notes;
}

function enrichArcticEvidence() {
  const toolName = String((parsed && parsed.tool) || (unit && unit.tool) || '');
  if (toolName.indexOf('arctic_') !== 0) return;

  const answerText = String((parsed && parsed.answer) || '').replace(/\s+/g, ' ').trim();
  if (!answerText) return;

  const rr = raw_result && typeof raw_result === 'object' ? raw_result : {};
  const up = unit && unit.params && typeof unit.params === 'object' ? unit.params : {};
  const firstTarget = Array.isArray(rr.targets) && rr.targets.length ? rr.targets[0] : {};
  const library = up.library || firstTarget.library || '';
  const symbol = up.symbol || firstTarget.symbol || '';

  const range =
    Array.isArray(rr.time_range) && rr.time_range.length ? rr.time_range.join(' -> ') :
    Array.isArray(rr.date_range) && rr.date_range.length ? rr.date_range.join(' -> ') :
    Array.isArray(up.date_range) && up.date_range.length ? up.date_range.join(' -> ') : '';

  const facts = [];
  if (rr.row_count != null) facts.push('row_count=' + rr.row_count);
  if (rr.count != null) facts.push('matches=' + rr.count);
  if (range) facts.push('range=' + range);
  if (Array.isArray(rr.columns_analyzed) && rr.columns_analyzed.length) {
    facts.push('columns=' + rr.columns_analyzed.slice(0, 12).join(', '));
  }

  const target = [library, symbol].filter(Boolean).join('/');
  const enriched = {
    document_id: null,
    document_name: target || 'ArcticDB',
    dataset_name: 'ArcticDB',
    page_start: null,
    page_end: null,
    section_title: [toolName, target].filter(Boolean).join(' | '),
    snippet: (facts.length ? '[' + facts.join('; ') + '] ' : '') + answerText.slice(0, 3000),
    retrieval_score: null,
    source_type: 'arcticdb'
  };

  // Drop the label-only placeholders; keep any entry that already carries real text.
  const generic = /^ArcticDB (tag catalog|sensor statistics|computed analysis|rows)$/i;
  const kept = evidence_summary.filter(function (e) {
    return e && e.snippet && !generic.test(String(e.snippet).trim());
  });

  evidence_summary.length = 0;
  evidence_summary.push(enriched);
  for (let i = 0; i < kept.length; i += 1) evidence_summary.push(kept[i]);
}

const deterministicAnswerItems = buildDeterministicAnswerItems(evidence_digest, evidence_summary, unit);
const deterministicClaims = buildDeterministicClaims(deterministicAnswerItems);
const deterministicAnalysisNotes = buildDeterministicAnalysisNotes(evidence_summary, evidence_digest, raw_result);
const normalizedClaims = Array.isArray(parsed.claims) && parsed.claims.length ? parsed.claims : deterministicClaims;
const normalizedAnswerItems = Array.isArray(parsed.answer_items) && parsed.answer_items.length ? parsed.answer_items : deterministicAnswerItems;
const normalizedAnalysisNotes = Array.isArray(parsed.analysis_notes) && parsed.analysis_notes.length ? parsed.analysis_notes : deterministicAnalysisNotes;
// ===== end DETERMINISTIC_FALLBACK_LAYER_V6 =====

return [{
  json: toPublicMongoContractDeep({
    ...stripOutputField(item),
    executor_output: item.output || item.tool_answer || item.answer || '',
    completed_units: carriedCompleted,
    unit,
    tool: normalizedToolName || 'ragflow_retrieval',
    status: parsed.status || item.status || 'ok',
    answer,
    claims: normalizedClaims,
    answer_items: normalizedAnswerItems,
    analysis_notes: normalizedAnalysisNotes,
    evidence_summary,
    evidence_digest,
    factor_inventory,
    tag_selection_trace,
    resolved_tags,
    raw_result,
    normalized_result: {
      answer,
      claims: normalizedClaims,
    answer_items: normalizedAnswerItems,
