function safeParse(x) {
  if (x && typeof x === 'object' && !Array.isArray(x)) return x;
  if (typeof x !== 'string') return {};
  const cleaned = x
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
  if (!cleaned) return {};
  try {
    return JSON.parse(cleaned);
  } catch {
    return {};
  }
}

function asString(x) {
  return typeof x === 'string' ? x.trim() : '';
}

function emptyChunks(v) {
  if (v == null) return false;

  if (typeof v === 'string') {
    try {
      return emptyChunks(JSON.parse(v));
    } catch {
      return false;
    }
  }

  if (Array.isArray(v?.chunks)) return v.chunks.length === 0;
  if (Array.isArray(v)) return v.some(e => emptyChunks(e));
  if (typeof v === 'object') return Object.values(v).some(e => emptyChunks(e));

  return false;
}

function oneOf(v, allowed, fallback) {
  const s = asString(v);
  return allowed.includes(s) ? s : fallback;
}

function normalizeClaim(c) {
  if (!c || typeof c !== 'object' || Array.isArray(c)) return null;

  const claim_text = asString(c.claim_text || c.text);
  if (!claim_text) return null;

  const supported_by_evidence_indices = Array.isArray(c.supported_by_evidence_indices)
    ? c.supported_by_evidence_indices
        .map(v => Number(v))
        .filter(v => Number.isFinite(v) && v > 0)
    : [];

  return {
    claim_text,
    evidence_type: oneOf(c.evidence_type, [
      'directional_effect',
      'documented_operating_value',
      'recommended_or_target_range',
      'historical_observation',
      'indirect_upstream_influence',
      'measured_verification',
      'other'
    ], 'other'),
    scope: oneOf(c.scope, [
      'general_knowledge',
      'reference_value',
      'historical_monthly_observation',
      'recommended_range',
      'measured_period_verification',
      'context_only',
      'other'
    ], 'other'),
    supports_question_part: oneOf(c.supports_question_part, [
      'factor_identification',
      'target_or_ideal_range',
      'period_verification',
      'relationship_lookup',
      'structured_lookup',
      'other'
    ], 'other'),
    inferential_use: oneOf(c.inferential_use, [
      'main_effect',
      'secondary_context',
      'target_range',
      'period_evidence',
      'insufficient_context'
    ], 'insufficient_context'),
    analysis_note: asString(c.analysis_note),
    supported_by_evidence_indices
  };
}

function normalizeClaims(arr) {
  if (!Array.isArray(arr)) return [];
  const out = [];
  for (const c of arr) {
    const n = normalizeClaim(c);
    if (n) out.push(n);
  }
  return out;
}

function normalizeAnswerItem(x) {
  if (!x || typeof x !== 'object' || Array.isArray(x)) return null;
  const subject = asString(x.subject || x.parameter || x.signal_name || x.name);
  const relationship = asString(x.relationship || x.effect || x.finding || x.claim_text || x.text);
  const notes = asString(x.notes || x.analysis_note || x.summary);
  if (!subject && !relationship && !notes) return null;

  const evidence_indices = Array.isArray(x.evidence_indices)
    ? x.evidence_indices.map(v => Number(v)).filter(v => Number.isFinite(v) && v > 0)
    : (Array.isArray(x.supported_by_evidence_indices)
        ? x.supported_by_evidence_indices.map(v => Number(v)).filter(v => Number.isFinite(v) && v > 0)
        : []);

  const evidence_ids = Array.isArray(x.evidence_ids)
    ? x.evidence_ids.map(v => asString(v)).filter(Boolean)
    : [];

  return {
    item_type: oneOf(x.item_type || x.type, [
      'factor',
      'range',
      'period_observation',
      'mechanism',
      'action',
      'limitation',
      'data_finding',
      'context'
    ], 'context'),
    subject,
    relationship,
    direction_or_condition: asString(x.direction_or_condition || x.condition || x.direction),
    value_or_range: asString(x.value_or_range || x.value || x.range),
    scope: oneOf(x.scope, [
      'general_knowledge',
      'reference_value',
      'historical_monthly_observation',
      'recommended_range',
      'measured_period_verification',
      'context_only',
      'other'
    ], 'other'),
    evidence_indices,
    evidence_ids,
    importance: oneOf(x.importance, ['primary', 'secondary', 'context'], 'secondary'),
    confidence: oneOf(x.confidence, ['high', 'medium', 'low'], 'medium'),
    notes
  };
}

function normalizeAnswerItems(arr) {
  if (!Array.isArray(arr)) return [];
  const out = [];
  for (const x of arr) {
    const n = normalizeAnswerItem(x);
    if (n) out.push(n);
  }
  return out;
}

function chooseAnswerItems(upstream, synthesized) {
  const up = normalizeAnswerItems(upstream);
  const sy = normalizeAnswerItems(synthesized);
  if (sy.length) return sy;
  if (up.length) return up;
  return [];
}

function claimSpecificityScore(claims) {
  if (!Array.isArray(claims) || !claims.length) return 0;

  let score = 0;
  for (const c of claims) {
    score += 1;
    if (c.evidence_type && c.evidence_type !== 'other') score += 3;
    if (c.scope && c.scope !== 'other') score += 2;
    if (c.supports_question_part && c.supports_question_part !== 'other') score += 3;
    if (c.inferential_use && c.inferential_use !== 'insufficient_context') score += 3;
    if (Array.isArray(c.supported_by_evidence_indices) && c.supported_by_evidence_indices.length > 0) score += 1;
    if (c.analysis_note) score += 1;
  }
  return score;
}

function chooseClaims(upstreamClaims, synthesizedClaims) {
  const up = normalizeClaims(upstreamClaims);
  const sy = normalizeClaims(synthesizedClaims);

  if (up.length && !sy.length) return up;
  if (!up.length && sy.length) return sy;
  if (!up.length && !sy.length) return [];

  const upScore = claimSpecificityScore(up);
  const syScore = claimSpecificityScore(sy);

  return upScore >= syScore ? up : sy;
}

function chooseArray(upstream, synthesized) {
  const up = Array.isArray(upstream) ? upstream : [];
  const sy = Array.isArray(synthesized) ? synthesized : [];
  if (up.length) return up;
  if (sy.length) return sy;
  return [];
}

function isNoEvidenceAnswer(answer) {
  const s = asString(answer);
  return (
    !s ||
    s === 'NO_EVIDENCE' ||
    s === 'No answer found in the knowledge base.' ||
    s === '知识库中未找到答案。'
  );
}

const item = $input.first().json || {};

if (item.execution_status === 'DEPENDENCY_BLOCKED') {
  return [{ json: item }];
}
if (item.execution_status === 'SKIPPED') {
  return [{ json: { ...item, execution_status: 'DEPENDENCY_BLOCKED' } }];
}

const synthOut = safeParse(item.output || {});
const normalized = (item.normalized_result && typeof item.normalized_result === 'object')
  ? item.normalized_result
  : safeParse(item.normalized_result || {});

const upstreamClaims =
  Array.isArray(normalized.claims) ? normalized.claims :
  Array.isArray(item.claims) ? item.claims : [];

const synthesizedClaims =
  Array.isArray(synthOut.claims) ? synthOut.claims : [];

const claims = chooseClaims(upstreamClaims, synthesizedClaims);

const answer_items = chooseAnswerItems(
  Array.isArray(normalized.answer_items) ? normalized.answer_items : item.answer_items,
  synthOut.answer_items
);

const evidence = chooseArray(
  Array.isArray(normalized.evidence_summary) ? normalized.evidence_summary : item.evidence_summary,
  synthOut.evidence_summary
);

const analysis_notes = chooseArray(
  Array.isArray(normalized.analysis_notes) ? normalized.analysis_notes : item.analysis_notes,
  synthOut.analysis_notes
);

const answer =
  asString(synthOut.answer) ||
  asString(normalized.answer) ||
  asString(item.tool_answer) ||
  asString(item.answer);

const raw_result =
  normalized.raw_result ||
  synthOut.raw_result ||
  item.raw_result ||
  {};

let execStatus = 'SUCCESS';

if (
  isNoEvidenceAnswer(answer) ||
  ((!claims.length) && emptyChunks(raw_result))
) {
  execStatus = 'NO_EVIDENCE';
}

return [{
  json: {
    ...item,
    answer: isNoEvidenceAnswer(answer) ? 'NO_EVIDENCE' : answer,
    claims,
    answer_items,
    analysis_notes,
    evidence_summary: evidence,
    raw_result,
    execution_status: execStatus
  }
}];

// MONGODB_FINAL_AGGREGATION_BOUNDARY_V1
// Preserve the aggregator's established internals while enforcing MongoDB
// names on every external input and output, including evidence provenance.
const MONGO_TO_INTERNAL_TOOL = Object.freeze({
  mongo_find_tags: 'arctic_find_tags',
  mongo_resolve_factors: 'arctic_resolve_factors',
  mongo_read: 'arctic_read',
  mongo_stats: 'arctic_stats',
  mongo_analyze: 'arctic_analyze',
  mongo_describe: 'arctic_describe'
});
const INTERNAL_TO_MONGO_TOOL = Object.freeze(
  Object.fromEntries(Object.entries(MONGO_TO_INTERNAL_TOOL).map(([mongo, internal]) => [internal, mongo]))
);

function replaceAggregationVocabulary(value, direction) {
  let out = String(value == null ? '' : value);
  const replacements = direction === 'internal'
    ? { ...MONGO_TO_INTERNAL_TOOL, MongoDB: 'ArcticDB', mongodb_: 'arctic_', mongodb: 'arcticdb' }
    : { ...INTERNAL_TO_MONGO_TOOL, ArcticDB: 'MongoDB', arctic_: 'mongodb_', arcticdb: 'mongodb' };
  for (const [from, to] of Object.entries(replacements)) {
    out = out.replace(new RegExp(`\\b${from}`, 'g'), to);
  }
  return out;
}

function aggregationContractKey(key, direction) {
  if (direction === 'internal') {
    if (MONGO_TO_INTERNAL_TOOL[key]) return MONGO_TO_INTERNAL_TOOL[key];
    if (key.startsWith('mongo_analyze_')) return key.replace(/^mongo_analyze_/, 'arctic_analyze_');
    if (key === 'mongodb_target_registry') return 'arctic_target_registry';
    if (key === 'mongodb') return 'arctic';
    return key;
  }
  if (INTERNAL_TO_MONGO_TOOL[key]) return INTERNAL_TO_MONGO_TOOL[key];
  if (key.startsWith('arctic_analyze_')) return key.replace(/^arctic_analyze_/, 'mongo_analyze_');
  if (key === 'arctic_target_registry') return 'mongodb_target_registry';
  if (key === 'arctic') return 'mongodb';
  return key;
}

function translateAggregationContract(value, direction) {
  if (Array.isArray(value)) return value.map(v => translateAggregationContract(v, direction));
  if (typeof value === 'string') return replaceAggregationVocabulary(value, direction);
  if (!value || typeof value !== 'object') return value;

  const out = {};
  for (const [key, child] of Object.entries(value)) {
    out[aggregationContractKey(key, direction)] = translateAggregationContract(child, direction);
  }

  const toInternal = direction === 'internal';
  const historianObject = toInternal
    ? (String(out.tool || '').startsWith('arctic_') ||
      (Object.prototype.hasOwnProperty.call(out, 'database') && Object.prototype.hasOwnProperty.call(out, 'collection')))
    : (String(out.tool || '').startsWith('mongo_') ||
      (Object.prototype.hasOwnProperty.call(out, 'library') && Object.prototype.hasOwnProperty.call(out, 'symbol')));

  if (historianObject && toInternal) {
    if (out.library == null && out.database != null) out.library = out.database;
    if (out.symbol == null && out.collection != null) out.symbol = out.collection;
    delete out.database;
    delete out.collection;
  } else if (historianObject) {
    if (out.database == null && out.library != null) out.database = out.library;
    if (out.collection == null && out.symbol != null) out.collection = out.symbol;
    delete out.library;
    delete out.symbol;
  }
  return out;
}

function toInternalAggregationContract(value) {
  return translateAggregationContract(value, 'internal');
}

function toPublicMongoAggregationContract(value) {
  return translateAggregationContract(value, 'public');
}

