  const cleaned = x
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
  if (!cleaned) return {};
  try {
    return JSON.parse(cleaned);
  } catch {}

  const fencedBlocks = Array.from(cleaned.matchAll(/```(?:json)?\s*([\s\S]*?)```/gi))
    .map(m => m && m[1] ? m[1].trim() : '')
    .filter(Boolean);
  let fallbackParsed = null;
  for (const block of fencedBlocks) {
    try {
      const parsed = JSON.parse(block);
      if (parsed && typeof parsed === 'object' && (parsed.tool || parsed.status || parsed.answer || parsed.raw_result)) {
        return parsed;
      }
      fallbackParsed = parsed;
    } catch {}
  }
  if (fallbackParsed && typeof fallbackParsed === 'object') return fallbackParsed;

  const first = cleaned.indexOf('{');
  const last = cleaned.lastIndexOf('}');
  if (first >= 0 && last > first) {
    try {
      return JSON.parse(cleaned.slice(first, last + 1));
    } catch {}
  }

  return {};
}

