    parsedToolAnswer.analysis_notes
  ];

  const evidenceSources = [
    u.evidence_summary,
    parsedNormalized.evidence_summary,
    parsedOutput.evidence_summary,
    parsedToolAnswer.evidence_summary
  ];

  const digestSources = [
    u.evidence_digest,
    parsedNormalized.evidence_digest,
    parsedOutput.evidence_digest,
    parsedToolAnswer.evidence_digest
  ];

  const rawResult =
    u.raw_result ||
    parsedNormalized.raw_result ||
    parsedOutput.raw_result ||
    parsedToolAnswer.raw_result ||
    {};

  const answers = [
    u.answer,
    parsedNormalized.answer,
    parsedOutput.answer,
    parsedToolAnswer.answer,
    u.tool_answer
  ];

  let claims = [];
  for (const src of claimsSources) {
    if (Array.isArray(src) && src.length) {
      claims = src;
      break;
    }
  }

  let analysis_notes = [];
  for (const src of analysisSources) {
    if (Array.isArray(src) && src.length) {
      analysis_notes = src;
      break;
    }
  }

  let evidence = [];
  for (const src of evidenceSources) {
    if (Array.isArray(src) && src.length) {
      evidence = src;
      break;
    }
  }

  let digest = [];
  for (const src of digestSources) {
    if (Array.isArray(src) && src.length) {
      digest = src;
      break;
    }
  }

  let answer = '';
  for (const a of answers) {
    const s = asString(a);
    if (s) {
      answer = s;
      break;
    }
  }

  return { claims, analysis_notes, evidence_summary: evidence, evidence_digest: digest, raw_result: rawResult, answer };
}

function flattenAndDedup(items) {
  const flat = [];

  for (const j of items) {
    if (Array.isArray(j.completed_units) && j.completed_units.length) {
      for (const u of j.completed_units) flat.push(u);
    } else if (j.unit_id != null || j.tool) {
      flat.push(j);
    }
  }

  const m = new Map();

  for (const u of flat) {
    const key = u.unit_id != null
      ? ('id:' + u.unit_id)
      : ('tool:' + (u.tool || '') + ':' + (u.answer || ''));

    const prev = m.get(key);

    if (!prev) {
      m.set(key, u);
      continue;
    }

    const score = function(x) {
      const ex = extractStructuredFromUnit(x);
      return (asString(ex.answer) ? 2 : 0)
        + ((x.execution_status && x.execution_status !== 'UNKNOWN') ? 1 : 0)
        + ((Array.isArray(ex.evidence_summary) && ex.evidence_summary.length > 0) ? 2 : 0)
        + ((Array.isArray(ex.claims) && ex.claims.length > 0) ? 5 : 0)
        + ((Array.isArray(ex.analysis_notes) && ex.analysis_notes.length > 0) ? 2 : 0);
    };

    if (score(u) > score(prev)) m.set(key, u);
  }

  return Array.from(m.values()).sort(function(a, b) {
    return Number(a.unit_id || 0) - Number(b.unit_id || 0);
  });
}

function sourceTypeForUnit(u, ev) {
  const explicit = asString(ev && ev.source_type);
  const tool = asString(u && u.tool);
  if (tool.startsWith('arctic_') || tool === 'mean_tool') {
    if (tool === 'arctic_analyze') return 'arctic_computed_analysis';
    if (tool === 'arctic_stats') return 'arctic_sensor_statistics';
    if (tool === 'arctic_read') return 'arctic_sensor_data';
    if (tool === 'arctic_find_tags') return 'arctic_tag_catalog';
    if (tool === 'arctic_describe') return 'arctic_schema';
    return 'arctic';
  }
  if (tool === 'ragflow_retrieval') return explicit || 'ragflow';
  if (tool === 'neo4j_query') return explicit || 'neo4j';
  if (tool === 'postgres_query') return explicit || 'postgres';
  return explicit || asString(u && u.source_type) || 'unknown';
}

// ARCTIC_EVIDENCE_SNIPPET_DETAIL_V6
// 原实现在 executor 未给 snippet 时直接返回工具名（"ArcticDB tag catalog"），
// 位号、库表、统计值都在单元里却没进证据条目，DB 来源的引用因此无法追溯。
// 这里从 params 与 raw_result 组装可核对的摘要。
function normalizeEvidenceSnippetForTool(u, ev) {
  const tool = asString(u && u.tool);
  const snippet = typeof ev === 'string' ? ev : asString(ev && (ev.snippet || ev.text));
  if (snippet) return snippet;
  if (!/^arctic_/.test(tool)) return snippet;

  const p = (u && u.params) || {};
  const raw = (u && (u.raw_result || u.result)) || {};
  const parts = [];

  const lib = asString(p.library);
  const sym = asString(p.symbol);
  if (lib) parts.push(sym && sym !== lib ? `库 ${lib}/${sym}` : `库 ${lib}`);

  // 位号：优先取标签选择轨迹，其次取请求列
  const tags = [];
  const seen = new Set();
  const pushTag = (t, desc) => {
    const name = asString(typeof t === 'string' ? t : (t && (t.tag || t.name || t.column)));
    if (!name || seen.has(name)) return;
    seen.add(name);
    const d = asString(desc || (t && (t.description || t.desc_cn)));
    tags.push(d ? `${name}（${d}）` : name);
  };
  for (const t of (Array.isArray(u && u.tag_selection_trace) ? u.tag_selection_trace : [])) pushTag(t);
  for (const t of (Array.isArray(raw.tags) ? raw.tags : [])) pushTag(t);
  for (const c of (Array.isArray(p.columns) ? p.columns : [])) pushTag(c);
  if (tags.length) parts.push(`位号 ${tags.slice(0, 6).join('、')}${tags.length > 6 ? ` 等 ${tags.length} 个` : ''}`);

  const dr = Array.isArray(p.date_range) ? p.date_range.filter(Boolean) : [];
  if (dr.length >= 2) parts.push(`时间范围 ${dr[0]} 至 ${dr[1]}`);

  // 关键统计：行数、非空、均值、极值
  const stat = [];
  const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : null);
  const rows = num(raw.row_count != null ? raw.row_count : raw.rows);
  if (rows !== null) stat.push(`${rows.toLocaleString('en-US')} 行`);
  const nn = num(raw.non_null_count != null ? raw.non_null_count : raw.non_null);
  if (nn !== null) stat.push(`非空 ${nn.toLocaleString('en-US')}`);
  for (const [k, label] of [['mean', '均值'], ['min', '最小'], ['max', '最大']]) {
    const v = num(raw[k]);
    if (v !== null) stat.push(`${label} ${v}`);
  }
  if (stat.length) parts.push(stat.join('，'));

  const label = tool === 'arctic_analyze' ? 'ArcticDB 计算分析'
    : tool === 'arctic_stats' ? 'ArcticDB 统计'
    : tool === 'arctic_read' ? 'ArcticDB 读取'
    : tool === 'arctic_find_tags' ? 'ArcticDB 标签目录'
    : tool === 'arctic_describe' ? 'ArcticDB 结构' : 'ArcticDB';

  if (Number(raw.matches) === 0 || raw.no_match === true) parts.push('未匹配到标签');
  return parts.length ? `${label}：${parts.join('；')}` : label;
}

// DB_EVIDENCE_TAG_DETAIL_V6
// 数据库证据此前只落一句 snippet；位号名、中文说明、库/表、时间窗、统计值
// 都在 unit.params / raw_result 里却没进证据条目，引用无法核对到具体位号。
function buildTagDescriptionMap(units) {
  const map = new Map();
  const take = (t) => {
    const name = asString(typeof t === 'string' ? t : (t && (t.tag || t.name || t.column))).toUpperCase();
    if (!name) return;
    const cur = map.get(name) || {};
    const cn = asString(t && (t.desc_cn || t.description_cn || t.description));
    const en = asString(t && (t.desc_en || t.description_en));
    if (cn && !cur.desc_cn) cur.desc_cn = cn;
    if (en && !cur.desc_en) cur.desc_en = en;
    map.set(name, cur);
  };
  for (const u of (Array.isArray(units) ? units : [])) {
    for (const t of (Array.isArray(u && u.tag_selection_trace) ? u.tag_selection_trace : [])) take(t);
    for (const t of (Array.isArray(u && u.resolved_tags) ? u.resolved_tags : [])) take(t);
    const raw = (u && (u.raw_result || u.result)) || {};
    for (const t of (Array.isArray(raw.tags) ? raw.tags : [])) take(t);
  }
  return map;
}

function dbMetaForUnit(u, descMap) {
  const tool = asString(u && u.tool);
  if (!/^arctic_|^mean_tool$|^mongo/i.test(tool)) return null;

  const p = (u && u.params) || (u && u.unit && u.unit.params) || {};
  const raw = (u && (u.raw_result || u.result)) || {};
  const label = tool === 'arctic_analyze' ? 'ArcticDB 时序分析'
    : tool === 'arctic_stats' ? 'ArcticDB 描述统计'
    : tool === 'arctic_read' ? 'ArcticDB 历史读取'
    : tool === 'arctic_find_tags' ? 'ArcticDB 位号目录'
    : tool === 'arctic_describe' ? 'ArcticDB 表结构'
    : tool === 'mean_tool' ? 'ArcticDB 均值计算'
    : 'ArcticDB';

  const names = [];
  const seen = new Set();
  const push = (v) => {
    const n = asString(typeof v === 'string' ? v : (v && (v.tag || v.name || v.column)));
    if (!n || seen.has(n.toUpperCase())) return;
    seen.add(n.toUpperCase());
    names.push(n);
  };
  for (const t of (Array.isArray(raw.tags) ? raw.tags : [])) push(t);
  for (const c of (Array.isArray(raw.columns_analyzed) ? raw.columns_analyzed : [])) push(c);
  for (const c of (Array.isArray(raw.returned_columns) ? raw.returned_columns : [])) push(c);
  for (const t of (Array.isArray(u && u.tag_selection_trace) ? u.tag_selection_trace : [])) push(t);
  for (const c of (Array.isArray(p.columns) ? p.columns : [])) push(c);

  const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : null);
  const cs = (raw && typeof raw.column_stats === 'object' && raw.column_stats) ? raw.column_stats : {};
  const tags = names.slice(0, 20).map((n) => {
    const meta = (descMap && descMap.get(n.toUpperCase())) || {};
    const st = cs[n] || cs[String(n).toUpperCase()] || null;
    const bits = [];
    if (st && typeof st === 'object') {
      const c = num(st.count);
      if (c !== null) bits.push('样本 ' + c.toLocaleString('en-US'));
      const pairs = [['mean', '均值'], ['min', '最小'], ['max', '最大'], ['std', '标准差'], ['latest', '最新']];
      for (const pair of pairs) {
        const v = num(st[pair[0]]);
        if (v !== null) bits.push(pair[1] + ' ' + v);
      }
      const lt = asString(st.latest_timestamp);
      if (lt) bits.push('最新时间 ' + lt);
    }
    return {
      tag: n,
      desc_cn: asString(meta.desc_cn),
      desc_en: asString(meta.desc_en),
      stats: bits.join('｜')
    };
  });

  const tr = Array.isArray(raw.time_range) && raw.time_range.filter(Boolean).length >= 2
    ? raw.time_range.filter(Boolean)
    : (Array.isArray(p.date_range) ? p.date_range.filter(Boolean) : []);

  const meta = {
    tool,
    source_label: label,
    library: asString(raw.library || p.library),
    symbol: asString(raw.symbol || p.symbol),
    tags,
    date_range: tr.length >= 2 ? (tr[0] + ' ~ ' + tr[1]) : '',
    row_count: num(raw.row_count != null ? raw.row_count : raw.rows),
    matched: num(raw.count)
  };
  const missing = (Array.isArray(raw.missing_columns) ? raw.missing_columns : [])
    .concat(Array.isArray(raw.all_null_columns) ? raw.all_null_columns : []);
  if (missing.length) meta.unavailable = missing.join('、');
  return meta;
}

function assignEvidenceIds(units) {
  const idMap = new Map();
  const localRefMap = new Map();
  const enriched = [];
  const __tagDescMap = buildTagDescriptionMap(units);
  let counter = 1;

  for (const u of units) {
    const extracted = extractStructuredFromUnit(u);
    const evs = Array.isArray(extracted.evidence_summary) ? extracted.evidence_summary : [];

    for (let i = 0; i < evs.length; i++) {
      const ev = evs[i];
      // MULTI_UNIT_EVIDENCE_BALANCE_V5
      // Runtime evidence from separate execution units represents separate
      // windows/targets even when its generic snippet is identical.
      const baseKey = evidenceKey(ev);
      const runtimeScoped = /^arctic_|^mean_tool$/i.test(asString(u.tool));
      const key = runtimeScoped
        ? `unit:${String(u.unit_id)}|${baseKey}`
        : baseKey;

      if (!idMap.has(key)) {
        const eid = 'E' + counter++;
        idMap.set(key, eid);

        const entry =
          typeof ev === 'string'
            ? {
                evidence_id: eid,
                text: ev,
                snippet: normalizeEvidenceSnippetForTool(u, ev),
                source_type: sourceTypeForUnit(u, ev),
                unit_id: u.unit_id
              }
            : Object.assign({}, ev, {
                evidence_id: eid,
                snippet: normalizeEvidenceSnippetForTool(u, ev),
                source_type: sourceTypeForUnit(u, ev),
                unit_id: u.unit_id
              });

        const __dbm = dbMetaForUnit(u, __tagDescMap);
        if (__dbm) entry.db_meta = __dbm;

        enriched.push(entry);
      }

      localRefMap.set(String(u.unit_id) + ':' + String(i + 1), idMap.get(key));
    }
  }

  return { idMap, localRefMap, enriched };
}

function buildSourceStatus(units) {
  const bySource = { ragflow: [], arctic: [], neo4j: [], postgres: [] };

  for (const u of units) {
    const t = u.tool || '';
    const s = u.execution_status || 'UNKNOWN';

    if (t === 'ragflow_retrieval') bySource.ragflow.push(s);
    else if (t.startsWith('arctic_') || t === 'mean_tool') bySource.arctic.push(s);
    else if (t === 'neo4j_query') bySource.neo4j.push(s);
    else if (t === 'postgres_query') bySource.postgres.push(s);
  }

  function sum(arr) {
    if (!arr.length) return 'not_used';
    if (arr.every(function(s) { return s === 'SUCCESS'; })) return 'ok';
    if (arr.some(function(s) { return s === 'SUCCESS'; })) return 'partial';
    if (arr.some(function(s) { return s === 'DATE_RANGE_NO_DATA'; })) return 'date_range_no_data';
    if (arr.some(function(s) { return s === 'TAG_DISCOVERY_FAILED'; })) return 'tag_failed';
    if (arr.some(function(s) { return s === 'DEPENDENCY_BLOCKED'; })) return 'blocked';
    if (arr.some(function(s) { return s === 'TOOL_RUNTIME_ERROR'; })) return 'error';
    return 'none';
  }

  const reasons = [];
  if (bySource.arctic.some(function(s) { return s === 'DATE_RANGE_NO_DATA'; })) reasons.push('No sensor data in requested time range');
  if (bySource.arctic.some(function(s) { return s === 'TAG_DISCOVERY_FAILED'; })) reasons.push('No matching sensor tags found');
  if (units.some(function(u) { return u.execution_status === 'DEPENDENCY_BLOCKED'; })) reasons.push('Some steps blocked due to unmet upstream dependencies');

  return {
    ragflow: sum(bySource.ragflow),
    arctic: sum(bySource.arctic),
    neo4j: sum(bySource.neo4j),
    postgres: sum(bySource.postgres),
    missing_reason: reasons.length ? reasons.join('; ') : null
  };
}

function buildMissingFlags(units) {
  const flags = [];

  for (const u of units) {
    const s = u.execution_status;
    if (!s || s === 'SUCCESS' || s === 'not_used') continue;

    let reason = null;
    let effect = null;

    if (s === 'DEPENDENCY_BLOCKED') {
      reason = 'dependency_not_met';
      effect = u.blocked_judgment_note || ('Step ' + u.tool + ' could not execute because an upstream step did not succeed');
    } else if (s === 'DATE_RANGE_NO_DATA') {
      reason = 'date_range_no_data';
      effect = 'No data in the requested time range; period verification could not be completed';
    } else if (s === 'TAG_DISCOVERY_FAILED') {
      reason = 'no_relevant_tag_found';
      effect = 'No matching tags were found; downstream measurement lookup could not proceed';
    } else if (s === 'PARTIAL_DATA_COVERAGE') {
      reason = 'partial_data_coverage';
      effect = 'Only partial verification was possible from the returned data';
    } else if (s === 'TOOL_RUNTIME_ERROR') {
      reason = 'tool_error';
      effect = u.tool + ' failed to execute; related evidence was unavailable';
    } else if (s === 'NO_EVIDENCE') {
      reason = 'insufficient_doc_support';
      effect = u.tool + ' returned no usable content';
    } else if (s === 'CONTRACT_VIOLATION') {
      reason = 'tool_error';
      effect = u.tool + ' returned an unexpected response format';
    } else if (s === 'SKIPPED') {
      reason = 'skipped';
      effect = u.tool + ' was skipped in this run';
    }

    if (reason) {
      flags.push({
        unit_id: u.unit_id,
        tool: u.tool,
        reason,
        execution_status: s,
        blocked_by: u.blocked_by_unit_id ? ('step ' + u.blocked_by_unit_id + ' (' + u.blocked_by_tool + ', ' + u.blocked_by_status + ')') : null,
        effect_on_answer: effect
      });
    }
  }

  return flags;
}

function buildTagTrace(units) {
  const traces = [];
  // TAG_TRACE_METADATA_UPSERT_V5
  // Units are ordered by execution dependency, so a data/statistics unit may
  // mention a tag before its catalog-discovery unit. Keep stable display order
  // while allowing later, richer metadata to upgrade the existing trace.
  const traceIndexByTag = new Map();

  function targetInfoForUnit(u) {
    const p = (u && u.params) || {};
    return {
      library: asString(p.library),
      symbol: asString(p.symbol),
      target: asString(p.name || p.target)
    };
  }

  function normalizeTagName(value) {
    let tag = asString(value);
    if (!tag) return '';

    // arctic_analyze often reports column IDs as process.TI1708.PV,
    // lims.DG002_H2VolP, catalyst.EcatNi. Keep the real tag/column part.
    tag = tag.replace(/^(process|sensor|timeseries|lims|lab|catalyst)\./i, '');
    return tag.trim();
  }

  function looksLikeTag(value) {
    const tag = normalizeTagName(value);
    if (!tag) return false;
    if (/\s/.test(tag)) return false;
    if (/^[A-Za-z][A-Za-z0-9_]*(?:\.PV)?$/.test(tag)) return true;
    return false;
  }

  function addTrace(t, fallbackRank, defaults) {
    const tag = normalizeTagName(t && (t.tag || t.column || t.column_id || t.target_column_id || t.candidate_column_id));
    if (!looksLikeTag(tag)) return;

    const d = defaults || {};
    const library = asString(t.library) || asString(d.library);
    const symbol = asString(t.symbol) || asString(d.symbol);
    const target = asString(t.target) || asString(d.target);
    const source = asString(t.source) || asString(d.source) || 'arcticdb';
    const descEn = asString(t.desc_en);
    const descCn = asString(t.desc_cn);
    const semanticWhat = descEn || descCn;
    const locatorWhat = [target, library, symbol].filter(Boolean).join(' / ');
    const explicitWhat = asString(t.what_it_measures);
    const what = semanticWhat || explicitWhat || locatorWhat;
    const candidate = {
      tag,
      desc_cn: descCn,
      desc_en: descEn,
      rank: t.rank != null ? t.rank : fallbackRank,
      selection_query: asString(t.selection_query) || asString(d.selection_query),
      source,
      library,
      symbol,
      target,
      what_it_measures: what
    };

    const existingIndex = traceIndexByTag.get(tag);
    if (existingIndex == null) {
      traceIndexByTag.set(tag, traces.length);
      traces.push(candidate);
      return;
    }

    const existing = traces[existingIndex];
    const candidateHasSemantics = Boolean(candidate.desc_cn || candidate.desc_en);
    const existingHasSemantics = Boolean(existing.desc_cn || existing.desc_en);
    const candidateFromCatalog = candidate.source === 'arctic_find_tags';
    const existingFromCatalog = existing.source === 'arctic_find_tags';

    const merged = {
      ...existing,
      desc_cn: existing.desc_cn || candidate.desc_cn,
      desc_en: existing.desc_en || candidate.desc_en,
      selection_query: existing.selection_query || candidate.selection_query,
      library: existing.library || candidate.library,
      symbol: existing.symbol || candidate.symbol,
      target: existing.target || candidate.target
    };

    if (
      (!existingHasSemantics && candidateHasSemantics) ||
      (!existingFromCatalog && candidateFromCatalog && candidateHasSemantics)
    ) {
      merged.rank = candidate.rank;
      merged.source = candidate.source;
    }

    const mergedSemanticWhat = merged.desc_en || merged.desc_cn;
    if (mergedSemanticWhat) {
      merged.what_it_measures = mergedSemanticWhat;
    } else if (!asString(merged.what_it_measures)) {
      merged.what_it_measures = candidate.what_it_measures;
    }

    traces[existingIndex] = merged;
  }

  function parseTagLines(text, defaults) {
    const lines = String(text || '').split(/\r?\n/);

    for (const line of lines) {
      // Handles all current Arctic catalog display formats and preserves
      // internal unspaced pipes in LIMS descriptions, e.g. ??||??||??.
      const m = line.match(/^\s*(\d+)[.)]\s+([A-Za-z][A-Za-z0-9_]*(?:\.PV)?)\s*(?:\|\s*)?(.*)$/);
      if (!m) continue;

      const parts = asString(m[3]).split(/\s+\|\s+/).map(asString).filter(Boolean);
      const firstDesc = parts[0] || '';
      const secondDesc = parts[1] || '';
      const firstIsCn = /[\u4e00-\u9fff]/.test(firstDesc);
      const secondIsCn = /[\u4e00-\u9fff]/.test(secondDesc);

      addTrace({
        rank: Number(m[1]),
        tag: m[2],
        desc_en: firstIsCn ? secondDesc : firstDesc,
        desc_cn: firstIsCn ? firstDesc : (secondIsCn ? secondDesc : ''),
        selection_query: asString(defaults && defaults.selection_query),
        what_it_measures: firstIsCn ? (secondDesc || firstDesc) : (firstDesc || secondDesc)
      }, Number(m[1]), defaults);
    }
  }

  function addColumns(columns, defaults) {
    const arr = Array.isArray(columns) ? columns : [];
    for (const col of arr) addTrace({ tag: col }, traces.length + 1, defaults);
  }

  function addColumnId(value, defaults) {
    const tag = normalizeTagName(value);
    if (tag) addTrace({ tag }, traces.length + 1, defaults);
  }

  function parseTagClaims(claims, defaults) {
    const list = Array.isArray(claims) ? claims : [];
    for (const c of list) {
      const text = asString(c && (c.claim_text || c.text));
      if (!text) continue;

      // Common normalized forms from the Answer Synthesizer:
      // Tag TI1708.PV measures Furnace-C ... (Chinese: C?...)
      // Tag AR3101_2.PV and AR3101_2_24.PV both measure secondary ... (Chinese: ??...)
      const m = text.match(/\bTag\s+([A-Za-z][A-Za-z0-9_]*(?:\.PV)?)(?:\s+and\s+([A-Za-z][A-Za-z0-9_]*(?:\.PV)?))?\s+(?:both\s+)?measures?\s+(.+?)(?:\s*\(Chinese:\s*([^)]*)\))?[.?]?$/i);
      if (m) {
        const descEn = asString(m[3]).replace(/[.?]\s*$/, '');
        const descCn = asString(m[4]);
        addTrace({ tag: m[1], desc_en: descEn, desc_cn: descCn, what_it_measures: descEn || descCn }, traces.length + 1, defaults);
        if (m[2]) addTrace({ tag: m[2], desc_en: descEn, desc_cn: descCn, what_it_measures: descEn || descCn }, traces.length + 1, defaults);
        continue;
      }

      const contains = text.match(/\bcontains\s+tag\s+([A-Za-z][A-Za-z0-9_]*(?:\.PV)?)[,\s]+(?:which\s+)?(?:is|measures)\s+(.+?)(?:,\s*also described as\s+['"]?([^'"]+)['"]?)?[.?]?$/i);
      if (contains) {
        const descEn = asString(contains[2]).replace(/[.?]\s*$/, '');
        const descCn = asString(contains[3]);
        addTrace({ tag: contains[1], desc_en: descEn, desc_cn: descCn, what_it_measures: descEn || descCn }, traces.length + 1, defaults);
      }
    }
  }

  for (const u of units) {
    if (!u || !String(u.tool || '').startsWith('arctic_')) continue;

    const extracted = extractStructuredFromUnit(u);
    const raw = rawResultOfUnit(u) || {};
    const unitTarget = targetInfoForUnit(u);
    const defaults = {
      ...unitTarget,
      source: u.tool,
      selection_query: asString(u && u.params && u.params.query)
    };

    if (Array.isArray(u.tag_selection_trace)) {
      for (const t of u.tag_selection_trace) addTrace(t, traces.length + 1, defaults);
    }
    if (Array.isArray(extracted.tag_selection_trace)) {
      for (const t of extracted.tag_selection_trace) addTrace(t, traces.length + 1, defaults);
    }

    const parsedExecutorAnswer = safeParse(u.executor_answer || {});
    parseTagLines([
      extracted.answer,
      u.answer,
      parsedExecutorAnswer.answer,
      u.executor_answer,
      JSON.stringify(u.normalized_result || {})
    ].join('\n'), defaults);
    parseTagClaims(extracted.claims, defaults);
    parseTagClaims(u.claims, defaults);

    if (Array.isArray(raw.matches)) {
      for (const m of raw.matches) addTrace(m, traces.length + 1, defaults);
    }

    addColumns(raw.columns_analyzed, defaults);
    addColumns(raw.columns_requested, defaults);
    addColumns(u.columns_analyzed, defaults);
    addColumns(u.columns_requested, defaults);

    if (u.tool === 'arctic_analyze') {
      for (const p of Array.isArray(raw.period_profile) ? raw.period_profile : []) {
        addTrace({ tag: p.column, target: p.target }, traces.length + 1, { ...defaults, target: asString(p.target) });
      }
      for (const q of Array.isArray(raw.data_quality) ? raw.data_quality : []) {
        addTrace({ tag: q.column, target: q.target }, traces.length + 1, { ...defaults, target: asString(q.target) });
      }
      for (const c of Array.isArray(raw.ranked_correlations) ? raw.ranked_correlations : []) {
        addColumnId(c.target_column_id || c.target, defaults);
        addColumnId(c.candidate_column_id || c.candidate, defaults);
      }
      for (const l of Array.isArray(raw.lag_findings) ? raw.lag_findings : []) {
        addColumnId(l.target_column_id || l.target, defaults);
        addColumnId(l.candidate_column_id || l.candidate, defaults);
      }
      for (const a of Array.isArray(raw.anomaly_windows) ? raw.anomaly_windows : []) {
        addColumnId(a.column, defaults);
      }
      for (const t of Array.isArray(raw.targets) ? raw.targets : []) {
        const targetDefaults = {
          ...defaults,
          target: asString(t.name || t.target),
          library: asString(t.library),
          symbol: asString(t.symbol)
        };
        addColumns(t.requested_columns, targetDefaults);
        addColumns(t.returned_columns, targetDefaults);
        addColumns(t.numeric_columns, targetDefaults);
        addColumns(t.missing_columns, targetDefaults);
      }
    }
  }

  return traces;
}

function collectAnalysisNotes(units, localRefMap) {
  const notes = [];

  for (const u of units) {
    const extracted = extractStructuredFromUnit(u);
    const raw = Array.isArray(extracted.analysis_notes) ? extracted.analysis_notes : [];

    for (const n of raw) {
      if (!n || typeof n !== 'object') continue;
      const text = asString(n.text);
      if (!text) continue;

      const evidenceIds = uniqueStrings(
        (Array.isArray(n.related_evidence_indices) ? n.related_evidence_indices : [])
          .map(function(i) {
            return localRefMap.get(String(u.unit_id) + ':' + String(Number(i))) || '';
          })
      );

      notes.push({
        unit_id: u.unit_id,
        note_type: asString(n.note_type) || 'limitation',
        text,
        related_evidence_ids: evidenceIds
      });
    }
  }

  return notes;
}

function parseDateMs(v) {
  const s = asString(v).replace(' ', 'T');
  const ms = Date.parse(s);
  return Number.isFinite(ms) ? ms : null;
}

function rawResultOfUnit(u) {
  const direct = u && u.raw_result;
  if (direct && typeof direct === 'object' && !Array.isArray(direct)) return direct;

  const normalized = u && u.normalized_result && u.normalized_result.raw_result;
  if (normalized && typeof normalized === 'object' && !Array.isArray(normalized)) return normalized;

  const parsedOutput = safeParse((u && u.output) || {});
  if (parsedOutput.raw_result && typeof parsedOutput.raw_result === 'object' && !Array.isArray(parsedOutput.raw_result)) {
    return parsedOutput.raw_result;
  }

  return {};
}

function observedRangeMatchesRequested(u, rr) {
  const requested = Array.isArray(u && u.params && u.params.date_range) ? u.params.date_range : [];
  const observed = Array.isArray(rr && rr.time_range) ? rr.time_range : [];

  if (requested.length < 2 || observed.length < 2) return true;

  const reqStart = parseDateMs(requested[0]);
  const reqEnd = parseDateMs(requested[1]);
  const obsStart = parseDateMs(observed[0]);
  const obsEnd = parseDateMs(observed[1]);

  if (reqStart == null || reqEnd == null || obsStart == null || obsEnd == null) return false;
  return obsEnd >= reqStart && obsStart <= reqEnd;
}

// ARCTIC_ANALYZE_RECOVERY_AND_DISPLAY_SPACING_V5
function isMeasuredPeriodFallbackClaim(u, extracted, unitQuestionPart) {
  const tool = asString(u && u.tool);
  if (unitQuestionPart !== 'period_verification') return false;
  if (tool !== 'arctic_stats' && tool !== 'arctic_read' && tool !== 'arctic_analyze') return false;

  const text = asString(extracted && extracted.answer).toLowerCase();
  if (
    text.includes('not march 2025') ||
    text.includes('no data found') ||
    text.includes('not the requested') ||
    text.includes('outside the requested')
  ) {
    return false;
  }

  if (tool === 'arctic_analyze') {
    return /样本|数据|下降|上升|突变|波动|相关|滞后|同步|count|row_count|change|correlation|lag|trend/i.test(text);
  }

  const rr = rawResultOfUnit(u);
  const rowCount = Number(rr.row_count || rr.count || 0);
  if (!Number.isFinite(rowCount) || rowCount <= 0) return false;

  return observedRangeMatchesRequested(u, rr);
}

// STRUCTURED_ARCTIC_STATS_CONTRACT_V5
function finiteOrNull(value) {
  const n = Number(value);
  return value !== null && value !== '' && Number.isFinite(n) ? n : null;
}

function deterministicArcticStatsClaims(unit, evidenceIds, questionPart) {
  if (asString(unit?.tool) !== 'arctic_stats' || !evidenceIds.length) return [];
  const raw = rawResultOfUnit(unit);
  const stats = raw?.column_stats && typeof raw.column_stats === 'object' && !Array.isArray(raw.column_stats)
    ? raw.column_stats
    : {};
  const rowCount = finiteOrNull(raw.row_count);
  const claims = [];

  for (const [column, value] of Object.entries(stats)) {
    if (!column || !value || typeof value !== 'object' || Array.isArray(value)) continue;
    const count = finiteOrNull(value.count);
    const mean = finiteOrNull(value.mean);
    const min = finiteOrNull(value.min);
    const max = finiteOrNull(value.max);
    const std = finiteOrNull(value.std);
    const latest = finiteOrNull(value.latest);
    const nullRate = rowCount != null && rowCount > 0 && count != null
      ? Math.max(0, Math.min(1, (rowCount - count) / rowCount))
      : null;
    const constant = value.constant === true || (min != null && max != null && min === max) || std === 0;
    const parts = [
      `${column}: count=${count ?? 'unknown'}`,
      `mean=${mean ?? 'unknown'}`,
      `min=${min ?? 'unknown'}`,
      `max=${max ?? 'unknown'}`,
      `latest=${latest ?? 'unknown'}`,
      `latest_timestamp=${asString(value.latest_timestamp) || 'unknown'}`,
      `null_rate=${nullRate == null ? 'unknown' : nullRate}`,
      `constant=${constant}`
    ];
    claims.push({
      unit_id: unit.unit_id,
      tool: unit.tool,
      source_type: 'sensor_data',
      claim_text: parts.join(', '),
      evidence_type: 'measured_verification',
      scope: 'measured_period_verification',
      supports_question_part: normalizeQuestionPart(questionPart || 'period_verification'),
      inferential_use: 'period_evidence',
      analysis_note: 'Deterministically preserved from ArcticDB structured statistics; no tag meaning or engineering unit inferred.',
      supported_by_evidence_ids: evidenceIds
    });
  }

  const requested = uniqueStrings(Array.isArray(raw.requested_columns) ? raw.requested_columns : []);
  const returned = uniqueStrings(Array.isArray(raw.returned_columns) ? raw.returned_columns : []);
  const missing = uniqueStrings(Array.isArray(raw.missing_columns) ? raw.missing_columns : []);
  const allNull = uniqueStrings(Array.isArray(raw.all_null_columns) ? raw.all_null_columns : []);
  const nonNumeric = uniqueStrings(Array.isArray(raw.non_numeric_columns) ? raw.non_numeric_columns : []);
  if (requested.length || returned.length || missing.length || allNull.length || nonNumeric.length) {
    claims.unshift({
      unit_id: unit.unit_id,
      tool: unit.tool,
      source_type: 'sensor_data',
      claim_text: [
        `ArcticDB target library=${asString(raw.library) || asString(unit?.params?.library)}`,
        `symbol=${asString(raw.symbol) || asString(unit?.params?.symbol)}`,
        `requested_columns=${JSON.stringify(requested)}`,
        `returned_columns=${JSON.stringify(returned)}`,
        `missing_columns=${JSON.stringify(missing)}`,
        `all_null_columns=${JSON.stringify(allNull)}`,
        `non_numeric_columns=${JSON.stringify(nonNumeric)}`,
        `row_count=${rowCount ?? 'unknown'}`,
        `time_range=${JSON.stringify(Array.isArray(raw.time_range) ? raw.time_range : [])}`
      ].join(', '),
      evidence_type: 'measured_verification',
      scope: 'measured_period_verification',
      supports_question_part: normalizeQuestionPart(questionPart || 'period_verification'),
      inferential_use: 'period_evidence',
      analysis_note: 'Structured ArcticDB query coverage and data-quality fields.',
      supported_by_evidence_ids: evidenceIds
    });
  }
  return claims;
}

function collectClaims(units, localRefMap) {
  const claims = [];

  for (const u of units) {
    const extracted = extractStructuredFromUnit(u);
    const rawClaims = Array.isArray(extracted.claims) ? extracted.claims : [];
    const unitQuestionPart = normalizeQuestionPart(u.question_part || 'other');
    const unitEvidenceIds = uniqueStrings(
      (Array.isArray(extracted.evidence_summary) ? extracted.evidence_summary : []).map(function(_, idx) {
        return localRefMap.get(String(u.unit_id) + ':' + String(idx + 1)) || '';
      })
    );
    const structuredStatsClaims = deterministicArcticStatsClaims(u, unitEvidenceIds, unitQuestionPart);
    if (structuredStatsClaims.length) {
      claims.push(...structuredStatsClaims);
      continue;
    }

    if (rawClaims.length) {
      for (const c of rawClaims) {
        const text = asString(c.claim_text || c.text);
        if (!text) continue;

        const localIdxs = Array.isArray(c.supported_by_evidence_indices)
          ? c.supported_by_evidence_indices.map(function(v) { return Number(v); }).filter(Number.isFinite)
          : [];

        const globalIds = uniqueStrings(
          localIdxs.map(function(i) {
            return localRefMap.get(String(u.unit_id) + ':' + String(i)) || '';
          })
        );

        if (!globalIds.length) continue;

        let evidenceType = normalizeEvidenceType(c.evidence_type);
        let scope = normalizeScope(c.scope);
        let supportsQuestionPart = normalizeQuestionPart(c.supports_question_part || unitQuestionPart || 'other');
        let inferentialUse = normalizeInferentialUse(c.inferential_use);
        const analysisNote = asString(c.analysis_note);

        const isPeriodArcticClaim =
          unitQuestionPart === 'period_verification' &&
          (u.tool === 'arctic_stats' || u.tool === 'arctic_read' || u.tool === 'arctic_describe' || u.tool === 'arctic_analyze') &&
          (
            evidenceType === 'measured_verification' ||
            scope === 'measured_period_verification' ||
            scope === 'historical_monthly_observation' ||
            inferentialUse === 'period_evidence'
          );

        if (isPeriodArcticClaim) {
          supportsQuestionPart = 'period_verification';
          inferentialUse = 'period_evidence';
          if (scope === 'other' || scope === 'context_only') scope = 'measured_period_verification';
          if (evidenceType === 'other') evidenceType = 'measured_verification';
        }

        // Relaxed rule:
        // Do not discard weak target/range evidence. Keep it as context.
        if (supportsQuestionPart === 'target_or_ideal_range') {
          const isRealRange =
            evidenceType === 'recommended_or_target_range' ||
            scope === 'recommended_range' ||
            inferentialUse === 'target_range';

          if (!isRealRange) {
            inferentialUse = 'secondary_context';
            if (scope === 'other') scope = 'context_only';
          }
        }

        // Relaxed rule:
        // Do not discard non-period-aligned evidence. Keep it as context.
        if (supportsQuestionPart === 'period_verification') {
          const isRealPeriod =
            evidenceType === 'measured_verification' ||
            scope === 'measured_period_verification' ||
            inferentialUse === 'period_evidence';

          if (!isRealPeriod) {
            inferentialUse = 'secondary_context';
            if (scope === 'other') scope = 'context_only';
          }
        }

        claims.push({
          unit_id: u.unit_id,
          tool: u.tool || '',
          source_type: u.source_type || 'unknown',
          claim_text: text,
          evidence_type: evidenceType,
          scope,
          supports_question_part: supportsQuestionPart,
          inferential_use: inferentialUse,
          analysis_note: analysisNote,
          supported_by_evidence_ids: globalIds
        });
      }
      continue;
    }

    const text = extracted.answer;
    if (!text || isNoEvidence(text)) continue;

    const evs = Array.isArray(extracted.evidence_summary) ? extracted.evidence_summary : [];
    const globalIds = uniqueStrings(
      evs.map(function(_, idx) {
        return localRefMap.get(String(u.unit_id) + ':' + String(idx + 1)) || '';
      })
    );

    if (!globalIds.length) continue;

    const measuredFallback = isMeasuredPeriodFallbackClaim(u, extracted, unitQuestionPart);

    claims.push({
      unit_id: u.unit_id,
      tool: u.tool || '',
      source_type: u.source_type || 'unknown',
      claim_text: text,
      evidence_type: measuredFallback ? 'measured_verification' : 'other',
      scope: measuredFallback ? 'measured_period_verification' : 'context_only',
      supports_question_part: unitQuestionPart,
      inferential_use: measuredFallback ? 'period_evidence' : 'secondary_context',
      analysis_note: measuredFallback
        ? 'ArcticDB period-aligned fallback text retained as measured period evidence.'
        : 'Fallback text claim retained as contextual evidence rather than discarded.',
      supported_by_evidence_ids: globalIds
    });
  }

  return claims;
}

function rankEvidenceType(questionPart, evidenceType, inferentialUse) {
  const useRank = {
    main_effect: 1,
    indirect_upstream_influence: 2,
    target_range: 1,
    period_evidence: 1,
    secondary_context: 8,
    insufficient_context: 10
  };

  if (inferentialUse && useRank[inferentialUse] != null) return useRank[inferentialUse];

  const ranks = {
    factor_identification: {
      directional_effect: 1,
      indirect_upstream_influence: 2,
      historical_observation: 4,
      documented_operating_value: 8,
      recommended_or_target_range: 9,
      measured_verification: 9,
      other: 10
    },
    target_or_ideal_range: {
      recommended_or_target_range: 1,
      measured_verification: 3,
      documented_operating_value: 9,
      historical_observation: 9,
      indirect_upstream_influence: 9,
      directional_effect: 9,
      other: 10
    },
    period_verification: {
      measured_verification: 1,
      historical_observation: 4,
      documented_operating_value: 9,
      recommended_or_target_range: 9,
      directional_effect: 9,
      indirect_upstream_influence: 9,
      other: 10
    },
    other: {
      directional_effect: 2,
      indirect_upstream_influence: 3,
      documented_operating_value: 6,
      historical_observation: 6,
      recommended_or_target_range: 6,
      measured_verification: 6,
      other: 10
    }
  };

  const table = ranks[questionPart] || ranks.other;
  return table[evidenceType] != null ? table[evidenceType] : 10;
}

function buildClaimBlocks(claims) {
  const ordered = claims.slice().sort(function(a, b) {
    const ra = rankEvidenceType(a.supports_question_part, a.evidence_type, a.inferential_use);
    const rb = rankEvidenceType(b.supports_question_part, b.evidence_type, b.inferential_use);
    if (ra !== rb) return ra - rb;
    return Number(a.unit_id || 0) - Number(b.unit_id || 0);
  });

  return ordered.map(function(c, idx) {
    return {
      claim_id: 'C' + (idx + 1),
      unit_id: c.unit_id,
      claim_type: c.evidence_type,
      source_type: c.source_type || 'unknown',
      tool: c.tool || '',
      claim_text: c.claim_text,
      supported_by_evidence_ids: c.supported_by_evidence_ids || [],
      confidence_note: null,
      scope: c.scope,
      supports_question_part: c.supports_question_part,
      inferential_use: c.inferential_use,
      analysis_note: c.analysis_note
    };
  });
}

function topClaims(blocks, part, limit) {
  const ordered = blocks
    .filter(function(c) { return (c.supports_question_part || 'other') === part; })
    .slice()
    .sort(function(a, b) {
      const ra = rankEvidenceType(a.supports_question_part || 'other', a.claim_type || 'other', a.inferential_use || '');
      const rb = rankEvidenceType(b.supports_question_part || 'other', b.claim_type || 'other', b.inferential_use || '');
      if (ra !== rb) return ra - rb;
      return Number(a.unit_id || 0) - Number(b.unit_id || 0);
    });

  const groups = new Map();
  for (const claim of ordered) {
    const key = String(claim.unit_id == null ? 'unknown' : claim.unit_id);
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(claim);
  }

  const queues = Array.from(groups.values());
  const out = [];
  while (out.length < limit && queues.some(queue => queue.length)) {
    for (const queue of queues) {
      if (out.length >= limit) break;
      if (queue.length) out.push(queue.shift());
    }
  }
  return out;
}

function buildQuestionPartBuckets(claimBlocks) {
  const factorClaims = topClaims(claimBlocks, 'factor_identification', 8);
  const rawRangeClaims = topClaims(claimBlocks, 'target_or_ideal_range', 6);
  const rawPeriodClaims = topClaims(claimBlocks, 'period_verification', 8);
  const otherClaims = topClaims(claimBlocks, 'other', 4);

  const direct = [];
  const indirect = [];
  const documented_context = [];
  const insufficient_context = [];

  for (const c of factorClaims) {
    if (c.inferential_use === 'main_effect' && c.claim_type === 'directional_effect') {
      direct.push(c);
    } else if (c.inferential_use === 'main_effect' && c.claim_type === 'indirect_upstream_influence') {
      indirect.push(c);
    } else if (c.claim_type === 'indirect_upstream_influence') {
      indirect.push(c);
    } else if (
      c.inferential_use === 'secondary_context' ||
      c.claim_type === 'documented_operating_value' ||
      c.scope === 'context_only'
    ) {
      documented_context.push(c);
    } else {
      insufficient_context.push(c);
    }
  }

  const rangeClaims = [];
  const target_context = [];

  for (const c of rawRangeClaims) {
    if (
      c.claim_type === 'recommended_or_target_range' ||
      c.scope === 'recommended_range' ||
      c.inferential_use === 'target_range'
    ) {
      rangeClaims.push(c);
    } else {
      target_context.push(c);
    }
  }

  const periodClaims = [];
  const period_context = [];

  for (const c of rawPeriodClaims) {
    if (
      c.claim_type === 'measured_verification' ||
      c.scope === 'measured_period_verification' ||
      c.inferential_use === 'period_evidence'
    ) {
      periodClaims.push(c);
    } else {
      period_context.push(c);
    }
  }

  return {
    factor_identification: {
      direct,
      indirect,
      documented_context,
      insufficient_context
    },
    target_or_ideal_range: rangeClaims,
    target_context,
    period_verification: periodClaims,
    period_context,
    other: otherClaims
  };
}

function buildCrossEvidenceAnalysis(claimBlocks, sourceStatus, analysisNotes) {
  const buckets = buildQuestionPartBuckets(claimBlocks);

  const direct = buckets.factor_identification.direct;
  const indirect = buckets.factor_identification.indirect;
  const context = buckets.factor_identification.documented_context;
  const ranges = buckets.target_or_ideal_range;
  const period = buckets.period_verification;

  const notes = [];

  notes.push({
    code: 'evidence_admissibility',
    finding: context.length ? 'context_values_present' : 'no_context_values',
    implication: context.length
      ? 'Some retrieved values are documented operating values or table/ledger context. They should not be treated as proof of influence unless paired with explicit directional or mechanism evidence.'
      : 'No context-only documented values were retained in the factor bucket.',
    supporting_claim_ids: context.map(c => c.claim_id)
  });

  notes.push({
    code: 'factor_evidence_balance',
    finding: direct.length && indirect.length
      ? 'direct_and_indirect_effects_present'
      : direct.length
        ? 'direct_effects_present'
        : indirect.length
          ? 'indirect_effects_present'
          : context.length
            ? 'only_documented_context_present'
            : 'no_factor_evidence',
    implication: direct.length
      ? 'At least one claim explicitly supports an effect relationship. Context-only values should be presented separately from that effect evidence.'
      : context.length
        ? 'The available factor evidence is mainly contextual and should be described cautiously.'
        : 'No admissible factor evidence was retained.',
    supporting_claim_ids: direct.concat(indirect, context).map(c => c.claim_id)
  });

  notes.push({
    code: 'range_verification_gap',
    finding: ranges.length && period.length
      ? 'range_and_period_evidence_present'
      : ranges.length
        ? 'range_without_period'
        : period.length
          ? 'period_without_range'
          : 'no_explicit_range_or_period_verification',
    implication: ranges.length && period.length
      ? 'A comparison is possible only where the target/range and period evidence refer to the same indicator.'
      : ranges.length
        ? 'Explicit range evidence exists, but period verification evidence is missing or insufficient.'
        : period.length
          ? 'Period evidence exists, but no explicit target or ideal range was retained for comparison.'
          : 'The workflow cannot verify ideal-range operation without explicit ranges and period-aligned evidence.',
    supporting_claim_ids: ranges.concat(period).map(c => c.claim_id)
  });

  notes.push({
    code: 'timeseries_validation_status',
    finding: sourceStatus.arctic,
    implication: ['not_used', 'blocked', 'none', 'error'].includes(sourceStatus.arctic)
      ? 'Measured time-series verification was not completed in this run.'
      : 'Measured time-series verification contributed to this run.',
    supporting_claim_ids: period.map(c => c.claim_id)
  });

  for (const n of analysisNotes) {
    notes.push({
      code: 'executor_analysis_note',
      finding: n.note_type || 'note',
      implication: n.text,
      supporting_evidence_ids: n.related_evidence_ids || [],
      supporting_claim_ids: []
    });
  }

  return notes;
}

function buildDepExplanations(units, claimBlocks) {
  const explanations = [];
  const claimByUnit = {};

  for (const c of claimBlocks) {
    if (!claimByUnit[c.unit_id]) claimByUnit[c.unit_id] = c;
  }

  for (const u of units) {
    if (!Array.isArray(u.depends_on) || !u.depends_on.length) continue;
    const toClaim = claimByUnit[u.unit_id];

    for (const depId of u.depends_on) {
      const fromClaim = claimByUnit[depId];
      const depUnit = units.find(function(x) { return x.unit_id === depId; });

      let relType = 'supporting';
      if (u.tool === 'arctic_read' && depUnit && depUnit.tool === 'arctic_find_tags') relType = 'tag_to_data';
      else if (u.tool === 'mean_tool' && depUnit && depUnit.tool === 'arctic_read') relType = 'data_to_computation';
      else if ((u.tool === 'arctic_read' || u.tool === 'arctic_stats') && depUnit && depUnit.source_type === 'document_knowledge') relType = 'theory_to_data_verification';

      const isBlocked = u.execution_status === 'DEPENDENCY_BLOCKED';
      const depStatus = (depUnit && depUnit.execution_status) || 'unknown';
      const depTool = (depUnit && depUnit.tool) || 'unknown';

      explanations.push({
        from_unit_id: depId,
        to_unit_id: u.unit_id,
        from_claim_id: fromClaim ? fromClaim.claim_id : null,
        to_claim_id: toClaim ? toClaim.claim_id : null,
        relation_type: relType,
        dependency_met: !isBlocked,
        upstream_status: depStatus,
        explanation: isBlocked
          ? ('Step ' + u.unit_id + ' (' + u.tool + ') was blocked because step ' + depId + ' (' + depTool + ', status: ' + depStatus + ') did not succeed. ' + (u.blocked_judgment_note || ''))
          : ('Step ' + u.unit_id + ' (' + u.tool + ') depends on the output of step ' + depId + ' (' + depTool + ')'),
        backed_by_evidence_ids: fromClaim ? fromClaim.supported_by_evidence_ids : []
      });
    }
  }

  return explanations;
}

function buildMinimalDraftAnswer(claimBlocks, sourceStatus, lang) {
  const buckets = buildQuestionPartBuckets(claimBlocks);

  const hasDirect = buckets.factor_identification.direct.length > 0;
  const hasIndirect = buckets.factor_identification.indirect.length > 0;
  const hasContext = buckets.factor_identification.documented_context.length > 0;
  const hasRange = buckets.target_or_ideal_range.length > 0;
  const hasPeriod = buckets.period_verification.length > 0;

  if (lang === 'zh') {
    const parts = [];
    if (hasDirect) parts.push('已保留明确影响关系证据');
    if (hasIndirect) parts.push('已保留间接上游影响证据');
    if (hasContext) parts.push('已将孤立记录值降级为背景信息');
    if (hasRange) parts.push('已保留显式目标/理想范围证据');
    else parts.push('未保留显式目标/理想范围证据');
    if (hasPeriod) parts.push('已保留时段验证证据');
    else parts.push('未保留足够的时段验证证据');
    return parts.join('；') + '。';
  }

  const parts = [];
  if (hasDirect) parts.push('explicit effect evidence retained');
  if (hasIndirect) parts.push('indirect upstream influence evidence retained');
  if (hasContext) parts.push('isolated documented values downgraded to context');
  if (hasRange) parts.push('explicit target/range evidence retained');
  else parts.push('no explicit target/range evidence retained');
  if (hasPeriod) parts.push('period-verification evidence retained');
  else parts.push('insufficient period-verification evidence retained');

  return parts.join('; ') + '.';
}

// UNIT_TRANSPORT_SLIM_V7：执行单元传输瘦身。
// Q5 exec 153424 执行数据 759MB：每个节点透传约 16MB 整项，检索单元证据存三份（evidence_digest、normalized_result 同样副本、
// executor_answer 文本版约 0.6MB/条），补检 / 反查环又让本节点之后这段多跑 1–2 圈。
// normalized_result 内与单元顶层完全相同的数组删去（本节点读取时单元顶层优先）；检索单元的大段 executor_answer 删去
// （下游只有本节点位号行解析与 EPB 分析单元异常解析读它，都针对历史库单元）。
function __slimUnitsForTransport(list) {
  const same = (a, b) => Array.isArray(a) && Array.isArray(b) && a.length === b.length && JSON.stringify(a) === JSON.stringify(b);
  return (Array.isArray(list) ? list : []).map(u => {
    if (!u || typeof u !== 'object' || Array.isArray(u)) return u;
    const out = { ...u };
    const nr = out.normalized_result;
    if (nr && typeof nr === 'object' && !Array.isArray(nr)) {
      const slim = { ...nr };
      for (const k of ['evidence_digest', 'evidence_summary', 'claims', 'analysis_notes']) {
        if (Array.isArray(out[k]) && out[k].length && same(slim[k], out[k])) delete slim[k];
      }
      out.normalized_result = slim;
    }
    if (/ragflow_retrieval/.test(String(out.tool || '')) && typeof out.executor_answer === 'string' && out.executor_answer.length > 2000) delete out.executor_answer;
    return out;
  });
}

// ---------- Main ----------
let all = flattenAndDedup(inputItems);

all = all.filter(function(u) {
  const extracted = extractStructuredFromUnit(u);
  return (asString(u.execution_status) && asString(u.execution_status) !== 'UNKNOWN')
    || asString(extracted.answer).length > 0
    || (Array.isArray(extracted.evidence_summary) && extracted.evidence_summary.length > 0)
    || (Array.isArray(extracted.claims) && extracted.claims.length > 0)
    || (Array.isArray(extracted.analysis_notes) && extracted.analysis_notes.length > 0);
});

const originalUserMessage =
  current.originalUserMessage ||
  ctx.originalUserMessage ||
  '';

const lang = detectLang(originalUserMessage);

if (!all.length) {
  return [{
    json: toPublicMongoAggregationContract({
      answer: lang === 'zh' ? '最终聚合前失败。' : 'Aggregation failed before final answer assembly.',
      aggregated_payload: {
        draft_answer: lang === 'zh' ? '最终聚合前失败。' : 'Aggregation failed before final answer assembly.',
        claim_blocks: [],
        dependency_explanations: [],
        source_status: { ragflow: 'not_used', arctic: 'not_used', neo4j: 'not_used', postgres: 'not_used', missing_reason: null },
        missing_evidence_flags: [],
        tag_selection_trace: [],
        evidence_summary: [],
        question_part_buckets: {},
        cross_evidence_analysis: [],
        analysis_notes: [],
        evidence_digest: []
      },
      evidence_summary: [],
      executed_calls: [],
      answer_mode: 'AGGREGATION_ERROR',
      plan_intent: current.plan_intent || 'qa',
      originalUserMessage,
      chatSessionId: current.chatSessionId || ctx.chatSessionId || '',
      general_fallback_used: false,
      completed_units: [],
      aggregation_debug: { input_count: inputItems.length, claim_count: 0 }
    })
  }];
}

const assigned = assignEvidenceIds(all);
const localRefMap = assigned.localRefMap;
const enrichedEvidence = assigned.enriched;

const sourceStatus = buildSourceStatus(all);
const tagTrace = buildTagTrace(all);
const missingFlags = buildMissingFlags(all);
const analysisNotes = collectAnalysisNotes(all, localRefMap);
const collectedClaims = collectClaims(all, localRefMap);

// FORMULA_CLAIM_INTEGRITY_V5
// Reject synthesized equations that repeat the same symbolic term on both
// sides. Such a claim cancels that term algebraically and cannot support a
// directional balance role unless a separate validated derivation exists.
function normalizedFormulaTerms(side) {
  return String(side || '')
    .split(/[+＋]/)
    .map(term => term
      .replace(/^.*?[：:]/, '')
      .replace(/[（(][^()（）]*[)）]/g, '')
      .replace(/(?:之和|总和|合计)$/g, '')
      .replace(/[\s*×·]/g, '')
      .trim())
    .filter(term => term.length >= 2 && !/^[-+]?\d+(?:\.\d+)?$/.test(term));
}

function repeatedTermsAcrossEquality(text) {
  const match = String(text || '').match(/([^。！？；;\n]{1,500})=([^。！？；;\n]{1,500})/);
  if (!match) return [];
  const left = normalizedFormulaTerms(match[1]);
  const right = new Set(normalizedFormulaTerms(match[2]));
  return Array.from(new Set(left.filter(term => right.has(term))));
}

const rawClaimBlocks = buildClaimBlocks(collectedClaims);
const rejectedFormulaClaims = [];
const claimBlocks = rawClaimBlocks.filter(claim => {
  const repeated = repeatedTermsAcrossEquality(claim && claim.claim_text);
  if (!repeated.length) return true;
  rejectedFormulaClaims.push({
    claim_id: claim.claim_id,
    repeated_terms: repeated,
    reason: 'same symbolic term appears on both sides of the synthesized equality'
  });
  return false;
});
if (rejectedFormulaClaims.length) {
  analysisNotes.push({
    note_type: 'formula_integrity',
    text: 'Rejected synthesized equality claims with identical symbolic terms on both sides.',
    rejected_claims: rejectedFormulaClaims
  });
}

const depExplanations = buildDepExplanations(all, claimBlocks);
const questionPartBuckets = buildQuestionPartBuckets(claimBlocks);
const crossEvidenceAnalysis = buildCrossEvidenceAnalysis(claimBlocks, sourceStatus, analysisNotes);


const directTextUnit = all.find(function(u) {
  const ex = extractStructuredFromUnit(u);
  const source = String((ex.raw_result && ex.raw_result.source) || '').trim().toLowerCase();
  return source === 'direct_response_text';
});

if (directTextUnit) {
  const ex = extractStructuredFromUnit(directTextUnit);
  const answer = asString(ex.answer);
  const aggregated_payload = {
    draft_answer: answer,
    claim_blocks: [],
    dependency_explanations: [],
    source_status: { direct_response: 'used', conversation_state: 'not_used', ragflow: 'not_used', arctic: 'not_used', neo4j: 'not_used', postgres: 'not_used', missing_reason: null },
    missing_evidence_flags: [],
    tag_selection_trace: [],
    evidence_summary: [],
    evidence_digest: [],
    question_part_buckets: {},
    cross_evidence_analysis: [],
    analysis_notes: [{ note_type: 'direct_response', text: 'Returned direct workflow-guard response without retrieval.' }]
  };

  return [{
    json: toPublicMongoAggregationContract({
      answer,
      aggregated_payload,
      evidence_summary: [],
      evidence_digest: [],
      executed_calls: [{ unit_id: directTextUnit.unit_id || 1, tool: directTextUnit.tool || 'direct_response', status: 'SUCCESS', source_type: 'direct_response_text' }],
      answer_mode: 'direct_response',
      plan_intent: current.plan_intent || 'qa',
      originalUserMessage,
      chatSessionId: current.chatSessionId || ctx.chatSessionId || '',
      general_fallback_used: false,
      completed_units: __slimUnitsForTransport(all),
      aggregation_debug: { input_count: inputItems.length, claim_count: 0, source_status: { direct_response: 'used' } }
    })
  }];
}



// MEMORY_SUMMARY_DATA_SCOPE_V5
function questionMemoryCardsFromUnit(unit) {
  const params = unit && unit.params && typeof unit.params === 'object' && !Array.isArray(unit.params)
    ? unit.params
    : {};
  const cards = Array.isArray(params.question_memory_cards) ? params.question_memory_cards : [];
  return cards.filter(card => card && typeof card === 'object' && !Array.isArray(card));
}

function isFalseNoHistoryAnswer(value) {
  const text = asString(value);
  return /NO_CONVERSATION_HISTORY/i.test(text) ||
    /(?:没有|无)(?:保存|可用|找到).{0,12}(?:历史|之前|先前|回答|对话)/i.test(text) ||
    /no\s+(?:saved|available|previous).{0,16}(?:history|answer|conversation)/i.test(text);
}

function questionMemoryFallback(unit, language) {
  const cards = questionMemoryCardsFromUnit(unit)
    .filter(card => !asString(card.superseded_by_question))
    .filter(card => asString(card.current_answer_summary));
  if (!cards.length) return '';
  const selected = cards.slice(-4);
  if (language === 'zh') {
    return selected.map(card => {
      const question = asString(card.current_question) || '相关历史问题';
      return `关于“${question}”：${asString(card.current_answer_summary)}`;
    }).join('\n\n');
  }
  return selected.map(card => {
    const question = asString(card.current_question) || 'related previous question';
    return `For “${question}”: ${asString(card.current_answer_summary)}`;
  }).join('\n\n');
}

const conversationSummaryUnit = all.find(function(u) {
  const ex = extractStructuredFromUnit(u);
  const tool = String(u.tool || '').trim().toLowerCase();
  const source = String((ex.raw_result && ex.raw_result.source) || '').trim().toLowerCase();
  return tool === 'direct_response' || tool === 'conversation_summary' || source === 'conversation_state';
});

// MEMORY_UNIT_MUST_NOT_HIJACK_TURN_V7
// 上面用的是 find 而不是 every：7 个单元里混进 1 个 direct_response，
// 整轮就在这里短路，同轮真实检索出来的 evidence_digest/claims 被一并清空。
// 实测 20260911 回归：T7（ArcticDB 跑 2 次）、T8、Q5、Q7（分组 RAG 4 次 +
// ArcticDB 4 次）全部 n_ev=0，T7 还写出了「本轮为对话摘要模式」。
// 只有本轮确实没有任何单元产出检索证据时，才算真正的总结轮
// （T5「概括成三句话」、T11「总结之前的对话」正是 0 检索单元，行为不变）。
const retrievalEvidenceUnits = all.filter(function (u) {
  const tool = String(u.tool || '').trim().toLowerCase();
  if (tool === 'direct_response' || tool === 'conversation_summary') return false;
  const ex = extractStructuredFromUnit(u);
  if (String((ex.raw_result && ex.raw_result.source) || '').trim().toLowerCase() === 'conversation_state') return false;
  return (Array.isArray(ex.claims) && ex.claims.length > 0)
    || (Array.isArray(ex.evidence_summary) && ex.evidence_summary.length > 0)
    || (Array.isArray(ex.evidence_digest) && ex.evidence_digest.length > 0)
    || asString(ex.answer).length > 0;
});

if (conversationSummaryUnit && !retrievalEvidenceUnits.length) {
  const ex = extractStructuredFromUnit(conversationSummaryUnit);
  const rawSummaryAnswer = asString(ex.answer);
  const memoryFallback = questionMemoryFallback(conversationSummaryUnit, lang);
  const answer = ((isFalseNoHistoryAnswer(rawSummaryAnswer) || !rawSummaryAnswer) && memoryFallback)
    ? memoryFallback
    : (rawSummaryAnswer || (lang === 'zh'
      ? '当前会话状态中没有保存之前的回答。'
      : 'The current conversation state has no saved previous answers to summarize.'));
  const aggregated_payload = {
    draft_answer: answer,
    claim_blocks: [],
    dependency_explanations: [],
    source_status: { conversation_state: 'used', ragflow: 'not_used', arctic: 'not_used', neo4j: 'not_used', postgres: 'not_used', missing_reason: null },
    missing_evidence_flags: [],
    tag_selection_trace: [],
    evidence_summary: [],
    evidence_digest: [],
    question_part_buckets: {},
    cross_evidence_analysis: [],
    analysis_notes: [{ note_type: 'conversation_summary', text: 'Answered from conversation_state without new retrieval.' }]
  };

  return [{
    json: toPublicMongoAggregationContract({
      answer,
      aggregated_payload,
      evidence_summary: [],
      evidence_digest: [],
      executed_calls: [{ unit_id: conversationSummaryUnit.unit_id || 1, tool: conversationSummaryUnit.tool || 'direct_response', status: 'SUCCESS', source_type: 'conversation_state' }],
      answer_mode: 'conversation_summary',
      plan_intent: current.plan_intent || 'summary',
      originalUserMessage,
      chatSessionId: current.chatSessionId || ctx.chatSessionId || '',
      general_fallback_used: false,
      completed_units: __slimUnitsForTransport(all),
      aggregation_debug: { input_count: inputItems.length, claim_count: 0, source_status: { conversation_state: 'used' } }
    })
  }];
}

const evidenceDigest = [];
for (const u of all) {
  const ex = extractStructuredFromUnit(u);
  if (Array.isArray(ex.evidence_digest)) {
    for (const d of ex.evidence_digest) evidenceDigest.push(d);
  }
}

const fallbackTexts = uniqueStrings(
  all
    .map(function(u) { return extractStructuredFromUnit(u).answer; })
    .filter(function(a) { return asString(a) && !isNoEvidence(a); })
);

let answer_mode;
let draftAnswer;

if (!claimBlocks.length && !fallbackTexts.length) {
  answer_mode = 'NO_EVIDENCE';
  draftAnswer = lang === 'zh' ? '知识库中未找到答案。' : 'No answer found in the knowledge base.';
} else {
  answer_mode = missingFlags.length > 0 ? 'PARTIAL_EVIDENCE' : 'SUCCESS';
  draftAnswer = buildMinimalDraftAnswer(claimBlocks, sourceStatus, lang);
}

const calls = all.map(function(u) {
  return {
    unit_id: u.unit_id != null ? u.unit_id : null,
    tool: u.tool || '',
    status: u.execution_status || 'UNKNOWN',
    source_type: u.source_type || 'unknown'
  };
});

const aggregated_payload = {
  draft_answer: draftAnswer,
  claim_blocks: claimBlocks,
  dependency_explanations: depExplanations,
  source_status: sourceStatus,
  missing_evidence_flags: missingFlags,
  tag_selection_trace: tagTrace,
  evidence_summary: enrichedEvidence,
  evidence_digest: evidenceDigest,
  question_part_buckets: questionPartBuckets,
  cross_evidence_analysis: crossEvidenceAnalysis,
  analysis_notes: analysisNotes
};

// UNIT_TRANSPORT_SLIM_V7b：顶层 evidence_summary / evidence_digest 与 aggregated_payload 内两份完全相同，
// 下游（EPB、Code in JavaScript、Save Conversation State、CRP）都读或兜底读 aggregated_payload；删字段而非置空数组，
// 否则 `item.x || payload.x` 遇到空数组不会回退。
return [{
  json: toPublicMongoAggregationContract({
    answer: draftAnswer,
    aggregated_payload,
    executed_calls: calls,
    answer_mode,
    plan_intent: current.plan_intent || 'qa',
    originalUserMessage,
    chatSessionId: current.chatSessionId || ctx.chatSessionId || '',
    general_fallback_used: false,
    completed_units: __slimUnitsForTransport(all),
    aggregation_debug: {
      input_count: inputItems.length,
      claim_count: claimBlocks.length,
      missing_flags_count: missingFlags.length,
      source_status: sourceStatus
    }
  })
}];

// EVENT_WINDOW_MULTISIGNAL_V5
const item = $input.first().json;
const units = Array.isArray(item.completed_units) ? item.completed_units : [];

function isNoEvidenceAnswer(s) {
  const t = typeof s === 'string' ? s.trim() : '';
  return !t || t === 'NO_EVIDENCE' || t === 'No answer found in the knowledge base.' || t === '知识库中未找到答案。';
}

function isMeasuredUnit(unit) {
  const tool = String(unit?.tool || '');
  const required = Array.isArray(unit?.required_evidence_types) ? unit.required_evidence_types : [];
  return /^arctic_/i.test(tool) || required.includes('measured_process_data') || unit?.params?.evidence_scope === 'measured_window_only';
}

const hasSuccess = units.some(u =>
  u?.execution_status === 'SUCCESS' &&
  typeof u?.answer === 'string' &&
  u.answer.trim() &&
  !isNoEvidenceAnswer(u.answer)
);

const noEvidenceOnly =
  item.answer_mode === 'NO_EVIDENCE' ||
  (units.length > 0 && units.every(u =>
    ['NO_EVIDENCE', 'SKIPPED', 'DEPENDENCY_BLOCKED', 'DATE_RANGE_NO_DATA', 'TAG_DISCOVERY_FAILED'].includes(u?.execution_status) ||
    isNoEvidenceAnswer(u?.answer)
  ));

const retrievalUnits = units.filter(u => u?.tool && u.tool !== 'direct_response');
const measuredEvidenceContract = retrievalUnits.length > 0 && retrievalUnits.every(isMeasuredUnit);
const triggerFallback = !measuredEvidenceContract && !hasSuccess && noEvidenceOnly;

return [{
  json: {
    ...item,
    gk_triggered: triggerFallback,
    general_fallback_used: triggerFallback,
    general_fallback_block_reason: measuredEvidenceContract ? 'measured_evidence_contract' : ''
  }
}];

