function compactFactorInventoryForStatic(arr, limit = 40) {
  return (Array.isArray(arr) ? arr : []).slice(0, limit).map(f => {
    if (!f || typeof f !== 'object' || Array.isArray(f)) {
      return { name: truncateStringForStatic(f, 120) };
    }
    return {
      name: truncateStringForStatic(f.name, 120),
      measurement_type: truncateStringForStatic(f.measurement_type, 40),
      process_context: truncateStringForStatic(f.process_context, 160),
      aliases: (Array.isArray(f.aliases) ? f.aliases : []).slice(0, 8).map(x => truncateStringForStatic(x, 100)),
      direction_or_role: truncateStringForStatic(f.direction_or_role, 220),
      preferred_tag_query: truncateStringForStatic(f.preferred_tag_query, 260),
      reject_context: (Array.isArray(f.reject_context) ? f.reject_context : []).slice(0, 6).map(x => truncateStringForStatic(x, 100)),
      evidence_ids: (Array.isArray(f.evidence_ids) ? f.evidence_ids : []).slice(0, 8),
      confidence: truncateStringForStatic(f.confidence, 20)
    };
