}

function compactResolvedTags(entry, rawResult) {
  const out = [];
  const seen = new Set();
  const add = value => {
    const tag = String(value || '').trim();
    const key = tag.toUpperCase();
    if (!tag || seen.has(key)) return;
    seen.add(key);
    out.push(tag);
  };
  const explicit = Array.isArray(entry?.resolved_tags) ? entry.resolved_tags : [];
  for (const item of explicit) add(item);
  const trace = Array.isArray(entry?.tag_selection_trace) ? entry.tag_selection_trace : [];
  for (const item of trace) {
    if (item && item.selected === true) add(item.tag || item.name);
  }

  // Preserve the exact overlap between conversation-confirmed candidates and
  // tags returned by the current catalog lookup. This survives loop-state
  // compaction without retaining descriptions or promoting neighboring tags.
  const inherited = entry?.params?.context_inheritance;
  const candidates = Array.isArray(entry?.params?.candidate_tags)
    ? entry.params.candidate_tags
    : [];
  if (inherited?.enabled === true && candidates.length) {
    const returned = Array.isArray(rawResult?.tags) ? rawResult.tags : [];
    const returnedKeys = new Set(
      returned
        .map(item => typeof item === 'string' ? item : (item && (item.tag || item.name)))
        .map(item => String(item || '').trim().toUpperCase())
        .filter(Boolean)
    );
    for (const candidate of candidates) {
      const tag = String(candidate || '').trim();
      if (returnedKeys.has(tag.toUpperCase())) add(tag);
    }
  }

  // A structured trace is authoritative even when it selects nothing, except
  // for the exact inherited overlap computed above.
  if (explicit.length || trace.length) return out.slice(0, 100);
  for (const item of (Array.isArray(rawResult?.tags) ? rawResult.tags : [])) {
    add(typeof item === 'string' ? item : (item && (item.tag || item.name)));
  }
  for (const item of (Array.isArray(rawResult?.results) ? rawResult.results : [])) {
    add(typeof item === 'string' ? item : (item && (item.tag || item.name)));
  }
  for (const factor of (Array.isArray(rawResult?.factor_results) ? rawResult.factor_results : [])) {
    for (const item of (Array.isArray(factor?.tags) ? factor.tags : [])) {
      add(typeof item === 'string' ? item : (item && (item.tag || item.name)));
    }
  }
  // MongoDB tag selection is capped at 100 by the tool contract. Keeping only
  // names avoids carrying repeated descriptions and selection queries.
  return out.slice(0, 100);
}

function compactUnitForStatic(entry) {
  const rr = entry && entry.raw_result && typeof entry.raw_result === 'object' && !Array.isArray(entry.raw_result)
    ? entry.raw_result
    : {};
  return {
