    evidence_summary: compactEvidenceForStatic(entry?.evidence_summary, 3),
    evidence_digest: (Array.isArray(entry?.evidence_digest) ? entry.evidence_digest : []).slice(0, 6),
    factor_inventory: compactFactorInventoryForStatic(
      entry?.factor_inventory || (entry?.normalized_result && entry.normalized_result.factor_inventory) || [],
      40
    ),
    raw_result: {
      chunk_count: rr.chunk_count ?? rr.count ?? null,
      row_count: rr.row_count ?? null,
      selection_mode: rr.selection_mode ?? null,
      analysis_types: Array.isArray(rr.analysis_types) ? rr.analysis_types.slice(0, 10) : undefined,
      warnings: Array.isArray(rr.warnings) ? rr.warnings.slice(0, 6).map(x => truncateStringForStatic(x, 500)) : undefined,
      time_range: Array.isArray(rr.time_range) ? rr.time_range.slice(0, 2) : undefined,
      probe_tags: Array.isArray(rr.probe_tags) ? rr.probe_tags.slice(0, 100) : undefined,
      non_null_columns: Array.isArray(rr.non_null_columns) ? rr.non_null_columns.slice(0, 48) : undefined,
      null_columns: Array.isArray(rr.null_columns) ? rr.null_columns.slice(0, 48) : undefined,
      data_scope: rr.data_scope ?? undefined,
      existence_conclusion_allowed: rr.existence_conclusion_allowed === true,
