    columns_analyzed: Array.isArray(entry?.columns_analyzed) ? entry.columns_analyzed.slice(0, 30) : entry?.columns_analyzed ?? null,
    columns_requested: Array.isArray(entry?.columns_requested) ? entry.columns_requested.slice(0, 30) : entry?.columns_requested ?? null
  };
}

