    ? catalog.ragflow.datasets
        .filter(ds => ds?.is_searchable === true)
        .map(ds => ds?.id)
    : [];

  const candidates = explicit.length ? explicit : fromDatasets;
  return filterSearchableDatasetIds(candidates, catalog);
}

