function stripFences(s) {
  return (s || '').trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}

function parseClassifierOutput(raw) {
  let parsed = {};
  try {
    parsed = JSON.parse(stripFences(raw || ''));
  } catch (e) {
    parsed = { intent: 'needs_kb', reply: '' };
  }

  const intent = String(parsed.intent || '').trim();
  return {
    intent: intent === 'small_talk' ? 'small_talk' : 'needs_kb',
    reply: typeof parsed.reply === 'string' ? parsed.reply.trim() : '',
    confidence: Number.isFinite(Number(parsed.confidence)) ? Number(parsed.confidence) : 0,
    technical_signals: Array.isArray(parsed.technical_signals) ? parsed.technical_signals.map(String).filter(Boolean) : []
  };
}

function isConversationMemoryRequest(question) {
  const q = String(question || '');
  return /\b(previous|earlier|above|before|last answer|your answer|you said|recap|summari[sz]e|summary|summarize|going back|original question|key points|three sentences|chat history|conversation)\b/i.test(q) ||
    /(刚才|前面|之前|上面|总结|總結|概括|上一|前一|你刚才|你剛才|回到.*最初|三句|三句话|核心要点)/.test(q);
}


// INTENT_AND_STATE_BOUNDARY_V5
// This guard recognizes generic evidence-working actions, not domain entities,
// tags, questions, thresholds, or site-specific vocabulary.
function isEvidenceTaskRequest(question) {
  const q = String(question || '').trim();
  if (!q) return false;
  const actionRequest =
    /\b(?:retrieve|search|look\s*up|inspect|check|select|choose|calculate|compute|analy[sz]e|compare|verify|validate|evaluate|determine|identify|explain|summari[sz]e|trace|correlate|estimate|measure|characteri[sz]e)\b/i.test(q) ||
    /(检索|搜索|查找|查询|查看|检查|核对|选择|计算|分析|比较|对比|验证|确认|判断|识别|解释|总结|追溯|关联|估算|测量|刻画|表征)/.test(q);
  const referencedObject =
    /\b(?:data|evidence|result|record|history|value|window|event|anomaly|baseline|trend|parameter|metric|document|source|previous|prior|above|following)\b/i.test(q) ||
    /(数据|证据|结果|记录|历史|数值|窗口|事件|异常|基线|趋势|参数|指标|文档|资料|来源|前述|上述|其中|那次|这次)/.test(q);
  const quantitativeForm =
    /(?:\d+(?:\.\d+)?\s*(?:%|ms|s|min|h|day|kpa|mpa|bar|℃|°c)\b)|(?:峰值|持续时间|偏离|恢复过程|相关性|滞后)/i.test(q);
  return actionRequest && (referencedObject || quantitativeForm);
}

const item = $input.first().json;
const wfData = $('Workflow Configuration').first().json;
const msg = String(wfData.chatInput || wfData['What is your question'] || item.chatInput || '').trim();
const parsed = parseClassifierOutput(item.output || '');

// PARSE_INTENT_NO_DIRECT_ANSWERS_V428_PATCH:
// Parse Intent is only an intent parser/router. It must not contain FCC-domain
// direct answers, thresholds, tag conclusions, event-window conclusions, or
// canned summaries. Domain guards belong in planning/normalization/finalization
// where they can use conversation state and evidence boundaries.
// STRUCTURED_INTENT_CONFIDENCE_V448
const requiresWorkflow =
  isConversationMemoryRequest(msg) ||
  isEvidenceTaskRequest(msg) ||
  parsed.technical_signals.length > 0;
const intent = !requiresWorkflow &&
  parsed.intent === 'small_talk' &&
  parsed.confidence >= 0.9
    ? 'small_talk'
    : 'needs_kb';

const reply = intent === 'small_talk' ? parsed.reply : '';

return [{ json: { ...wfData, intent, small_talk_reply: reply } }];

// UNIFIED_RUNTIME_REFERENCE_CONTRACT_V5
var REF_PATTERN = /^(?:(?:\$ref:)?step_?|\$ref:)(\d+)\.([A-Za-z0-9_\[\].*]+)$/i;

// TAG_CATALOG_QUERY_NORMALIZATION_V6c
// 目录检索匹配的是标签描述（"沉降器与二再差压"这类），描述里不会出现
// "控制器/位号/是什么"这些查询用词，带进去只会稀释召回。
// 实测：query="两器压差" -> count=1；query="压差控制器 位号" -> count=0。
// 归一化在 Normalize Execution Units 做过一次，但 Unit ordered Splitter 会在
// 下游把 query 重写回原样，因此下沉到执行前最后一道关卡。
// FORMULA_EXPANSION_LAST_MILE_V6
// 问「怎么算/公式」的检索必须带上公式记号，否则召回的是概念段而不是带式子的分块。
// 该扩展原在 Normalize Execution Units，但那里 units 被重新赋值 17 次，扩展被盖掉；
// 这里是执行前最后一道关卡，补足并抬高 top_k。
function bossNeedsFormulaQueryV6(text) {
  const q = String(text || '');
  if (!/怎么算|怎么计算|如何计算|计算方法|公式|方程|calculate|calculation|formula|equation/i.test(q)) return false;
  return /压差|压力|差压|压降|静压头|balance|pressure|head/i.test(q);
}
const FORMULA_TOKENS_V6 = [
  '公式 方程 计算方法 压力平衡 静压头 压降 摩擦阻力 推动力 阻力',
  'ρgh ρhg ΔP=ρgh Δp=ρ·Δh·g p=ρhg ΔPsp ΔPgrid ΔPv',
  'formula equation calculation method pressure balance static head hydrostatic head pressure drop driving force resistance'
].join('\n');

function bossNormalizeCatalogQueryV6c(raw) {
  const text = String(raw == null ? '' : raw).trim();
  if (!text) return text;
  const tags = text.match(/[A-Z]{2,6}\d{3,5}[A-Z]?(?:\.[A-Z]{2,4})?/g) || [];
  const GENERIC = [
    '正常控制范围', '控制范围', '告诉我', '对应的', '相关的', '叫什么', '是什么', '什么是',
    '有哪些', '是多少', '查一下', '控制器', '控制点', '点位', '位号', '标签', '测点',
    '仪表', '表号', '编号', '名称', '哪些', '多少', '查询', '查找', '检索', '请问', '对应',
    'tags', 'tag', 'point', 'name', 'what', 'which', 'the', 'for', 'of', 'is'
  ].sort((a, b) => b.length - a.length);
  let stripped = text;
  for (const w of GENERIC) stripped = stripped.split(w).join(' ');
  stripped = stripped.replace(/[?？。，,、;；:：!！()（）]/g, ' ').replace(/\s+/g, ' ').trim();
  const seen = new Set();
  const kept = [];
  for (const seg of tags.concat(stripped.split(' '))) {
    const t = String(seg || '').trim();
    if (!t) continue;
    if (/^[\u4e00-\u9fff]$/.test(t)) continue;   // 剥完残留的单字虚词不进查询串
    const k = t.toLowerCase();
    if (seen.has(k)) continue;
    seen.add(k);
    kept.push(t);
  }
  // V6d：中文词序变体。目录描述与问题常用相反词序（"差压" vs "压差"、
  // "差温" vs "温差"），字面匹配会互相错过；两个方向都补进查询串。
  const ORDER_PAIRS = [['压差', '差压'], ['温差', '差温'], ['液位', '位液']];
  for (const [a, b] of ORDER_PAIRS) {
    const hasA = kept.some(t => t.indexOf(a) >= 0);
    const hasB = kept.some(t => t.indexOf(b) >= 0);
    if (hasA && !hasB && !seen.has(b)) { seen.add(b); kept.push(b); }
    if (hasB && !hasA && !seen.has(a)) { seen.add(a); kept.push(a); }
  }
  const merged = kept.join(' ').trim();
  return merged.length >= 2 ? merged : text;
}

function asString(v) {
  return typeof v === 'string' ? v.trim() : '';
}

// MONGODB_PUBLIC_CONTRACT_V1
// The mature injector logic below still uses the legacy Arctic names
// internally. Normalize mongo_* input to that internal representation, then
// convert every emitted unit back to the public MongoDB MCP contract. This
// avoids a risky rewrite of the dependency, batching, and analysis logic.
const MONGO_TO_INTERNAL_TOOL = {
  mongo_find_tags: 'arctic_find_tags',
  mongo_read: 'arctic_read',
  mongo_stats: 'arctic_stats',
  mongo_analyze: 'arctic_analyze',
  mongo_describe: 'arctic_describe',
  mongo_resolve_factors: 'arctic_resolve_factors'
};

const INTERNAL_TO_MONGO_TOOL = Object.fromEntries(
  Object.entries(MONGO_TO_INTERNAL_TOOL).map(([mongo, internal]) => [internal, mongo])
);

function toInternalTool(tool) {
  const value = asString(tool);
  return MONGO_TO_INTERNAL_TOOL[value] || value;
}

function toMongoTool(tool) {
  const value = asString(tool);
  return INTERNAL_TO_MONGO_TOOL[value] || value;
}

function toInternalTarget(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return value;
  const out = { ...value };
  if (!asString(out.library) && asString(out.database)) out.library = out.database;
  if (!asString(out.symbol) && asString(out.collection)) out.symbol = out.collection;
  if (Array.isArray(out.targets)) out.targets = out.targets.map(toInternalTarget);
  return out;
}

function toMongoTarget(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return value;
  const out = { ...value };
  if (!asString(out.database) && asString(out.library)) out.database = out.library;
  if (!asString(out.collection) && asString(out.symbol)) out.collection = out.symbol;
  delete out.library;
  delete out.symbol;
  if (Array.isArray(out.targets)) out.targets = out.targets.map(toMongoTarget);
  if (out.blocked_tool) out.blocked_tool = toMongoTool(out.blocked_tool);
  return out;
}

function toMongoUnit(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return value;
  const out = { ...value };
  if (out.tool) out.tool = toMongoTool(out.tool);
  if (out.params && typeof out.params === 'object' && !Array.isArray(out.params)) {
    out.params = toMongoTarget(out.params);
  }
  if (out.unit && typeof out.unit === 'object' && !Array.isArray(out.unit)) {
    out.unit = toMongoUnit(out.unit);
  }
  return out;
}

function toMongoCompletedUnits(values) {
  return Array.isArray(values) ? values.map(toMongoUnit) : [];
}

function uniqueOrdered(arr) {
  const out = [];
  const seen = new Set();
  for (const raw of arr || []) {
    const s = String(raw || '').trim();
    if (!s) continue;
    const key = s.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(s);
  }
  return out;
}

function normalizeRuntimeRef(v) {
  let text = asString(v);
  const template = /^\{\{\s*(step_?\d+\.[^}]+?)\s*\}\}$/i.exec(text);
  if (template) text = template[1].trim();
  if (/^step_?\d+\./i.test(text)) text = '$ref:' + text;
  if (/^\$ref:\d+\./i.test(text)) text = text.replace(/^\$ref:(\d+)\./i, '$ref:step$1.');
  return text;
}

function isRuntimeRef(v) {
  return REF_PATTERN.test(normalizeRuntimeRef(v));
}

function getDefaultArcticTarget(item) {
  const target = item?.catalog?.mongodb?.default_target ||
    item?.catalog?.arcticdb?.default_target || {};
  return {
    library: asString(target.database || target.library),
    symbol: asString(target.collection || target.symbol)
  };
}

function unitIdOf(u) {
  if (!u || typeof u !== 'object') return null;
  if (u.unit_id != null) return Number(u.unit_id);
  if (u.unit && u.unit.unit_id != null) return Number(u.unit.unit_id);
  return null;
}

function getChainCompleted(item) {
  const chainKey = 'chain_' + (item.chatSessionId || 'default');
  const sd = $getWorkflowStaticData('global');
  const globalCompleted = Array.isArray(sd[chainKey]) ? sd[chainKey] : [];
  const localCompleted = Array.isArray(item.completed_units) ? item.completed_units : [];

  const out = [];
  const seen = new Set();

  for (const src of [localCompleted, globalCompleted]) {
    for (const raw of src || []) {
      if (!raw || typeof raw !== 'object') continue;
      const id = unitIdOf(raw);
      if (id == null || !Number.isFinite(id)) continue;

      const u = {
        ...raw,
        unit_id: id,
        tool: toInternalTool(raw.tool || (raw.unit && raw.unit.tool) || ''),
        answer: raw.answer || '',
        executor_answer: raw.executor_answer || raw.tool_answer || '',
        params: toInternalTarget(raw.params || (raw.unit && raw.unit.params) || {}),
        evidence_digest: raw.evidence_digest || (raw.normalized_result && raw.normalized_result.evidence_digest) || null,
        factor_inventory: raw.factor_inventory || (raw.normalized_result && raw.normalized_result.factor_inventory) || null,
        raw_result: raw.raw_result || null,
        normalized_result: raw.normalized_result || null,
        tag_selection_trace: raw.tag_selection_trace || null,
        execution_status: raw.execution_status || ''
      };

      if (!seen.has(id)) {
        seen.add(id);
        out.push(u);
      } else {
        const idx = out.findIndex(x => Number(x.unit_id) === id);
        if (idx >= 0 && scoreUnit(u) > scoreUnit(out[idx])) out[idx] = u;
      }
    }
  }

  return out;
}

function scoreUnit(u) {
  let s = 0;
  if (u.execution_status === 'SUCCESS') s += 10;
  if (u.answer) s += 2;
  if (u.executor_answer) s += 2;
  if (Array.isArray(u.tag_selection_trace) && u.tag_selection_trace.length) s += 5;
  if (Array.isArray(u.factor_inventory) && u.factor_inventory.length) s += 8;
  if (u.normalized_result && Array.isArray(u.normalized_result.factor_inventory) && u.normalized_result.factor_inventory.length) s += 8;
  if (Array.isArray(u.evidence_digest) && u.evidence_digest.length) s += 2;
  if (u.raw_result) s += 1;
  return s;
}

function parseTagsFromText(text) {
  const s = String(text || '');
  const tags = [];

  const rankedLine = /^\s*\d+\.\s*([A-Za-z][A-Za-z0-9_]*(?:\.[A-Za-z0-9_]+)?)(?=\s*\|)/gm;
  let m;
  while ((m = rankedLine.exec(s)) !== null) {
    tags.push(m[1]);
  }

  const dcsTag = /\b[A-Z]{1,6}[A-Z0-9_]*\d{2,6}[A-Z0-9_]*\.PV\b/g;
  while ((m = dcsTag.exec(s)) !== null) {
    tags.push(m[0]);
  }

  const structuredTag = /\b(?:[A-Za-z][A-Za-z0-9]*\d[A-Za-z0-9]*_[A-Za-z0-9]+|(?:Ecat|Scat|SRcat)[A-Za-z0-9]+|(?:StackFG|Sample)_[A-Za-z0-9]+)\b/g;
  while ((m = structuredTag.exec(s)) !== null) {
    tags.push(m[0]);
  }

  return Array.from(new Set(tags));
}

function tagSearchRejectedAll(dep) {
  if (!dep || dep.tool !== 'arctic_find_tags') return false;
  const text = (
    String(dep.executor_answer || '') + '\n' +
    String(dep.answer || '') + '\n' +
    JSON.stringify(dep.normalized_result || {})
  ).toLowerCase();

  return /no\s+(?:direct|usable|relevant|matching)\s+tags|no\s+tags\s+(?:found|matching)|none\s+(?:of\s+the\s+)?(?:returned\s+)?(?:candidate\s+)?tags?\s+(?:directly\s+)?(?:match|measure)|all\s+(?:returned\s+)?candidates?\s+(?:were\s+)?rejected|all\s+.*rejected|did\s+not\s+find\s+any\s+matching\s+tags|returned\s+zero\s+results|not\s+directly\s+measure|not\s+a\s+direct\s+measurement|none\s+were\s+selected|none\s+of\s+(?:these|the)\s+tags?\s+measure|no\s+tags?\s+directly\s+(?:match|matching|measure|measures)|no\s+tags?\s+matched|未找到.*标签|没有.*匹配|无.*标签/.test(text);
}


function getTagsFromUnit(dep) {
  if (!dep) return [];

  if (Array.isArray(dep.resolved_tags) && dep.resolved_tags.length) {
    return Array.from(new Set(dep.resolved_tags.map(String).map(x => x.trim()).filter(Boolean)));
  }

  // INHERITED_EXACT_TAG_DEPENDENCY_V5
  // A broad follow-up search may reject every contextual candidate even though
  // it returned exact tags already confirmed in the conversation registry.
  // Preserve only the exact intersection; never promote neighboring results.
  const inheritedContext = dep?.params?.context_inheritance;
  const inheritedCandidates = Array.isArray(dep?.params?.candidate_tags)
    ? dep.params.candidate_tags.map(value => String(value || '').trim()).filter(Boolean)
    : [];
  if (inheritedContext?.enabled === true && inheritedCandidates.length) {
    const raw = dep.raw_result && typeof dep.raw_result === 'object'
      ? dep.raw_result
      : (dep.normalized_result?.raw_result || {});
    const returned = (Array.isArray(raw.tags) ? raw.tags : [])
      .map(value => typeof value === 'string' ? value : value && (value.tag || value.name))
      .map(value => String(value || '').trim())
      .filter(Boolean);
    const returnedKeys = new Set(returned.map(value => value.toUpperCase()));
    const exactInherited = inheritedCandidates.filter(value =>
      returnedKeys.has(value.toUpperCase())
    );
    if (exactInherited.length) return Array.from(new Set(exactInherited));
  }

  if (Array.isArray(dep.tag_selection_trace)) {
    const accepted = dep.tag_selection_trace
      .filter(x => x && x.tag)
      .filter(x => {
        const matchType = String(x.match_type || '').trim().toLowerCase();
        if (x.selected === false) return false;
        if (matchType === 'reject' || matchType === 'rejected' || matchType === 'no_clear_match') return false;
        return true;
      })
      .map(x => x.tag)
      .filter(Boolean);
    if (accepted.length) return Array.from(new Set(accepted));

    if (dep.tag_selection_trace.length) return [];
  }

  // STRICT_VERTICAL_SELECTION_V5
  // Multi-query selection is valid only through structured trace/resolved tags.
  // Never promote tag-shaped prose or the candidate catalog after format loss.
  if (Array.isArray(dep?.params?.queries)) return [];

  if (dep.raw_result && typeof dep.raw_result === 'object') {
    if (Array.isArray(dep.raw_result.tags)) {
      const arr = dep.raw_result.tags
        .map(x => typeof x === 'string' ? x : x && (x.tag || x.name))
        .filter(Boolean);
      if (arr.length) return Array.from(new Set(arr));
    }


    if (Array.isArray(dep.raw_result.factor_results)) {
      const arr = dep.raw_result.factor_results
        .flatMap(factor => Array.isArray(factor?.tags) ? factor.tags : [])
        .map(x => typeof x === 'string' ? x : x && (x.tag || x.name))
        .filter(Boolean);
      if (arr.length) return Array.from(new Set(arr));
    }

    if (Array.isArray(dep.raw_result.results)) {
      const arr = dep.raw_result.results
        .map(x => typeof x === 'string' ? x : x && (x.tag || x.name))
        .filter(Boolean);
      if (arr.length) return Array.from(new Set(arr));
    }
  }

  // PARTIAL_TAG_RESULT_PRECEDENCE_V5
  // Structured selections and raw results outrank prose that may discuss only
  // the unmatched portion of a partially successful catalog lookup.
  if (tagSearchRejectedAll(dep)) return [];

  const text =
    String(dep.executor_answer || '') + '\n' +
    String(dep.answer || '') + '\n' +
    JSON.stringify(dep.normalized_result || {});

  return parseTagsFromText(text);
}

// CANDIDATE_PRESENCE_PROBE_SET_V5
// Data existence and semantic identity are independent. Return direct tags
// plus contextual candidates for historian probing, while preserving their
// original semantic classification for downstream calculation readiness.
function getProbeTagsFromUnit(dep) {
  if (!dep) return [];
  const tags = [...getTagsFromUnit(dep)];
  const add = value => {
    const tag = String(value || '').trim();
    if (tag) tags.push(tag);
  };
  for (const entry of (Array.isArray(dep.tag_selection_trace) ? dep.tag_selection_trace : [])) {
    if (!entry || !/contextual/i.test(String(entry.match_type || ''))) continue;
    add(entry.tag || entry.name);
  }
  const raw = dep.raw_result && typeof dep.raw_result === 'object'
    ? dep.raw_result
    : (dep.normalized_result?.raw_result || {});
  for (const value of (Array.isArray(raw.probe_tags) ? raw.probe_tags : [])) add(value);
  for (const value of (Array.isArray(raw.candidate_tags) ? raw.candidate_tags : [])) add(value);
  for (const factor of (Array.isArray(raw.factor_resolution) ? raw.factor_resolution : [])) {
    for (const value of (Array.isArray(factor?.candidate_tags) ? factor.candidate_tags : [])) add(value);
  }
  return uniqueOrdered(tags);
}

function getRagflowContext(completedUnits) {
  return completedUnits
    .filter(u => u.tool === 'ragflow_retrieval' && u.execution_status === 'SUCCESS' && u.answer)
    .map(u => u.answer)
    .join(' ');
}

function stripEvidenceMarkers(text) {
  return String(text || '')
    .replace(/\[[EC]\d+[^\]]*\]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function firstParagraphText(text) {
  const cleaned = stripEvidenceMarkers(text);
  if (!cleaned) return '';
  const paragraph = cleaned
    .split(/\n\s*\n|(?:\r?\n){2,}/)
    .map(s => s.trim())
    .filter(Boolean)[0] || cleaned;
  return paragraph;
}

function ragUnitText(u) {
  const parts = [u && u.answer, u && u.executor_answer];
  const claims = Array.isArray(u && u.claims) ? u.claims : [];
  for (const c of claims) {
    if (c && typeof c === 'object') parts.push(c.claim_text || c.analysis_note || '');
    else parts.push(c);
  }
  const norm = u && u.normalized_result && typeof u.normalized_result === 'object'
    ? u.normalized_result
    : {};
  if (Array.isArray(norm.claims)) {
    for (const c of norm.claims) {
      if (c && typeof c === 'object') parts.push(c.claim_text || c.analysis_note || '');
      else parts.push(c);
    }
  }
  return stripEvidenceMarkers(parts.join(' '));
}

function ragUnitFirstParagraphText(u) {
  const primary = firstParagraphText((u && u.answer) || (u && u.executor_answer) || '');
  if (primary) return primary;
  return firstParagraphText(ragUnitText(u));
}

function ragUnitInventoryText(u) {
  const parts = [ragUnitFirstParagraphText(u), ragUnitText(u)];
  const norm = u && u.normalized_result && typeof u.normalized_result === 'object'
    ? u.normalized_result
    : {};
  const digests = []
    .concat(Array.isArray(u && u.evidence_digest) ? u.evidence_digest : [])
    .concat(Array.isArray(norm.evidence_digest) ? norm.evidence_digest : []);
  for (const d of digests) {
    if (!d || typeof d !== 'object') continue;
    parts.push(d.content_summary || d.summary || '');
    parts.push(d.snippet || '');
    for (const k of ['key_points', 'key_values', 'operational_actions', 'limitations']) {
      if (Array.isArray(d[k])) parts.push(d[k].join('. '));
    }
  }
  const summaries = []
    .concat(Array.isArray(u && u.evidence_summary) ? u.evidence_summary : [])
    .concat(Array.isArray(norm.evidence_summary) ? norm.evidence_summary : []);
  for (const ev of summaries) {
    if (!ev || typeof ev !== 'object') continue;
    parts.push(ev.section_title || '');
    parts.push(ev.snippet || '');
  }
  return stripEvidenceMarkers(parts.join('. '));
}

function selectRagContextUnits(completedUnits, unit) {
  const preferredIds = new Set(
    (Array.isArray(unit && unit.rag_context_unit_ids) ? unit.rag_context_unit_ids : [])
      .map(Number)
      .filter(Number.isFinite)
  );

  function partRank(u) {
    const part = String(u && u.question_part || '').trim();
    if (part === 'factor_identification') return 0;
    if (part === 'target_or_ideal_range') return 1;
    return 2;
  }

  return (completedUnits || [])
    .filter(u => u && u.tool === 'ragflow_retrieval')
    .filter(u => {
      const part = String(u.question_part || '').trim();
      return part === 'factor_identification' || part === 'target_or_ideal_range';
    })
    .filter(u => (
      u.execution_status === 'SUCCESS' ||
      ((u.answer || u.executor_answer) && String(u.answer || u.executor_answer).trim() !== 'NO_EVIDENCE')
    ))
    .sort((a, b) => {
      const ar = partRank(a);
      const br = partRank(b);
      if (ar !== br) return ar - br;
      const ap = preferredIds.has(Number(a.unit_id)) ? 0 : 1;
      const bp = preferredIds.has(Number(b.unit_id)) ? 0 : 1;
      if (ap !== bp) return ap - bp;
      return Number(a.unit_id || 0) - Number(b.unit_id || 0);
    });
}

function compactEvidenceForFactorExtraction(ev, idx) {
  if (!ev || typeof ev !== 'object' || Array.isArray(ev)) {
    const s = compactFactorText(ev, 500);
    return s ? { evidence_id: 'E' + String(idx + 1), snippet: s } : null;
  }

  const snippet = compactFactorText(ev.snippet || ev.text || ev.content || '', 700);
  const out = {
    evidence_id: ev.evidence_id || ev.id || ('E' + String(idx + 1)),
    document_name: compactFactorText(ev.document_name || ev.document || ev.source || '', 180),
    dataset_name: compactFactorText(ev.dataset_name || ev.dataset || '', 140),
    section_title: compactFactorText(ev.section_title || ev.section || '', 180),
    snippet
  };

  return Object.fromEntries(Object.entries(out).filter(([, v]) => v !== '' && v != null));
}

function buildRagUnitsForFactorExtraction(completedUnits, unit) {
  return selectRagContextUnits(completedUnits, unit)
    .slice(0, 8)
    .map((u) => {
      const norm = u && u.normalized_result && typeof u.normalized_result === 'object' ? u.normalized_result : {};
      const evidence = []
        .concat(Array.isArray(u.evidence_summary) ? u.evidence_summary : [])
        .concat(Array.isArray(norm.evidence_summary) ? norm.evidence_summary : [])
        .map(compactEvidenceForFactorExtraction)
        .filter(Boolean)
        .slice(0, 12);

      return {
        unit_id: Number(u.unit_id || 0),
        question_part: asString(u.question_part),
        lang_variant: asString(u.lang_variant),
        answer: compactFactorText(u.answer || u.executor_answer || norm.answer || '', 2600),
        evidence_summary: evidence
      };
    })
    .filter(u => u.answer || (Array.isArray(u.evidence_summary) && u.evidence_summary.length));
}

function hasChineseText(text) {
  return /[\u4e00-\u9fff]/.test(String(text || ''));
}

function cleanRagTerm(term) {
  let s = stripEvidenceMarkers(term)
    .replace(/^.*\b(?:include|includes|including|such as)\b\s+(?:the\s+)?/i, '')
    .replace(/^\s*(?:the\s+)?(?:key|main|important|independent|optimization|operating|control)?\s*(?:variables|factors|parameters|conditions|levers|targets|constraints)\s+(?:are|is)\s+(?:the\s+)?/i, '')
    .replace(/^.*(?:\u5305\u62ec|\u5173\u952e\u53c2\u6570|\u5173\u952e\u64cd\u4f5c\u6761\u4ef6|\u63a7\u5236\u76ee\u6807|\u7ea6\u675f\u6761\u4ef6)[:\uFF1A]?\s*/i, '')
    .replace(/^\s*(?:and|or|the|a|an|specifically|additionally|also)\s+/i, '')
    .replace(/^\s*(?:\u548c|\u53ca|\u4ee5\u53ca|\u5e76\u4e14|\u6b64\u5916|\u5177\u4f53\u6765\u8bf4|\u5176\u4e2d|\u540c\u65f6)\s*/i, '')
    .replace(/\b(?:are|is)\s+(?:independent|key|main|important|core|optimization|operating|control)\b.*$/i, '')
    .replace(/\b(?:raises?|lowers?|increases?|decreases?|affects?|influences?|requires?|identified|noted|recommended|controlled)\b.*$/i, '')
    .replace(/(?:\u4f1a|\u53ef|\u901a\u8fc7|\u5219|\u5bfc\u81f4|\u5f71\u54cd|\u63d0\u9ad8|\u964d\u4f4e|\u63a7\u5236|\u8c03\u6574|\u9700\u76f8\u5e94).*$/i, '')
    .replace(/[()\uFF08\uFF09]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  s = s.replace(/[.;,:\uFF0C\uFF1B\u3002\uFF1A\u3001]+$/g, '').trim();
  const words = s.split(/\s+/).filter(Boolean);
  if (!hasChineseText(s) && words.length > 12) {
    const m = s.match(/(?:[A-Za-z0-9/%'-]+\s+){0,7}(?:temperature|pressure|flow|rate|ratio|activity|point|range|reflux|pumparound|circulation|cut|draw|level|density|quality|yield|throughput|severity|preheat|boiling|distillation|flash|pour)(?:\s+[A-Za-z0-9/%'-]+){0,5}/i);
    if (m) s = m[0].trim();
  }

  return s;
}

function splitRagCandidateFragments(text) {
  const fragments = String(text || '')
    .replace(/\band\b/gi, ',')
    .replace(/\bor\b/gi, ',')
    .replace(/[;.\n\uFF1B\u3002\u3001]/g, ',')
    .split(/[,，]+/)
    .map(cleanRagTerm)
    .filter(Boolean);

  const out = [];
  const seen = new Set();
  for (const fragment of fragments) {
    const key = fragment.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(fragment);
  }
  return out;
}

function extractRagMeasurementTerms(completedUnits, unit) {
  const units = selectRagContextUnits(completedUnits, unit);
  const text = units.map(ragUnitText).join('. ');
  if (!text) return [];

  const keywords = /temperature|pressure|flow|rate|ratio|activity|point|range|reflux|pumparound|circulation|cut|draw|level|density|quality|yield|throughput|severity|preheat|boiling|distillation|flash|pour|\u6e29\u5ea6|\u538b\u529b|\u6d41\u91cf|\u56de\u6d41|\u5faa\u73af|\u62bd\u51fa|\u9876\u6e29|\u9876\u538b|\u5242\u6cb9\u6bd4|\u91cd\u65f6\u7a7a\u901f|\u8f6c\u5316\u7387|\u50ac\u5316\u5242|\u53cd\u5e94\u6e29\u5ea6|\u6cb8\u70b9|\u5e72\u70b9|\u95ea\u70b9|\u503e\u70b9|\u5854\u5e95|\u5854\u9876|\u4eba\u5b57\u6321\u677f|\u6c14\u76f8\u6e29\u5ea6|\u53d6\u70ed\u8d1f\u8377|\u62d4\u51fa\u7387|\u6536\u7387|\u8d28\u91cf/i;
  const chunks = text
    .split(/[,;\.\n\uFF0C\uFF1B\u3002\u3001]+/)
    .map(cleanRagTerm)
    .filter(Boolean)
    .filter(s => keywords.test(s))
    .filter(s => {
      if (hasChineseText(s)) return s.length >= 2 && s.length <= 60;
      const words = s.split(/\s+/).filter(Boolean);
      return words.length >= 2 && words.length <= 14;
    })
    .filter(s => !/evidence|document|available|retrieved|general|specific|cannot|does not|no evidence/i.test(s));

  const out = [];
  const seen = new Set();
  for (const c of chunks) {
    const key = c.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(c);
    if (out.length >= 30) break;
  }
  return out;
}

function isRagDerivedFactorSlot(unit) {
  const p = unit && unit.params ? unit.params : {};
  const f = p.process_factor && typeof p.process_factor === 'object' ? p.process_factor : {};
  const id = asString(f.id);
  return (
    p.query_role === 'rag_derived_process_factor_tag_search' ||
    p.factor_source === 'completed_rag_factor_answer' ||
    /^rag_factor_slot_\d+$/i.test(id)
  );
}

function compactFactorText(value, maxLen = 180) {
  const s = stripEvidenceMarkers(String(value || ''))
    .replace(/\s+/g, ' ')
    .replace(/^[\s;:,]+|[\s;:,]+$/g, '')
    .trim();
  return s.length > maxLen ? s.slice(0, maxLen).trim() : s;
}

function normalizeFactorStringList(value, limit = 12) {
  const raw = Array.isArray(value)
    ? value
    : (typeof value === 'string' ? value.split(/[|;,\uFF0C\u3001]+/) : []);
  return uniqueOrdered(raw.map(v => compactFactorText(v, 140)).filter(Boolean)).slice(0, limit);
}

function normalizeConfidence(value) {
  const s = asString(value).toLowerCase();
  return /^(high|medium|low)$/.test(s) ? s : 'medium';
}

function inferMeasurementType(name, context, explicitType) {
  const raw = asString(explicitType).toLowerCase().replace(/[^a-z_ -]+/g, ' ').trim();
  const known = ['temperature', 'pressure', 'flow', 'rate', 'ratio', 'level', 'composition', 'quality', 'activity', 'severity', 'throughput', 'other'];
  if (known.includes(raw)) return raw;

  const lower = [name, context, raw].join(' ').toLowerCase();
  if (/temperature|temp|preheat|outlet temp|\bti\b|\btrc\b|\u6e29\u5ea6/.test(lower)) return 'temperature';
  if (/pressure|differential pressure|\bpic\b|\bprc\b|\bpi\b|\u538b\u529b|\u538b\u5dee|\u5dee\u538b|\u538b\u964d/.test(lower)) return 'pressure';
  if (/throughput|unit load|fresh feed|feed rate|feed flow/.test(lower)) return 'throughput';
  const chineseRateLike = !/(?:\u542b\u91cf|\u6d53\u5ea6|\u8d28\u91cf|\u5b58\u91cf|\u85cf\u91cf)/.test(lower) &&
    /(?:\u84b8\u6c7d|\u6c14\u4f53|\u4ecb\u8d28|\u6cb9|\u6c34|\u8fdb\u6599|\u56de\u6d41|\u5faa\u73af|\u62bd\u51fa|\u6ce8\u5165|\u52a0\u5165).{0,8}(?:\u91cf|\u7387)/.test(lower);
  if (/flow|rate|circulation|reflux|pumparound|steam|\bfi\b|\bfic\b|\bfrc\b|\u6d41\u91cf/.test(lower) || chineseRateLike) return 'flow';
  if (/ratio|catalyst[- ]?to[- ]?oil|cat.?oil|\u6bd4/.test(lower)) return 'ratio';
  if (/level|\blic\b|\bli\b|\u6db2\u4f4d/.test(lower)) return 'level';
  if (/sulfur|nitrogen|salt|density|solid|composition|content/.test(lower)) return 'composition';
  if (/95|dry point|flash|pour|freezing|distillation|quality|endpoint|end point|\u8d28\u91cf/.test(lower)) return 'quality';
  if (/activity|catalyst/.test(lower)) return 'activity';
  if (/severity|conversion|reaction depth|cracking/.test(lower)) return 'severity';
  return 'other';
}

function normalizeFactorInventoryItem(raw, sourceUnit) {
  let obj = null;
  if (typeof raw === 'string') obj = { name: raw };
  else if (raw && typeof raw === 'object' && !Array.isArray(raw)) obj = raw;
  if (!obj) return null;

  const rawName = obj.name || obj.factor || obj.variable || obj.parameter || obj.label || obj.term;
  const name = cleanRagTerm(rawName);
  if (!name) return null;

  const processContext = compactFactorText(obj.process_context || obj.context || obj.equipment || obj.stream || '', 180);
  const measurementType = inferMeasurementType(name, processContext, obj.measurement_type || obj.measurement || obj.type);
  const aliases = uniqueOrdered([
    name,
    ...normalizeFactorStringList(obj.aliases || obj.synonyms || [], 12)
  ]).slice(0, 12);

  return {
    name,
    measurement_type: measurementType,
    process_context: processContext,
    aliases,
    direction_or_role: compactFactorText(obj.direction_or_role || obj.effect || obj.role || obj.target_or_range || obj.range || obj.constraint || '', 220),
    preferred_tag_query: compactFactorText(obj.preferred_tag_query || obj.tag_query || obj.query || '', 260),
    reject_context: normalizeFactorStringList(obj.reject_context || obj.exclusions || [], 8),
    evidence_ids: normalizeFactorStringList(obj.evidence_ids || obj.evidence || [], 10),
    confidence: normalizeConfidence(obj.confidence),
    source_unit_id: sourceUnit ? Number(sourceUnit.unit_id || 0) || null : null,
    source_question_part: sourceUnit ? asString(sourceUnit.question_part) : ''
  };
}

function factorInventoryArraysFromUnit(u) {
  const norm = u && u.normalized_result && typeof u.normalized_result === 'object' ? u.normalized_result : {};
  const raw = u && u.raw_result && typeof u.raw_result === 'object' ? u.raw_result : {};
  return [u && u.factor_inventory, norm.factor_inventory, raw.factor_inventory]
    .filter(Array.isArray);
}

function factorInventorySourceUnits(completedUnits, unit) {
  const extractorUnits = (completedUnits || [])
    .filter(u => u && u.tool === 'rag_factor_extraction')
    .filter(u => u.execution_status === 'SUCCESS' || u.answer || u.executor_answer || (u.normalized_result && u.normalized_result.factor_inventory))
    .sort((a, b) => Number(a.unit_id || 0) - Number(b.unit_id || 0));

  const factorUnits = (completedUnits || [])
    .filter(u => u && u.tool === 'ragflow_retrieval')
    .filter(u => String(u.question_part || '').trim() === 'factor_identification')
    .filter(u => u.execution_status === 'SUCCESS' || u.answer || u.executor_answer || (u.normalized_result && u.normalized_result.answer))
    .sort((a, b) => Number(a.unit_id || 0) - Number(b.unit_id || 0));

  const supportingUnits = selectRagContextUnits(completedUnits, unit);
  const unitMap = new Map();
  for (const u of extractorUnits) unitMap.set(String(u.unit_id || unitMap.size), u);
  for (const u of factorUnits) unitMap.set(String(u.unit_id || unitMap.size), u);
  for (const u of supportingUnits) unitMap.set(String(u.unit_id || unitMap.size), u);
  return Array.from(unitMap.values());
}

function factorDedupeKey(factor) {
  const name = asString(factor && factor.name).toLowerCase().replace(/[^a-z0-9\u4e00-\u9fff]+/g, ' ').trim();
  const context = asString(factor && factor.process_context).toLowerCase().replace(/[^a-z0-9\u4e00-\u9fff]+/g, ' ').trim();
  return name + '|' + context;
}

function collectStructuredFactorInventory(completedUnits, unit) {
  const units = factorInventorySourceUnits(completedUnits, unit);
  const out = [];
  const byKey = new Map();

  for (const sourceUnit of units) {
    for (const arr of factorInventoryArraysFromUnit(sourceUnit)) {
      for (const raw of arr) {
        const factor = normalizeFactorInventoryItem(raw, sourceUnit);
        if (!factor) continue;
        const key = factorDedupeKey(factor);
        if (!key || key === '|') continue;

        const existingIndex = byKey.get(key);
        if (existingIndex == null) {
          byKey.set(key, out.length);
          out.push(factor);
          continue;
        }

        const existing = out[existingIndex];
        existing.aliases = uniqueOrdered([...(existing.aliases || []), ...(factor.aliases || [])]).slice(0, 12);
        existing.reject_context = uniqueOrdered([...(existing.reject_context || []), ...(factor.reject_context || [])]).slice(0, 8);
        existing.evidence_ids = uniqueOrdered([...(existing.evidence_ids || []), ...(factor.evidence_ids || [])]).slice(0, 10);
        if (!existing.preferred_tag_query && factor.preferred_tag_query) existing.preferred_tag_query = factor.preferred_tag_query;
        if (!existing.direction_or_role && factor.direction_or_role) existing.direction_or_role = factor.direction_or_role;
        if (!existing.process_context && factor.process_context) existing.process_context = factor.process_context;
        if (existing.confidence !== 'high' && factor.confidence === 'high') existing.confidence = 'high';
      }
    }
  }

  const rankMeasurement = factor => {
    const mt = asString(factor && factor.measurement_type).toLowerCase();
    if (/^(temperature|pressure|flow|rate|level|ratio|throughput)$/.test(mt)) return 0;
    if (/^(activity|severity)$/.test(mt)) return 1;
    if (/^(quality|composition)$/.test(mt)) return 2;
    return 3;
  };
  const rankPart = part => {
    if (part === 'factor_identification') return 0;
    if (part === 'target_or_ideal_range') return 1;
    return 2;
  };
  const rankConfidence = conf => conf === 'high' ? 0 : (conf === 'medium' ? 1 : 2);

  return out.sort((a, b) => {
    const mr = rankMeasurement(a) - rankMeasurement(b);
    if (mr) return mr;
    const pr = rankPart(a.source_question_part) - rankPart(b.source_question_part);
    if (pr) return pr;
    const cr = rankConfidence(a.confidence) - rankConfidence(b.confidence);
    if (cr) return cr;
    return Number(a.source_unit_id || 0) - Number(b.source_unit_id || 0);
  });
}

function factorCandidateName(candidate) {
  if (candidate && typeof candidate === 'object' && !Array.isArray(candidate)) {
    return cleanRagTerm(candidate.name || candidate.label || candidate.factor || candidate.variable || candidate.parameter || '');
  }
  return cleanRagTerm(candidate);
}

function factorCandidateAliases(candidate) {
  if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) {
    const name = factorCandidateName(candidate);
    return name ? [name] : [];
  }
  return uniqueOrdered([factorCandidateName(candidate), ...(candidate.aliases || [])]).filter(Boolean).slice(0, 12);
}

function queryLooksLikeQuestion(query) {
  const q = asString(query);
  if (!q) return true;
  const lower = q.toLowerCase();
  const words = q.split(/\s+/).filter(Boolean).length;
  return (
    words > 32 ||
    /\?/.test(q) ||
    /\b(what|why|how|whether|did|does|should|question)\b/.test(lower) ||
    /operating conditions affect|production of|ideal operating ranges|maximi[sz]e|requested period/.test(lower)
  );
}

function measurementHintForFactor(factor) {
  const f = normalizeFactorInventoryItem(factor, null) || { name: factorCandidateName(factor), measurement_type: 'other', process_context: '', aliases: [] };
  const lower = [f.name, f.measurement_type, f.process_context, ...(f.aliases || [])].join(' ').toLowerCase();
  if (f.measurement_type === 'temperature' || /temperature|preheat|outlet temp|\u6e29\u5ea6/.test(lower)) return 'temperature measurement';
  if (f.measurement_type === 'pressure' || /pressure|\u538b\u529b/.test(lower)) return 'pressure measurement';
  if (f.measurement_type === 'flow' || f.measurement_type === 'rate' || f.measurement_type === 'throughput' || /flow|rate|throughput|circulation|reflux|pumparound|fresh feed|\u6d41\u91cf/.test(lower)) return 'flow rate measurement';
  if (f.measurement_type === 'level' || /level|\u6db2\u4f4d/.test(lower)) return 'level measurement';
  if (f.measurement_type === 'ratio' || /ratio|catalyst[- ]?to[- ]?oil/.test(lower)) return 'ratio measurement';
  if (f.measurement_type === 'quality' || /95|dry point|flash|pour|distillation|quality/.test(lower)) return 'product quality measurement';
  if (f.measurement_type === 'activity') return 'catalyst activity measurement';
  if (f.measurement_type === 'severity') return 'operating severity measurement';
  return 'process variable measurement';
}

function buildFactorSearchQuery(selected, unit, params) {
  const factor = normalizeFactorInventoryItem(selected, null) || {
    name: factorCandidateName(selected),
    measurement_type: inferMeasurementType(factorCandidateName(selected), '', ''),
    process_context: '',
    aliases: factorCandidateAliases(selected),
    preferred_tag_query: '',
    reject_context: []
  };

  const preferred = compactFactorText(factor.preferred_tag_query || '', 260);
  if (preferred && !queryLooksLikeQuestion(preferred)) {
    return mergeQueryTerms(preferred, ['exact process tag metadata'], 280);
  }

  const lower = [factor.name, factor.process_context, ...(factor.aliases || [])].join(' ').toLowerCase();
  const contextHints = [];
  if (/fresh feed|feed preheat|feed oil|feedstock|\bfeed\b/.test(lower) && !/water|utility/.test(lower)) {
    contextHints.push('process feed oil');
  }
  if (/recycle|slurry/.test(lower)) {
    contextHints.push('process recycle oil slurry oil');
  }

  return mergeQueryTerms(
    factor.name,
    uniqueOrdered([
      measurementHintForFactor(factor),
      factor.process_context,
      ...contextHints,
      ...(factor.aliases || []).filter(a => a.toLowerCase() !== factor.name.toLowerCase()).slice(0, 3),
      'exact process tag metadata'
    ]),
    280
  );
}

function extractRagFactorSlotTerms(completedUnits, unit) {
  const structured = collectStructuredFactorInventory(completedUnits, unit);
  if (structured.length) return structured.slice(0, 120);

  const factorUnits = (completedUnits || [])
    .filter(u => u && u.tool === 'ragflow_retrieval')
    .filter(u => String(u.question_part || '').trim() === 'factor_identification')
    .filter(u => u.execution_status === 'SUCCESS' || u.answer || u.executor_answer)
    .sort((a, b) => Number(a.unit_id || 0) - Number(b.unit_id || 0));

  const supportingUnits = selectRagContextUnits(completedUnits, unit);
  const unitMap = new Map();
  for (const u of factorUnits) unitMap.set(String(u.unit_id || unitMap.size), u);
  for (const u of supportingUnits) unitMap.set(String(u.unit_id || unitMap.size), u);
  const units = Array.from(unitMap.values());
  const inventoryUnits = factorUnits.length ? factorUnits : units;
  let text = inventoryUnits
    .map(ragUnitInventoryText)
    .filter(Boolean)
    .join('. ');
  if (!text) text = units.map(ragUnitText).join('. ');
  if (!text) return [];

  const keywords = /temperature|pressure|flow|rate|ratio|activity|point|range|reflux|pumparound|circulation|cut|draw|level|density|quality|yield|throughput|severity|preheat|preheater|outlet|feed|feedstock|fresh|recycle|slurry|steam|addition|surface area|cracking|boiling|distillation|flash|pour|\u6e29\u5ea6|\u538b\u529b|\u6d41\u91cf|\u56de\u6d41|\u5faa\u73af|\u62bd\u51fa|\u9876\u6e29|\u9876\u538b|\u5242\u6cb9\u6bd4|\u91cd\u65f6\u7a7a\u901f|\u8f6c\u5316\u7387|\u50ac\u5316\u5242|\u53cd\u5e94\u6e29\u5ea6|\u6cb8\u70b9|\u5e72\u70b9|\u95ea\u70b9|\u503e\u70b9|\u5854\u5e95|\u5854\u9876|\u6c14\u76f8|\u53d6\u70ed|\u62d4\u51fa\u7387|\u6536\u7387|\u8d28\u91cf/i;
  const reject = /evidence|document|available|retrieved|general|specific|cannot|does not|no evidence|ideal range|target range|recommended range|available evidence|not provide|not available|requested period|2025/i;

  const candidates = [];
  const seen = new Set();

  function pushCandidate(value) {
    const s = cleanRagTerm(value);
    if (!s || reject.test(s)) return;
    if (hasChineseText(s)) {
      if (s.length < 2 || s.length > 70) return;
    } else {
      const words = s.split(/\s+/).filter(Boolean);
      if (words.length < 2 || words.length > 12) return;
    }
    const key = s.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    candidates.push(s);
  }

  splitRagCandidateFragments(text)
    .filter(Boolean)
    .filter(s => keywords.test(s))
    .filter(s => !reject.test(s))
    .filter(s => {
      if (hasChineseText(s)) return s.length >= 2 && s.length <= 60;
      const words = s.split(/\s+/).filter(Boolean);
      return words.length >= 2 && words.length <= 12;
    })
    .forEach(pushCandidate);

  return candidates.slice(0, 120);
}

function applyRagDerivedFactorSlot(completedUnits, unit, params) {
  const p = unit && unit.params ? unit.params : {};
  const slotIndex = Number(
    p.factor_slot_index ??
    (p.process_factor && typeof p.process_factor === 'object' ? p.process_factor.slot_index : 0) ??
    0
  );
  const safeSlotIndex = Number.isFinite(slotIndex) && slotIndex >= 0 ? Math.floor(slotIndex) : 0;
  const candidates = extractRagFactorSlotTerms(completedUnits, unit);
  const selected = candidates[safeSlotIndex] || null;
  const selectedName = factorCandidateName(selected);
  const selectedFactor = normalizeFactorInventoryItem(selected, null) || (selectedName ? {
    name: selectedName,
    measurement_type: inferMeasurementType(selectedName, '', ''),
    process_context: '',
    aliases: [selectedName],
    direction_or_role: '',
    preferred_tag_query: '',
    reject_context: [],
    evidence_ids: [],
    confidence: 'medium'
  } : null);
  const slotId = 'rag_factor_slot_' + String(safeSlotIndex + 1);

  if (!selectedName || !selectedFactor) {
    params.query = 'NO_RAG_DERIVED_FACTOR_FOR_SLOT_' + String(safeSlotIndex + 1);
    params.top_k = Math.min(Math.max(Number(params.top_k || 1), 1), 3);
    params.llm_max_tags = 0;
    params.process_factor = {
      id: slotId,
      label: 'No RAG-derived process factor available for slot ' + String(safeSlotIndex + 1),
      aliases: [],
      slot_index: safeSlotIndex,
      source: 'completed_rag_factor_inventory',
      selection_focus: 'No factor was available for this slot. Do not select tags unless metadata directly matches a real injected factor.'
    };
    return {
      applied: false,
      selected: '',
      selected_factor: null,
      candidates,
      slot_index: safeSlotIndex
    };
  }

  params.query = buildFactorSearchQuery(selectedFactor, unit, params);
  params.factor_query = selectedName;
  params.process_factor = {
    id: slotId,
    label: selectedName,
    aliases: factorCandidateAliases(selectedFactor),
    measurement_type: selectedFactor.measurement_type,
    process_context: selectedFactor.process_context,
    direction_or_role: selectedFactor.direction_or_role,
    preferred_tag_query: selectedFactor.preferred_tag_query,
    reject_context: selectedFactor.reject_context,
    evidence_ids: selectedFactor.evidence_ids,
    confidence: selectedFactor.confidence,
    source_unit_id: selectedFactor.source_unit_id,
    slot_index: safeSlotIndex,
    source: 'completed_rag_factor_inventory',
    selection_focus: 'Select tags whose MongoDB historian metadata directly measures this evidence-derived process factor: "' + selectedName + '". Match measurement type and process context. Reject unrelated unit, stream, equipment, utility, or measurement types.'
  };
  params.tag_selection_mode = 'llm_metadata_rerank';
  params.query_role = 'rag_derived_process_factor_tag_search';
  params.semantic = true;
  params.llm_select = true;
  params.llm_decide = true;
  params.llm_max_tags = 4;
  params.llm_catalog_limit = Math.max(Number(params.llm_catalog_limit || 0), 200);
  params.top_k = Math.max(Number(params.top_k || 0), 8);

  return {
    applied: true,
    selected: selectedName,
    selected_factor: selectedFactor,
    candidates,
    slot_index: safeSlotIndex
  };
}

function factorProfileFromUnit(unit) {
  const p = unit && unit.params ? unit.params : {};
  const f = p.process_factor && typeof p.process_factor === 'object' ? p.process_factor : {};
  const id = asString(f.id);
  const label = asString(f.label);
  const aliases = Array.isArray(f.aliases) ? f.aliases.map(asString).filter(Boolean) : [];
  const query = asString(p.factor_query) || asString(p.query);
  if (!id && !label && !aliases.length) return null;

  return {
    id,
    label,
    aliases: uniqueOrdered([label, ...aliases, query]).filter(Boolean)
  };
}

function termMatchesFactor(term, profile) {
  if (!profile) return true;
  const raw = String(term || '').trim();
  if (!raw) return false;
  const s = raw.toLowerCase();

  for (const alias of profile.aliases || []) {
    const a = String(alias || '').trim().toLowerCase();
    if (!a) continue;
    if (s.includes(a) || a.includes(s)) return true;

    const words = a.split(/\s+/).filter(w => w.length >= 4);
    if (words.length >= 2 && words.every(w => s.includes(w))) return true;
  }

  return false;
}

function extractRagMeasurementTermsForUnit(completedUnits, unit) {
  const allTerms = extractRagMeasurementTerms(completedUnits, unit);
  const profile = factorProfileFromUnit(unit);
  if (!profile) return allTerms;

  const matched = allTerms.filter(t => termMatchesFactor(t, profile));
  const seedTerms = uniqueOrdered([...(profile.aliases || [])])
    .filter(t => t.length <= 80)
    .slice(0, 8);

  return uniqueOrdered([...matched, ...seedTerms]).slice(0, 14);
}

function mergeQueryTerms(baseQuery, terms, maxLen) {
  const parts = [];
  const seen = new Set();
  for (const raw of [baseQuery, ...(terms || [])]) {
    const s = String(raw || '').trim();
    if (!s) continue;
    const key = s.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    parts.push(s);
  }
  const joined = parts.join(' ');
  return joined.length > maxLen ? joined.slice(0, maxLen).trim() : joined;
}

function filterTagsByContext(tags, ragContext) {
  const list = Array.from(new Set(tags || [])).filter(Boolean);

  // Keep this conservative. If no usable RAG context, do not over-filter.
  const ctx = String(ragContext || '').toLowerCase();
  if (!ctx) return list;

  const preferredPatterns = [
    /^TRC/i,
    /^TIC/i,
    /^TI/i,
    /^PRC/i,
    /^PIC/i,
    /^PI/i,
    /^FT/i,
    /^FIC/i,
    /^FI/i,
    /^LIC/i,
    /^LI/i
  ];

  const preferred = list.filter(t => preferredPatterns.some(re => re.test(t)));
  return preferred.length ? preferred : list;
}

function sameArcticTarget(unitA, targetParams) {
  const a = unitA && unitA.params ? unitA.params : {};
  const libA = asString(a.library);
  const symA = asString(a.symbol);
  const libB = asString(targetParams && targetParams.library);
  const symB = asString(targetParams && targetParams.symbol);

  if (!libB && !symB) return true;
  if (libB && libA !== libB) return false;
  if (symB && symA !== symB) return false;
  return true;
}

function latestArcticFindTags(completedUnits, targetParams) {
  const candidates = completedUnits
    .filter(u => u.tool === 'arctic_find_tags')
    .filter(u => sameArcticTarget(u, targetParams || {}))
    .filter(u => getTagsFromUnit(u).length > 0)
    .sort((a, b) => Number(b.unit_id || 0) - Number(a.unit_id || 0));

  return candidates[0] || null;
}

function fallbackTagsForTarget(dep, targetParams) {
  // Do not inject predefined process or lab tags. Tag choices must come from arctic_find_tags and the LLM metadata rerank.
  return [];
}

function resolveRef(refStr, completedUnits, targetParams) {
  const normalizedRef = normalizeRuntimeRef(refStr);
  const m = REF_PATTERN.exec(normalizedRef);
  if (!m) return { resolved: false, value: refStr, source: null };

  const stepId = parseInt(m[1], 10);
  const field = m[2];

  let dep = completedUnits.find(u => Number(u.unit_id) === stepId);
  const probeTagField = /^probe_tags$/i.test(field);
  const nonNullTagField = /^non_null_columns$/i.test(field);
  const tagField = /^(?:tags|selected_tags|probe_tags|non_null_columns|columns|matches\[\*\]\.(?:tag|column))$/i.test(field);

  if (nonNullTagField && dep) {
    const sources = [
      dep,
      dep.raw_result,
      dep.normalized_result,
      dep.normalized_result && dep.normalized_result.raw_result
    ].filter(value => value && typeof value === 'object');
    const values = uniqueOrdered(sources.flatMap(source =>
      Array.isArray(source.non_null_columns) ? source.non_null_columns : []
    ));
    return { resolved: true, value: values, source: dep.unit_id };
  }

  if (tagField && (!dep || dep.tool === 'arctic_find_tags')) {
    // STRICT_EXPLICIT_STEP_REFERENCE_V1: never borrow another step's selection.
    if (!dep) return { resolved: false, value: refStr, source: null };
    let tags = probeTagField ? getProbeTagsFromUnit(dep) : getTagsFromUnit(dep);
    // CATALOG_PROBES_JOIN_DATA_CHAIN_V7：主目录查询没有位号时，合并声明的备份目录查询（同一目录请求的不同查询词）选中的位号。
    if (!tags.length && !probeTagField) {
      const __ids = Array.isArray(targetParams && targetParams.catalog_probe_unit_ids)
        ? targetParams.catalog_probe_unit_ids.map(Number).filter(Number.isFinite) : [];
      for (const id of __ids) {
        const p = completedUnits.find(u => Number(u.unit_id) === id);
        if (p && p.tool === 'arctic_find_tags') tags = uniqueOrdered(tags.concat(getTagsFromUnit(p)));
      }
      if (tags.length) {
        try { injectionTrace.push({ policy: 'CATALOG_PROBES_JOIN_DATA_CHAIN_V7', ref: refStr, from_units: __ids, value_preview: tags.slice(0, 12) }); } catch (e) {}
      }
    }
    if (!tags.length) return { resolved: true, value: [], source: dep.unit_id };

    if (probeTagField) {
      return { resolved: true, value: tags, source: dep.unit_id };
    }
    const ragContext = getRagflowContext(completedUnits);
    const filtered = filterTagsByContext(tags, ragContext);

    return {
      resolved: true,
      value: filtered.length > 0 ? filtered : tags,
      source: dep.unit_id
    };
  }

  if (!dep) return { resolved: false, value: refStr, source: null };

  if (/^(?:columns_analyzed|returned_columns|numeric_columns)$/i.test(field)) {
    const sources = [
      dep,
      dep.raw_result,
      dep.normalized_result,
      dep.normalized_result && dep.normalized_result.raw_result
    ].filter(x => x && typeof x === 'object');
    const values = [];
    for (const source of sources) {
      if (Array.isArray(source[field])) values.push(...source[field]);
      if (source.column_stats && typeof source.column_stats === 'object') {
        values.push(...Object.keys(source.column_stats));
      }
      for (const target of Array.isArray(source.targets) ? source.targets : []) {
        values.push(...(Array.isArray(target.returned_columns) ? target.returned_columns : []));
        values.push(...(Array.isArray(target.numeric_columns) ? target.numeric_columns : []));
      }
    }
    const columns = uniqueOrdered(values);
    return {
      resolved: columns.length > 0,
      value: columns.length ? columns : refStr,
      source: dep.unit_id
    };
  }

  if (['query', 'question', 'answer'].includes(field)) {
    const v = asString(dep.answer);
    return { resolved: !!v, value: v || refStr, source: dep.unit_id };
  }

  return { resolved: false, value: refStr, source: dep.unit_id };
}

const item = $input.first().json || {};
const unit = {
  ...(item.unit || {}),
  tool: toInternalTool(item?.unit?.tool)
};
const params = toInternalTarget({ ...(unit.params || {}) });
const completed = getChainCompleted(item);
const defaultTarget = getDefaultArcticTarget(item);

let injected = false;
const injectionTrace = [];

function shouldFlattenRefArray(path) {
  return /(^|\.)(columns|target_columns|candidate_columns)$/.test(String(path || ''));
}

function targetParamsForPath(path) {
  const m = /^params\.targets\.(\d+)\./.exec(String(path || ''));
  if (!m || !Array.isArray(params.targets)) return params;
  const target = params.targets[Number(m[1])] || {};
  return { ...params, ...target, strict_step_ref: true };
}

function resolveRuntimeRefsInValue(value, path) {
  const normalizedRef = typeof value === 'string' ? normalizeRuntimeRef(value) : '';
  if (typeof value === 'string' && REF_PATTERN.test(normalizedRef)) {
    const ref = normalizedRef;
    const targetParams = targetParamsForPath(path);
    const { resolved, value: resolvedValue, source } = resolveRef(ref, completed, targetParams);

    if (resolved) {
      injected = true;
      injectionTrace.push({
        field: path,
        ref,
        resolved_from_unit_id: source,
        value_preview: Array.isArray(resolvedValue) ? resolvedValue.slice(0, 12) : resolvedValue
      });
      return resolvedValue;
    }

    const fallback = path.endsWith('.library') || path === 'library'
      ? defaultTarget.library
      : ((path.endsWith('.symbol') || path === 'symbol') ? defaultTarget.symbol : '');

    if (fallback) {
      injected = true;
      injectionTrace.push({
        field: path,
        ref,
        resolved_from_unit_id: source,
        fallback: 'arctic_default_target',
        value_preview: fallback
      });
      return fallback;
    }

    injectionTrace.push({
      field: path,
      ref,
      resolved_from_unit_id: source,
      unresolved: true
    });
    return value;
  }

  if (Array.isArray(value)) {
    const out = [];
    for (let i = 0; i < value.length; i += 1) {
      const child = resolveRuntimeRefsInValue(value[i], `${path}.${i}`);
      if (Array.isArray(child) && shouldFlattenRefArray(path)) out.push(...child);
      else out.push(child);
    }
    return out;
  }

  if (value && typeof value === 'object') {
    const out = {};
    for (const [k, v] of Object.entries(value)) {
      out[k] = resolveRuntimeRefsInValue(v, path ? `${path}.${k}` : k);
    }
    return out;
  }

  return value;
}

const resolvedParams = resolveRuntimeRefsInValue(params, 'params');
for (const key of Object.keys(params)) delete params[key];
Object.assign(params, resolvedParams);
// GENERIC_SIGNIFICANCE_CONTRACT_V1
if (unit.tool === 'arctic_find_tags' && params.query_role === 'statistical_predictor_discovery') {
  const ids = new Set((unit.depends_on || []).map(Number));
  params.predictor_evidence = completed
    .filter(u => ids.has(Number(u.unit_id)) && u.tool === 'ragflow_retrieval')
    .map(u => ({unit_id: u.unit_id, answer: u.answer || u.executor_answer || '',
      evidence: u.evidence_digest || u.evidence_summary || [],
      factor_inventory: u.factor_inventory || []}));
  // EVIDENCE_PREDICTOR_DISPATCH_V1: this role owns semantic query creation.
  // Do not let legacy lexical/HTML fallback builders replace its inputs.
  delete params.primary_query;
  delete params.fallback_queries;
  unit.tag_selection_mode = 'evidence_predictor_discovery';
  return [{json: {...item, completed_units: toMongoCompletedUnits(completed),
    unit: toMongoUnit({...unit, params}), param_injector_ran: true,
    param_injector_injected: true, param_injection_trace: [...injectionTrace, {
      policy: 'evidence_predictor_dispatch',
      source_unit_ids: params.predictor_evidence.map(e => e.unit_id),
      evidence_available: params.predictor_evidence.length > 0
    }]}}];
}

function significanceContractErrors(p) {
  const errors = [];
  const columns = v => Array.isArray(v) && v.length > 0 && v.every(x =>
    typeof x === 'string' && x.trim() && !normalizeRuntimeRef(x).match(REF_PATTERN));
  if (!columns(p.target_columns)) errors.push('missing_or_unresolved_outcomes');
  if (!columns(p.candidate_columns)) errors.push('missing_or_unresolved_predictors');
  const outcomes = Array.isArray(p.target_columns) ? p.target_columns : [];
  const predictors = Array.isArray(p.candidate_columns) ? p.candidate_columns : [];
  if (outcomes.some(x => predictors.includes(x))) errors.push('overlapping_outcomes_predictors');
  const targets = Array.isArray(p.targets) ? p.targets : [];
  if (!targets.length || targets.some(t => !columns(t.columns))) errors.push('missing_or_unresolved_source_columns');
  const aliases = new Map();
  targets.forEach((t, index) => {
    const name = String(t.name || `${t.library}_${t.symbol}`).trim()
      .replace(/[^A-Za-z0-9_]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 60) || `target_${index}`;
    for (const column of Array.isArray(t.columns) ? t.columns : []) {
      const identity = JSON.stringify([t.library, t.symbol, column]);
      for (const alias of [column, `${name}.${column}`]) {
        if (!aliases.has(alias)) aliases.set(alias, new Set());
        aliases.get(alias).add(identity);
      }
    }
  });
  const model = [...outcomes, ...predictors];
  if (model.some(x => !aliases.has(x))) errors.push('model_columns_not_loaded');
  if (model.some(x => aliases.get(x)?.size > 1)) errors.push('ambiguous_model_columns');
  const identities = model.map(x => [...(aliases.get(x) || [])][0]).filter(Boolean);
  if (new Set(identities).size !== identities.length) errors.push('repeated_physical_model_columns');
  if (!Array.isArray(p.date_range) || p.date_range.length !== 2 ||
      p.date_range.some(x => typeof x !== 'string' || !x.trim() || !Number.isFinite(Date.parse(x))) ||
      Date.parse(p.date_range[0]) > Date.parse(p.date_range[1]) || p.date_range_bounded_by_default === true)
    errors.push('missing_or_invalid_explicit_period');
  if (typeof p.resample_rule !== 'string' || !p.resample_rule.trim()) errors.push('missing_sampling_interval');
  if (!Number.isInteger(p.significance_hac_maxlags) || p.significance_hac_maxlags < 0)
    errors.push('missing_or_invalid_hac_maxlags');
  return errors;
}

if (unit.tool === 'arctic_analyze' && Array.isArray(params.analysis_types) &&
    params.analysis_types.includes('regression_significance')) {
  const errors = significanceContractErrors(params);
  // Preserve the whole model: generic date defaults, column caps and independent
  // batching below must not silently change a significance request.
  const resultUnit = errors.length ? {
    ...unit, tool: 'direct_response', source_type: 'system',
    required_evidence_types: [], optional_evidence_types: [],
    params: {
      mode: 'unresolved_analysis_columns', no_retrieval: true,
      blocked_tool: 'arctic_analyze', status: 'missing_prerequisites',
      validation_errors: errors, requested_analysis: params,
      text: 'Statistical significance analysis was not executed. Missing or invalid prerequisites: ' +
        errors.join(', ') + '. This does not establish that measurements are absent or effects are insignificant.',
      summary_instruction: 'Report these analysis gaps in the user language. Preserve other retrieved evidence; this is not a conversation summary.'
    }
  } : {...unit, params};
  delete resultUnit.arctic_analyze_column_batches;
  delete resultUnit.arctic_analyze_time_windows;
  delete resultUnit.arctic_analyze_boundary_probe;
  return [{json: {...item, completed_units: toMongoCompletedUnits(completed), unit: toMongoUnit(resultUnit),
    param_injector_ran: true, param_injector_injected: true,
    param_injection_trace: [...injectionTrace, {
      policy: 'generic_significance_contract', status: errors.length ? 'blocked' : 'ready', errors
    }]}}];
}


// ARCTIC_RESOLVED_COLUMN_BUDGET_V5
function cleanResolvedColumns(value) {
  return uniqueOrdered((Array.isArray(value) ? value.flat(Infinity) : [value])
    .map(String)
    .map(x => x.trim())
    .filter(Boolean)
    .filter(x => !/^(?:undefined|null)$/i.test(x))
    .filter(x => !isRuntimeRef(x)));
}

function capResolvedColumns(value, field, maxColumns) {
  const columns = cleanResolvedColumns(value);
  if (columns.length > maxColumns) {
    injected = true;
    injectionTrace.push({
      field,
      policy: 'arctic_column_budget',
      requested_count: columns.length,
      emitted_count: maxColumns
    });
  }
  return columns.slice(0, maxColumns);
}

function configuredArcticReadLimits() {
  let arctic = {};
  try {
    const workflowItem = $('Workflow Configuration').first().json || {};
    const runParams = workflowItem.run_params && typeof workflowItem.run_params === 'object'
      ? workflowItem.run_params
      : JSON.parse(workflowItem.run_params || '{}');
    arctic = runParams?.arcticdb && typeof runParams.arcticdb === 'object'
      ? runParams.arcticdb
      : {};
  } catch (e) {}
  const bounded = (value, fallback, maximum) => {
    const number = Number(value);
    return Number.isFinite(number) && number >= 1 && number <= maximum
      ? Math.floor(number)
      : fallback;
  };
  return {
    columnLimit: bounded(arctic.read_column_limit, 20, 48),
    boundedHeadLimit: bounded(arctic.bounded_read_head_limit, 50, 1000),
    // ARCTIC_STATS_COLUMN_BATCHING_V5
    // Operational request sizing only; it does not alter tags or time scope.
    statsColumnBatchSize: bounded(arctic.stats_column_batch_size, 3, 12)
  };
}

// LONG_RANGE_READ_TO_STATS_V5
// A long unbounded raw read is not a viable way to answer a distribution or
// threshold question. Convert it to the historian's compact statistics tool
// unless the user explicitly asked for raw rows or an export.
function dateRangeSpanDays(value) {
  if (!Array.isArray(value) || value.length !== 2) return null;
  const start = Date.parse(value[0]);
  const end = Date.parse(value[1]);
  if (!Number.isFinite(start) || !Number.isFinite(end) || end < start) return null;
  return (end - start) / 86400000;
}

function explicitlyRequestsRawRows(value) {
  return /(?:原始(?:数据|记录)|逐条|逐行|每一条|明细(?:数据|记录)|导出|下载|完整记录|raw\s+(?:rows|records|data)|row[- ]level|export|download)/i.test(String(value || ''));
}

const requestedRangeDays = dateRangeSpanDays(params.date_range);
if (
  unit.tool === 'arctic_read' &&
  requestedRangeDays != null &&
  requestedRangeDays > 7 &&
  !explicitlyRequestsRawRows(item.originalUserMessage) &&
  !params.head && !params.tail && !params.limit
) {
  unit.tool = 'arctic_stats';
  delete params.resample_rule;
  delete params.aggregation;
  injected = true;
  injectionTrace.push({
    field: 'unit.tool',
    policy: 'long_range_read_to_stats',
    requested_days: Number(requestedRangeDays.toFixed(3)),
    from: 'arctic_read',
    to: 'arctic_stats'
  });
}

const maxArcticColumns = 48;
const arcticReadLimits = configuredArcticReadLimits();
if (['arctic_stats', 'arctic_read'].includes(unit.tool) && Array.isArray(params.columns)) {
  const limit = unit.tool === 'arctic_read'
    ? arcticReadLimits.columnLimit
    : maxArcticColumns;
  params.columns = capResolvedColumns(params.columns, 'params.columns', limit);
}
if (
  unit.tool === 'arctic_read' &&
  Array.isArray(params.date_range) &&
  params.date_range.length === 2 &&
  Number(params.head || 0) > arcticReadLimits.boundedHeadLimit
) {
  const requestedHead = Number(params.head);
  params.head = arcticReadLimits.boundedHeadLimit;
  injected = true;
  injectionTrace.push({
    field: 'params.head',
    policy: 'bounded_read_preview_limit',
    requested_count: requestedHead,
    emitted_count: params.head
  });
}
if (unit.tool === 'arctic_analyze') {
  if (Array.isArray(params.candidate_columns)) {
    params.candidate_columns = capResolvedColumns(
      params.candidate_columns,
      'params.candidate_columns',
      maxArcticColumns
    );
  }

  // ANALYZE_TARGET_COLUMN_RECONCILIATION_V5
  // Some valid plans express relationship roles at the top level while the
  // physical target omits columns. Reconcile the two representations before
  // applying column budgets. Never stringify undefined as a column name.
  if (Array.isArray(params.targets) && params.targets.length) {
    const declaredColumns = cleanResolvedColumns(
      []
        .concat(Array.isArray(params.target_columns) ? params.target_columns : [])
        .concat(Array.isArray(params.candidate_columns) ? params.candidate_columns : [])
    );
    const hasPhysicalColumns = params.targets.some(
      target => cleanResolvedColumns(target?.columns).length > 0
    );
    if (!hasPhysicalColumns && declaredColumns.length) {
      params.targets = params.targets.map((target, index) => ({
        ...(target && typeof target === 'object' ? target : {}),
        columns: index === 0 ? declaredColumns : []
      }));
      injected = true;
      injectionTrace.push({
        field: 'params.targets.0.columns',
        policy: 'reconciled_from_top_level_analysis_columns',
        target_count: Array.isArray(params.target_columns) ? params.target_columns.length : 0,
        candidate_count: Array.isArray(params.candidate_columns) ? params.candidate_columns.length : 0,
        emitted_count: declaredColumns.length
      });
    }
  }

  let remaining = maxArcticColumns;
  if (Array.isArray(params.targets)) {
    params.targets = params.targets.map((raw, index) => {
      const target = raw && typeof raw === 'object' ? { ...raw } : {};
      const columns = cleanResolvedColumns(target.columns);
      const kept = columns.slice(0, Math.max(0, remaining));
      remaining -= kept.length;
      if (kept.length < columns.length) {
        injected = true;
        injectionTrace.push({
          field: `params.targets.${index}.columns`,
          policy: 'arctic_column_budget',
          requested_count: columns.length,
          emitted_count: kept.length
        });
      }
      target.columns = kept;
      return target;
    });
  }
}

// EVENT_CORRELATION_INTEGRITY_V5
function normalizeAnalyzeColumn(value) {
  return String(value || '').trim().toUpperCase();
}

function dedupeAnalyzeTargets(targets) {
  const seenColumnsBySource = new Set();
  const kept = [];
  const dropped = [];

  for (const rawTarget of Array.isArray(targets) ? targets : []) {
    if (!rawTarget || typeof rawTarget !== 'object') continue;
    const target = { ...rawTarget };
    const columns = Array.isArray(target.columns)
      ? target.columns.map(String).map(x => x.trim()).filter(Boolean)
      : [];
    if (!columns.length) {
      dropped.push({ target: target.name || '', reason: 'no_resolved_columns' });
      continue;
    }

    // WINDOW_AWARE_ANALYZE_TARGET_IDENTITY_V5
    // The same physical columns in disjoint analysis windows are intentional,
    // not duplicates. Within one window, overlapping columns remain deduped.
    const targetRange = Array.isArray(target.date_range)
      ? target.date_range.map(value => String(value || '').trim()).slice(0, 2)
      : [];
    const rangeKey = targetRange.length === 2
      ? targetRange.join('..').toLowerCase()
      : 'unbounded';
    const sourceKey = [
      String(target.library || '').trim().toLowerCase(),
      String(target.symbol || '').trim().toLowerCase(),
      rangeKey
    ].join('|');
    const distinctColumns = [];
    const duplicateColumns = [];
    for (const column of columns) {
      const identity = `${sourceKey}|${normalizeAnalyzeColumn(column)}`;
      if (seenColumnsBySource.has(identity)) duplicateColumns.push(column);
      else {
        seenColumnsBySource.add(identity);
        distinctColumns.push(column);
      }
    }

    if (!distinctColumns.length) {
      dropped.push({
        target: target.name || '',
        reason: 'duplicates_existing_source_columns',
        columns: duplicateColumns
      });
      continue;
    }

    if (duplicateColumns.length) {
      dropped.push({
        target: target.name || '',
        reason: 'removed_overlapping_source_columns',
        columns: duplicateColumns
      });
    }
    kept.push({ ...target, columns: distinctColumns });
  }

  return { kept, dropped };
}

// RELATIONSHIP_RESAMPLE_EXECUTION_CONTRACT_V5
// The tool agent must receive an explicit cadence; omission allowed it to
// invent a daily default that collapsed short windows to one observation.
function explicitlyRequestsCadence(text) {
