// ARCTIC_CADENCE_CANONICALIZATION_V5
// Arctic Analyzer requires an explicit quantity and unit. Models may emit a
// valid bare unit such as "h" or "d"; canonicalize it at the execution boundary
// without changing an explicitly supplied quantity.
function canonicalArcticResampleRule(value) {
  const raw = String(value || '').trim().toLowerCase().replace(/\s+/g, '');
  if (!raw) return '';
  const aliases = {
    s: '1s',
    sec: '1s',
    second: '1s',
    min: '1min',
    minute: '1min',
    h: '1h',
    hr: '1h',
    hour: '1h',
    d: '1d',
    day: '1d'
  };
  if (aliases[raw]) return aliases[raw];
  const match = /^(\d+)(s|sec|second|min|minute|h|hr|hour|d|day)$/.exec(raw);
  if (!match) return '';
  const unitAliases = {
    s: 's',
    sec: 's',
    second: 's',
    min: 'min',
    minute: 'min',
    h: 'h',
    hr: 'h',
    hour: 'h',
    d: 'd',
    day: 'd'
  };
  return `${match[1]}${unitAliases[match[2]]}`;
}

