function requestedEventContextHours(text) {
  const value = String(text || '');
  const patterns = [
    /前后\s*(\d+(?:\.\d+)?)\s*(?:个)?小时/i,
    /(?:±|\+\/-)\s*(\d+(?:\.\d+)?)\s*(?:h|小时)/i,
    /(\d+(?:\.\d+)?)\s*(?:hours?|hrs?|h)\s*(?:before\s+and\s+after|around)/i
