// REST 未配置才走 MCP。边界直读与越限时刻定位共用，时间格式与返回解析只维护一处。
async function __historianRead(args) {
  let spec = null, base = '';
  try {
    const tools = ((item.catalog || {}).mongodb || {}).tools || [];
    spec = tools.find(t => t && /_read$/.test(String(t.name || '')) && t.path && t.inputs) || null;
  } catch (e) {}
  try {
    const wc = $('Workflow Configuration').first().json || {};
    const rp = typeof wc.run_params === 'string' ? JSON.parse(wc.run_params) : (wc.run_params || {});
    base = String((rp.mongodb && rp.mongodb.rest_base_url) || '').replace(/\/+$/, '');
  } catch (e) {}
  if (spec && base) {
    if (Date.now() > __mcpDeadline - 1000) throw new Error('historian read time budget exhausted');
    const allowed = new Set(Object.keys(spec.inputs || {}));
    const body = {};
    for (const [k, v] of Object.entries(args || {})) if (allowed.has(k) && v !== undefined) body[k] = v;
    const res = await __piCtx.helpers.httpRequest({
      method: String(spec.method || 'POST').toUpperCase(), url: base + spec.path, body, json: true,
      timeout: Math.max(1000, Math.min(10000, __mcpDeadline - Date.now()))
    });
    return { via: 'rest', res: (typeof res === 'string' ? JSON.parse(res) : res) || {} };
  }
  return { via: 'mcp', res: await __mcpCallTool('mongo_read', args) };
}

async function __readHistoryBoundaryDirect(p) {
  const trace = { policy: 'HISTORY_BOUNDARY_DIRECT_READ_V7' };
  try {
    const target = Array.isArray(p.targets) && p.targets[0] ? p.targets[0] : p;
    const col = cleanResolvedColumns(target.columns)[0];
    if (!col) { trace.skipped = 'no_resolved_column'; injectionTrace.push(trace); return []; }
    // MCP_READ_ARGS_V7：mongo_read 只收 database / collection（exec 143060：多传 library/symbol 被参数校验拒绝）。
    const base = {
      database: target.database || p.database || target.library || p.library,
      collection: target.collection || p.collection || target.symbol || p.symbol
    };
    if (!base.database) delete base.database;
    if (!base.collection) delete base.collection;
    const filters = [{ col, op: '!=', val: null }];
    const q1 = await __historianRead({ ...base, columns: [col], head: 1, filters });
    const first = q1.res;
    const last = (await __historianRead({ ...base, columns: [col], tail: 1, filters })).res;
    const toolName = 'mongo_read(' + q1.via + ')';
    // MCP_RECORDS_TIME_V7：MCP mongo_read 原始返回为 {data, records:[{time, <列>}]}，没有 time_range（exec 147286 因此拒用）。
    const ts = r => {
      if (Array.isArray(r && r.time_range) && r.time_range.length) return r.time_range.map(String);
      const recs = Array.isArray(r && r.records) ? r.records : [];
      const tOf = x => { const o = x && typeof x === 'object' ? x : {}; return o.time || o.timestamp || o.date || o.index || ''; };
      return recs.length ? [String(tOf(recs[0])), String(tOf(recs[recs.length - 1]))] : [];
    };
    const a = ts(first)[0];
    const b = ts(last).slice(-1)[0];
    const am = Date.parse(a);
    const bm = Date.parse(b);
    Object.assign(trace, { tool: toolName, column: col, first: a || null, last: b || null });
    if (!Number.isFinite(am) || !Number.isFinite(bm) || am <= 0 || bm < am) {
      trace.rejected = true;
      trace.first_raw = first && (first.__raw || first.__error) || null;
      trace.last_raw = last && (last.__raw || last.__error) || null;
      injectionTrace.push(trace);
      return [];
    }
    injectionTrace.push(trace);
    return [a, b];
  } catch (e) {
    trace.error = String((e && e.message) || e).slice(0, 300);
    injectionTrace.push(trace);
    return [];
  }
}

