      const u = completed.find(x => Number(x.unit_id) === id);
      if (!u) continue;
      const srcs = [u.raw_result, u.normalized_result && u.normalized_result.raw_result, u]
        .filter(x => x && typeof x === 'object');
      for (const src of srcs) {
        const tr = Array.isArray(src.time_range) ? src.time_range : [];
        if (tr.length !== 2) continue;
        const a = Date.parse(tr[0]);
        const b = Date.parse(tr[1]);
