// FOCUSED_RAG_TAG_CONTEXT_V5
// Reuse only a short, query-relevant process phrase from same-turn RAG. The
// scorer is lexical and generic: it contains no equipment names, tag IDs, or
// question-specific branches.
function semanticQueryFragments(value) {
  const text = String(value || '').toLowerCase();
  const fragments = [];
  const generic = new Set([
    '什么', '如何', '是否', '哪些', '多少', '情况', '数据', '历史', '正常',
    '范围', '变化', '分析', '比较', '最近', '当前', '结果', '影响',
    'what', 'which', 'how', 'data', 'history', 'normal', 'range', 'current'
  ]);

  for (const run of (text.match(/[\u4e00-\u9fff]{2,}/g) || [])) {
    for (const size of [4, 3, 2]) {
      for (let index = 0; index + size <= run.length; index += 1) {
        const part = run.slice(index, index + size);
        if (!generic.has(part)) fragments.push(part);
      }
    }
  }
  for (const word of (text.match(/[a-z][a-z0-9_-]{2,}/g) || [])) {
    if (!generic.has(word)) fragments.push(word);
  }
  return uniqueOrdered(fragments).slice(0, 80);
}

function focusedRagTagContext(completedUnits, query) {
  const fragments = semanticQueryFragments(query);
  if (!fragments.length) return { phrases: [], source_unit_ids: [] };

  const candidates = [];
  for (const sourceUnit of (completedUnits || [])) {
    if (!sourceUnit || sourceUnit.tool !== 'ragflow_retrieval') continue;
    const evidenceTexts = (Array.isArray(sourceUnit.evidence_digest) ? sourceUnit.evidence_digest : []).flatMap(item => {
      if (!item || typeof item !== 'object') return [];
      return [
        item.section_title,
        item.snippet,
        item.content_summary,
        item.relevance_to_question,
        ...(Array.isArray(item.key_points) ? item.key_points : [])
      ].filter(Boolean).map(text => ({ text, priority: 12 }));
    });
    const factorTexts = (Array.isArray(sourceUnit.factor_inventory) ? sourceUnit.factor_inventory : []).flatMap(item => {
      if (!item || typeof item !== 'object') return [];
      return [
        item.name,
        item.process_context,
        item.preferred_tag_query,
        ...(Array.isArray(item.aliases) ? item.aliases : [])
      ].filter(Boolean).map(text => ({ text, priority: 8 }));
    });
    const rawTexts = [
      { text: sourceUnit.answer, priority: 0 },
      { text: sourceUnit.executor_answer, priority: 0 },
      { text: sourceUnit.normalized_result && sourceUnit.normalized_result.answer, priority: 0 },
      ...evidenceTexts,
      ...factorTexts
    ].filter(item => item && item.text);

    for (const rawItem of rawTexts) {
      const cleaned = stripEvidenceMarkers(rawItem.text).replace(/\s+/g, ' ').trim();
      if (!cleaned) continue;
      for (const sentenceRaw of cleaned.split(/[。！？!?；;\n]+/)) {
      const sentence = sentenceRaw.trim();
      if (sentence.length < 6) continue;
      if (/(?:不相关|无关|不涉及|没有任何|均未|而非|并非|未(?:能|曾|直接|明确|实际)?(?:提供|涉及|包含|找到|检索到|返回|给出)|近似结果|near[- ]?miss|irrelevant|not\s+(?:related|relevant)|does\s+not\s+(?:provide|contain|mention))/i.test(sentence)) continue;
      const lower = sentence.toLowerCase();
      const matched = fragments.filter(fragment => lower.includes(fragment));
      const distinctLong = matched.filter(fragment => fragment.length >= 3);
      if (!distinctLong.length && matched.length < 2) continue;
      const score = rawItem.priority + matched.reduce((sum, fragment) => sum + Math.min(fragment.length, 5), 0);
      candidates.push({
        sentence,
        score,
        unit_id: Number(sourceUnit.unit_id || 0) || null
      });
      }
    }
  }

  candidates.sort((a, b) => b.score - a.score || b.sentence.length - a.sentence.length || Number(a.unit_id || 0) - Number(b.unit_id || 0));
  const sourceUnitIds = uniqueOrdered(candidates.map(candidate => candidate.unit_id).filter(Boolean)).map(Number).sort((a, b) => a - b);
  const orderedCandidates = [];
  for (const sourceId of sourceUnitIds) {
    orderedCandidates.push(...candidates.filter(candidate => candidate.unit_id === sourceId).slice(0, 2));
  }
  orderedCandidates.push(...candidates);
  const phrases = [];
  const selectedSourceIds = [];
  for (const candidate of orderedCandidates) {
    const phrase = compactFactorText(candidate.sentence, 120);
    if (!phrase || phrases.some(existing => existing.includes(phrase) || phrase.includes(existing))) continue;
    phrases.push(phrase);
    if (candidate.unit_id) selectedSourceIds.push(candidate.unit_id);
    if (phrases.length >= 4) break;
  }
  return {
    phrases,
    source_unit_ids: uniqueOrdered(selectedSourceIds).map(Number)
  };
}

