// ARCTIC_UTC_QUERY_CONTRACT_V5
// Planned ArcticDB date ranges are UTC query bounds. arctic_read may return
// offset-bearing local timestamps for display; do not shift the query bounds
// before execution.

// FULL_HISTORY_WINDOW_DERIVATION_V5
// Availability checks discover the symbol's first/last timestamps at runtime.
// Only then are complete, contiguous windows generated under the MCP limit.
function completedUnitById(unitId) {
  const wanted = Number(unitId);
  return completed.find(entry => Number(entry?.unit_id) === wanted) || null;
}

function collectTimeRanges(value, out = [], depth = 0) {
  if (depth > 8 || value == null) return out;
  if (Array.isArray(value)) {
    if (value.length >= 1 && value.length <= 2 && value.every(part => typeof part === 'string')) {
      const parsed = value.map(part => Date.parse(part));
      if (parsed.every(Number.isFinite)) out.push(value);
    }
    for (const child of value) collectTimeRanges(child, out, depth + 1);
    return out;
  }
  if (typeof value === 'object') {
    for (const [key, child] of Object.entries(value)) {
      if (/time_range|date_range|index_range/i.test(key)) collectTimeRanges(child, out, depth + 1);
      else if (depth < 4) collectTimeRanges(child, out, depth + 1);
    }
  }
  return out;
}

function boundaryTimestamp(unitId, side) {
  const entry = completedUnitById(unitId);
  const ranges = collectTimeRanges(entry || {});
  const values = ranges.flat().map(value => ({ value, ms: Date.parse(value) })).filter(row => Number.isFinite(row.ms));
  if (!values.length) return null;
  values.sort((a, b) => a.ms - b.ms);
  return side === 'end' ? values[values.length - 1] : values[0];
}

function contiguousWindows(startMs, endMs, maxDays = 175) {
  if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs < startMs) return [];
  const span = Math.max(1, Math.min(Number(maxDays) || 175, 179)) * 86400000;
  const windows = [];
  let cursor = startMs;
  while (cursor <= endMs && windows.length < 64) {
    const stop = Math.min(endMs, cursor + span - 1);
    windows.push([new Date(cursor).toISOString(), new Date(stop).toISOString()]);
    cursor = stop + 1;
  }
  return windows;
}

function collectNamedColumns(value, keyPattern, out = [], depth = 0) {
  if (depth > 8 || value == null) return out;
  if (Array.isArray(value)) {
    for (const child of value) collectNamedColumns(child, keyPattern, out, depth + 1);
    return out;
  }
  if (typeof value === 'object') {
    for (const [key, child] of Object.entries(value)) {
      if (keyPattern.test(key) && Array.isArray(child)) out.push(...child.map(asString).filter(Boolean));
      else collectNamedColumns(child, keyPattern, out, depth + 1);
    }
  }
  return uniqueOrdered(out);
}

