  const requested = uniqueOrdered(Array.isArray(params.columns) ? params.columns : []);
  const confirmedSet = new Set(confirmed.map(value => value.toLowerCase()));
  const remaining = requested.filter(value => !confirmedSet.has(value.toLowerCase()));
  const windows = start && end ? contiguousWindows(start.ms, end.ms) : [];
  if (confirmed.length && remaining.length === 0) {
