// MEMORY_REFERENCE_RESOLUTION_V6
// Planner memory references are execution envelopes, never historian columns.
function memoryStateForExecution() {
  let captured = {};
  try { captured = $('Capture context').first().json || {}; } catch (e) {}
  const planner = captured.conversation_state_for_planner || {};
  const llm = captured.conversation_state_for_llm || {};
  return {
    fact_cards: [
      ...(Array.isArray(planner.fact_cards) ? planner.fact_cards : []),
      ...(Array.isArray(llm.fact_cards) ? llm.fact_cards : [])
    ],
    arctic_target_registry: [
      ...(Array.isArray(planner.arctic_target_registry) ? planner.arctic_target_registry : []),
      ...(Array.isArray(llm.arctic_target_registry) ? llm.arctic_target_registry : [])
    ]
  };
}

function isTagLike(value) {
  return /^[A-Z][A-Z0-9_]{1,30}(?:\.(?:PV|SP|OP|MV|SV|CV))?$/i.test(asString(value));
}

function resolveMemoryColumnReference(reference) {
  const raw = asString(reference);
  if (!/^\$memory:/i.test(raw)) return null;
  const intentTokens = raw.slice(raw.indexOf(':') + 1).toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
  const needsConfirmed = intentTokens.includes('confirmed');
  const needsNonNull = intentTokens.includes('non') && intentTokens.includes('null');
  const state = memoryStateForExecution();
  const facts = state.fact_cards.filter(fact => {
    const relation = asString(fact?.relation).toLowerCase();
    const status = asString(fact?.status).toLowerCase();
    const value = asString(fact?.value).toLowerCase();
    const subject = asString(fact?.subject);
    if (!isTagLike(subject)) return false;
    if (needsConfirmed && status !== 'confirmed') return false;
    if (needsNonNull && !(relation.includes('data_availability') && value.includes('non_null'))) return false;
    return true;
  });

  // A follow-up must consume one coherent availability snapshot, not a union of
  // unrelated old analyses. Prefer the newest source timestamp/turn group.
  const groups = new Map();
  for (const fact of facts) {
    const key = asString(fact?.source_ts || fact?.source_turn || 'undated');
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(asString(fact.subject));
  }
  const latestKey = [...groups.keys()].sort((a, b) => {
    const ams = Date.parse(a); const bms = Date.parse(b);
    if (Number.isFinite(ams) && Number.isFinite(bms)) return bms - ams;
    return b.localeCompare(a);
  })[0];
  let columns = latestKey ? groups.get(latestKey) : [];

  if (!columns.length) {
    columns = state.arctic_target_registry
      .filter(row => !needsConfirmed || /confirmed|available|non.?null/i.test(asString(row?.status || row?.data_status)))
      .map(row => row?.tag || row?.column)
      .filter(isTagLike);
  }
  return uniqueOrdered(columns);
}

if (unit.tool === 'arctic_analyze' && Array.isArray(params.targets)) {
  const resolutionTrace = [];
  let unresolvedReference = null;
  params.targets = params.targets.map(target => {
    const nextTarget = { ...(target || {}) };
    const columns = Array.isArray(nextTarget.columns) ? nextTarget.columns : [];
    const resolved = [];
    for (const column of columns) {
      const memoryColumns = resolveMemoryColumnReference(column);
      if (memoryColumns === null) resolved.push(column);
      else if (memoryColumns.length) {
        resolved.push(...memoryColumns);
        resolutionTrace.push({ reference: column, resolved_count: memoryColumns.length });
      } else unresolvedReference = asString(column);
    }
    nextTarget.columns = uniqueOrdered(resolved.filter(isTagLike));
    if (resolutionTrace.length) nextTarget.target_resolution_source = 'conversation_structured_availability_facts';
    return nextTarget;
  }).filter(target => Array.isArray(target.columns) && target.columns.length);

  if (unresolvedReference && !params.targets.length) {
    unit.skip_execution = true;
    unit.skip_result = {
      tool: 'arctic_analyze',
      status: 'error',
      error: 'The requested measurement set could not be resolved from structured conversation memory.',
      raw_result: {
        unresolved_memory_reference: unresolvedReference,
        analysis_completed: false,
        data_scope: 'unresolved_measurement_set'
      }
    };
  }
  if (resolutionTrace.length) {
    unit.memory_reference_resolution = resolutionTrace;
    injected = true;
    injectionTrace.push({
      field: 'unit.params.targets[].columns',
      enrichment: 'structured_memory_reference_resolution',
      references: resolutionTrace
    });
  }
}

// ARCTIC_TARGET_CONSISTENCY_V5
// Discovery and consumption must use the same configured historian target.
// FORMULA_EXPANSION_LAST_MILE_V6：执行前补足公式检索记号
// TAG_ANCHORED_RETRIEVAL_V7
// 依赖位号检索单元的知识库检索（如报警阈值）要找的是这些位号本身的资料；问句式查询把报警位号表排到第 4 且是别的片段，
// 直接用位号作查询词时报警位号表稳定排第 1（RAGFlow 实测）。加一路只含已选位号的变体，放在最前。
if (unit.tool === 'ragflow_retrieval') {
  try {
    const depIds = (Array.isArray(unit.depends_on) ? unit.depends_on : []).map(Number).filter(Number.isFinite);
    const tagBases = [];
    for (const id of depIds) {
      const dep = completed.find(u => Number(u.unit_id) === id);
      if (!dep || dep.tool !== 'arctic_find_tags') continue;
      for (const t of getTagsFromUnit(dep)) {
        const b = String(t || '').toUpperCase().trim().replace(/\.[A-Z]{1,4}$/, '');
        if (b && !tagBases.includes(b)) tagBases.push(b);
      }
    }
    // TAG_DOCUMENT_RETRIEVAL_V7：位号资料检索单元只用位号查询——裸位号（报警位号表）与「位号.PV」（装置月报里的叫法）。
    if (tagBases.length && params.tag_document_lookup === true) {
      const bases = tagBases.slice(0, 6);
      const tmpl = { dataset_ids: params.dataset_ids, page_size: params.page_size, top_k: params.top_k, keyword: params.keyword };
      params.query_variants = [
        { ...tmpl, variant_id: 'tag_document_bare', lang_variant: 'resolved_tag_identifiers', question: bases.join(' ') },
        { ...tmpl, variant_id: 'tag_document_pv', lang_variant: 'resolved_tag_historian_names', question: bases.map(b => b + '.PV').join(' ') }
      ];
      params.question = bases.join(' ');
      params.variant_count = params.query_variants.length;
      params.tag_anchored_query = params.question;
      injected = true;
      injectionTrace.push({ field: 'params.query_variants', policy: 'TAG_DOCUMENT_RETRIEVAL_V7', value_preview: params.query_variants.map(v => v.question) });
    } else if (tagBases.length) {
      const q = tagBases.slice(0, 6).join(' ');
      const existing = Array.isArray(params.query_variants) && params.query_variants.length
        ? params.query_variants
        : [{ question: params.question, variant_id: 'single_query' }];
      const template = existing[0] && typeof existing[0] === 'object' ? existing[0] : {};
      params.query_variants = [{ ...template, variant_id: 'tag_anchored', lang_variant: 'resolved_tag_identifiers', question: q }].concat(existing);
      params.variant_count = params.query_variants.length;
      params.tag_anchored_query = q;
      injected = true;
      injectionTrace.push({ field: 'params.query_variants', policy: 'TAG_ANCHORED_RETRIEVAL_V7', value_preview: q });
    }
  } catch (e) {}
}

if (unit.tool === 'ragflow_retrieval') {
  const context = [
    params.question,
    params.resolved_question,
    params.question_literal,
    item.originalUserMessage
  ].map(x => String(x || '')).join(' ');

  if (bossNeedsFormulaQueryV6(context)) {
    function enrichFormulaQuery(target) {
      const question = String(target.question || '').trim();
      if (!question) return;

      if (!question.includes('ρgh')) {
        target.question = [question, FORMULA_TOKENS_V6].join('\n');
      }

      target.page_size = Math.max(Number(target.page_size || 0), 10);
      target.top_k = Math.max(Number(target.top_k || 0), 128);
      target.keyword = true;
    }

    enrichFormulaQuery(params);

    if (Array.isArray(params.query_variants)) {
      params.query_variants = params.query_variants.map(variant => {
        const enriched = { ...variant };
        enrichFormulaQuery(enriched);
        return enriched;
      });
    }
  }
}
if (['arctic_find_tags', 'arctic_stats', 'arctic_read', 'arctic_analyze'].includes(unit.tool)) {
  if (defaultTarget.library && (!asString(params.library) || isRuntimeRef(params.library))) {
    params.library = defaultTarget.library;
    injected = true;
    injectionTrace.push({
      field: 'library',
      fallback: 'arctic_default_target',
      value_preview: defaultTarget.library
    });
  }

  if (defaultTarget.symbol && (!asString(params.symbol) || isRuntimeRef(params.symbol))) {
    params.symbol = defaultTarget.symbol;
    injected = true;
    injectionTrace.push({
      field: 'symbol',
      fallback: 'arctic_default_target',
      value_preview: defaultTarget.symbol
    });
  }
}

// BOUNDED_STATS_WINDOW_V6
// arctic_stats / arctic_analyze were dispatched with no date_range, so the
// backend tried to aggregate the whole ~2-year history in one shot and returned
// HTTP 504. A bounded window answers in ~2 min. Caller-supplied ranges win.
try {
  const __tool = String((typeof unit !== 'undefined' && unit && unit.tool) || '');
  if (__tool === 'arctic_stats' || __tool === 'arctic_analyze') {
    const __hasRange = (v) => Array.isArray(v)
      ? v.filter(Boolean).length >= 2
      : !!(v && typeof v === 'object' && (v.start || v.from));
    if (!__hasRange(params.date_range) && unit.full_available_range !== true) {
      let __days = 90;
      try {
        const __rpRaw = $('Workflow Configuration').first().json.run_params;
        const __rp = typeof __rpRaw === 'string' ? JSON.parse(__rpRaw) : (__rpRaw || {});
        const __n = Number(__rp && __rp.arcticdb && __rp.arcticdb.stats_default_window_days);
        if (Number.isFinite(__n) && __n > 0) __days = __n;
      } catch (e) {}
      const __pad = (n) => String(n).padStart(2, '0');
      const __fmt = (d) => d.getFullYear() + '-' + __pad(d.getMonth() + 1) + '-' + __pad(d.getDate())
        + ' ' + __pad(d.getHours()) + ':' + __pad(d.getMinutes()) + ':' + __pad(d.getSeconds());
      // STATS_WINDOW_ANCHOR_TO_LATEST_DATA_V7：历史库数据止于 2025-12-20，按「当前时间」往前推的窗与数据不重叠
      //（MT25 T8 exec 147325：2026-06-25～2026-09-23，返回列 0）。统计单元先直读最晚非空时刻作窗尾。
      let __end = new Date();
      let __fmtEnd = __fmt;
      let __anchor = '';
      if (__tool === 'arctic_stats') {
        try {
          const __b = await __readHistoryBoundaryDirect(params);
          const __ms = __b.length === 2 ? Date.parse(__b[1]) : NaN;
          if (Number.isFinite(__ms) && __ms > 0) {
            __end = new Date(__ms);
            __anchor = __b[1];
            __fmtEnd = (d) => d.toISOString().replace('T', ' ').replace(/\.\d{3}Z$/, '');
          }
        } catch (e) {}
      }
      const __start = new Date(__end.getTime() - __days * 24 * 3600 * 1000);
      params.date_range = [__fmtEnd(__start), __fmtEnd(__end)];
      if (__anchor) params.date_range_anchored_to_latest_data = __anchor;
      params.date_range_bounded_by_default = true;
      params.date_range_bounded_days = __days;
      try {
        injectionTrace.push({
          field: 'date_range',
          fallback: params.date_range_anchored_to_latest_data ? 'bounded_stats_window_anchored_to_latest_data' : 'bounded_stats_window_default',
          value_preview: params.date_range.join(' ~ ')
        });
      } catch (e) {}
      try { injected = true; } catch (e) {}
    }
  }
} catch (e) {}

// Final validation after parameter resolution.
if (['arctic_read', 'arctic_stats', 'arctic_analyze'].includes(unit.tool)) {
  const hasRuntimeRef = value => {
    if (typeof value === 'string') return value.includes('$ref:');
    if (Array.isArray(value)) return value.some(hasRuntimeRef);
    if (value && typeof value === 'object') {
      return Object.values(value).some(hasRuntimeRef);
    }
    return false;
  };

  const validColumns = value => {
    const columns = Array.isArray(value) ? value : [value];
    return columns.length > 0 && columns.every(column =>
      typeof column === 'string' &&
      column.trim().length > 0 &&
      !hasRuntimeRef(column)
    );
  };

  const columnsValid = unit.tool === 'arctic_analyze'
    ? Array.isArray(params.targets) &&
      params.targets.length > 0 &&
      params.targets.every(target => validColumns(target?.columns))
    : validColumns(params.columns);

  if (hasRuntimeRef(params) || !columnsValid) {
    const blockedTool = unit.tool;
    const message =
      `The ${blockedTool} request was not executed because its ` +
      `parameters or measurement columns could not be resolved. ` +
      `This does not establish that the measurements are absent.`;

    return [{
      json: {
        ...item,
        completed_units: toMongoCompletedUnits(completed),
        unit: toMongoUnit({
          ...unit,
          tool: 'direct_response',
          source_type: 'system',
          required_evidence_types: [],
          optional_evidence_types: [],
          params: {
            mode: 'unresolved_analysis_columns',
            no_retrieval: true,
            blocked_tool: blockedTool,
            text: message,
            summary_instruction: 'Return params.text exactly.'
          }
        }),
        param_injector_ran: true,
        param_injector_injected: true,
        param_injection_trace: [
          ...injectionTrace,
          {
            policy: 'unresolved_timeseries_request_blocked',
            blocked_tool: blockedTool
          }
        ]
      }
    }];
  }
}

return [{
  json: {
    ...item,
    completed_units: toMongoCompletedUnits(completed),
    unit: toMongoUnit({
      ...unit,
      ...(unit.tool === 'arctic_stats'
        ? { stats_column_batch_size: unit.full_history_presence === true ? 6 : arcticReadLimits.statsColumnBatchSize }
        : {}),
