    param_injection_trace: injectionTrace
  }
}];

function asArray(x) {
  return Array.isArray(x) ? x : [];
}

function asObject(x) {
  return x && typeof x === 'object' && !Array.isArray(x) ? x : {};
}

function asString(x) {
  return typeof x === 'string' ? x.trim() : '';
}

function oneLine(x) {
  return String(x || '')
    .replace(/\s+/g, ' ')
    .trim();
}

function uniqueStrings(arr) {
  const out = [];
  const seen = new Set();
  for (const v of arr || []) {
    const s = asString(v);
    if (!s) continue;
    const k = s.toLowerCase();
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(s);
  }
  return out;
}

function textBlob() {
  return Array.from(arguments)
    .flatMap(v => Array.isArray(v) ? v : [v])
    .map(v => {
      if (typeof v === 'string') return v;
      if (v && typeof v === 'object') return JSON.stringify(v);
      return '';
    })
    .join(' ');
}

function getDefaultArcticTarget(catalog) {
  const target = asObject(catalog?.arcticdb?.default_target);

  return {
    library: asString(target.library),
    symbol: asString(target.symbol)
  };
}


// STRUCTURED_MEMORY_ROUTING_V448
// STRUCTURED_MEMORY_LOCAL_PARSER_V5
function parseStructuredNodeOutput(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  if (typeof value !== 'string') return {};
  const cleaned = value
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/```\s*$/i, '')
    .trim();
  try { return JSON.parse(cleaned); } catch (e) {}
  const first = cleaned.indexOf('{');
  const last = cleaned.lastIndexOf('}');
  if (first >= 0 && last > first) {
    try { return JSON.parse(cleaned.slice(first, last + 1)); } catch (e) {}
  }
  return {};
}

function structuredMemoryResolution() {
  try {
    const node = $('Decompose Question').first().json || {};
    const parsed = parseStructuredNodeOutput(node.output || node.answer || node);
    return asObject(parsed.memory_resolution);
  } catch (e) {
    return {};
  }
}

function structuredMemoryEntities(resolution) {
  return Array.from(new Set(
    asArray(resolution.current_entities)
      .concat(asArray(resolution.inherited_entities))
      .map(String)
      .map(x => x.trim())
      .filter(Boolean)
  ));
}

// CONTRACT_ROUTE_PRECEDENCE_V5
function structuredMemoryMustStop(resolution) {
  // A missing historical prerequisite may constrain an answer, but it must not
  // cancel a valid retrieval plan that can obtain the missing evidence.
  const route = asString(resolution.route).toLowerCase();
  if (route === 'retrieve') return false;
  const status = asString(resolution.status).toLowerCase();
  const unresolved = status === 'unconfirmed' || status === 'contradicted';
  return resolution.depends_on_history === true &&
    unresolved &&
    asArray(resolution.missing_requirements).length > 0;
}

function structuredMemorySafeResponse(item, resolution) {
  const supplied = asString(resolution.safe_response);
  if (supplied) return supplied;
  const zh = /[\u4e00-\u9fff]/.test(String(item.originalUserMessage || ''));
  const status = asString(resolution.status) || 'unknown';
  const missing = asArray(resolution.missing_requirements).map(String).filter(Boolean);
  const facts = asArray(resolution.matched_fact_ids).map(String).filter(Boolean);
  const turns = asArray(resolution.matched_turns).map(String).filter(Boolean);
  if (zh) {
    return `当前问题依赖的历史前提状态为“${status}”，不能把它当作已确认事实继续计算、归因或取值。当前缺失条件：${missing.length ? missing.join('；') : '未提供'}。${facts.length ? `关联事实卡：${facts.join(', ')}。` : ''}${turns.length ? `来源轮次：${turns.join(', ')}。` : ''}请先补齐缺失条件并确认前提，再继续外部检索或分析。`;
  }
  return `The historical prerequisite for this question has status "${status}" and must not be treated as confirmed for further calculation, attribution, or value lookup. Missing requirements: ${missing.length ? missing.join('; ') : 'not provided'}.${facts.length ? ` Matched fact cards: ${facts.join(', ')}.` : ''}${turns.length ? ` Source turns: ${turns.join(', ')}.` : ''} Confirm the prerequisite and missing requirements before external retrieval or analysis.`;
}

function buildStructuredMemoryUnit(baseUnit, item, resolution) {
  const params = asObject(baseUnit.params);
  return {
    ...baseUnit,
    unit_id: Number(baseUnit.unit_id) || 1,
    tool: 'direct_response',
    params: {
      ...params,
      mode: 'structured_memory_resolution',
      no_retrieval: true,
      display_policy: 'finalizer',
      text: structuredMemorySafeResponse(item, resolution),
      memory_resolution: resolution,
      question_literal: item.originalUserMessage || '',
      resolved_question: params.resolved_question || item.originalUserMessage || ''
    },
    depends_on: [],
    question_part: 'other',
    required_evidence_types: [],
    optional_evidence_types: [],
    allow_synthesis: true,
    retrieval_group: null,
    lang_variant: null
  };
}

// KNOWN_TAGS_CONFIRMED_ONLY_V5
function getKnownTagsFromConversation(conversationState) {
  const confirmedTags = [];

  // New measured evidence supersedes older catalog-only uncertainty.
  for (const target of asArray(conversationState?.arctic_target_registry)) {
    const count = Number(target?.count);
    const status = asString(target?.data_status || target?.status).toLowerCase();
    if ((Number.isFinite(count) && count > 0) || /^(ok|usable|available)$/.test(status)) {
      confirmedTags.push(target?.tag || target?.name);
    }
  }

  for (const card of asArray(conversationState?.fact_cards)) {
    const status = asString(card?.status).toLowerCase();
    const entityType = asString(card?.entity_type).toLowerCase();
    if (status !== 'confirmed' || entityType !== 'tag') continue;
    confirmedTags.push(...asArray(card.entities));
    if (card.value != null) confirmedTags.push(card.value);
  }

  for (const item of asArray(conversationState?.answer_fact_index?.tags)) {
    if (typeof item === 'string') {
      confirmedTags.push(item);
      continue;
    }
    const status = asString(item?.status || item?.confidence || item?.source_role).toLowerCase();
    if (status && !/confirmed|exact|verified|evidence/.test(status)) continue;
    confirmedTags.push(item?.normalized || item?.value || item?.tag || item?.name);
  }

  const cleanConfirmed = uniqueStrings(confirmedTags)
    .map(t => asString(t))
    .filter(t => /\b[A-Z]{1,8}[A-Z0-9_]*\d{2,6}[A-Z0-9_]*(?:\.[A-Z0-9_]+)?\b/i.test(t))
    .filter(t => !/^E\d+$/i.test(t));
  if (cleanConfirmed.length) return cleanConfirmed;

  if (asArray(conversationState?.fact_cards).length || asArray(conversationState?.answer_fact_index?.tags).length) {
    return [];
  }

  const turns = asArray(conversationState?.turns);
  const blob = textBlob(
    turns.map(t => textBlob(
      t.user_question,
      t.resolved_question,
      t.assistant_answer
    ))
  );

  const tags = new Set();
  const tagPattern = /\b[A-Z]{1,8}[A-Z0-9_]*\d{2,6}[A-Z0-9_]*(?:\.[A-Z0-9_]+)?\b/g;
  let m;

  while ((m = tagPattern.exec(blob)) !== null) {
    const tag = m[0].trim();
    if (!tag) continue;
    if (/^(MPA|KPA|PSI)$/i.test(tag)) continue;
    if (/^\d+$/.test(tag)) continue;
    if (/^E\d+$/i.test(tag)) continue;
    tags.add(tag);
  }

  const rawTags = Array.from(tags);
  const upper = new Set(rawTags.map(t => t.toUpperCase()));
  return rawTags.filter(t => {
    const u = t.toUpperCase();
    if (!u.includes('.') && upper.has(u + '.PV')) return false;
    return true;
  });
}

function extractDateRangeFromQuestion(question) {
  const q = String(question || '');

  const fullRange = q.match(/(20\d{2})[-\/年](\d{1,2})[-\/月](\d{1,2})(?:日)?\s*(?:到|至|~|—|–|-)\s*(20\d{2})[-\/年](\d{1,2})[-\/月](\d{1,2})(?:日)?/);
  if (fullRange) {
    const s = `${fullRange[1]}-${String(fullRange[2]).padStart(2, '0')}-${String(fullRange[3]).padStart(2, '0')} 00:00:00`;
    const e = `${fullRange[4]}-${String(fullRange[5]).padStart(2, '0')}-${String(fullRange[6]).padStart(2, '0')} 23:59:59`;
    return [s, e];
  }

  const ym = q.match(/(20\d{2})[年/-](\d{1,2})(?![-\/月]\d)/);
  if (ym) {
    const year = Number(ym[1]);
    const month = Number(ym[2]);

    if (month >= 1 && month <= 12) {
      const start = `${year}-${String(month).padStart(2, '0')}-01 00:00:00`;
      const endDate = new Date(Date.UTC(year, month, 1));
      const end = `${endDate.getUTCFullYear()}-${String(endDate.getUTCMonth() + 1).padStart(2, '0')}-${String(endDate.getUTCDate()).padStart(2, '0')} 00:00:00`;
      return [start, end];
    }
  }

  return null;
}

function isConversationSummaryUnit(unit, params) {
  // FINAL_DISPLAY_POLICY_V5
  // Retrieval policy and presentation policy are independent. A bounded
  // no-retrieval answer is not automatically a conversation summary.
  return (
    params.mode === 'conversation_summary' ||
    unit.tool === 'conversation_summary'
  );
}

function bossIsHandlingProcedureRequest(question) {
  const q = String(question || '');
  const asksHandling = /\u5904\u7f6e|\u600e\u4e48\u529e|\u5982\u4f55\u5904\u7406|\u5904\u7406|\u5e94\u5bf9|\u63aa\u65bd|\u64cd\u4f5c|\u8c03\u6574|\u6392\u67e5|\u5e94\u6025|handle|handling|mitigation|mitigate|procedure|response|respond|action/i.test(q);
  const explicitlyHistorical = /\u5386\u53f2|\u5b9e\u65f6|\u6570\u636e\u5e93|\u65f6\u5e8f|\u8d8b\u52bf|\u7edf\u8ba1|historical|real-time|trend|statistics|data/i.test(q);
  return asksHandling && !explicitlyHistorical;
}

function isHistoryVerificationRequest(question, conversationState) {
  const q = oneLine(question);
  if (bossIsHandlingProcedureRequest(q)) return false;
  if (bossIsCauseHypothesisOnlyRequest(q)) return false;
  const blob = textBlob(q, conversationState);

  const asksThresholdOnly =
    /阈值|报警阈值|报警设定|报警值|联锁值|设定值|target|range|threshold|setpoint/i.test(q) &&
    !/历史|实时|数据库|时序|趋势|筛|筛一下|查一下|统计|超标|越限|超限|超出|超过|低于|高于|data|historical|real-time|trend|statistics/i.test(q);

  const asksHistory =
    /历史|实时|数据库|实时数据库|时序|趋势|筛|筛一下|查一下|统计|是否有|有没有|超标|越限|超限|超出|超过|低于|高于|historical|real[-\s]?time|database|historian|time[-\s]?series|trend|statistics|check|filter|screen|whether|any|exceed|exceedance|limit|alarm/i.test(q);

  const hasKnownTags = getKnownTagsFromConversation(conversationState).length > 0;

  return !asksThresholdOnly && asksHistory && hasKnownTags;
}

