// PLAN_SUMMARY_OVERRIDES_LLM_MEMORY_DENIAL_V6b
// 规划链（Decompose Question -> Planner Agent）会在 memory_resolution 里断言
// “conversation_state.turns 中未提供可总结的内容”，并把步骤 mode 写成
// structured_memory_resolution，总结轮因此把那句断言当答案输出
// （exec 115451/115456/115457/115461，答案 28-80 字），而同一次执行里
// Capture context 的 conversation_state.turns 有 13 轮。
// 断言由 LLM 生成，轮次是代码能直接数的，以代码为准。
// 纠正必须落在 item.units 源头：bossBuildMemoryOnlyUnit 等多处逻辑是从
// asArray(item.units)[0] 重建单元的，只改 units 副本会被逐一覆盖回去。
if (
  asString(item.plan_intent).toLowerCase() === 'summary' ||
  asString(asObject(item.plan).intent).toLowerCase() === 'summary' ||
  asString(item.answer_mode).toLowerCase() === 'conversation_summary'
) {
  const __turns = asArray(conversationState.turns);
  if (__turns.length) {
    for (const __u of asArray(item.units)) {
      const __unit = asObject(__u);
      const __p = asObject(__unit.params);
      if (asString(__unit.tool) !== 'direct_response') continue;
      if (asString(__p.mode) === 'conversation_summary') continue;
      __p.mode = 'conversation_summary';
      __p.conversation_turns = __turns;
      __unit.params = __p;
    }
  }
}

const defaultTarget = getDefaultArcticTarget(catalog);
