const memoryResolution = structuredMemoryResolution();
// LLM_RESOLUTION_ADVISORY_V7：Decompose Question 给的 memory_resolution.status 只作提示，会话状态才是依据。
// 会话状态里没有记录未确认 / 矛盾的事件、而计划有可执行步骤时，LLM 的 unconfirmed（会话无任何事件时也包括 contradicted）
// 不应让后面的守卫把整轮改成拒答（短链 T7 exec 155417）。覆盖情况随输出给出，供自检与后续轮次使用。
let __llmResolutionSelfCheck = null;
(function () {
  try {
    const llmStatus = asString(memoryResolution.status).toLowerCase();
    if (llmStatus !== 'unconfirmed' && llmStatus !== 'contradicted') return;
    const stateStatus = asString(asObject(conversationState.event_status).status).toLowerCase();
    const stateUnresolved = stateStatus === 'unconfirmed' || stateStatus === 'contradicted';
    if (stateUnresolved) return; // 会话自己记录的未确认事件，守卫照常
    if (llmStatus === 'contradicted' && stateStatus) return; // 会话有事件而 LLM 判矛盾：仍尊重
    const executable = asArray(item.units).some(u => !/^(?:direct_response|conversation_summary)$/.test(asString(asObject(u).tool)));
    if (!executable) return;
    __llmResolutionSelfCheck = {
      llm_status: llmStatus,
      state_event_status: stateStatus || null,
      llm_missing_requirements: asArray(memoryResolution.missing_requirements).map(String).slice(0, 6),
      action: 'treated_as_unknown',
      reason: 'conversation state records no unresolved event and the plan has executable steps'
    };
    memoryResolution.llm_status = llmStatus;
    memoryResolution.status = 'unknown';
  } catch (e) {}
})();
// HISTORY_KNOWN_TAGS_PRESENCE_PROBE_V5
const knownTags = uniqueStrings(structuredMemoryEntities(memoryResolution).concat(getKnownTagsFromConversation(conversationState)));
const dateRange = extractDateRangeFromQuestion(originalQuestion);


