// CONTEXTUAL_EQUIPMENT_ENTITY_TERMS_V5
function bossLooksLikeUsefulEquipmentTerm(term) {
  const s = asString(term);
  if (s.length < 2 || s.length > 18) return false;
  if (/^(这个装置|当前装置|本装置|相关位号|哪些位号|历史实时数据库|实时数据库|控制是什么|没有有效数据|证据详情|测点选择)$/.test(s)) return false;
  if (/^(Source|Document|Dataset|Snippet|Evidence|Chunk|Use in Answer)$/i.test(s)) return false;
  return true;
}

function bossAddContextualTerm(terms, v) {
  const s = asString(v);
  if (!s || s.length > 80) return;
  terms.push(s);
}

function bossExtractEquipmentEntityTerms(source) {
  const s = String(source || '');
  const out = [];
  const add = (v) => {
    const term = asString(v).replace(/[，。；：、,.。:;]+$/g, '');
    if (bossLooksLikeUsefulEquipmentTerm(term)) out.push(term);
  };

  const cnEquipment = s.match(/[\u4e00-\u9fff]{1,10}(?:反应器|再生器|沉降器|分馏塔|滑阀|调节阀|控制阀|烟机|主风机|压缩机|泵|塔|炉|罐|槽|管|阀|器)[\u4e00-\u9fff]{0,6}/g) || [];
  cnEquipment.forEach(add);

  const cnRegeneratorShort = s.match(/[一二三四半][\u4e00-\u9fff]?再/g) || [];
  cnRegeneratorShort.forEach(add);

  const cnPair = s.match(/[\u4e00-\u9fff]{1,8}(?:与|和|及|到|至)[\u4e00-\u9fff]{1,8}(?:压差|差压|压力差)/g) || [];
  cnPair.forEach(add);

  const enEquipment = s.match(/\b(?:reactor|regenerator|settler|disengager|riser|standpipe|slide valve|control valve|flue gas valve|two[-\s]?vessel|reactor[-\s]?regenerator)\b/ig) || [];
  enEquipment.forEach(add);

  return uniqueStrings(out).slice(0, 24);
}

function bossContextualTagSearchTerms(item, conversationState) {
  // MATCHED_SCOPE_TAG_LOOKUP_CONTEXT_V5
  // Search context is the current question plus the facts/entities selected by
  // the decomposer. Whole-conversation text is intentionally excluded because
  // unrelated old topics broaden catalog retrieval and multiply analysis work.
  const resolution = structuredMemoryResolution();
  const matchedIds = new Set(
    asArray(resolution.matched_fact_ids).map(asString).filter(Boolean)
  );
  const matchedFacts = asArray(conversationState?.fact_cards)
    .filter(factValue => matchedIds.has(asString(asObject(factValue).fact_id)));
  const current = textBlob(
    item?.originalUserMessage,
    item?.resolved_question,
    item?.question,
    item?.query,
    resolution.current_entities,
    resolution.inherited_entities
  );
  const matched = textBlob(
    matchedFacts.map(factValue => {
      const fact = asObject(factValue);
      return textBlob(fact.subject, fact.entities, fact.note);
    })
  );

  const terms = [];
  const add = (v) => bossAddContextualTerm(terms, v);
  add(current);

  for (const source of [current, matched]) {
    const s = String(source || '');
    bossExtractEquipmentEntityTerms(s).forEach(add);

    const tagLike = s.match(/\b[A-Z]{1,8}[A-Z0-9_]*\d{2,6}[A-Z0-9_]*(?:\.[A-Z0-9_]+)?\b/g) || [];
    tagLike.filter(x => !/^E\d+$/i.test(String(x || ''))).forEach(add);

    const cnPhrases = s.match(/[\u4e00-\u9fff]{2,12}(?:压差|差压|压力|滑阀|控制器|位号|回路)/g) || [];
    cnPhrases.forEach(add);

    const enPhrases = s.match(/\b(?:reactor|regenerator|settler|differential pressure|pressure differential|pressure balance|slide valve|controller|loop|tag|instrument)\b/ig) || [];
    enPhrases.forEach(add);
  }

  return uniqueStrings(terms).slice(0, 32);
}

function bossScopedMemoryTagCandidates(item, conversationState) {
  const resolution = structuredMemoryResolution();
  const matchedIds = new Set(
    asArray(resolution.matched_fact_ids).map(asString).filter(Boolean)
  );
  const matchedFacts = asArray(conversationState?.fact_cards)
    .filter(factValue => matchedIds.has(asString(asObject(factValue).fact_id)));
  const source = textBlob(
    item?.originalUserMessage,
    resolution.current_entities,
    resolution.inherited_entities,
    matchedFacts.map(factValue => {
      const fact = asObject(factValue);
      return textBlob(fact.subject, fact.entities);
    })
  );
  const matches = source.match(/\b[A-Z]{1,8}[A-Z0-9_]*\d{2,6}[A-Z0-9_]*(?:\.[A-Z0-9_]+)?\b/g) || [];
  return uniqueStrings(matches.filter(tag => !/^E\d+$/i.test(tag)));
}

