function bossIsWindowFollowupAnalysisRequest(question) {
  const q = String(question || '');
  const asksWindow =
    /\u9644\u8fd1|\u524d\u540e|\u7a97\u53e3|2\s*\u4e2a?\s*\u5c0f\u65f6|\u4e24\s*\u4e2a?\s*\u5c0f\u65f6|around|before|after|window/i.test(q);
  const asksAnalysis =
    /\u5206\u6790|\u8d8b\u52bf|\u5f02\u5e38|\u5019\u9009|analysis|anomaly|trend/i.test(q);
  const hasExceedanceContext =
    /\u8d85\u6807|\u8d8a\u9650|\u8d85\u9650|\u8d85\u51fa|\u62a5\u8b66|\u5f02\u5e38|exceed|alarm|anomaly/i.test(q);
  return asksWindow && (asksAnalysis || hasExceedanceContext);
}


function bossHasLocalizedExceedanceWindow(conversationState) {
  const blob = bossConversationBlob('', conversationState);
  const hasTimestamp =
    /20\d{2}[-/]\d{1,2}[-/]\d{1,2}(?:[ T]\d{1,2}:\d{2}(?::\d{2})?)?/i.test(blob) ||
    /20\d{2}\s*年\s*\d{1,2}\s*月\s*\d{1,2}\s*日(?:\s*\d{1,2}\s*[:：]\s*\d{2})?/i.test(blob);
  const hasLocalizedWindow =
    /超标窗口|超标事件|候选超标|超标附近|越限窗口|越限事件|exceedance\s+(?:window|event|candidate)|around\s+exceedance/i.test(blob);
  const saysOnlyPresence =
    /存在性探测|非空存在性|presence\s*probe|data\s*presence|无法(?:确认|判断|判定).*超标|尚未.*定位.*超标|未.*定位.*超标|cannot\s+(?:confirm|determine).*exceedance|no\s+exceedance\s+(?:window|event).*located/i.test(blob);
  return hasTimestamp && hasLocalizedWindow && !saysOnlyPresence;
}

function bossQuestionHasExplicitTimestamp(question) {
  const q = String(question || '');
  return /20\d{2}[-/]\d{1,2}[-/]\d{1,2}(?:[ T]\d{1,2}:\d{2}(?::\d{2})?)?/i.test(q) ||
    /20\d{2}\s*年\s*\d{1,2}\s*月\s*\d{1,2}\s*日(?:\s*\d{1,2}\s*[:：]\s*\d{2})?/i.test(q);
}

function bossShouldDirectMissingWindow(originalQuestion, activeQuestion, conversationState) {
  // GLOBAL_MISSING_WINDOW_GUARD_V431_PATCH:
  // Only the current user question may trigger this guard. Historical/resolved
  // context can contain an older window request and must not convert unrelated
  // follow-ups into a missing-window direct response.
  const current = String(originalQuestion || '');
  return bossIsWindowFollowupAnalysisRequest(current) &&
    !bossQuestionHasExplicitTimestamp(current) &&
    !bossHasLocalizedExceedanceWindow(conversationState);
}

function bossDirectGuardLanguage(question) {
  return /[\u4e00-\u9fff]/.test(String(question || '')) ? 'zh' : 'en';
}

function bossPressureTokens(question) {
  const s = String(question || '');
  const matches = s.match(/\d+(?:\.\d+)?(?:\s*[-–~]\s*\d+(?:\.\d+)?)?\s*(?:kpa|mpa|psi|千帕|兆帕)/ig) || [];
  const seen = new Set();
  return matches
    .map(v => v.replace(/\s+/g, ' ').trim())
    .filter(v => {
      const k = v.toLowerCase();
      if (seen.has(k)) return false;
      seen.add(k);
      return true;
    });
}

function bossEventLabel(question) {
  const s = String(question || '');
  const m = s.match(/\bT\d+\b/i) || s.match(/(那次|上次|之前|previous|prior|last)\s*(?:event|case|incident|exceedance|alarm)?/i);
  return m ? m[0] : '';
}

function bossIsPriorEventDirectionClarification(question) {
  const s = String(question || '');
  const refersPrior = /\bT\d+\b|那次|上次|之前|历史上|previous|prior|last/i.test(s);
  const hasLimitEvent = /超标|越限|超限|超出|报警|exceed|alarm|limit/i.test(s);
  const asksDirectionOrBoundary = /高端|低端|高差压|低差压|过高|过低|方向|high[-\s]?side|low[-\s]?side|\bhigh\b|\blow\b|important|还重要|仍然重要|边界|boundary/i.test(s) || bossPressureTokens(s).length > 0;
  return refersPrior && hasLimitEvent && asksDirectionOrBoundary;
}

function bossPriorEventDirectionText(question) {
  const lang = bossDirectGuardLanguage(question);
  const label = bossEventLabel(question);
  const nums = bossPressureTokens(question);
  const numberText = nums.length ? nums.join(' / ') : (lang === 'zh' ? '该压力/差压数值' : 'the stated pressure/differential-pressure value');
  if (lang === 'zh') {
    return `当前对话不能仅凭已有上下文判断${label ? label + ' ' : ''}是否属于高侧或低侧超限，因为还缺少已确认的报警/联锁阈值、超限时间戳和事件窗口。${numberText}仍然可能重要，但它只能作为相应保护边界或操作边界来解释，不能反向证明一个尚未定位的历史超限事件。若后续确认该事件，需要按本装置 DCS/SIS 报警表、联锁逻辑、趋势窗口和对应测点方向重新判断。`;
  }
  return `The current conversation cannot determine whether ${label ? label + ' ' : 'the prior event '}was a high-side or low-side exceedance, because the confirmed alarm/interlock threshold, exceedance timestamp, and event window are still missing. ${numberText} may still be important, but only as the relevant protection or operating boundary; it cannot prove the direction of an unlocalized historical event. If the event is later confirmed, the direction should be checked against this unit's DCS/SIS alarm list, interlock logic, trend window, and tag definition.`;
}

function bossIsPressureNumberConflictClarification(question) {
  const s = String(question || '');
  const asksRelationship = /冲突|矛盾|一样吗|区别|不冲突|conflict|contradict|same|different|compare|comparable|相同|不同/i.test(s);
  const mentionsPressureObject = /(kpa|mpa|psi|千帕|兆帕|压力|压差|差压|pressure|differential)/i.test(s);
  return asksRelationship && mentionsPressureObject && bossPressureTokens(s).length >= 2;
}

function bossPressureNumberConflictText(question) {
  const lang = bossDirectGuardLanguage(question);
  const nums = bossPressureTokens(question);
  const a = nums[0] || (lang === 'zh' ? '第一个数值' : 'the first number');
  const b = nums[1] || (lang === 'zh' ? '第二个数值' : 'the second number');
  if (lang === 'zh') {
    return `${a} 和 ${b} 本身不必然冲突，关键要先确认它们描述的是不是同一个压力对象。若一个是差压/低差压保护或联锁边界，另一个是某设备或测点的绝对压力/操作范围，即使单位都能换算成压力单位，也不能直接比较大小或当作同一阈值。当前对话还没有独立确认这两个数值各自对应的具体测点、报警项或联锁项；最终应以 DCS/SIS 报警表、联锁设定、回路图和操作规程为准。`;
  }
  return `${a} and ${b} do not necessarily conflict by themselves; the first check is whether they describe the same pressure object. If one value is a differential-pressure or low-differential protection/interlock boundary while the other is an absolute pressure or operating range for a vessel/tag, they should not be compared as the same threshold even though both use pressure units. The current conversation has not independently confirmed the exact tag, alarm item, or interlock item for each value, so the final check should come from the DCS/SIS alarm list, interlock settings, loop sheets, and operating procedures.`;
}

