function bossIsUnconfirmedEventCausalFollowup(question) {
  const q = String(question || '');
  // UNCONFIRMED_EVENT_CAUSAL_FOLLOWUP_PATCH: generic guard for cause/association follow-ups that refer to
  // an earlier alleged exceedance/event before a real event window exists.
  const refersPriorEvent = /T\d+|那次|上次|前面|之前|筛选出来|筛出来|previous|prior|that\s+event/i.test(q);
  const mentionsEvent = /超标|越限|超限|报警|事件|exceed|alarm|event|limit/i.test(q);
