function bossCompactControlConceptRagUnits(units, question) {
  // CONTROL_CONCEPT_SINGLE_RAG_UNIT_PATCH: concept-definition questions need broad but bounded coverage,
  // not multiple full RAG/synthesis loops.
  if (!bossIsControlConceptDefinitionRequest(question)) return units;
  const ragUnits = asArray(units).filter(u => asObject(u).tool === 'ragflow_retrieval');
  if (ragUnits.length <= 1) return units;

  const first = asObject(ragUnits[0]);
  const mergedParams = ragUnits
    .map(u => asObject(u).params)
    .reduce((acc, params) => {
      const datasetIds = uniqueStrings([...(acc.dataset_ids || []), ...asArray(params.dataset_ids)]);
      return {
        ...acc,
        ...params,
        dataset_ids: datasetIds,
        question: uniqueStrings([
          acc.question,
          params.question,
          params.question_zh,
          params.question_en,
          '物理机理 控制对象 执行机构 约束 风险 适用边界 未确认项 pressure balance catalyst circulation slide valve differential pressure override interlock'
        ]).join('\n'),
        page_size: Math.min(Number(params.page_size || acc.page_size || 8), 8),
        top_k: Math.min(Number(params.top_k || acc.top_k || 64), 64),
        similarity_threshold: params.similarity_threshold ?? acc.similarity_threshold ?? 0.2,
        vector_similarity_weight: params.vector_similarity_weight ?? acc.vector_similarity_weight ?? 0.3,
        keyword: params.keyword ?? acc.keyword ?? true
      };
    }, asObject(first.params));

  const compact = {
    ...first,
    unit_id: 1,
    params: mergedParams,
    depends_on: [],
    question_part: first.question_part || 'other',
    required_evidence_types: uniqueStrings(
      ragUnits.flatMap(u => asArray(asObject(u).required_evidence_types))
    ),
    optional_evidence_types: uniqueStrings(
      ragUnits.flatMap(u => asArray(asObject(u).optional_evidence_types))
    ),
    allow_synthesis: true,
    retrieval_group: first.retrieval_group || null,
    lang_variant: first.lang_variant || null
  };

  const nonRag = asArray(units).filter(u => asObject(u).tool !== 'ragflow_retrieval');
  return [compact].concat(nonRag.map((u, idx) => ({ ...u, unit_id: idx + 2 })));
}

function bossIsUnlocalizedEventCauseFollowup(question, conversationState) {
  const q = String(question || '');
  // UNLOCALIZED_EVENT_CAUSE_FOLLOWUP_PATCH: cause questions after a presence probe must not inherit a
  // non-existent exceedance event/window from earlier turns.
  const asksCause = /原因|真正|可能|归因|导致|驱动|有关|相关|关系|cause|causes|driver|root\s+cause|why|related|associated|link/i.test(q);
  const mentionsEvent = /超标|越限|超限|报警|事件|exceed|alarm|event|limit/i.test(q);
  const blob = bossConversationBlob(q, conversationState);
  const onlyPresence =
    /非空样本|非空存在性|存在性探测|无法(?:确认|判断|判定).*超标|未.*定位.*超标|不能.*当作超标|presence\s*probe|data\s*presence|cannot\s+(?:confirm|determine).*exceedance|no\s+exceedance\s+(?:window|event).*located|no\s+usable\s+numeric\s+data|not\s+possible\s+to\s+determine/i.test(blob);
  return asksCause && mentionsEvent && (onlyPresence || bossHasUnconfirmedEvent(conversationState));
}

function bossGuardDirectText(kind) {
  // GUARD_DIRECT_TEXT_OUTPUTS_PATCH: guard responses are final deterministic answers.
  const q = String(typeof originalQuestion !== 'undefined' ? originalQuestion : '');
  const wantsEnglish = /[A-Za-z]{4,}/.test(q) && !/[\u4e00-\u9fff]/.test(q);
  if (wantsEnglish && kind === 'counterfactual') {
    const eventLabel = bossEventLabel(q) || 'the referenced exceedance';
    return `The current conversation has not confirmed a specific exceedance event. The available information only shows candidate tags or non-null samples; it does not confirm the alarm threshold, exceedance timestamp, event start/end window, or reusable event context. Therefore, the answer cannot assume that ${eventLabel} truly occurred, and cannot determine whether adjusting the mentioned operating variable back into the design range would have prevented it. If a real event is later confirmed, returning that variable to its design range may reduce variable-driven risk, but threshold configuration, pressure control, slide-valve action, wet-gas-compressor suction pressure, regenerator pressure disturbance, relevant protective-control actions, and instrument/data quality would still need to be checked.`;
  }
  if (wantsEnglish && kind === 'cause') {
    return 'The current conversation cannot determine the cause of the exceedance yet, because no confirmed threshold, exceedance timestamp, event window, or reusable event context has been established. Non-null samples are not the same as an exceedance event, so the workflow should not assign causality to any equipment or variable. If a true exceedance is later confirmed, candidate cause paths include pressure control, slide-valve action, catalyst inventory/circulation, wet-gas-compressor suction pressure, regenerator pressure disturbance, relevant protective-control actions, and instrument or data-quality issues. The next step is to confirm the alarm threshold and event window, then compare variable trends, alarms, controller outputs, and DCS/SIS records around that window.';
  }
  if (kind === 'counterfactual') {
    return '当前对话并未确认具体的超标事件：已有信息只证明候选测点或短窗口内存在非空样本，尚未确认报警阈值、超标时刻、起止窗口或可复用事件上下文。因此不能以“那次超标已经发生”为前提判断把藏量或其他变量调到设计范围后是否仍会发生。若后续确认证据表明确有超标事件，相关变量回到设计范围可能降低由该变量偏离导致的压差异常风险，但不能排除阈值设置、压力控制、滑阀动作、气压机入口压力、再生压力扰动或仪表/数据质量等其他原因。下一步应先确认报警阈值和事件窗口，再比较调整前后的变量趋势、压差和控制动作。';
  }
  if (kind === 'cause') {
    return '当前还不能判断超标原因，因为当前会话只确认过候选测点、非空读数或缺少阈值，并没有定位到明确的超标阈值、超标时刻、起止窗口或可复用事件上下文。非空样本不能等同于超标事件，不能据此做因果归因，也不能把某个设备或变量说成与该事件明确相关。若后续确认存在真实超标事件，可把压力控制、滑阀动作、催化剂藏量/循环量、气压机入口压力、再生压力扰动、反飞动阀动作以及仪表/数据质量作为候选原因路径。下一步应先确认报警阈值并定位事件窗口，再对窗口前后的变量趋势、报警记录、控制输出和DCS/SIS记录做归因分析。';
  }
  return '当前会话尚未定位到明确的超标事件窗口，不能把非空样本当作超标，也不能编造窗口或原因。下一步应先确认阈值并定位事件窗口，再开展对应分析。';
}


function bossDirectWindowMissingText() {
  // DIRECT_TEXT_FOR_SUMMARY_AND_WINDOW_PATCH: direct-response text must survive later param filtering.
  const q = String(typeof originalQuestion !== 'undefined' ? originalQuestion : '');
  const wantsEnglish = /[A-Za-z]{4,}/.test(q) && !/[\u4e00-\u9fff]/.test(q);
  if (wantsEnglish) {
    return 'A two-hour before/after exceedance-window analysis cannot be performed yet, because the current conversation has only confirmed candidate tags or non-null short-window samples. It has not confirmed the alarm threshold, the exceedance timestamp, the start/end event window, or reusable event context. Non-null data is not the same as an exceedance, so the workflow must not invent a +/-2 hour window. The next step is to confirm the alarm high/low limit or DCS/SIS alarm record, locate the true exceedance timestamp, and then extract the +/-2 hour trends for differential pressure, pressure control, slide-valve action, wet-gas-compressor suction pressure, regenerator pressure, and related tags.';
  }
  return '当前不能做“超标附近前后2小时”的趋势分析，因为当前会话只确认了候选测点/短窗口非空样本，尚未确认报警阈值、超标时刻、起止窗口或可复用的事件上下文。非空样本不等于超标，不能把有数据的时间段直接当作超标窗口，也不能编造±2小时窗口。下一步应先用已确认的报警上下限或DCS/SIS报警记录定位真实超标时刻，再提取该时刻前后2小时的压差、压力控制、滑阀动作、气压机入口压力、再生压力和相关测点趋势做分析。';
}

function bossStripEvidenceTail(text) {
  return String(text || '')
    .split(/\n\s*(?:证据详情|Evidence Details|Sensor Tag Selection)\b/i)[0]
    .replace(/\[[EC]\d+\]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function bossFirstSentences(text, count) {
  const cleaned = bossStripEvidenceTail(text);
  if (!cleaned) return [];
  const parts = cleaned
    .split(/(?<=[。！？.!?])\s+/)
    .map(s => s.trim())
    .filter(Boolean);
  return parts.slice(0, Math.max(1, count || 3));
}

function bossConversationSummaryText(item, conversationState, requestedCount) {
  const q = String(item.originalUserMessage || '');
  const turns = asArray(conversationState?.turns);
  if (!turns.length) return '';

  const blob = textBlob(
    q,
    turns.map(t => textBlob(t.user_question, t.resolved_question, t.assistant_answer)),
    conversationState?.answer_fact_index
  );
  const wantsThree = /三句|三句话|3\s*句|three\s+sentences/i.test(q);
  const lang = /[\u4e00-\u9fff]/.test(q) ? 'zh' : 'en';
  // SUMMARY_TEXT_LANGUAGE_V437: deterministic conversation summaries must
  // match the current user language. Otherwise the downstream English display
  // cleanup can strip Chinese characters and leave punctuation only.
  const msg = {
    core: lang === 'zh'
      ? '两器差压控制的核心，是维持反应器与再生器之间合适的压差，使催化剂循环既有推动力，又不越过设备、报警和联锁约束。'
      : 'Two-vessel differential pressure control keeps an appropriate pressure difference between the reactor and regenerator so catalyst circulation has enough driving force while staying within equipment, alarm, and interlock constraints.',
    balance: lang === 'zh'
      ? '压差判断不能只看一个读数，需要把静压头、管线/设备阻力、滑阀压降和反再压力平衡放在同一条压力平衡链里理解。'
      : 'Differential pressure should not be judged from a single reading; static head, line and equipment resistance, slide-valve pressure drop, and reactor-regenerator pressure balance need to be interpreted as one pressure-balance chain.',
    threshold: lang === 'zh'
      ? '已讨论到的通用阈值或联锁值只能作为参考，具体高低报警、联锁和允许范围仍要以本装置DCS/SIS报警表、联锁逻辑和操作规程确认为准。'
      : 'Any general threshold or interlock value discussed so far is only a reference; the actual high/low alarms, interlocks, and allowable range must be confirmed from this unit\'s DCS/SIS alarm list, interlock logic, and operating procedures.',
    handling: lang === 'zh'
      ? '处置思路应先核实仪表和报警，再检查压力控制、滑阀动作、气压机入口压力、再生压力扰动及相关联锁状态，避免把未确认事件直接归因。'
      : 'For abnormal handling, first verify instrumentation and alarms, then check pressure control, slide-valve action, wet-gas-compressor suction pressure, regenerator pressure disturbances, and related interlocks before assigning a cause.',
    tags: lang === 'zh'
      ? '历史位号讨论中，候选测点和相近写法应按已保存证据与不确定性表述；精确身份仍需要通过位号表、P&ID或DCS点表继续核对。'
      : 'In the tag discussion, candidate tags and near aliases should be reported with their saved evidence support and uncertainty; exact identity still needs confirmation in the tag list, P&ID, or DCS point list.',
    data: lang === 'zh'
      ? '历史数据查询目前只能证明部分候选测点存在非空样本，不能在缺少明确报警阈值和事件时间窗时把这些样本判定为超标。'
      : 'Historian checks can only show whether candidate tags have non-null samples; without a confirmed alarm threshold and event window, those samples cannot be treated as exceedances.'
  };
  const points = [];

  function addIf(cond, text) {
    if (cond && !points.includes(text)) points.push(text);
  }

  // SUMMARY_CORE_POINTS_V418_PATCH: treat two-vessel DP, differential-pressure tags, and tag-only recalls as the same control topic.
  addIf(/两器(?:压差|差压)|差压控制|压差控制|反应器.*再生器|reactor.*regenerator|differential\s+pressure/i.test(blob), msg.core);
  addIf(/计算|怎么算|公式|ΔP|静压|压降|阻力|平衡|压差|差压|balance|pressure\s+drop/i.test(blob), msg.balance);
  addIf(/阈值|报警|联锁|14\s*kPa|setpoint|alarm|interlock/i.test(blob), msg.threshold);
  addIf(/处置|怎么处置|滑阀|气压机|反飞动|DCS|SIS|handle|mitigation/i.test(blob), msg.handling);
  addIf(/位号|测点|tag/i.test(blob), msg.tags);
  addIf(/ArcticDB|历史实时|实时数据库|非空|超标|越限|exceed|non-null/i.test(blob), msg.data);

  if (!points.length) {
    const recent = turns
      .slice(-3)
      .flatMap(t => bossFirstSentences(t.assistant_answer, 2));
    points.push(...recent);
  }

  const selected = points.slice(0, wantsThree ? 3 : Math.max(3, Math.min(Number(requestedCount) || 6, 6)));
  if (!selected.length) return '';

  if (wantsThree) {
    const fillers = lang === 'zh' ? [
      '具体报警阈值、控制器位号和测点对应关系不能凭通用知识拍定，必须回到DCS/SIS、P&ID、位号表和操作规程确认。',
      '历史实时数据只能作为验证手段，只有在明确阈值和事件窗口后，才能判断是否真正超标以及前后变量如何变化。'
    ] : [
      'Specific alarm thresholds, controller tags, and tag mappings cannot be fixed from general knowledge; they must be checked against DCS/SIS, P&IDs, tag lists, and operating procedures.',
      'Historian data is only a verification source; only after the threshold and event window are known can the workflow decide whether an exceedance occurred and how nearby variables changed.'
    ];
    for (const f of fillers) {
      if (selected.length >= 3) break;
      if (!selected.includes(f)) selected.push(f);
    }
    while (selected.length < 3) selected.push('仍需回到已保存的证据和现场配置，确认阈值、位号和事件窗口后再做进一步判断。');
    return `第一，${selected[0].replace(/^第[一二三]，?/, '')}第二，${selected[1].replace(/^第[一二三]，?/, '')}第三，${selected[2].replace(/^第[一二三]，?/, '')}`;
  }

  return selected.map((p, i) => `${i + 1}. ${p}`).join('\n');
}

function bossIsTagIdentityOrComparisonQuestion(question) {
  const q = String(question || '');
  // TAG_COMPARE_NOT_COUNTERFACTUAL_V426_PATCH: tag identity/comparison questions require catalog/historian evidence,
  // and must not be captured by prior-event counterfactual guards via history text.
  const mentionsTagLike =
    /\b[A-Z]{1,8}[A-Z0-9_]*\d{2,6}[A-Z0-9_]*(?:\.[A-Z0-9_]+)?\b/.test(q) ||
    /tag|TAG|位号|测点|仪表|控制器|DCS|SIS|PV|OP|SP/i.test(q);
  const asksIdentityOrDifference =
    /difference|different|same|compare|distinguish|主用|备用|区别|差别|一样|相同|哪个|是否是|是不是|is\s+there\s+a\s+difference/i.test(q);
  return mentionsTagLike && asksIdentityOrDifference;
}

function bossIsPriorEventCounterfactualFollowup(question) {
  const q = String(question || '');
  // UNCONFIRMED_PRIOR_EVENT_COUNTERFACTUAL_PATCH: generic guard for follow-ups that assume a prior exceedance/event
  // was confirmed when the saved conversation only contains data-presence probes.
  const refersPriorEvent = /T\d+|那次|上次|前面|之前|筛选出来|筛出来|previous|prior|that\s+event/i.test(q);
  const mentionsEvent = /超标|越限|超限|报警|事件|exceed|alarm|event|limit/i.test(q);
  const asksCounterfactual = /还会|是否还|会不会|能否避免|如果|假如|would|still|avoid|prevent|if\s+/i.test(q);
  return refersPriorEvent && mentionsEvent && asksCounterfactual;
}

