function bossIsCauseHypothesisOnlyRequest(question) {
  const q = String(question || '');
  const asksCause = /\u539f\u56e0|\u53ef\u80fd|\u4e3a\u4ec0\u4e48|\u4e3a\u4f55|cause|causes|possible\s+reason|why/i.test(q);
  const asksData = /\u5386\u53f2|\u5b9e\u65f6|\u6570\u636e\u5e93|\u65f6\u5e8f|\u8d8b\u52bf|\u7b5b|\u67e5|\u7edf\u8ba1|\u4ece\u6570\u636e|\u770b\u6570\u636e|historical|real-time|trend|statistics|from\s+data|based\s+on\s+data/i.test(q);
  return asksCause && !asksData;
}

function bossIsTagLookupRequest(question) {
  const q = String(question || '');
  return bossHas(/\u4f4d\u53f7|\u6d4b\u70b9|tag|TAG|\u4eea\u8868|\u63a7\u5236\u5668|DCS|SIS|\u8054\u9501|\u4e3b\u7528|\u5907\u7528|PV|OP|SP/i, q) ||
    /\b[A-Z]{1,8}[A-Z0-9_]*\d{2,6}[A-Z0-9_]*(?:\.[A-Z0-9_]+)?\b/.test(q);
}

function bossIsControlConceptDefinitionRequest(question) {
  const q = String(question || '');
  const asksDefinition = /\u662f\u4ec0\u4e48|\u4ec0\u4e48\u662f|what\s+is|define|definition|explain/i.test(q);
  const asksControlConcept = /\u63a7\u5236|control|regulation|interlock|protection|\u8054\u9501|\u4fdd\u62a4|\u538b\u5dee|differential\s+pressure|pressure\s+balance/i.test(q);
  const asksMeasuredData = bossIsHistoryRequest(q) || /\u4f4d\u53f7|\u6d4b\u70b9|tag|TAG|PV|OP|SP|DCS|SIS/i.test(q);
  return asksDefinition && asksControlConcept && !asksMeasuredData;
}

function bossIsHistoryRequest(question) {
  const q = String(question || '');
  if (bossIsHandlingProcedureRequest(q)) return false;
  if (bossIsCauseHypothesisOnlyRequest(q)) return false;
  const asksThresholdOnly =
    /阈值|报警阈值|报警设定|报警值|联锁值|设定值|target|range|threshold|setpoint/i.test(q) &&
    !/历史|实时|数据库|时序|趋势|筛|筛一下|查一下|统计|超标|越限|超限|超出|超过|低于|高于|data|historical|real-time|trend|statistics|exceed|exceedance|limit|database|historian/i.test(q);
  if (asksThresholdOnly) return false;
  return bossHas(/\u5386\u53f2|\u5b9e\u65f6|\u6570\u636e\u5e93|\u65f6\u5e8f|\u8d8b\u52bf|\u7b5b|\u67e5|\u7edf\u8ba1|\u8d85\u6807|\u8d8a\u9650|\u8d85\u9650|\u8d85\u51fa|\u8d85\u8fc7|\u4f4e\u4e8e|\u9ad8\u4e8e|historical|real[-\s]?time|database|historian|time[-\s]?series|trend|statistics|check|filter|screen|exceed|exceedance|limit|alarm/i, q);
}

function bossQuestionAsksCounterfactual(question) {
  const q = String(question || '');
  return /还会|是否还|会不会|能否避免|如果|假如|调回|设计范围|would|still|avoid|prevent|if\s+|adjusted\s+back|design\s+range/i.test(q);
}

function bossIsPriorClaimClarification(question) {
  const q = String(question || '');
  // EVENT_STATUS_ROUTING_V442:
  // Memory-claim clarification must not capture counterfactual questions such
  // as "you said X; if adjusted back, would it still happen?".
  if (bossQuestionAsksCounterfactual(q)) return false;
  const refersPriorAnswer = /\b(previously|earlier|before|did\s+you\s+(?:previously\s+)?say|have you said|our previous|last answer)\b|之前|前面|刚才|是否说过|有没有说过/i.test(q);
  const asksClaim = /\b(did|was|were|is|are|might|related|relation|associated|link|said)\b|是否|是不是|有没有|相关|有关|提到|说过/i.test(q);
  return refersPriorAnswer && asksClaim;
}

function bossEventStatus(conversationState) {
  const es = conversationState?.event_status;
  return es && typeof es === 'object' && !Array.isArray(es) ? es : null;
}

function bossHasUnconfirmedEvent(conversationState) {
  return String(bossEventStatus(conversationState)?.status || '').toLowerCase() === 'unconfirmed';
}

function bossPriorClaimClarificationText(question, conversationState) {
