    { re: /instrument|仪表|data\s*quality|数据质量/i, zh: '仪表或数据质量因素', en: 'instrument or data-quality issues' }
  ];
  const matched = topicPatterns.find(x => x.re.test(q));
  const topic = matched ? (lang === 'zh' ? matched.zh : matched.en) : (lang === 'zh' ? '这个因素' : 'that factor');
  const mentioned = matched ? matched.re.test(blob) : true;
  if (lang === 'zh') {
    if (mentioned) {
      return `是的，但只能理解为前文列出的条件性候选路径之一，不能理解为已经确认${topic}导致了${eventLabel}。当前会话尚未确认真实超限阈值、触发时间戳和事件窗口，因此不能把非空样本或候选测点升级为已证实的超限事件，也不能确认${topic}与该事件存在因果关系。后续必须先确认DCS/SIS报警记录和事件窗口，再检查相关变量、控制输出和趋势。`;
    }
    return `我在已保存的对话上下文里没有看到可以确认${topic}曾被作为结论提出。即使后续把它列为候选因素，也需要先确认${eventLabel}是否是真实超限事件、对应阈值和时间窗口，再做趋势和报警记录核对。`;
  }
  if (mentioned) {
    return `Yes, but only as a conditional candidate path mentioned earlier, not as a confirmed cause of ${eventLabel}. The conversation still has not confirmed a real exceedance threshold, trigger timestamp, or event window, so non-null samples or candidate tags must not be upgraded into a proven exceedance event. To verify whether ${topic} was involved, first confirm the DCS/SIS alarm record and event window, then compare related variables, controller output, and trends.`;
  }
  return `I do not see saved conversation context that supports treating ${topic} as a prior confirmed conclusion. Even if it is later considered as a candidate factor, the workflow must first confirm whether ${eventLabel} was a real exceedance, including the threshold and event window, before checking trends and alarm records.`;
}

function bossNeedsControlImplementationExpansion(question) {
  const q = String(question || '');
  // CONTROL_IMPLEMENTATION_RETRIEVAL_EXPANSION_PATCH
  // CONTROL_ABNORMAL_HANDLING_RETRIEVAL_PATCH: expand both concept explanations and abnormal handling requests
  // for a control object, without binding to a fixed test sentence.
  const isBasicControlConcept = /是什么|什么是|定义|解释|what\s+is|define|explain/i.test(q);
  const asksHandling = /处置|怎么处置|怎么办|如何处理|处理|应对|措施|操作|调整|排查|应急|超标|越限|超限|异常|handle|handling|mitigation|mitigate|procedure|response|respond|action|abnormal|exceed/i.test(q);
  const isTwoVesselDp = /两器压差|两器差压|反应器.*再生器.*压差|反再.*差压|reactor.*regenerator.*differential\s+pressure|two[-\s]?vessel.*differential\s+pressure/i.test(q);
  return isTwoVesselDp && (isBasicControlConcept || asksHandling);
}

