  const asksCalculation = /怎么算|怎么计算|如何计算|计算方法|公式|方程|calculate|calculation|formula|equation/i.test(q);
  if (!asksCalculation) return false;
  const pressureLike = /压差|压力|差压|differential\s+pressure|pressure\s+drop|pressure\s+balance/i.test(q);
