// THRESHOLD_RETRIEVAL_EXPANSION_PATCH_V6
// Alarm/interlock values are written in emergency-response language
// (联锁值 / 跳车 / 自保 / 处置卡), not under the phrase 报警阈值, so a bare
// threshold query misses them. Widen the vocabulary and pull more chunks.
function bossNeedsThresholdRetrieval(question) {
  const q = String(question || '');
  const asksThreshold =
    /阈值|报警值|报警上限|报警下限|联锁|跳车|自保|设定值|限值|上下限|高限|低限|超标|越限|超限|threshold|setpoint|alarm|interlock|trip|shutdown|limit|exceed/i.test(q);
  if (!asksThreshold) return false;
  return /压差|压力|差压|两器|反再|differential\s+pressure|pressure/i.test(q);
}

function bossExpandThresholdRetrievalUnits(units, question) {
  if (!bossNeedsThresholdRetrieval(question)) return units;
  return (units || []).map((unit) => {
    const u = asObject(unit);
    if (u.tool !== 'ragflow_retrieval') return unit;
    const params = asObject(u.params);
    const baseQuestion = String(params.question || params.resolved_question || question || '').trim();
    // SUBJECT_BOUND_THRESHOLD_EXPANSION_V6b
    // 原实现把一大串通用报警词（报警阈值/联锁值/跳车值/处置卡…）裸拼在问题后面，
    // 这串词不带任何主体约束，会把召回稀释到"同样带报警但不是这个设备"的分块上：
    // exec 115428 的 18 条证据里混入塞阀阀位、污水汽提 P3404、催化剂床层压降
    // PDI36413B；exec 115446 更是几乎整轮召回烟气/SO2/氨逃逸。
    // 这里从本轮问题里抽出主体词，逐行前置到扩展词上，让扩展保持在主体范围内。
    const __subjectTerms = (String(baseQuestion || '')
      .match(/两器压差|两器差压|反再差压|沉降器与二再|沉降器|二再|再生器|反应器|压差|差压|[A-Z]{2,6}\d{3,5}[A-Z]?(?:\.[A-Z]{2,4})?/g) || []);
    const __subject = uniqueStrings(__subjectTerms).slice(0, 6).join(' ');
    const __bind = (line) => (__subject ? `${__subject} ${line}` : line);
    const thresholdFocus = [
      baseQuestion,
      __bind('报警阈值 报警上限 报警下限 高高报 高报 低报 低低报 联锁值 联锁设定 联锁跳车 跳车值 自保值 停车值 切断值 设定值 控制范围 操作弹性 应急处置卡 处置卡 事故现象 立即行动 特阀 反再差压 两器差压 kPa'),
      __bind('alarm setpoint high high low low interlock value trip value shutdown value cutoff permissive operating range emergency response card differential pressure kPa psi'),
      'THRESHOLD_QUERY_TOKENS_PATCH'
    ].filter(Boolean).join('\n');
    return {
      ...u,
      params: {
        ...params,
        question: thresholdFocus,
        question_zh: [String(params.question_zh || ''), '报警阈值 联锁值 跳车值 自保值 切断值 高高报 低低报 控制范围 应急处置卡 反再差压 kPa'].filter(Boolean).join('\n'),
        question_en: [String(params.question_en || ''), 'alarm setpoint interlock trip shutdown cutoff operating range emergency response card differential pressure kPa'].filter(Boolean).join('\n'),
        page_size: Math.max(Number(params.page_size || 0), 20),
        top_k: Math.max(Number(params.top_k || 0), 128),
        keyword: true
      }
    };
  });
}

