function bossExtractTagTokensFromQuestion(question) {
  const out = [];
  const seen = new Set();
  const re = /\b[A-Z]{1,8}[A-Z0-9_]*\d{2,6}[A-Z0-9_]*(?:\.[A-Z0-9_]+)?\b/g;
  let m;
  while ((m = re.exec(String(question || '').toUpperCase())) !== null) {
    const token = m[0].replace(/\.$/, '');
    if (!seen.has(token)) {
      seen.add(token);
      out.push(token);
    }
  }
  return out;
}

function bossTagAliasVariants(token) {
  const raw = String(token || '').trim().toUpperCase();
  if (!raw) return [];
  const base = raw.replace(/\.(PV|OP|SP|MV|SV|CV)$/i, '');
  const variants = [raw, base, `${base}.PV`];
  // TAG_COMPARE_ALIAS_EXPANSION_V427_PATCH: generic near-alias expansion for historian/catalog searches.
  // Some plant tags differ by an alarm/status letter immediately before the numeric suffix.
  const insertedA = base.replace(/^([A-Z]+?)(\d{2,6}[A-Z0-9_]*)$/, function(_, prefix, rest) {
    return /A$/i.test(prefix) ? `${prefix}${rest}` : `${prefix}A${rest}`;
  });
  if (insertedA && insertedA !== base) {
    variants.push(insertedA, `${insertedA}.PV`);
  }
  for (const v of [base, insertedA]) {
    if (v) variants.push(`FC-${v}`, `FC-${v}.PV`);
  }
  return uniqueStrings(variants);
}

function bossBuildTagComparisonAliasUnit(baseUnit, item, defaultTarget, originalQuestion, unitId) {
  const tokens = bossExtractTagTokensFromQuestion(originalQuestion);
  const saved = getKnownTagsFromConversation(conversationState);
  const variants = uniqueStrings(tokens.flatMap(bossTagAliasVariants).concat(saved)).slice(0, 32);
  if (!variants.length) return null;
  const params = asObject(baseUnit.params);
  return {
    ...baseUnit,
    unit_id: Number(unitId || baseUnit.unit_id || 1),
    tool: 'arctic_find_tags',
    params: {
