// PLANNER_MONGO_NAMING_TO_INTERNAL_V7
// 规划器工具名自 09-18 起由 arctic_* 变为 mongo_*（exec 140962 及更早全为 arctic_*，exec 142408 起全为 mongo_*）。
// 其余节点进门都有 toInternal*（mongo→arctic）转换，唯独本节点没有，而本节点的兜底判断只认 arctic_*：
// 描述侧备份目录查询、位号问句补文档检索、stats/analyze 成对补齐、全历史分窗等对规划器单元一律失效
// （MT25 T7 exec 147277：目录查询零命中后备份查询未补，整轮无数据）。进门时转成内部叫法，与 09-16 之前的规划器输出一致。
function __toInternalHistorianTarget(t) {
  const o = { ...asObject(t) };
  if (o.library == null && o.database != null) o.library = o.database;
  if (o.symbol == null && o.collection != null) o.symbol = o.collection;
  delete o.database;
  delete o.collection;
  return o;
}
function __toInternalHistorianUnit(u) {
  const src = asObject(u);
  const tool = asString(src.tool);
  // NO_HARDCODE_V7：前缀统一转换，不维护工具名对照表。
  const internal = /^mongo_/.test(tool) ? tool.replace(/^mongo_/, 'arctic_') : '';
  if (!internal) return u;
  const p = __toInternalHistorianTarget(src.params);
  if (Array.isArray(p.targets)) p.targets = p.targets.map(__toInternalHistorianTarget);
  return { ...src, tool: internal, params: p, original_tool: tool };
}
if (Array.isArray(item.units)) item.units = item.units.map(__toInternalHistorianUnit);
// AS_OF_TIMESTAMP_TO_WINDOW_V7：as_of 是数据版本号（整数）。Planner 把事件时刻写进 as_of 时（MT25 T10 exec 154594：
// as_of "2025-11-01 08:05:00"、无 date_range → 服务端 422，且被拆成 13 个全历史窗口全部失败），去掉 as_of；
// 单元没有时间范围时把它当作分析时点，时间范围取前后各 2 小时（与事件窗口同一口径）。
// 改在 item.units 源头（后面多处逻辑从 item.units 重建单元，只改副本会被覆盖）。
if (Array.isArray(item.units)) item.units = item.units.map((raw) => {
  const u = asObject(raw);
  if (!/^(?:mongo|arctic)_(?:read|stats|analyze)$/.test(asString(u.tool))) return raw;
  const params = asObject(u.params);
  const isVersion = v => Number.isInteger(v) || /^\d+$/.test(String(v).trim());
  const toMs = v => { const t = String(v).trim().replace(' ', 'T'); const ms = Date.parse(/[zZ]|[+-]\d{2}:?\d{2}$/.test(t) ? t : t + 'Z'); return Number.isFinite(ms) ? ms : null; };
  const hasRange = o => Array.isArray(o && o.date_range) && o.date_range.filter(Boolean).length === 2;
  let moment = null, touched = false;
  const p2 = { ...params };
  if (p2.as_of !== undefined && p2.as_of !== null && !isVersion(p2.as_of)) { moment = moment ?? toMs(p2.as_of); delete p2.as_of; touched = true; }
  if (Array.isArray(p2.targets)) {
    p2.targets = p2.targets.map(t => {
      const o = { ...asObject(t) };
      if (o.as_of !== undefined && o.as_of !== null && !isVersion(o.as_of)) { moment = moment ?? toMs(o.as_of); delete o.as_of; touched = true; }
      return o;
    });
  }
  if (!touched) return raw;
  if (moment !== null && !hasRange(p2) && !asArray(p2.targets).some(hasRange)) {
    const f = ms => new Date(ms).toISOString().slice(0, 19).replace('T', ' ');
    p2.date_range = [f(moment - 2 * 3600000), f(moment + 2 * 3600000)];
    p2.as_of_moment_window = { moment: f(moment), hours_each_side: 2 };
  }
  return { ...u, params: p2 };
});

// EVENT_WINDOW_FOR_ANALYZE_V7：本轮问句出现会话已保存越限时段的日期、而分析单元没有时间范围时，用该越限时段前后各 2 小时。
