      .map(x => String(x || '')).join(' ');
    // 判断本轮是否在谈这次越限：问句里写了越限日期；或问题拆解判定本轮是依赖历史的追问、且会话里该事件为已确认
    //（补全后的问句不一定带日期：exec 155303「已筛选出的两器压差相关测点超标事件」）
    let followUp = false;
