    if (!hit.length) return;
    const pt = x => { const v = String(x || '').trim().replace(' ', 'T'); return Date.parse(/[zZ]|[+-]\d{2}:?\d{2}$/.test(v) ? v : v + (v.length <= 16 ? ':00Z' : 'Z')); };
