    const b = Math.max(...hit.map(e => pt(e.last_crossing)).filter(Number.isFinite));
    if (!Number.isFinite(a) || !Number.isFinite(b)) return;
    const f = ms => new Date(ms).toISOString().slice(0, 19).replace('T', ' ');
    const range = [f(a - 2 * 3600000), f(b + 2 * 3600000)];
