      if (hasRange(p) || asArray(p.targets).some(hasRange)) return raw;
      return { ...u, params: { ...p, date_range: range.slice(), event_window_from_saved_episode: { first_crossing: f(a), last_crossing: f(b), hours_each_side: 2 } } };
