// 目录检索匹配的是标签描述（"沉降器与二再差压"这类），描述里永远不会出现
// "控制器""位号""标签""是什么"这些查询用词；把它们原样带进 query 只会稀释召回。
// 实测：query="两器压差" -> count=1；query="压差控制器 位号" -> count=0。
// 这里剥掉通用查询词，保留物理量与设备词；位号形态原样保留；剥空则回退原文。
function bossNormalizeTagCatalogQuery(raw) {
  const text = String(raw || '').trim();
  if (!text) return text;
  const tags = text.match(/[A-Z]{2,6}\d{3,5}[A-Z]?(?:\.[A-Z]{2,4})?/g) || [];
  // V6b：按长度降序剥，避免"多少"先命中把"是多少"切成残留的"是"
  const GENERIC = [
    '正常控制范围', '控制范围', '告诉我', '对应的', '相关的', '叫什么', '是什么', '什么是',
    '有哪些', '是多少', '查一下', '控制器', '控制点', '点位', '位号', '标签', '测点',
    '仪表', '表号', '编号', '名称', '哪些', '多少', '查询', '查找', '检索', '请问', '对应',
    'tags', 'tag', 'point', 'name', 'what', 'which', 'the', 'for', 'of', 'is'
  ].sort((a, b) => b.length - a.length);
  let stripped = text;
  for (const w of GENERIC) stripped = stripped.split(w).join(' ');
  stripped = stripped.replace(/[?？。，,、;；:：!！()（）]/g, ' ').replace(/\s+/g, ' ').trim();
  // V6b：剥完残留的单字虚词不进查询串
  const STOP1 = new Set(['的', '是', '在', '和', '与', '或', '了', '吗', '呢', '把', '被', '给']);
  const kept = [];
  for (const seg of stripped.split(' ')) {
    const t = seg.trim();
    if (!t) continue;
    if (/^[\u4e00-\u9fff]$/.test(t) && STOP1.has(t)) continue;
    if (/^[\u4e00-\u9fff]$/.test(t)) continue;
    kept.push(t);
  }
  const merged = uniqueStrings(tags.concat(kept)).join(' ').trim();
  return merged.length >= 2 ? merged : text;
}

