}

function matchedMemoryPayload(state, resolution) {
  const ids = new Set(asArray(resolution.matched_fact_ids).map(String));
  const refs = new Set(asArray(resolution.matched_turns).map(String));
  const facts = asArray(state.fact_cards).filter(card => ids.has(String(card.fact_id || '')));
  const turns = asArray(state.turns).filter(turn => refs.has(String(turn.turn_ref || '')));
  return {
    facts,
    turns: turns.length ? turns : asArray(state.turns).slice(-6)
  };
}



// DIRECT_SUMMARY_PAYLOAD_COMPACTION_V5
// DIRECT_SUMMARY_STRIP_RUNTIME_FAILURES_V5
function stripRuntimeFailureSentences(value) {
  const raw = String(value || '');
  const parts = raw.split(/(?<=[。！？.!?])\s+|\n+/);
  const kept = [];
  for (const part of parts) {
    const s = String(part || '').trim();
    if (!s) continue;
    const lower = s.toLowerCase();
    const runtimeFailure =
      /timezone|tz-aware|tz-naive|timestamp.*(error|mismatch|mixed)|fetch failed|could not connect|nodeoperationerror|mcp server/.test(lower) ||
      /时区|时间戳.*(?:错误|混用|不匹配)|连接失败|无法连接|运行时错误|系统错误/.test(s);
    if (runtimeFailure) continue;
    kept.push(s);
  }
  return kept.join('\n').trim();
}

function compactDirectSummaryText(value, limit) {
  const s = stripRuntimeFailureSentences(value)
    .replace(/\r/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  const n = Number(limit || 800);
  return s.length > n ? s.slice(0, n).trim() + '...' : s;
}

function compactDirectSummaryTurns(turns, limit) {
  const maxTurns = Math.max(6, Math.min(Number(limit || 14), 24));
  return asArray(turns).slice(-maxTurns).map(t => {
    const obj = asObject(t);
    return {
      turn_ref: obj.turn_ref || null,
      ts: obj.ts || null,
      user_question: compactDirectSummaryText(obj.user_question || obj.question || '', 260),
      resolved_question: compactDirectSummaryText(obj.resolved_question || '', 360),
      assistant_answer: compactDirectSummaryText(obj.assistant_answer || obj.answer || '', 850),
      answer_mode: asString(obj.answer_mode),
      evidence_count: Number(obj.evidence_count || 0)
    };
  });
}

function compactDirectSummaryFactCards(cards, limit) {
  const maxCards = Math.max(20, Math.min(Number(limit || 90), 140));
  return asArray(cards).slice(-maxCards).map(card => {
    const obj = asObject(card);
    return {
      fact_id: obj.fact_id,
      source_turn: obj.source_turn,
      subject: compactDirectSummaryText(obj.subject, 160),
      relation: compactDirectSummaryText(obj.relation, 120),
      value: obj.value ?? null,
      status: asString(obj.status),
      entity_type: asString(obj.entity_type),
      entities: asArray(obj.entities).slice(0, 12),
      numbers: asArray(obj.numbers).slice(0, 12),
      evidence_ids: asArray(obj.evidence_ids).slice(0, 12),
      evidence_grounded: obj.evidence_grounded === true,
      note: compactDirectSummaryText(obj.note, 300)
    };
  });
}

function buildGenericSummaryContract(source, state) {
  const base = asObject(source);
  const params = { ...asObject(base.params) };
  delete params.text;
  return {
    ...base,
    unit_id: Number(base.unit_id) || 1,
    tool: 'direct_response',
    params: {
      ...params,
      mode: 'conversation_summary',
      no_retrieval: true,
      display_policy: 'finalizer',
      question: item.originalUserMessage || '',
      question_literal: item.originalUserMessage || '',
      resolved_question: params.resolved_question || item.originalUserMessage || '',
      summary_instruction: params.summary_instruction || 'Summarize the saved conversation faithfully. Preserve uncertainty, evidence boundaries, and the distinction between confirmed facts, candidates, and missing information. When earlier turns report a failed or unavailable analysis but later turns contain a successful replacement analysis for the same issue, treat the later result as the current state and mention the earlier failure only as superseded context when it affects the answer.',
      conversation_turns: compactDirectSummaryTurns((asArray(state.turn_archive).length ? asArray(state.turn_archive) : asArray(state.turns)), 14), // CONVERSATION_ARCHIVE_V7
      fact_cards: compactDirectSummaryFactCards(state.fact_cards, 90),
      // QUESTION_RELEVANCE_MEMORY_V5
      topic_summaries: asObject(state.topic_summaries),
      question_memory_cards: asArray(state.question_memory_cards).slice(-60),
      event_status: state.event_status || null
    },
    depends_on: [],
    question_part: 'other',
    required_evidence_types: [],
    optional_evidence_types: [],
    allow_synthesis: true
  };
}

function buildGenericMemoryContract(source, state, resolution) {
  const base = asObject(source);
  const payload = matchedMemoryPayload(state, resolution);
  const params = { ...asObject(base.params) };
  delete params.text;
  return {
    ...base,
    unit_id: Number(base.unit_id) || 1,
    tool: 'direct_response',
    params: {
      ...params,
