      question: item.originalUserMessage || '',
      question_literal: item.originalUserMessage || '',
      resolved_question: params.resolved_question || item.originalUserMessage || '',
      summary_instruction: 'Answer the current question only from the supplied structured memory. State what is confirmed, what remains unconfirmed, and which missing requirements prevent a stronger conclusion. Do not invent values or perform retrieval.',
      memory_resolution: cloneValue(resolution),
