}

// FULL_HISTORY_PRESENCE_CONTRACT_V5
function guardUnboundedStatistics(list) {
  // Preserve the planner's statistics contract. arctic_stats reports per-column
  // non-null counts, missing columns, and all-null columns without treating the
  // first preview rows as evidence for the complete history.
  return asArray(list).map(cloneValue);
}


// UNCONFIRMED_EVENT_CONTRACT_V452
// If a later question asks for values, windows, peak/margin calculations, or
// attribution that depend on an event still marked unconfirmed in memory, stop
// before retrieval. This uses structured plan/evidence fields, not test ids,
// tag names, equipment names, or literal question templates.
function eventStatusIsNonEvent(statusObj) {
  const src = asObject(statusObj);
  const status = asString(src.status).toLowerCase();
  const reason = asString(src.reason).toLowerCase();
  const missing = asArray(src.missing_requirements).map(String).filter(Boolean);
  const eventType = asString(src.event_type).toLowerCase();
  const saysNonEvent = /不涉及事件确认|未涉及事件确认|不是事件确认|非事件|not\s+(?:an?\s+)?event|no\s+event\s+confirmation|not\s+event\s+confirmation/.test(reason);
  return ['unconfirmed', 'contradicted'].includes(status) &&
    missing.length === 0 &&
    (saysNonEvent || !eventType || eventType === 'event');
}

// EVENT_GUARD_AND_TAG_FORMAT_V5
function currentEventStatus() {
  const resolutionStatus = asString(memoryResolution.status).toLowerCase();
  const fromState = asObject(conversationState.event_status);
  const fromResolution = asObject(memoryResolution.event_status);

  if (eventStatusIsNonEvent(fromResolution)) return { status: '', event_type: '', missing_requirements: [], reason: '', source_turn: '' };
  if (eventStatusIsNonEvent(fromState) && !['unconfirmed', 'contradicted', 'confirmed', 'candidate', 'informational'].includes(resolutionStatus)) {
    return { status: '', event_type: '', missing_requirements: [], reason: '', source_turn: '' };
  }

  if (['confirmed', 'candidate', 'informational'].includes(resolutionStatus)) {
    return {
      status: resolutionStatus,
      event_type: asString(fromResolution.event_type) || asString(fromState.event_type) || 'event',
      missing_requirements: asArray(memoryResolution.missing_requirements).map(String).filter(Boolean),
      reason: asString(memoryResolution.reason) || 'current memory resolution is not blocked',
      source_turn: asString(fromResolution.source_turn) || asString(fromState.source_turn)
    };
  }

  // EVENT_STATE_OUTRANKS_LLM_RESOLUTION_V7：历史库确定性定位确认、带锚点时间的事件，不被 LLM 的 unconfirmed 推翻
  // （MT25 T8 exec 152468：状态 confirmed/2023-07-23，Decompose Question 写 unconfirmed，整轮被改成拒答）。contradicted 仍尊重。
  const __stateAnchor = asString(asObject(fromState.event_window).anchor_timestamp) ||
    asString(asObject(asObject(fromState.statistical_anomaly).strongest_event).timestamp);
  if (resolutionStatus === 'unconfirmed' && asString(fromState.status).toLowerCase() === 'confirmed' && __stateAnchor) {
    return {
      status: 'confirmed',
      event_type: asString(fromState.event_type) || 'event',
      missing_requirements: [],
      reason: 'conversation_state.event_status is confirmed with anchor ' + __stateAnchor + '; the memory-resolution model said unconfirmed',
      source_turn: asString(fromState.source_turn)
    };
  }

  if (['unconfirmed', 'contradicted'].includes(resolutionStatus)) {
    const src = Object.keys(fromResolution).length ? fromResolution : fromState;
    const missing = asArray(memoryResolution.missing_requirements).concat(asArray(src.missing_requirements)).map(String).filter(Boolean);
    const candidate = {
      status: resolutionStatus,
      event_type: asString(src.event_type) || 'event',
      missing_requirements: missing,
      reason: asString(src.reason) || 'current memory resolution is unresolved',
      source_turn: asString(src.source_turn)
    };
    return eventStatusIsNonEvent(candidate) ? { status: '', event_type: '', missing_requirements: [], reason: '', source_turn: '' } : candidate;
  }

  const src = Object.keys(fromResolution).length ? fromResolution : fromState;
  if (eventStatusIsNonEvent(src)) return { status: '', event_type: '', missing_requirements: [], reason: '', source_turn: '' };
  return {
    status: asString(src.status).toLowerCase(),
    event_type: asString(src.event_type) || 'event',
    missing_requirements: asArray(src.missing_requirements).map(String).filter(Boolean),
    reason: asString(src.reason),
    source_turn: asString(src.source_turn)
  };
}

function evidenceContractText(units) {
  return asArray(units).map(unit => {
    const params = asObject(unit.params);
    return [
      unit.tool,
      unit.question_part,
      asArray(unit.required_evidence_types).join(' '),
      asArray(unit.optional_evidence_types).join(' '),
      params.mode,
      asArray(params.analysis_types).join(' '),
      asArray(params.required_evidence_types).join(' ')
    ].join(' ');
  }).join(' ').toLowerCase();
}

function dependsOnUnconfirmedEvent(units) {
  const ev = currentEventStatus();
  if (!['unconfirmed', 'contradicted'].includes(ev.status)) return false;

  const q = asString(item.originalUserMessage);
  const intent = currentQuestionEventIntent();
  const hasArctic = asArray(units).some(u => /^arctic_/i.test(asString(u.tool)));
  // NO_SAVED_EVENT_NOT_A_DEPENDENCY_V7：会话里没有已保存的事件、LLM 路由是取数、计划含历史库单元时，这一轮是去取证的首次筛查，
  // 不是「依赖未确认事件的追问」（短链 T7 exec 155417：Decompose Question 判 unconfirmed，筛查被整轮改成拒答）。
  if (!asString(asObject(conversationState.event_status).status) && asString(memoryResolution.route).toLowerCase() === 'retrieve' && hasArctic) return false;
  const exactTagCount = exactTagsFromQueryText(q).length + asArray(units).reduce((n, u) => {
    const p = asObject(u.params);
    return n + exactTagsFromQueryText([p.query, asArray(p.columns).join(' '), JSON.stringify(p.targets || [])].join(' ')).length;
  }, 0);
  const asksDataComparison = /历史|实时|数据库|时序|趋势|统计|数据|窗口|分钟|波动|同步|突变|下降|上升|比较|对比|count|min|max|mean|std|range|trend|data|window|minute|compare|sync|synchron|change|drop|rise|fluctuat|statistic/.test(q);
  const explicitDataOnly = hasArctic && exactTagCount > 0 && asksDataComparison && !intent.asksEvent && !intent.asksCause;
  if (explicitDataOnly) return false;

  const blob = evidenceContractText(units);
  const planRequiresEvent =
    /peak|excess|margin|alarm_event|alarm events|event_context|event_window|caus|attribution|real_possible_cause|threshold_comparison|direction_classification/.test(blob);

  return planRequiresEvent || (intent.asksEvent && (intent.asksNumeric || intent.asksCause || intent.asksDirection || intent.asksWindow));
}

function currentQuestionEventIntent() {
  const q = asString(item.originalUserMessage).toLowerCase();
  return {
    asksEvent: /exceed|exceedance|alarm|limit|event|超标|超限|越限|报警|事件/.test(q),
    asksNumeric: /peak|actual\s+value|how\s+much|margin|pv\b|op\b|sp\b|output|setpoint|取值|峰值|超限|超标幅度|输出|设定/.test(q),
    asksCause: /cause|caused|reason|attribut|真正原因|原因|归因/.test(q),
    asksDirection: /high[-\s]?side|low[-\s]?side|higher|lower|高侧|低侧|高限|低限/.test(q),
    asksWindow: /window|before|after|that\s+time|at\s+the\s+time|那时|当时|窗口|前后/.test(q)
  };
}

function eventStatusLooksRelevant(ev) {
  const intent = currentQuestionEventIntent();
  if (!intent.asksEvent) return true;
  const eventType = asString(ev.event_type).toLowerCase();
  const reason = asString(ev.reason).toLowerCase();
  const missing = asArray(ev.missing_requirements).join(' ').toLowerCase();
  const blob = `${eventType} ${reason} ${missing}`;
  return /exceed|exceedance|alarm|limit|threshold|event|超标|超限|越限|报警|阈值/.test(blob);
}

function defaultEventMissingRequirements(zh) {
  const intent = currentQuestionEventIntent();
  const base = zh
    ? ['已确认的事件身份', '报警/联锁阈值或限值', '超标时间戳或事件窗口']
    : ['confirmed event identity', 'alarm/interlock threshold or limit', 'exceedance timestamp or event window'];
  if (intent.asksNumeric) base.push(zh ? '对应测点的PV/OP/SP或趋势数据' : 'usable PV/OP/SP or trend data for the relevant point');
  if (intent.asksCause || intent.asksDirection) base.push(zh ? '相关阀位、压力和控制输出的窗口趋势' : 'windowed valve-position, pressure, and controller-output trends');
  return base;
}

function missingRequirementsText(ev, zh) {
  const missing = ev.missing_requirements.length && eventStatusLooksRelevant(ev)
    ? ev.missing_requirements
    : defaultEventMissingRequirements(zh);
  return missing.join(zh ? '；' : '; ');
}

function buildUnconfirmedEventText(units) {
  const q = asString(item.originalUserMessage);
  const zh = /[\u4e00-\u9fff]/.test(q);
  const ev = currentEventStatus();
  const blob = evidenceContractText(units);
  // DIRECT_EVENT_PASSTHROUGH_V453: combine structured evidence goals with
  // language-level intent terms from the current question. These are generic
  // calculation/value/direction intents, not test ids, tag names, or case rules.
  const qLower = q.toLowerCase();
  const asksNumeric = /peak|excess|exceedance\s+margin|margin|measured_value|measured_values|value_lookup|threshold_comparison/.test(blob) ||
    /peak|actual\s+value|how\s+much|margin|pv\b|op\b|sp\b|output|setpoint|取值|峰值|超限|超标幅度|给出.*值|输出|设定/.test(qLower);
  const asksCause = /caus|attribution|real_possible_cause/.test(blob) ||
    /cause|caused|reason|attribut|真正原因|原因|归因/.test(qLower);
  const asksWindow = /event_window|anomaly_window|period_verification|alarm_event/.test(blob) ||
    /window|before|after|that\s+time|at\s+the\s+time|那时|当时|窗口|前后/.test(qLower);
  const asksDirection = /direction_classification/.test(blob) ||
    /high[-\s]?side|low[-\s]?side|higher|lower|高侧|低侧|高限|低限/.test(qLower);
  const mentionedNumbers = Array.from(new Set((q.match(/[-+]?\d+(?:\.\d+)?\s*(?:kPa|MPa|bar|psi|℃|°C|t\/h|%|h|min|s)?/gi) || []).map(x => x.trim()).filter(x => /[a-z%℃°]/i.test(x))));
  const missing = missingRequirementsText(ev, zh);
  const matchedFacts = asArray(memoryResolution.matched_fact_ids).map(String).filter(Boolean);
  const matchedTurns = asArray(memoryResolution.matched_turns).map(String).filter(Boolean);
  const supplied = asString(memoryResolution.safe_response);

  if (supplied && !asksNumeric) return supplied;

  if (zh) {
    const parts = [
      `这个追问依赖的历史事件目前仍是“${ev.status || 'unconfirmed'}”，不能把它当作已经确认的超标事件继续计算、归因或取值。缺失条件：${missing}。`
    ];
    if (asksDirection) parts.push('因此当前不能判断该事件是高侧还是低侧超限。');
    if (asksNumeric) parts.push('因此当前不能计算实际峰值、超限幅度，也不能给出该时刻的PV、OP或SP。');
    if (mentionedNumbers.length) parts.push(`当前问题提到的数值（${mentionedNumbers.join(', ')}）只能作为待核验的历史上下文或参考值，不能直接当作本装置本次事件的已确认阈值。`);
    if (asksCause) parts.push('因此当前不能判断真正原因，也不能把原因归到某个阀门、变量或控制回路。');
    if (asksWindow) parts.push('因此当前不能构造超标前后窗口，也不能把非空样本当作超标记录。');
    if (matchedFacts.length || matchedTurns.length) parts.push(`可参考的历史上下文：${matchedTurns.length ? `轮次 ${matchedTurns.join(', ')}` : ''}${matchedFacts.length ? `；事实卡 ${matchedFacts.join(', ')}` : ''}。`);
    parts.push('下一步应先从DCS/SIS报警表、联锁设定表、事件记录或正确测点清单确认阈值、时间窗口和测点身份，再做趋势读取、峰值/差值计算或原因分析。');
    return parts.join('\n\n');
  }

  const parts = [
    `The historical event required by this follow-up is still "${ev.status || 'unconfirmed'}", so it must not be treated as a confirmed exceedance for further calculation, attribution, or value lookup. Missing requirements: ${missing}.`
  ];
  if (asksDirection) parts.push('Therefore, it cannot classify the event as a high-side or low-side exceedance yet.');
  if (asksNumeric) parts.push('Therefore, the workflow cannot calculate the actual peak, exceedance margin, PV, OP, or SP for that event yet.');
  if (mentionedNumbers.length) parts.push(`The value(s) mentioned in the question (${mentionedNumbers.join(', ')}) remain historical context or reference values to be verified; they cannot be treated as confirmed thresholds for this unit or event yet.`);
  if (asksCause) parts.push('Therefore, it cannot assign the real cause to a valve, variable, controller, or operating path yet.');
  if (asksWindow) parts.push('Therefore, it cannot build a before/after event window or treat non-null historian samples as exceedance records.');
  if (matchedFacts.length || matchedTurns.length) parts.push(`Relevant saved context: ${matchedTurns.length ? `turns ${matchedTurns.join(', ')}` : ''}${matchedFacts.length ? `${matchedTurns.length ? '; ' : ''}fact cards ${matchedFacts.join(', ')}` : ''}.`);
  parts.push('Confirm the threshold, timestamp/window, and correct point identity from DCS/SIS alarm records, interlock settings, event logs, or loop sheets before trend extraction, peak/margin calculation, or cause analysis.');
  return parts.join('\n\n');
}

function buildUnconfirmedEventContract(source, state, resolution, originalUnits) {
  const base = asObject(source);
  const payload = matchedMemoryPayload(state, resolution);
  const params = { ...asObject(base.params) };
  return {
    ...base,
    unit_id: Number(base.unit_id) || 1,
    tool: 'direct_response',
    params: {
      ...params,
      mode: 'unconfirmed_event_prerequisite',
      no_retrieval: true,
      display_policy: 'literal',
      question: item.originalUserMessage || '',
      question_literal: item.originalUserMessage || '',
      resolved_question: params.resolved_question || item.originalUserMessage || '',
      text: buildUnconfirmedEventText(originalUnits),
      summary_instruction: 'Answer only from structured memory and event status. Do not retrieve. Explain which prerequisite is unconfirmed and which missing requirements block calculation, value lookup, event-window analysis, or attribution.',
      memory_resolution: cloneValue(resolution),
      matched_fact_cards: payload.facts,
      conversation_turns: payload.turns,
      event_status: currentEventStatus()
    },
    depends_on: [],
    question_part: 'other',
    required_evidence_types: [],
    optional_evidence_types: [],
    allow_synthesis: true
  };
}

function enforceGenericContracts(currentUnits) {
  const planned = asArray(item.units).map(cloneValue);
  const source = (forceFreshHistorianVerification || forceEvidenceCompletenessRetrieval)
    ? asArray(currentUnits).map(cloneValue)
    : (planned.length ? planned : asArray(currentUnits).map(cloneValue));
  const summarySource = source.find(u =>
    asObject(u.params).mode === 'conversation_summary' || u.tool === 'conversation_summary'
  );
  if (summarySource) return [buildGenericSummaryContract(summarySource, conversationState)];

  if (dependsOnUnconfirmedEvent(source)) {
    return [buildUnconfirmedEventContract(source[0] || {}, conversationState, memoryResolution, source)];
  }

  const route = asString(memoryResolution.route);
  const matchedFacts = asArray(memoryResolution.matched_fact_ids);
  const shouldUseMemory = !forceFreshHistorianVerification && !forceEvidenceCompletenessRetrieval && (route === 'memory_only' || (
    structuredMemoryMustStop(memoryResolution) &&
    (matchedFacts.length > 0 || route !== 'retrieve')
  ));
  if (shouldUseMemory) {
    return [buildGenericMemoryContract(source[0] || {}, conversationState, memoryResolution)];
  }

  return guardUnboundedStatistics(source);
}



// CONFLICTING_LOCAL_DATE_PREPROCESSOR_REMOVED_V5
// Query-time timezone semantics are owned only by ARCTIC_UTC_QUERY_BOUNDARY_V5.


// COMPACT_EXACT_PROCESS_TAG_FANOUT_V5
function exactTagsFromQueryText(text) {
  const raw = asString(text);
  const out = [];
  const seen = new Set();
  const pattern = /\b[A-Za-z]{1,8}[A-Za-z0-9_]*\d{2,6}[A-Za-z0-9_]*(?:\.[A-Za-z0-9_]+)?\b/g;
  let m;
  while ((m = pattern.exec(raw)) !== null) {
    const tag = m[0];
    const key = tag.toUpperCase();
    if (!seen.has(key)) {
      seen.add(key);
      out.push(tag);
    }
  }
  return out;
}

function compactExactProcessTagFanout(list) {
  const target = getDefaultArcticTarget(catalog);
  if (!target.library || !target.symbol) return list;
  const src = asArray(list).map(cloneValue);
  const findUnits = src.filter(u => asString(u.tool) === 'arctic_find_tags');
  const processFind = findUnits.find(u => {
    const p = asObject(u.params);
    return asString(p.library) === target.library && asString(p.symbol) === target.symbol;
  });
  if (!processFind) return list;

  const explicitTags = exactTagsFromQueryText(asObject(processFind.params).query);
  if (explicitTags.length < 2) return list;

  const processStats = src.filter(u => {
    const p = asObject(u.params);
    return asString(u.tool) === 'arctic_stats' &&
      asString(p.library) === target.library &&
      asString(p.symbol) === target.symbol;
  });
  if (!processStats.length) return list;

  const kept = [processFind, ...processStats].map(cloneValue);
  const oldToNew = new Map();
  kept.forEach((u, idx) => {
    oldToNew.set(Number(u.unit_id), idx + 1);
    u.unit_id = idx + 1;
  });
  for (const u of kept) {
    const p = asObject(u.params);
    if (asString(u.tool) === 'arctic_stats') {
      u.depends_on = [oldToNew.get(Number(processFind.unit_id)) || 1];
      if (asString(p.columns).startsWith('$ref:')) {
        u.params = { ...p, columns: `$ref:${u.depends_on[0]}.tags` };
      }
    } else {
      u.depends_on = [];
    }
  }
  return kept;
}



// DATA_ONLY_ARCTIC_COMPACTION_V5
function asksForDocumentKnowledge(text) {
  const q = asString(text).toLowerCase();
  return /机理|原因|为什么|处理|调整|操作规程|报警|阈值|限值|目标|理想|设计值|范围|setpoint|threshold|alarm|limit|target|ideal|mechanism|cause|procedure|recommend/.test(q);
}

function isDataOnlyArcticRequest(text, list) {
  const q = asString(text);
  const hasArctic = asArray(list).some(u => /^arctic_/i.test(asString(u.tool)));
  if (!hasArctic) return false;
  const asksStats = /count|min|max|mean|latest|range|std|标准差|极差|波动|同步|突变|下降|分钟级|数据|统计|对比|比较|趋势/.test(q);
  const hasExactTags = exactTagsFromQueryText(q).length >= 1 || asArray(list).some(u => exactTagsFromQueryText(asObject(u.params).query).length >= 1);
  return asksStats && hasExactTags && !asksForDocumentKnowledge(q);
}

function dropRagForDataOnlyArctic(list) {
  if (!isDataOnlyArcticRequest(item.originalUserMessage || '', list)) return list;
  // PLANNED_EVIDENCE_UNITS_KEPT_V7：Planner 标了 required_evidence_types 的非历史库单元（技术报告记录、设备关系图等）
  // 是明确计划的证据来源，不因「纯数据请求」被删（report8 Q5 exec 154426：R1101 被当成位号，报告检索与关系图单元被删）
  const arctic = asArray(list).filter(u => /^arctic_/i.test(asString(u.tool)) || asArray(asObject(u).required_evidence_types).length > 0);
  return arctic.length ? arctic : list;
}

function compactExactProcessAnalyzeFanout(list) {
  const target = getDefaultArcticTarget(catalog);
  if (!target.library || !target.symbol) return list;
  const src = asArray(list).map(cloneValue);
  const findUnits = src.filter(u => asString(u.tool) === 'arctic_find_tags');
  const processFind = findUnits.find(u => {
    const p = asObject(u.params);
    return asString(p.library) === target.library && asString(p.symbol) === target.symbol;
  });
  if (!processFind) return list;
  const explicitTags = exactTagsFromQueryText(asObject(processFind.params).query);
  if (explicitTags.length < 2) return list;

  const analyzeUnits = src.filter(u => asString(u.tool) === 'arctic_analyze');
  if (!analyzeUnits.length) return list;

  const kept = [processFind];
  for (const raw of analyzeUnits) {
    const u = cloneValue(raw);
    const p = asObject(u.params);
    const targets = asArray(p.targets).filter(t => {
      const tt = asObject(t);
      return asString(tt.library) === target.library && asString(tt.symbol) === target.symbol;
    });
    if (!targets.length) continue;
    targets[0] = { ...targets[0], columns: asString(targets[0].columns).startsWith('$ref:') ? '$ref:step1.tags' : targets[0].columns };
    u.params = { ...p, targets: [targets[0]] };
    u.depends_on = [1];
    kept.push(u);
  }
  if (kept.length < 2) return list;
  kept.forEach((u, idx) => { u.unit_id = idx + 1; });
  return kept;
}



// SHORT_WINDOW_ANALYSIS_AND_FINALIZER_GROUNDING_V5
function parseDateMsForResample(v) {
  const s = asString(v).replace(' ', 'T');
  const ms = Date.parse(s);
  return Number.isFinite(ms) ? ms : null;
}

function tuneShortWindowArcticAnalyze(list) {
  return asArray(list).map(raw => {
    const unit = cloneValue(raw);
    const params = asObject(unit.params);
    if (asString(unit.tool) !== 'arctic_analyze') return unit;
    const range = asArray(params.date_range);
    if (range.length !== 2) return unit;
    const start = parseDateMsForResample(range[0]);
    const end = parseDateMsForResample(range[1]);
    if (start == null || end == null || end <= start) return unit;
    const hours = (end - start) / 3600000;
    const analysis = asArray(params.analysis_types).join(' ').toLowerCase();
    const needsTimeDomain = /correlation|lag_scan|anomaly_windows|period_profile|data_quality/.test(analysis);
    if (!needsTimeDomain) return unit;

    let resampleRule = asString(params.resample_rule);
    if (!resampleRule) {
      if (hours <= 6) resampleRule = '15min';
      else if (hours <= 48) resampleRule = '1h';
      else if (hours <= 24 * 14) resampleRule = '6h';
      else resampleRule = 'D';
    }

    unit.params = {
      ...params,
      resample_rule: resampleRule,
      min_overlap: Number(params.min_overlap || 0) > 0 ? params.min_overlap : (hours <= 6 ? 4 : 3)
    };
    return unit;
  });
}



// ANALYZE_TARGET_COLUMNS_FANOUT_V5
function normalizeExplicitTagToken(token) {
  const s = asString(token).replace(/^(process|lims|catalyst)\./i, '');
  return exactTagsFromQueryText(s)[0] || '';
}

function fanoutAnalyzeTargetColumnsToFindTags(list) {
  const out = asArray(list).map(cloneValue);
  const byId = new Map(out.map(u => [Number(u.unit_id), u]));
  const tagsByFindId = new Map();

  for (const unit of out) {
    if (asString(unit.tool) !== 'arctic_analyze') continue;
    const params = asObject(unit.params);
    const targetTags = uniqueStrings(
      asArray(params.target_columns)
        .concat(asArray(params.columns))
        .map(normalizeExplicitTagToken)
        .filter(Boolean)
    );
    if (!targetTags.length) continue;

    for (const target of asArray(params.targets)) {
      const columns = asString(asObject(target).columns);
      const m = columns.match(/^\$ref:step?(\d+)\.tags$/i);
      if (!m) continue;
      const refId = Number(m[1]);
      if (!Number.isFinite(refId) || !byId.has(refId)) continue;
      const existing = tagsByFindId.get(refId) || [];
      tagsByFindId.set(refId, uniqueStrings(existing.concat(targetTags)));
    }
  }

  for (const [refId, tags] of tagsByFindId.entries()) {
    const find = byId.get(refId);
    if (!find || asString(find.tool) !== 'arctic_find_tags') continue;
    const params = asObject(find.params);
    const existingTags = exactTagsFromQueryText(params.query);
    const mergedTags = uniqueStrings(existingTags.concat(tags));
    find.params = {
      ...params,
      query: mergedTags.length ? mergedTags.join(' ') : params.query,
      top_k: Math.max(Number(params.top_k || 0), mergedTags.length || 0, 8)
    };
  }

  return out;
}



// ARCTIC_UTC_QUERY_BOUNDARY_V5
// Arctic query bounds are UTC. The MCP accepts timezone-naive UTC strings, so
// explicit offsets are converted to UTC before their suffix is removed. A
// naive bound is already part of the workflow's UTC query contract.
function normalizeArcticUtcQueryDate(s) {
  const raw = asString(s);
  if (!raw) return s;
  if (!/(?:Z|[-+]\d{2}:?\d{2})$/i.test(raw)) return raw;
  const ms = Date.parse(raw);
  if (!Number.isFinite(ms)) return raw;
  return new Date(ms).toISOString().slice(0, 19);
}

// PROMOTE_FIRST_COVERAGE_TO_ANALYZE_V5
// arctic_read is a preview endpoint. When a unit explicitly requires first
// values or period coverage, use the server-side period profile contract.
function promoteFirstCoverageReadsToAnalyze(list) {
  return asArray(list).map(raw => {
    const unit = cloneValue(raw);
    const params = asObject(unit.params);
    const requirements = asArray(unit.required_evidence_types).map(asString);
    const needsPeriodProfile = requirements.some(x => /^(?:first_values|actual_coverage|period_profile|data_quality)$/i.test(x));
    const needsTimeSeriesAnalysis =
      requirements.some(x => /^(?:time_series|sequence|chronology|change_order)$/i.test(x)) ||
      /先后|变化顺序|逐点变化|what changed first|sequence|chronolog/i.test(
        String(item.originalUserMessage || '')
      );
    const eligible =
      asString(unit.tool) === 'arctic_read' &&
      (needsPeriodProfile || needsTimeSeriesAnalysis) &&
      asArray(params.date_range).length === 2 &&
      asArray(params.columns).length > 0 &&
      asArray(params.filters).length === 0 &&
      params.presence_probe !== true;
    if (!eligible) return unit;

    const library = asString(params.library);
    const symbol = asString(params.symbol);
    unit.tool = 'arctic_analyze';
    const columns = asArray(params.columns).map(asString).filter(Boolean);
    const startMs = Date.parse(String(params.date_range[0]).replace(' ', 'T') + 'Z');
    const endMs = Date.parse(String(params.date_range[1]).replace(' ', 'T') + 'Z');
    const hours = Number.isFinite(startMs) && Number.isFinite(endMs)
      ? Math.max(0, (endMs - startMs) / 3600000)
      : 0;
    const analysisTypes = needsTimeSeriesAnalysis
      ? ['period_profile', 'data_quality', 'anomaly_windows', 'lag_scan']
      : ['period_profile', 'data_quality'];
    unit.params = {
      date_range: cloneValue(params.date_range),
      targets: [{
        name: 'period_data',
        library,
        symbol,
        columns
      }],
      analysis_types: analysisTypes,
      target_columns: needsTimeSeriesAnalysis ? columns : undefined,
      resample_rule: needsTimeSeriesAnalysis
        ? (hours > 48 ? '1h' : (hours > 6 ? '5min' : '1min'))
        : undefined,
      min_overlap: needsTimeSeriesAnalysis ? 4 : undefined,
      top_n: Math.max(12, Math.min(100, columns.length))
    };
    unit.normalization_trace = asArray(unit.normalization_trace).concat([{
      action: 'promote_preview_read_to_period_profile',
      reason: 'first_values_or_actual_coverage_requires_server_side_period_profile'
    }]);
    return unit;
  });
}

function normalizeArcticTimeseriesDateRanges(list) {
  return asArray(list).map(raw => {
    const unit = cloneValue(raw);
    const params = asObject(unit.params);
    if (!/^arctic_(?:read|stats|analyze)$/i.test(asString(unit.tool))) return unit;
    const next = { ...params };
    if (Array.isArray(next.date_range) && next.date_range.length === 2) {
      next.date_range = next.date_range.map(normalizeArcticUtcQueryDate);
      delete next.date_range_timezone;
    }
    if (Array.isArray(next.targets)) {
      next.targets = next.targets.map(t => {
        const target = { ...asObject(t) };
        if (Array.isArray(target.date_range) && target.date_range.length === 2) {
          target.date_range = target.date_range.map(normalizeArcticUtcQueryDate);
          delete target.date_range_timezone;
        }
        return target;
      });
    }
    unit.params = next;
    return unit;
  });
}



// EVENT_DEPENDENT_RANGE_ANCHOR_V5
function confirmedEventAnchorMs() {
  const event = asObject(conversationState.event_status);
  if (asString(event.status).toLowerCase() !== 'confirmed') return null;
  const strongest = asObject(asObject(event.statistical_anomaly).strongest_event);
  const window = asObject(event.event_window);
  const raw = asString(strongest.timestamp || window.anchor_timestamp);
  if (!raw) return null;
  const ms = Date.parse(raw.replace(' ', 'T'));
  return Number.isFinite(ms) ? ms : null;
}

function anchorEventDependentRanges(list) {
  const anchor = confirmedEventAnchorMs();
  if (anchor == null) return list;

  return asArray(list).map(raw => {
    const unit = cloneValue(raw);
    const params = asObject(unit.params);
    if (!/^arctic_(?:read|stats|analyze)$/i.test(asString(unit.tool))) return unit;
    const evidenceContract = [
      unit.question_part,
      asArray(unit.required_evidence_types).join(' '),
      asArray(unit.optional_evidence_types).join(' '),
      asArray(params.analysis_types).join(' ')
    ].join(' ').toLowerCase();
    if (!/(?:recovery|event_window|anomaly_window|event_characterization)/.test(evidenceContract)) {
      return unit;
    }

    const range = asArray(params.date_range);
    if (range.length !== 2) return unit;
    let start = parseDateMsForResample(range[0]);
    let end = parseDateMsForResample(range[1]);
    if (start == null || end == null || end < start) return unit;
    if (anchor >= start && anchor <= end) return unit;

    const includeTime = range.some(value => /[T ]\d{2}:\d{2}/.test(asString(value)));
    if (anchor < start) start = anchor;
    if (anchor > end) end = anchor;
    unit.params = {
      ...params,
      date_range: [
        formatNaiveUtcMs(start, includeTime),
        formatNaiveUtcMs(end, includeTime)
      ]
    };
    unit.normalization_trace = asArray(unit.normalization_trace).concat([{
      action: 'include_confirmed_event_anchor',
      reason: 'event-dependent evidence must include the saved event anchor'
    }]);
    return unit;
  });
}

units = normalizeArcticTimeseriesDateRanges(anchorEventDependentRanges(promoteFirstCoverageReadsToAnalyze(fanoutAnalyzeTargetColumnsToFindTags(tuneShortWindowArcticAnalyze(dropRagForDataOnlyArctic(compactExactProcessAnalyzeFanout(compactExactProcessTagFanout(enforceGenericContracts(units)))))))));
// REMOVE_SPECIAL_TAG_LOCK_AND_OR_NOISE_V5
// Tag-search query expansion now uses whitespace-separated terms so boolean words do not become catalog noise.

// FINAL_CONCEPT_COMPACTION_V5
units = bossCompactControlConceptRagUnits(units, originalQuestion);


// SPLIT_PRESENCE_PROBE_READS_V5
function looksLikeProcessPvTag(tag) {
  return /\b[A-Z]{1,8}[A-Z0-9_]*\d{2,6}[A-Z0-9_]*\.PV\b/i.test(String(tag || ''));
}

function splitPresenceProbeReads(list, defaultTarget) {
  const out = [];
  let nextId = 1;
  // PLANNED_EVIDENCE_UNITS_KEPT_V7：重新编号时记录旧→新编号，最后重映射 depends_on
  // （exec 154426：3/4/5 改编为 1/2/3 而依赖仍是 [3]，统计单元依赖分析单元、分析单元依赖自己，统计永不执行）
  const oldToNew = new Map();
  const mark = (oldId, newId) => { const k = Number(oldId); if (!Number.isFinite(k)) return; if (!oldToNew.has(k)) oldToNew.set(k, []); oldToNew.get(k).push(newId); };
  for (const raw of asArray(list)) {
    const unit = asObject(raw);
    const params = asObject(unit.params);
    const cols = asArray(params.columns).map(asString).filter(Boolean);
    const isProbe = asString(unit.tool) === 'arctic_read' && params.presence_probe === true && cols.length > 1 && !asArray(params.filters).length;
    if (!isProbe) {
      mark(unit.unit_id, nextId);
      out.push({ ...unit, unit_id: nextId++ });
      continue;
    }

    const allProcessPv = cols.every(looksLikeProcessPvTag);
    const lib = asString(params.library);
    const sym = asString(params.symbol);
    if (allProcessPv && (lib !== defaultTarget.library || sym !== defaultTarget.symbol)) {
      continue;
    }

    for (const col of cols.slice(0, 16)) {
      mark(unit.unit_id, nextId);
      out.push({
        ...unit,
        unit_id: nextId++,
        params: {
          ...params,
          columns: [col],
          filters: [{ col, op: '!=', val: null }],
          head: Math.min(Number(params.head || 3), 3),
          presence_probe: true,
          presence_probe_strategy: 'per_tag_non_null_filter',
          no_default_epoch_window: true
        },
        depends_on: []
      });
    }
  }
  for (const u of out) {
    if (!Array.isArray(u.depends_on) || !u.depends_on.length) continue;
    const mapped = [];
    for (const d of u.depends_on) for (const n of (oldToNew.get(Number(d)) || [])) if (n !== u.unit_id && mapped.indexOf(n) < 0) mapped.push(n);
    u.depends_on = mapped;
  }
  return out;
}

// PROBE_ONLY_PLAN_ADDS_STATS_V7：计划意图是取数，而历史库数据单元全是探测读数（presence_probe，只读几行）时，
// 补一个同位号的统计单元（时间窗口走默认）。验证链 T7 exec 155245：Planner 只规划了「位号查找 + 3 行探测读数」，
// 回答只能写「无法判定是否超标」。
units = (function addStatsWhenOnlyProbes(list) {
  const arr = asArray(list);
  if (asString(item.plan_intent).toLowerCase() !== 'data_retrieval') return arr;
  const data = arr.filter(u => /^arctic_(?:read|stats|analyze)$/.test(asString(asObject(u).tool)));
  if (!data.length) return arr;
  if (!data.every(u => asString(u.tool) === 'arctic_read' && asObject(u.params).presence_probe === true)) return arr;
  const probe = data[0];
  const pp = asObject(probe.params);
  let nextId = 0;
  for (const u of arr) { const n = Number(asObject(u).unit_id); if (Number.isFinite(n) && n > nextId) nextId = n; }
  const stats = {
    unit_id: nextId + 1,
    tool: 'arctic_stats',
    params: { library: pp.library, symbol: pp.symbol, columns: cloneValue(pp.columns) },
    depends_on: cloneValue(asArray(probe.depends_on)),
    question_part: probe.question_part || 'period_verification',
    required_evidence_types: cloneValue(asArray(probe.required_evidence_types)),
    optional_evidence_types: [],
    allow_synthesis: true,
    normalization_trace: [{ action: 'add_stats_for_probe_only_plan', reason: 'presence_probe_cannot_answer_a_data_question' }]
  };
  if (!stats.params.library) delete stats.params.library;
  if (!stats.params.symbol) delete stats.params.symbol;
  return arr.concat([stats]);
})(units);
units = splitPresenceProbeReads(units, defaultTarget);


// ARCTIC_TARGET_INHERITANCE_V5
function verifiedArcticRegistryByTag(state) {
  const map = new Map();
  for (const raw of asArray(asObject(state).arctic_target_registry)) {
    const entry = asObject(raw);
    const tag = asString(entry.tag || entry.name);
    const library = asString(entry.library);
    const symbol = asString(entry.symbol);
    const count = Number(entry.count);
    const status = asString(entry.data_status || entry.status);
    if (!tag || !library || !symbol) continue;
    if (!(Number.isFinite(count) && count > 0) && !/^ok|usable|available$/i.test(status)) continue;
    const key = tag.toUpperCase();
    const prior = map.get(key);
    if (!prior || Number(entry.count || 0) > Number(prior.count || 0)) map.set(key, entry);
  }
  return map;
}

function userExplicitlyNamesArcticTarget(question, target) {
  const q = String(question || '').toLowerCase();
  const library = asString(asObject(target).library).toLowerCase();
  const symbol = asString(asObject(target).symbol).toLowerCase();
  return (library && q.includes(library)) || (symbol && q.includes(symbol));
}

function routeColumnsThroughVerifiedTargets(columns, fallbackTarget, registry) {
  const groups = new Map();
  for (const raw of asArray(columns)) {
    const tag = asString(raw);
    if (!tag) continue;
    const known = registry.get(tag.toUpperCase());
    const target = known || fallbackTarget;
    const library = asString(target.library);
    const symbol = asString(target.symbol);
    const key = `${library}|${symbol}`;
    if (!groups.has(key)) groups.set(key, { library, symbol, columns: [] });
    groups.get(key).columns.push(tag);
  }
  return Array.from(groups.values());
}

function inheritVerifiedArcticTargets(list, state, question) {
  const registry = verifiedArcticRegistryByTag(state);
  if (!registry.size) return list;
  return asArray(list).map(raw => {
    const unit = cloneValue(raw);
    const tool = asString(unit.tool);
    const params = asObject(unit.params);

    if (tool === 'arctic_analyze' && asArray(params.targets).length) {
      const targets = [];
      for (const targetRaw of asArray(params.targets)) {
        const target = asObject(targetRaw);
        if (!Array.isArray(target.columns) || userExplicitlyNamesArcticTarget(question, target)) {
          targets.push(target);
          continue;
        }
        for (const group of routeColumnsThroughVerifiedTargets(target.columns, target, registry)) {
          targets.push({ ...target, ...group, target_resolution_source: 'conversation_arctic_target_registry' });
        }
      }
      unit.params = { ...params, targets };
      return unit;
    }

    if (/^arctic_(?:find_tags|read|stats)$/i.test(tool)) {
      const tags = tool === 'arctic_find_tags'
        ? exactTagsFromQueryText(params.query)
        : asArray(params.columns).map(asString).filter(Boolean);
      const known = tags.map(tag => registry.get(tag.toUpperCase())).filter(Boolean);
      const keys = new Set(known.map(x => `${asString(x.library)}|${asString(x.symbol)}`));
      if (known.length === tags.length && tags.length && keys.size === 1 && !userExplicitlyNamesArcticTarget(question, params)) {
        const chosen = known[0];
        unit.params = {
          ...params,
          library: asString(chosen.library),
          symbol: asString(chosen.symbol),
          target_resolution_source: 'conversation_arctic_target_registry'
        };
      }
    }
    return unit;
  });
}

units = inheritVerifiedArcticTargets(units, conversationState, originalQuestion);

// FULL_HISTORY_RANGE_FROM_REGISTRY_V5
// A prior statistics/existence turn records the measured symbol coverage.
// Reuse that structured range for a later full-history analysis so the
// existing long-window packer can keep each analyzer target below row limits.
function addRegistryRangeToFullHistoryAnalysis(list, state) {
  const registry = asArray(asObject(state).arctic_target_registry).map(asObject);
  if (!registry.length) return list;

  return asArray(list).map(raw => {
    const unit = cloneValue(raw);
    const params = asObject(unit.params);
    if (asString(unit.tool) !== 'arctic_analyze') return unit;
    if (asArray(params.date_range).length === 2) return unit;
    const targets = asArray(params.targets);
    if (!targets.length || targets.some(target => asArray(asObject(target).date_range).length === 2)) {
      return unit;
    }

    const ranges = [];
    for (const targetRaw of targets) {
      const target = asObject(targetRaw);
      const library = asString(target.library);
      const symbol = asString(target.symbol);
      for (const columnRaw of asArray(target.columns)) {
        const column = asString(columnRaw).toUpperCase();
        const entry = registry.find(row =>
          asString(row.tag).toUpperCase() === column &&
          asString(row.library) === library &&
          asString(row.symbol) === symbol &&
          asArray(row.time_range).length === 2
        );
        if (entry) ranges.push(asArray(entry.time_range).slice(0, 2));
      }
    }
    if (!ranges.length) return unit;

    const starts = ranges.map(range => parseNaiveUtcMs(range[0])).filter(Number.isFinite);
    const ends = ranges.map(range => parseNaiveUtcMs(range[1])).filter(Number.isFinite);
    if (!starts.length || !ends.length) return unit;
    const start = Math.min(...starts);
    const end = Math.max(...ends);
    if (!(end > start)) return unit;

    unit.params = {
      ...params,
      date_range: [
        formatNaiveUtcMs(start, true),
        formatNaiveUtcMs(end, true)
      ],
      history_range_source: 'conversation_arctic_target_registry'
    };
    unit.normalization_trace = asArray(unit.normalization_trace).concat([{
      action: 'restore_full_history_range',
      source: 'conversation_arctic_target_registry',
      covered_registry_entries: ranges.length
    }]);
    return unit;
  });
}

units = addRegistryRangeToFullHistoryAnalysis(units, conversationState);

// LONG_ARCTIC_ANALYZE_WINDOWS_V5
// The Arctic analysis API accepts at most 180 days per request. Expand longer
// ranges structurally and chain the generated units so the existing result
// aggregator receives every non-overlapping segment.
function parseNaiveUtcMs(value) {
  const raw = asString(value);
  if (!raw) return null;
  const normalized = raw.replace(' ', 'T');
  const withZone = /(?:Z|[-+]\d{2}:?\d{2})$/i.test(normalized) ? normalized : `${normalized}Z`;
  const ms = Date.parse(withZone);
  return Number.isFinite(ms) ? ms : null;
}

function formatNaiveUtcMs(ms, includeTime) {
  const iso = new Date(ms).toISOString();
  return includeTime ? iso.slice(0, 19).replace('T', ' ') : iso.slice(0, 10);
}

function splitDateRangeIntoWindows(range, maxDays) {
  const values = asArray(range);
  if (values.length !== 2) return [];
  const start = parseNaiveUtcMs(values[0]);
  const end = parseNaiveUtcMs(values[1]);
  if (start == null || end == null || end <= start) return [];
  const maxMs = maxDays * 86400000;
  if (end - start <= maxMs) return [];

  const includeTime = values.some(v => /[T ]\d{2}:\d{2}/.test(asString(v)));
  const windows = [];
  let cursor = start;
  while (cursor <= end && windows.length < 64) {
    const windowEnd = Math.min(end, cursor + maxMs - 1000);
    windows.push([
      formatNaiveUtcMs(cursor, includeTime),
      formatNaiveUtcMs(windowEnd, includeTime)
    ]);
    cursor = windowEnd + 1000;
  }
  return windows;
}


// PACK_LONG_ARCTIC_WINDOWS_V5
function packLongArcticAnalyzeRanges(list) {
  return asArray(list).map(raw => {
    const unit = cloneValue(raw);
    const params = asObject(unit.params);
    if (asString(unit.tool) !== 'arctic_analyze') return unit;

    const windows = splitDateRangeIntoWindows(params.date_range, 180);
    if (!windows.length || !asArray(params.targets).length) return unit;

    const packedTargets = [];
    windows.forEach((windowRange, windowIndex) => {
      asArray(params.targets).forEach((targetRaw, targetIndex) => {
        const target = { ...asObject(targetRaw) };
        const baseName = asString(target.name) || `target_${targetIndex + 1}`;
        packedTargets.push({
          ...target,
          name: `${baseName}_window_${windowIndex + 1}`,
          date_range: windowRange
        });
      });
    });

    const nextParams = {
      ...params,
      targets: packedTargets
    };
    delete nextParams.date_range;
    unit.params = nextParams;
    return unit;
  });
}

units = packLongArcticAnalyzeRanges(units);

// DIRECT_NO_RETRIEVAL_MEMORY_PAYLOAD_V5
// Some planners emit direct_response + no_retrieval as a guard, but without
// params.text or structured memory payload. In that case the executor cannot
// answer and falls back to NO_EVIDENCE. Convert only those under-specified
// direct units into a full conversation-state contract. This is structural:
// it does not inspect test ids, tags, thresholds, or domain-specific wording.
function hydrateDirectNoRetrievalMemoryPayload(list, state) {
  return asArray(list).map(raw => {
    const unit = asObject(raw);
    const params = asObject(unit.params);
    const isDirectNoRetrieval = asString(unit.tool) === 'direct_response' && params.no_retrieval === true;
    if (!isDirectNoRetrieval) return raw;

    const hasAnswerMaterial =
      asString(params.text) ||
      asArray(params.conversation_turns).length ||
      asArray(params.fact_cards).length ||
      asArray(params.matched_fact_cards).length ||
      asString(params.safe_response);
    if (hasAnswerMaterial) return raw;

    const hydrated = buildGenericSummaryContract(unit, state);
    hydrated.params.mode = 'conversation_summary';
    hydrated.params.no_retrieval = true;
    hydrated.params.summary_instruction =
      params.summary_instruction ||
      'Answer the current question from the saved conversation state. Preserve confirmed/candidate/unconfirmed distinctions. Prefer later successful evidence over earlier failed attempts for the same issue. Do not invent data or perform retrieval.';
    return hydrated;
  });
}



// SINGLE_PLAN_OWNERSHIP_V5
// Match Tools and Planner Agent own retrieval and analysis planning. This node
// may normalize their units, but must not replace a complete plan based on
// inferred entity counts or conversation history.
