// RESTORE_STRUCTURED_COMPUTE_ROUTE_V5
// A retrieval decision with a complete computation contract must execute that
// contract. Structured memory may supply targets and dates, but cannot replace
// the requested calculation with a direct answer.
function restoreStructuredComputeRoute(list, resolution) {
  const route = asString(resolution && resolution.route).toLowerCase();
  if (route !== 'retrieve') return list;

  return asArray(list).map(raw => {
    const unit = asObject(raw);
    const params = { ...asObject(unit.params) };
    const hasComputeContract =
      asArray(params.targets).length > 0 &&
      asArray(params.date_range).length >= 2 &&
      asArray(params.analysis_types).length > 0;
    if (asString(unit.tool) !== 'direct_response' || !hasComputeContract) return raw;

    for (const key of [
      'mode',
      'no_retrieval',
      'text',
      'memory_resolution',
      'matched_fact_cards',
      'conversation_turns',
      'question_memory_cards',
      'event_status',
      'safe_response',
      'summary_instruction',
      'sentence_count'
    ]) delete params[key];

    return {
      ...unit,
      tool: 'arctic_analyze',
      params,
      depends_on: asArray(unit.depends_on),
      question_part: unit.question_part || 'period_verification',
      required_evidence_types: uniqueStrings(
        asArray(unit.required_evidence_types).concat(['measured_data'])
      ),
      optional_evidence_types: uniqueStrings(
        asArray(unit.optional_evidence_types).concat(['computed_analysis'])
      ),
      allow_synthesis: true
    };
  });
}

units = restoreStructuredComputeRoute(units, memoryResolution);

// TARGET_SEMANTIC_PERSISTENCE_V5
function addAnalyzeTargetsToCatalogQueries(list) {
  const explicitTags = [];
  for (const raw of asArray(list)) {
    const unit = asObject(raw);
    if (asString(unit.tool) !== 'arctic_analyze') continue;
    for (const target of asArray(asObject(unit.params).targets)) {
      for (const tag of asArray(asObject(target).columns)) {
        const value = asString(tag);
        if (value && !/^\$ref:/i.test(value)) explicitTags.push(value);
      }
    }
  }
  const tags = uniqueStrings(explicitTags);
  if (!tags.length) return list;

  return asArray(list).map(raw => {
    const unit = asObject(raw);
    if (asString(unit.tool) !== 'arctic_find_tags') return raw;
    const params = asObject(unit.params);
    return {
      ...unit,
      params: {
        ...params,
        query: uniqueStrings([asString(params.query)].concat(tags)).join(' '),
        candidate_tags: uniqueStrings(asArray(params.candidate_tags).concat(tags)),
        semantic_enrichment_for_targets: tags
      }
    };
  });
}

units = addAnalyzeTargetsToCatalogQueries(units);

// OBSOLETE_MULTIFACTOR_NORMALIZER_REMOVED_V5
// Multi-factor presence reconciliation is authoritative only at the final splitter boundary.

// ARCTIC_DEPENDENCY_COLUMN_BUDGET_V5
function enforceArcticDependencyColumnBudget(list, maxColumns) {
  const source = asArray(list);
  const byId = new Map(source.map(u => [Number(u?.unit_id), u]));
  const caps = new Map();

  for (const raw of source) {
    const unit = asObject(raw);
    if (!['arctic_stats', 'arctic_read', 'arctic_analyze'].includes(asString(unit.tool))) continue;
    const parents = asArray(unit.depends_on)
      .map(Number)
      .map(id => byId.get(id))
      .filter(parent => asString(parent?.tool) === 'arctic_find_tags');
    if (!parents.length) continue;
    const requested = parents.reduce(
      (sum, parent) => sum + Math.max(1, Number(asObject(parent.params).top_k || 8)),
      0
    );
    if (requested <= maxColumns) continue;
    const perParent = Math.max(1, Math.floor(maxColumns / parents.length));
    for (const parent of parents) {
      const id = Number(parent.unit_id);
      caps.set(id, Math.min(caps.get(id) || Infinity, perParent));
    }
  }

  return source.map(raw => {
    const unit = asObject(raw);
    const cap = caps.get(Number(unit.unit_id));
    if (!Number.isFinite(cap)) return raw;
    const params = asObject(unit.params);
    return {
      ...unit,
      params: {
        ...params,
        top_k: Math.min(Math.max(1, Number(params.top_k || cap)), cap),
        ...(params.llm_max_tags != null
          ? { llm_max_tags: Math.min(Math.max(1, Number(params.llm_max_tags || cap)), cap) }
          : {}),
        column_budget: {
          max_total_columns: maxColumns,
          allocated_to_unit: cap,
          policy: 'dependency_graph_budget'
        }
      }
    };
  });
}

units = enforceArcticDependencyColumnBudget(units, 48);

// CONFIRMED_EVENT_CHARACTERIZATION_V5
// GENERIC_CONFIRMED_EVENT_FACT_V5
// Once memory resolves a confirmed anomaly, a follow-up asking for missing
// event metrics must characterize that event. Re-running anomaly discovery on
// a wider context window can select a different event and break continuity.
function preserveConfirmedEventForCharacterization(list, state, resolution) {
  const memory = matchedMemoryPayload(state, resolution);
  const anchors = asArray(memory.facts).filter(factValue => {
    const fact = asObject(factValue);
    const value = asString(fact.value).toLowerCase();
    const isEventFact =
      asString(fact.entity_type).toLowerCase() === 'event' ||
      ['event_identity', 'has_statistical_anomaly'].includes(
        asString(fact.relation).toLowerCase()
      );
    return (
      isEventFact &&
      asString(fact.status).toLowerCase() === 'confirmed' &&
      value &&
      value !== 'none'
    );
  });
  if (!anchors.length) return list;

  const anchorFact = anchors
    .slice()
    .sort((a, b) => {
      const at = Date.parse(asString(asObject(a).source_ts)) || 0;
      const bt = Date.parse(asString(asObject(b).source_ts)) || 0;
      return bt - at;
    })[0];
  const eventContract = {
    source_fact_id: asString(anchorFact.fact_id),
    subject: asString(anchorFact.subject),
    relation: asString(anchorFact.relation),
    value: cloneValue(anchorFact.value),
    entities: cloneValue(asArray(anchorFact.entities)),
    numbers: cloneValue(asArray(anchorFact.numbers)),
    note: asString(anchorFact.note),
    status: 'confirmed',
    rule:
      'Characterize this inherited event. Wider-window observations may provide baseline or recovery context but cannot replace the selected event.'
  };

  return asArray(list).map(raw => {
    const unit = asObject(raw);
    const params = asObject(unit.params);
    const types = asArray(params.analysis_types).map(asString).filter(Boolean);
    if (
      asString(unit.tool) !== 'arctic_analyze' ||
      !types.includes('anomaly_windows') ||
      !types.some(type => ['period_profile', 'baseline_comparison', 'data_quality'].includes(type))
    ) return raw;

    // ANCHORED_EVENT_CHARACTERIZATION_V5
    // Keep anomaly analysis inside the already anchored event window. Removing
    // it leaves only aggregate profile statistics and forces the finalizer to
    // guess event metrics from older text.
    return {
      ...unit,
      params: {
        ...params,
        analysis_types: uniqueStrings(types.concat(['anomaly_windows']))
      },
      required_evidence_types: uniqueStrings(
        asArray(unit.required_evidence_types).concat(['anomaly_windows'])
      ),
      anchored_event_contract: {
        ...eventContract,
        anchor_timestamp: asString(
          asObject(asObject(state).event_status).event_window?.anchor_timestamp
        ),
        rule:
          'Characterize only the inherited anchor timestamp. Other events may be context but cannot replace the selected event. If current evidence cannot compute an anchor-specific metric, report it as unavailable.'
      }
    };
  });
}

units = preserveConfirmedEventForCharacterization(
