// LITERAL_TAG_CATALOG_CHECK_V7
// MT25 T7（exec 143092）：计划只有一个 mongo_read，列名写死为前几轮文档里的 PDR3125，全计划没有目录查询；
// 历史库里的实际列是同一回路的 PDRA3125.PV / PDRA3125B.PV，读出全为 null，结论退化为「无法判定」。
// 写死位号必须先过目录：补一个目录查询置于最前，取数单元依赖它并记下待校验位号（校验与同回路改写在 Param Injector）。
(function () {
  const list = asArray(units);
  const isFind = u => /^(?:arctic|mongo)_find_tags$/.test(asString(asObject(u).tool));
  const TAGRE = /^[A-Z]{1,6}\d{2,6}[A-Z]?(?:\.[A-Z]{1,4})?$/;
  const literal = [];
  const consumers = [];
  let prefix = 'mongo';
  for (const u of list) {
    const m = /^(arctic|mongo)_(?:read|stats|analyze)$/.exec(asString(asObject(u).tool));
    if (!m) continue;
    const p = asObject(asObject(u).params);
    const cols = asArray(p.columns)
      .concat(asArray(p.targets).reduce((acc, t) => acc.concat(asArray(asObject(t).columns)), []));
    const lit = cols.map(x => asString(x).trim()).filter(x => TAGRE.test(x.toUpperCase()));
    if (!lit.length) continue;
    prefix = m[1];
    for (const t of lit) if (literal.indexOf(t) < 0) literal.push(t);
    consumers.push(u);
  }
  if (!consumers.length) return;
  // LITERAL_TAG_CHECK_WITH_EXISTING_LOOKUP_V7：计划里已有目录查询时（MT25 T10 exec 147561），不另补查询；
  // 用同库同集合的目录查询校验，加依赖，并把这些查询挪到第一个此类取数单元之前（执行顺序跟数组走）。
  const __finds = list.filter(isFind);
  if (__finds.length) {
    const __where = u => {
      const p = asObject(asObject(u).params);
      const t = asArray(p.targets).length ? asObject(asArray(p.targets)[0]) : {};
      return [asString(p.library || p.database || t.library || t.database), asString(p.symbol || p.collection || t.symbol || t.collection)].join('/');
    };
    const __moved = new Set();
    for (const u of consumers) {
      const same = __finds.filter(f => __where(f) === __where(u));
      const use = same.length ? same : __finds;
      const ids = use.map(f => Number(asObject(f).unit_id)).filter(Number.isFinite);
      u.params = Object.assign({}, asObject(u.params), { catalog_checked_tags: literal.slice(), catalog_check_unit_ids: ids });
      u.depends_on = Array.from(new Set(asArray(u.depends_on).map(Number).filter(Number.isFinite).concat(ids)));
      for (const f of use) __moved.add(f);
    }
    const firstIdx = Math.min.apply(null, consumers.map(c => list.indexOf(c)));
    const toMove = list.filter(u => __moved.has(u) && list.indexOf(u) > firstIdx);
    if (toMove.length) {
      const rest = list.filter(u => toMove.indexOf(u) < 0);
      const at = rest.indexOf(list[firstIdx]);
      units = rest.slice(0, at).concat(toMove, rest.slice(at));
    }
    return;
  }
  const subject = [
    asString(conversationState && conversationState.latest_topic),
    asString(originalQuestion)
  ].filter(Boolean).join(' ');
  const terms = uniqueStrings((subject.match(/[\u4e00-\u9fff]{2,6}/g) || [])).slice(0, 6);
  let nextId = 0;
  for (const u of list) { const n = Number(asObject(u).unit_id); if (Number.isFinite(n) && n > nextId) nextId = n; }
  const lookup = {
    unit_id: nextId + 1,
    tool: prefix + '_find_tags',
    params: Object.assign({
      query: literal.concat(terms).join(' '),
      top_k: 24,
      resolved_question: String(originalQuestion || ''),
      question_literal: String(originalQuestion || ''),
      forced_catalog_lookup: true,
      literal_tag_check: literal.slice(),
      empty_result_is_not_absence: true
    }, asObject(asObject(consumers[0]).params).database ? { database: asObject(asObject(consumers[0]).params).database } : {},
       asObject(asObject(consumers[0]).params).collection ? { collection: asObject(asObject(consumers[0]).params).collection } : {}),
    depends_on: [],
    question_part: 'structured_lookup',
    required_evidence_types: ['tag_identification'],
    optional_evidence_types: ['tag_descriptions'],
    allow_synthesis: true,
    retrieval_group: null,
    lang_variant: null
  };
  for (const u of consumers) {
    u.params = Object.assign({}, asObject(u.params), { catalog_checked_tags: literal.slice() });
    u.depends_on = Array.from(new Set(asArray(u.depends_on).map(Number).filter(Number.isFinite).concat([lookup.unit_id])));
  }
  units = [lookup].concat(list);
})();

