  if (/料位|藏量|床层/.test(src)) { push('料位'); push('藏量'); }
  if (/滑阀|阀位/.test(src)) push('滑阀');
  // 设备位号可能只有一个字母前缀（R1101 沉降器、V3403 罐），{2,6} 会漏掉，这里放宽到 {1,6}
