      return Object.assign({}, uo, {
        params: Object.assign({}, p, {
          // INITIAL_QUESTION_FIRST_TURN_ONLY_V7：公司点评——T5 应只针对 T1 总结（exec 153380 第三句混入 T2 报警值与 T3/T4 处置）。
          summary_scope: 'initial_question_first_turn',
          initial_user_question: __firstQ,
          conversation_turns: compactDirectSummaryTurns([__firstTurn], 1),
          all_turn_count: __allTurns.length,
          summary_instruction:
            '用户要求回到本次对话最初提出的问题「' + __firstQ + '」，概括它的核心要点。只概括第一轮对这个问题已给出的回答内容；'
            + '后续轮次追问的阈值、报警与联锁数值、处置步骤、位号等内容不属于最初的问题，不要写进概括。'
            + '严格遵守用户要求的句数或格式。只用第一轮已给出的内容，不得编造数值，不得进行检索。'
        })
      });
    });
  }
}

// PLAN_DEPENDENCY_SELFCHECK_V7
// 规划器产出的计划此前没有任何合法性校验。实测 exec 136361（T7）：
// unit 2 的 depends_on 指向它自己 [2]，自依赖在图上是死结，永远无法满足，
// 该单元与 F34 依它补出的 unit 4 双双 DEPENDENCY_BLOCKED，整轮没取到任何数据。
// 对比 exec 136362（T8）depends_on=[1] 正常，补出的单元跑通并返回 126721 条样本。
// 这里只按图结构与参数引用修正，不做任何语义判断；必须排在成对补齐之前，
// 否则补出来的单元会继承坏边。
const __planRepairs = [];
(function selfCheckPlan() {
  const list = asArray(units);
  if (!list.length) return;

  const known = new Set();
  for (const u of list) {
    const n = Number(asObject(u).unit_id);
    if (Number.isFinite(n)) known.add(n);
  }

  for (const u of list) {
    const uo = asObject(u);
    const self = Number(uo.unit_id);
    const deps = asArray(uo.depends_on);
    if (!deps.length) continue;

    const kept = [];
    for (const d of deps) {
      const n = Number(d);
      if (!Number.isFinite(n)) continue;
      if (n === self) {
        __planRepairs.push({ unit_id: self, removed: n, reason: 'self_dependency' });
        continue;
      }
      if (!known.has(n)) {
        __planRepairs.push({ unit_id: self, removed: n, reason: 'unknown_unit' });
        continue;
      }
      kept.push(n);
    }

    if (!kept.length) {
      // 参数里的 $ref:stepN 本身就说明它要等 N 的结果，据此补回依赖
      const blob = JSON.stringify(uo.params || {});
      const m = /\$ref:step(\d+)/.exec(blob);
      if (m) {
        const target = Number(m[1]);
        if (Number.isFinite(target) && target !== self && known.has(target)) {
          kept.push(target);
          __planRepairs.push({ unit_id: self, added: target, reason: 'ref_step_recovered' });
        }
      }
    }
    uo.depends_on = kept;
  }
})();

// ARCTIC_STATS_ANALYZE_PAIRING_V7
// 规划器对同一道题会在 arctic_stats 与 arctic_analyze 之间二选一，而两者是同一份
// 数据的两个视角：stats 给分布摘要（count/mean/min/max），analyze 带
// analysis_types:['anomaly_windows',...] 才产出带时间戳的事件点。
// 实测 T7：exec 136304 选了 analyze → 9 个带日期的异常点 → T8 锚定成功；
//        exec 136338 选了 stats  → 无任何时间点 → T8 只能报告无锚点。
// 问「有没有超标」要的是事件集合，分布摘要在原理上答不了，故按结构补齐另一半。
(function pairArcticViews() {
  const list = asArray(units);
  if (!list.length) return;

  function paramsOf(u) {
    const p = asObject(asObject(u).params);
    const t = asArray(p.targets)[0];
    const tgt = asObject(t);
    return {
      library: asString(p.library || tgt.library),
      symbol: asString(p.symbol || tgt.symbol),
      columns: p.columns != null ? p.columns : tgt.columns,
      name: asString(tgt.name)
    };
  }
  function keyOf(u) {
    const k = paramsOf(u);
    return [k.library, k.symbol, JSON.stringify(k.columns == null ? null : k.columns)].join('|');
  }

  const have = { arctic_stats: new Set(), arctic_analyze: new Set() };
  for (const u of list) {
    const tool = asString(asObject(u).tool);
    if (have[tool]) have[tool].add(keyOf(u));
  }

  let nextId = 0;
  for (const u of list) {
    const n = Number(asObject(u).unit_id);
    if (Number.isFinite(n) && n > nextId) nextId = n;
  }

  const added = [];
  for (const u of list) {
    const uo = asObject(u);
    const tool = asString(uo.tool);
    if (tool !== 'arctic_stats' && tool !== 'arctic_analyze') continue;
    const other = tool === 'arctic_stats' ? 'arctic_analyze' : 'arctic_stats';
    const k = keyOf(u);
    if (have[other].has(k)) continue;      // 另一半已在计划里
    const pr = paramsOf(u);
    if (!pr.library || !pr.symbol) continue;  // 参数不全就不补，避免造出跑不了的单元

    nextId += 1;
    have[other].add(k);
    const params = other === 'arctic_analyze'
      ? {
          targets: [{
            name: pr.name || asString(asObject(uo.params).question) || '目标位号',
            library: pr.library,
            symbol: pr.symbol,
            columns: pr.columns
          }],
          analysis_types: ['anomaly_windows', 'data_quality']
        }
      : { library: pr.library, symbol: pr.symbol, columns: pr.columns };

    // LITERAL_TAG_CHECK_WITH_EXISTING_LOOKUP_V7：补出的单元沿用源单元的目录校验字段
    for (const __k of ['catalog_checked_tags', 'catalog_check_unit_ids', 'catalog_probe_unit_ids']) {
      if (asObject(uo.params)[__k] !== undefined) params[__k] = asObject(uo.params)[__k];
    }
    added.push({
      unit_id: nextId,
      tool: other,
      params: params,
      depends_on: asArray(uo.depends_on).slice(),
      question_part: uo.question_part,
      required_evidence_types: asArray(uo.required_evidence_types).slice(),
      optional_evidence_types: asArray(uo.optional_evidence_types).slice(),
      allow_synthesis: uo.allow_synthesis,
      paired_from_unit_id: uo.unit_id
    });
  }

  if (added.length) units = list.concat(added);
})();

// TAG_LOOKUP_DOCUMENT_COMPLEMENT_V7
// 计划里只有 arctic_find_tags、既无文档检索也无数据读取时，补一个 ragflow_retrieval。
// 控制回路位号（如 PRCA3101/PRCA3102）是 DCS 组态位号，不在历史库目录里，
// 只查目录永远查不到。实测 exec 138893：两个目录查询、0 次文档检索，
// 该位号全链路 0 次；对照 exec 136202 答出该位号，来源是规程文档经设备上下文摘出，
// 目录查询同样 0 次。触发只看工具构成，问句取规划器自己给目录查询写的 query，
// dataset_ids 与检索设置由下游 Unit ordered Splitter 按目录补齐。
(function complementTagLookupWithDocuments() {
  const list = asArray(units);
  if (!list.length) return;
  const tools = list.map(u => asString(asObject(u).tool));
  const DATA_TOOLS = ['arctic_stats', 'arctic_read', 'arctic_analyze'];
  const hasTagLookup = tools.indexOf('arctic_find_tags') >= 0;
  const hasDocRetrieval = tools.indexOf('ragflow_retrieval') >= 0;
  const hasDataTool = tools.some(t => DATA_TOOLS.indexOf(t) >= 0);
  if (!hasTagLookup || hasDocRetrieval || hasDataTool) return;

  const lookups = list.filter(u => asString(asObject(u).tool) === 'arctic_find_tags');
  // 取主题最完整的那条 query：按长度选规划器写得最充分的一条，去掉重复空白
  let seed = '';
  for (const u of lookups) {
    const p = asObject(asObject(u).params);
    const q = asString(p.query || p.resolved_question || '').replace(/\s+/g, ' ').trim();
    if (q.length > seed.length) seed = q;
  }
  const literal = asString(item.originalUserMessage || '');
  if (!seed) seed = literal;
  if (!seed) return;

  let nextId = 0;
  for (const u of list) {
    const n = Number(asObject(u).unit_id);
    if (Number.isFinite(n) && n > nextId) nextId = n;
  }
  const req = [];
  for (const u of lookups) {
    for (const t of asArray(asObject(u).required_evidence_types)) {
      const v = asString(t);
      if (v && req.indexOf(v) < 0) req.push(v);
    }
  }
  units = list.concat([{
    unit_id: nextId + 1,
    tool: 'ragflow_retrieval',
    params: {
      question: seed.slice(0, 400),
      question_literal: literal,
      resolved_question: seed.slice(0, 400)
    },
    depends_on: [],
    question_part: asString(asObject(lookups[0]).question_part) || 'structured_lookup',
    required_evidence_types: req,
    optional_evidence_types: [],
    allow_synthesis: true,
    paired_from_unit_id: asObject(lookups[0]).unit_id,
    pairing_reason: 'tag_lookup_document_complement'
  }]);
})();

// HISTORY_BOUNDARY_UNITS_V7 已由 F66 撤下：边界读数改由 Param Injector 直接经 MCP 读取（HISTORY_BOUNDARY_DIRECT_READ_V7）。

// TAG_DOCUMENT_RETRIEVAL_V7
// 单题 exec 143004：阈值检索单元是否依赖目录查询由规划器决定，这次没有依赖，按位号检索不触发，报警位号表没召回；
// 设备上下文为 null 时身份补查也挑错位号。位号解析后用位号本身检索（报警设定、装置文档里的叫法）不应取决于这些。
// 计划里有目录查询就追加一个检索单元，依赖全部目录查询，查询词由 Param Injector 按已解析位号填入。
(function () {
  const list = asArray(units);
  const isFind = u => /^(?:arctic|mongo)_find_tags$/.test(asString(asObject(u).tool));
  const finds = list.filter(isFind);
  if (!finds.length) return;
  if (list.some(u => asObject(asObject(u).params).tag_document_lookup === true)) return;
  const findIds = finds.map(u => Number(asObject(u).unit_id)).filter(Number.isFinite);
  const datasetIds = [];
  for (const u of list) {
    if (asString(asObject(u).tool) !== 'ragflow_retrieval') continue;
    for (const id of asArray(asObject(asObject(u).params).dataset_ids)) {
      if (id && datasetIds.indexOf(id) < 0) datasetIds.push(id);
    }
  }
  let nextId = 0;
  for (const u of list) { const n = Number(asObject(u).unit_id); if (Number.isFinite(n) && n > nextId) nextId = n; }
  const unit = {
    unit_id: nextId + 1,
    tool: 'ragflow_retrieval',
    params: Object.assign({
      question: String(originalQuestion || ''),
      question_literal: String(originalQuestion || ''),
      resolved_question: String(originalQuestion || ''),
      tag_document_lookup: true,
      catalog_probe_unit_ids: findIds.slice(),
      page_size: 20,
      top_k: 128,
      keyword: true
    }, datasetIds.length ? { dataset_ids: datasetIds } : {}),
    depends_on: findIds.slice(),
    question_part: 'structured_lookup',
    required_evidence_types: ['tag_identification'],
    optional_evidence_types: ['tag_descriptions'],
    allow_synthesis: true,
    retrieval_group: null,
    lang_variant: null
  };
  const lastFind = Math.max.apply(null, finds.map(u => list.indexOf(u)));
  units = list.slice(0, lastFind + 1).concat([unit], list.slice(lastFind + 1));
})();

// CATALOG_PROBES_JOIN_DATA_CHAIN_V7
// 单题 exec 142990：规划器的目录查询（单元 3）零命中，上面补的备份查询（单元 9，description_side）直接匹配
// PDRA3125.PV / PDRA3125B.PV；但取数单元只依赖单元 3、且执行顺序跟数组走，先于备份查询执行，被改成「未执行全库时序分析」。
// 备份查询本就是「单条目录查询零命中后整条取数链断掉」的兜底，这里把它接进取数链：
// 引用 $ref:stepN.tags 的取数单元依赖加上所有 forced_catalog_lookup 查询，并声明 catalog_probe_unit_ids；
// 这些查询在数组里挪到第一个取数单元之前。
(function () {
  const list = asArray(units);
  const isFind = u => /^(?:arctic|mongo)_find_tags$/.test(asString(asObject(u).tool));
  const probes = list.filter(u => isFind(u) && asObject(asObject(u).params).forced_catalog_lookup === true);
  if (!probes.length) return;
  const probeIds = probes.map(u => Number(asObject(u).unit_id)).filter(Number.isFinite);
  const findIds = new Set(list.filter(isFind).map(u => Number(asObject(u).unit_id)));
  const consumers = [];
  for (const u of list) {
    if (!/^(?:arctic|mongo)_(?:stats|read|analyze)$/.test(asString(asObject(u).tool))) continue;
    const refs = Array.from(JSON.stringify(asObject(u).params || {}).matchAll(/\$ref:(?:step_?)?(\d+)\.(?:tags|probe_tags)\b/g))
      .map(m => Number(m[1]))
      .filter(id => findIds.has(id) && probeIds.indexOf(id) < 0);
    // LITERAL_TAG_CATALOG_CHECK_V7：写死位号的取数单元同样接入备份目录查询
    if (!refs.length && !asArray(asObject(asObject(u).params).catalog_checked_tags).length) continue;
    u.params = Object.assign({}, asObject(u.params), { catalog_probe_unit_ids: probeIds.slice() });
    u.depends_on = Array.from(new Set(asArray(u.depends_on).map(Number).filter(Number.isFinite).concat(probeIds)));
    consumers.push(u);
  }
  if (!consumers.length) return;
  // LITERAL_TAG_CATALOG_CHECK_V7：落点取「首个取数单元」与「首个依赖备份查询的单元」中更靠前者
  const __dependents = list.filter(u => asArray(asObject(u).depends_on)
    .map(Number).some(id => probeIds.indexOf(id) >= 0));
  const firstIdx = Math.min.apply(null, consumers.concat(__dependents).map(c => list.indexOf(c)));
  const anchor = list[firstIdx];
  const rest = list.filter(u => probes.indexOf(u) < 0);
  const at = rest.indexOf(anchor);
  units = rest.slice(0, at).concat(probes, rest.slice(at));
})();

return [
  {
    json: {
      ...item,
      units,
      plan_repairs: __planRepairs,
      // F26：一个记忆单元不该把整轮翻成总结轮。
      // 实测 exec 135268（Q7）：规划器判 retrieve、证据包 12 条，
      // 却因为存在一个 direct_response 记忆单元而被标成 conversation_summary，
      // finalizer 按总结轮写作，12 条出处全部作废、0 个 [E#]。
      // 只有在完全没有检索类单元时，本轮才真的是总结轮。
      answer_mode: (function () {
        const RETRIEVAL = ['ragflow_retrieval', 'arctic_find_tags', 'arctic_stats',
                           'arctic_read', 'arctic_analyze', 'arctic_describe',
                           'arctic_resolve_factors', 'neo4j_query'];
        const hasRetrieval = asArray(units).some(u => RETRIEVAL.indexOf(asString(asObject(u).tool)) >= 0);
        const hasMemory = asArray(units).some(u =>
          asString(asObject(u).tool) === 'direct_response' &&
          asString(asObject(asObject(u).params).mode) === 'conversation_summary');
        return (hasMemory && !hasRetrieval) ? 'conversation_summary' : item.answer_mode;
      })(),
      llm_resolution_self_check: __llmResolutionSelfCheck // LLM_RESOLUTION_ADVISORY_V7
    }
  }
];

function asArray(x) {
  return Array.isArray(x) ? x : [];
}

function asObject(x) {
  return x && typeof x === 'object' && !Array.isArray(x) ? x : {};
}

function asString(x) {
  return typeof x === 'string' ? x.trim() : '';
}

// MONGODB_EVIDENCE_PACKET_BOUNDARY_V1
// Keep the established packet-building logic stable internally while
// enforcing MongoDB naming for all external inputs and emitted evidence.
const MONGO_TO_INTERNAL_TOOL = Object.freeze({
  mongo_find_tags: 'arctic_find_tags',
  mongo_resolve_factors: 'arctic_resolve_factors',
  mongo_read: 'arctic_read',
  mongo_stats: 'arctic_stats',
  mongo_analyze: 'arctic_analyze',
  mongo_describe: 'arctic_describe'
});
const INTERNAL_TO_MONGO_TOOL = Object.freeze(
  Object.fromEntries(Object.entries(MONGO_TO_INTERNAL_TOOL).map(([mongo, internal]) => [internal, mongo]))
);

function replacePacketVocabulary(value, direction) {
  let out = String(value == null ? '' : value);
  const replacements = direction === 'internal'
    ? { ...MONGO_TO_INTERNAL_TOOL, MongoDB: 'ArcticDB', mongodb_: 'arctic_', mongodb: 'arcticdb' }
    : { ...INTERNAL_TO_MONGO_TOOL, ArcticDB: 'MongoDB', arctic_: 'mongodb_', arcticdb: 'mongodb' };
  for (const [from, to] of Object.entries(replacements)) {
    out = out.replace(new RegExp(`\\b${from}`, 'g'), to);
  }
  return out;
}

function packetContractKey(key, direction) {
  if (direction === 'internal') {
    if (MONGO_TO_INTERNAL_TOOL[key]) return MONGO_TO_INTERNAL_TOOL[key];
    if (key.startsWith('mongo_analyze_')) return key.replace(/^mongo_analyze_/, 'arctic_analyze_');
    if (key === 'mongodb_target_registry') return 'arctic_target_registry';
    if (key === 'mongodb') return 'arctic';
    return key;
  }
  if (INTERNAL_TO_MONGO_TOOL[key]) return INTERNAL_TO_MONGO_TOOL[key];
  if (key.startsWith('arctic_analyze_')) return key.replace(/^arctic_analyze_/, 'mongo_analyze_');
  if (key === 'arctic_target_registry') return 'mongodb_target_registry';
  if (key === 'arctic') return 'mongodb';
  return key;
}

function translatePacketContract(value, direction) {
  if (Array.isArray(value)) return value.map(v => translatePacketContract(v, direction));
  if (typeof value === 'string') return replacePacketVocabulary(value, direction);
  if (!value || typeof value !== 'object') return value;

  const out = {};
  for (const [key, child] of Object.entries(value)) {
    out[packetContractKey(key, direction)] = translatePacketContract(child, direction);
  }

  const toInternal = direction === 'internal';
  const historianObject = toInternal
    ? (String(out.tool || '').startsWith('arctic_') ||
      (Object.prototype.hasOwnProperty.call(out, 'database') && Object.prototype.hasOwnProperty.call(out, 'collection')))
    : (String(out.tool || '').startsWith('mongo_') ||
      (Object.prototype.hasOwnProperty.call(out, 'library') && Object.prototype.hasOwnProperty.call(out, 'symbol')));

  if (historianObject && toInternal) {
    if (out.library == null && out.database != null) out.library = out.database;
    if (out.symbol == null && out.collection != null) out.symbol = out.collection;
    delete out.database;
    delete out.collection;
  } else if (historianObject) {
    if (out.database == null && out.library != null) out.database = out.library;
    if (out.collection == null && out.symbol != null) out.collection = out.symbol;
    delete out.library;
    delete out.symbol;
  }
  return out;
}

function toInternalPacketContract(value) {
  return translatePacketContract(value, 'internal');
}

function toPublicMongoPacketContract(value) {
  return translatePacketContract(value, 'public');
}

function normalizeId(x, fallback) {
  const s = asString(x).replace(/[\[\]]/g, '').toUpperCase();
  if (/^E\d+$/.test(s)) return s;
  return fallback;
}

function compact(x, maxLen = 1600) {
  const s = String(x || '').replace(/\s+/g, ' ').trim();
  return s.length <= maxLen ? s : s.slice(0, maxLen) + '...';
}

const item = toInternalPacketContract($input.first().json || {});
const payload = asObject(item.aggregated_payload);

const completedUnits = asArray(
  item.completed_units ||
  payload.completed_units ||
  item.units ||
  []
);

// EVIDENCE_RECALL_V1：Evidence Recall LLM 点回的条目（按单元序号 + 字段 + 序号定位，与 Build Evidence Index 的编号一致），
// 在下方追加席位；收集时不受单元上限限制，主体过滤不剔除。
const __recallObjs = new Map();
let __recallInPacket = 0, __recallExtraSeats = 0;
for (const __p of asArray(asObject(item.evidence_recall).picks)) {
  const __s = asString(asObject(__p).loc).split(':');
  let __d = null;
  if (__s[0] === 'u') {
    const __u = asObject(completedUnits[Number(__s[1])]);
    const __arr = __s[2] === 'n' ? asArray(asObject(__u.normalized_result).evidence_digest) : asArray(__u.evidence_digest);
    __d = __arr[Number(__s[3])];
  } else if (__s[0] === 'i') __d = asArray(item.evidence_digest)[Number(__s[2])];
  else if (__s[0] === 'p') __d = asArray(payload.evidence_digest)[Number(__s[2])];
  if (__d && typeof __d === 'object') __recallObjs.set(__d, asString(asObject(__p).need) || 'recalled');
}

// MISSING_CLAIM_CHECK_V1：缺失核对查到、但不在上一稿证据包里的条目，修改轮按条目（正文前 400 字，与 Build Evidence Index 同一认法）追加入包，
// 用证据取回的追加席（≤8 席，共用）。首稿之前 Apply Missing Claim Check 还没运行，取不到就跳过。
try {
  const __mcR = asArray(asObject(asObject($('Apply Missing Claim Check').last().json).missing_claim_check).recall).map(asObject);
  if (__mcR.length) {
    const __want = new Map(__mcR.map(r => [String(r.key || ''), String(r.need || 'missing_claim')]).filter(x => x[0]));
    const __cl = t => String(t || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    const __visit = d => { const o = asObject(d); const k = __cl(o.content_summary || o.snippet || o.summary).slice(0, 400); if (k && __want.has(k) && !__recallObjs.has(d)) __recallObjs.set(d, __want.get(k)); };
    for (const __u of completedUnits) { asArray(asObject(__u).evidence_digest).forEach(__visit); asArray(asObject(asObject(__u).normalized_result).evidence_digest).forEach(__visit); }
    asArray(item.evidence_digest).forEach(__visit); asArray(payload.evidence_digest).forEach(__visit);
  }
} catch (e) {}

// F35：原为 12，是个没有出处的魔数；下游 Compact Result Projector 写的是
