    '一下', '这个', '那个', '我们', '你们', '进行', '出现', '存在', '以及', '还有',
    '或者', '但是', '因为', '所以', '如果', '然后', '目前', '当前', '相关', '有关',
    '给出', '提供', '说明', '解释', '分析', '看看', '帮我', '告诉', '之后', '之前',
