    .replace(/\b([A-Za-z0-9_]+\d[A-Za-z0-9_]*)\.\s*\n+\s*(PV|OP|SP)\b/g, '$1.$2')
    .replace(/\b([A-Za-z0-9_]+\d[A-Za-z0-9_]*)\.\s+((?:PV|OP|SP)\b)/g, '$1.$2')
    .replace(/\b([A-Z][A-Z0-9_]*\d[A-Z0-9_]*)\.\s+([A-Z]{1,4})\b/g, '$1.$2')
    .replace(/\b([A-Z][A-Z0-9_]*\d[A-Z0-9_]*)\.\s*\n+\s*([A-Z]{1,4})\b/g, '$1.$2')
    .trim();
}


// DIRECT_EVENT_PASSTHROUGH_V453
// Direct-response units with no_retrieval and params.text are already bounded
// answers. They should not be rewritten by the finalizer or replaced by a
// generic memory-summary fallback.
function directNoRetrievalText() {
  const sources = [];
  try { sources.push(...asArray($('Normalize Execution Units').first().json.units)); } catch (e) {}
  try { sources.push(...asArray($('Unit ordered Splitter').all().map(x => x.json?.unit).filter(Boolean))); } catch (e) {}
  for (const unit of sources) {
    const params = asObject(unit && unit.params);
    if (unit && unit.tool === 'direct_response' && params.no_retrieval === true && asString(params.text)) {
      return asString(params.text);
    }
  }
  return '';
}

function bestAnswerText(finalizer, aggregator, rawOutput) {
  // Persist the exact answer body shown to the user; memory metadata is stored separately.
  if (asString(rawOutput)) return asString(rawOutput);
  const directText = directNoRetrievalText();
  if (directText) return directText;
  const aggPayload = asObject(aggregator.aggregated_payload);
  // DIRECT_AGGREGATOR_ANSWER_PRESERVE_PATCH: direct/conversation-state guard answers are already final and
  // should not be overwritten by a generic finalizer fallback.
  const sourceStatus = asObject(aggPayload.source_status);
  const conversationUsed = String(sourceStatus.conversation_state || '').toLowerCase() === 'used';
  const directUsed = String(sourceStatus.direct_response || '').toLowerCase() === 'used';
  const aggAnswer = asString(aggregator.answer || aggPayload.draft_answer);
  if ((conversationUsed || directUsed) && aggAnswer) return aggAnswer;
  return asString(
    finalizer.answer ||
    aggAnswer ||
    rawOutput
  );
}

