function isBadMemoryAnswer(text, mode) {
  const s = String(text || '').trim();

  if (!s) return true;
  if (/^NO_EVIDENCE$/i.test(s)) return true;
  if (/^NO_ANSWER$/i.test(s)) return true;
  if (/^NO_CONVERSATION_HISTORY$/i.test(s)) return true;
  if (/No answer found in the knowledge base/i.test(s)) return true;
  if (/There are no previous assistant answers saved/i.test(s)) return true;
  if (/intent classifier/i.test(s)) return true;
  if (/previous chat history holder/i.test(s)) return true;
  if (/what you'd like me to summarize/i.test(s)) return true;
  if (/Ask me a knowledge-base question/i.test(s)) return true;
  if (/^Hi! Ask me/i.test(s)) return true;
  if (/^You're welcome\.?$/i.test(s)) return true;
  if (/^Goodbye\.?$/i.test(s)) return true;

  const decode = (x) => x.replace(/\\u([0-9a-fA-F]{4})/g, (_, h) => String.fromCharCode(parseInt(h, 16)));
  const badChineseSnippets = [
    '\\u5f53\\u524d\\u4f1a\\u8bdd\\u72b6\\u6001\\u91cc\\u6ca1\\u6709\\u4fdd\\u5b58\\u5230\\u524d\\u51e0\\u8f6e\\u56de\\u7b54',
    '\\u5f53\\u524d\\u4f1a\\u8bdd\\u72b6\\u6001\\u4e2d\\u6ca1\\u6709\\u4fdd\\u5b58\\u4e4b\\u524d\\u7684\\u56de\\u7b54\\u8bb0\\u5f55',
    '\\u65e0\\u6cd5\\u57fa\\u4e8e\\u4e4b\\u524d\\u7684\\u56de\\u7b54\\u505a\\u603b\\u7ed3',
    '\\u6ca1\\u6709\\u68c0\\u7d22\\u5230',
    '\\u672a\\u80fd\\u68c0\\u7d22\\u5230'
  ].map(decode);

  if (badChineseSnippets.some(x => x && s.includes(x))) return true;

  const m = String(mode || '').trim().toLowerCase();
  if (m === 'no_conversation_history') return true;

  return false;
}

