    equipment: [],
    corrections: []
  };
}

function normalizeFactIndex(raw) {
  const base = defaultFactIndex();
  const obj = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
  return {
    tags: asArray(obj.tags).slice(-80),
    numbers: asArray(obj.numbers).slice(-80),
