function getRecentTurnLimit() {
  const wf = nodeJson('Workflow Configuration');
  const rp = safeParse(wf.run_params) || {};
  const n = Number(rp?.memory?.recent_turn_limit || 16);
  return Number.isFinite(n) && n >= 4 ? Math.min(n, 40) : 16;
}

function pushUniqueFact(list, fact, keyFields) {
  const arr = Array.isArray(list) ? list.slice() : [];
  const key = keyFields.map(k => String(fact[k] || '').toUpperCase()).join('|');
  if (!key.replace(/\|/g, '')) return arr;
  const exists = arr.some(x => keyFields.map(k => String(x[k] || '').toUpperCase()).join('|') === key);
  if (!exists) arr.push(fact);
  return arr.slice(-80);
}


function mergeFactIndex(previous, added) {
  const out = normalizeFactIndex(previous);
  const next = normalizeFactIndex(added);
  for (const f of next.tags) out.tags = pushUniqueFact(out.tags, f, ['normalized']);
  for (const f of next.numbers) out.numbers = pushUniqueFact(out.numbers, f, ['value']);
  for (const f of next.timestamps) out.timestamps = pushUniqueFact(out.timestamps, f, ['value']);
  for (const f of next.events) out.events = pushUniqueFact(out.events, f, ['summary']);
  for (const f of next.equipment) out.equipment = pushUniqueFact(out.equipment, f, ['value']);
  for (const f of next.corrections) out.corrections = pushUniqueFact(out.corrections, f, ['from', 'to']);
  return normalizeFactIndex(out);
}


