function normalizeQuestionMemoryCards(raw) {
  return asArray(raw).filter(x => x && typeof x === 'object' && !Array.isArray(x)).slice(-120);
}

function tokenizeForQuestionMemory() {
  const text = Array.from(arguments).map(v => {
    if (typeof v === 'string') return v;
    if (v && typeof v === 'object') return JSON.stringify(v);
    return '';
  }).join(' ');
  const out = [];
  const push = (v) => {
    const s = String(v || '').trim();
    if (!s) return;
    const k = s.toLowerCase();
    if (k.length < 2 || /^(the|and|for|with|from|this|that|是否|这个|那个|前面|当前|可以|不能|无法)$/.test(k)) return;
    out.push(s);
  };
  (text.match(/\b[A-Z]{1,8}[A-Z0-9_]*\d{2,6}[A-Z0-9_]*(?:\.[A-Z0-9_]+)?\b/g) || []).forEach(push);
  (text.match(/[一-龥]{2,12}(?:压差|差压|压力|异常|位号|测点|阀位|开度|回路|控制|归因|峰值|超限|超标|数据|趋势|规程|整改|事件)/g) || []).forEach(push);
  (text.match(/\b(?:differential pressure|pressure|anomaly|event|tag|control|loop|valve|setpoint|output|mode|trend|peak|limit|procedure|causal|correlation|lag)\b/ig) || []).forEach(push);
  return Array.from(new Set(out.map(String))).slice(0, 40);
}

function compactQuestionMemoryText(text, limit) {
  const s = String(text || '').replace(/\r/g, ' ').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
  const n = Number(limit || 500);
  return s.length > n ? s.slice(0, n).trim() + '...' : s;
}

function currentFactCardsForTurn(cards, turn) {
  return asArray(cards).filter(c => String(c.source_turn || '') === String(turn.turn_ref || ''));
}

function inferQuestionMemoryStatus(turn, eventStatus, cards) {
  const event = asObject(eventStatus);
  const eventStatusText = asString(event.status);
  if (eventStatusText) return eventStatusText;
  const statuses = asArray(cards).map(c => asString(c.status)).filter(Boolean);
  if (statuses.includes('contradicted')) return 'contradicted';
  if (statuses.includes('unconfirmed')) return 'unconfirmed';
  if (statuses.includes('candidate')) return 'candidate';
  if (statuses.includes('confirmed')) return 'confirmed';
  const text = [turn.user_question, turn.resolved_question, turn.assistant_answer].join('\n');
  if (/尚未确认|未确认|无法(?:确认|判断|判定)|不能(?:确认|判断|判定)|cannot\s+(?:confirm|determine)|not\s+confirmed/i.test(text)) return 'unconfirmed';
  return 'informational';
}

function relationTypeForQuestionMemory(current, previous, overlap) {
  const c = [current.current_question, current.current_answer_summary, current.status].join(' ');
  const p = [previous.current_question, previous.current_answer_summary, previous.status].join(' ');
  if (/未确认|unconfirmed|事件|event/i.test(c) && /未确认|unconfirmed|事件|event/i.test(p)) return 'depends_on_event_status';
  if (/数据|趋势|异常窗口|z=|zscore|ArcticDB|historical|analysis|correlation|lag/i.test(p)) return 'uses_data_analysis_from';
  if (/非|不是|排除|rejected|not .*tag|not .*differential/i.test(p)) return 'uses_rejected_or_boundary_fact';
  if (/规程|操作|整改|procedure|mitigation|action/i.test(p)) return 'uses_procedure_context';
  if (overlap >= 3) return 'same_topic_context';
  return 'related_context';
}

function buildRelatedQuestionEdges(currentCard, previousCards) {
  const currentTokens = new Set(asArray(currentCard.entities).map(x => String(x).toLowerCase()));
  const edges = [];
  for (const prev of normalizeQuestionMemoryCards(previousCards).slice(-80)) {
    const q = asString(prev.current_question);
    if (!q || q === currentCard.current_question) continue;
    const prevTokens = new Set(asArray(prev.entities).map(x => String(x).toLowerCase()));
    let overlap = 0;
    for (const t of currentTokens) if (prevTokens.has(t)) overlap += 1;
    const statusBonus = asString(prev.status) && asString(prev.status) === asString(currentCard.status) ? 0.08 : 0;
    const recencyBonus = 0.05;
    const relevance = Math.min(0.99, Math.round((0.25 + overlap * 0.13 + statusBonus + recencyBonus) * 100) / 100);
    if (overlap === 0 && relevance < 0.38) continue;
    edges.push({
      question: q,
      relation: relationTypeForQuestionMemory(currentCard, prev, overlap),
      relevance,
      use: compactQuestionMemoryText(`与当前问题共享 ${overlap} 个实体/主题线索；历史问题状态为 ${asString(prev.status) || 'unknown'}。`, 220),
      internal: {
        turn_ref: prev.internal?.turn_ref || prev.turn_ref || null
      }
    });
  }
  return edges.sort((a, b) => b.relevance - a.relevance).slice(0, 8);
}



// MEMORY_SUMMARY_DATA_SCOPE_V5
function walkObjectsForDataScope(value, visit, seen) {
  if (!value || typeof value !== 'object') return;
  const visited = seen || new Set();
  if (visited.has(value)) return;
  visited.add(value);
  visit(value);
  if (Array.isArray(value)) {
    for (const child of value) walkObjectsForDataScope(child, visit, visited);
  } else {
    for (const child of Object.values(value)) walkObjectsForDataScope(child, visit, visited);
  }
}

function deriveDataScope(aggregator) {
  // FULL_SYMBOL_EXISTENCE_SCOPE_V5
  let hasProbe = false;
  let hasFullSymbolExistenceProbe = false;
  let hasFullRange = false;
  let hasBoundedRange = false;
  const windows = [];
  walkObjectsForDataScope(aggregator, obj => {
    if (obj.presence_probe === true) hasProbe = true;
    if (obj.full_available_range === true || /full_available_range/i.test(asString(obj.verification_intent))) {
      hasFullRange = true;
    }
    const range = asArray(obj.date_range);
    const filters = asArray(obj.filters);
    const hasNonNullFilter = filters.some(filter => {
      const f = asObject(filter);
      return asString(f.col) && /^(?:!=|not_null|is_not_null)$/i.test(asString(f.op)) && (f.val === null || f.val === undefined);
    });
    if (hasNonNullFilter && range.length !== 2) hasFullSymbolExistenceProbe = true;
    if (range.length === 2) {
      hasBoundedRange = true;
      windows.push(range.slice(0, 2).map(String));
    }
  });
  if (hasFullRange) {
    return {
      kind: 'full_available_range_analysis',
      global_conclusion_allowed: true,
      windows: windows.slice(0, 6),
      limitation: ''
    };
  }
  if (hasFullSymbolExistenceProbe) {
    return {
      kind: 'full_symbol_non_null_existence_probe',
      existence_conclusion_allowed: true,
      coverage_conclusion_allowed: false,
      global_conclusion_allowed: false,
      windows: [],
      limitation: 'A returned non-null row proves that valid data exists somewhere in the full symbol; the sample timestamps are not a query window and do not prove continuous full-period coverage.'
    };
  }
  if (hasBoundedRange) {
    return {
      kind: 'bounded_range_analysis',
      existence_conclusion_allowed: true,
      coverage_conclusion_allowed: false,
      global_conclusion_allowed: false,
      windows: windows.slice(0, 6),
      limitation: 'This result applies only to the explicitly analyzed date range.'
    };
  }
  if (hasProbe) {
    return {
      kind: 'short_window_presence_probe',
      existence_conclusion_allowed: false,
      coverage_conclusion_allowed: false,
      global_conclusion_allowed: false,
      windows: windows.slice(0, 6),
      limitation: 'This result only describes an explicitly bounded probe window/sample.'
    };
  }
  return {
    kind: 'not_applicable_or_unspecified',
    global_conclusion_allowed: false,
    windows: [],
    limitation: ''
  };
}

function entityOverlapForScope(a, b) {
  const left = new Set(asArray(a && a.entities).map(x => String(x).toLowerCase()));
  let overlap = 0;
  for (const value of asArray(b && b.entities)) if (left.has(String(value).toLowerCase())) overlap += 1;
  return overlap;
}

function applyDataScopeSupersession(previousCards, addedCard) {
  const cards = normalizeQuestionMemoryCards(previousCards).map(card => ({ ...card }));
  if (!addedCard || asString(asObject(addedCard.data_scope).kind) !== 'full_available_range_analysis') return cards;
  for (const card of cards) {
    if (asString(asObject(card.data_scope).kind) !== 'short_window_presence_probe') continue;
    if (entityOverlapForScope(card, addedCard) < 1) continue;
    card.superseded_by_question = addedCard.current_question;
    card.superseded_reason = 'A later full-available-range analysis for overlapping entities supersedes the earlier short-window presence probe.';
  }
  return cards;
}

function buildQuestionMemoryCard(turn, memoryUpdate, mergedCards, previousState, eventStatus, aggregator) {
  const currentCards = currentFactCardsForTurn(mergedCards, turn);
  const explicitEntities = asArray(memoryUpdate.entities)
    .concat(currentCards.flatMap(c => asArray(c.entities)))
    .concat(tokenizeForQuestionMemory(turn.user_question, turn.resolved_question, turn.assistant_answer));
  const entities = Array.from(new Set(explicitEntities.map(String).map(x => x.trim()).filter(Boolean))).slice(0, 40);
  const status = inferQuestionMemoryStatus(turn, eventStatus, currentCards);
  const missing = asArray(asObject(eventStatus).missing_requirements)
    .concat(asArray(memoryUpdate.missing_requirements))
    .map(String).filter(Boolean).slice(0, 16);
  const dataFacts = currentCards
    .filter(c => /historical|measured|period|data|analysis|统计|异常|窗口/i.test([c.relation, c.entity_type, c.note].join(' ')))
    .map(c => compactQuestionMemoryText(c.note || c.value || c.subject, 260))
    .filter(Boolean)
    .slice(0, 10);
  const card = {
    current_question: turn.user_question || turn.resolved_question || '',
    resolved_question: turn.resolved_question || '',
    current_answer_summary: compactQuestionMemoryText(turn.assistant_answer, 700),
    status,
    entities,
    confirmed_facts: currentCards.filter(c => c.status === 'confirmed').map(c => compactQuestionMemoryText(c.note || c.value || c.subject, 220)).filter(Boolean).slice(0, 12),
    candidate_facts: currentCards.filter(c => c.status === 'candidate').map(c => compactQuestionMemoryText(c.note || c.value || c.subject, 220)).filter(Boolean).slice(0, 12),
    rejected_or_boundary_facts: currentCards.filter(c => /contradicted|unconfirmed/.test(String(c.status || ''))).map(c => compactQuestionMemoryText(c.note || c.value || c.subject, 220)).filter(Boolean).slice(0, 12),
    data_analysis_results: dataFacts,
    resolved_data_targets: extractAggregatorArcticTargets(aggregator, turn.turn_ref),
    data_scope: deriveDataScope(aggregator),
    missing_requirements: Array.from(new Set(missing)),
    related_questions: [],
    internal: {
      turn_ref: turn.turn_ref,
      ts: turn.ts,
      evidence_count: turn.evidence_count
    }
  };
  card.related_questions = buildRelatedQuestionEdges(card, previousState.question_memory_cards);
  return card;
}

function mergeQuestionMemoryCards(previousCards, addedCard) {
  const map = new Map();
  for (const card of normalizeQuestionMemoryCards(previousCards)) {
    const key = asString(card.current_question) || asString(card.internal?.turn_ref) || JSON.stringify(card).slice(0, 120);
    map.set(key, card);
  }
  if (addedCard && asString(addedCard.current_question)) {
    map.set(asString(addedCard.current_question), addedCard);
  }
  return Array.from(map.values()).slice(-120);
}

function getMemoryUpdate(finalizer) {
  return asObject(finalizer.memory_update);
}

// MEMORY_STATUS_ALIAS_NORMALIZATION_V5
function normalizeMemoryStatus(value) {
  const allowed = new Set(['confirmed', 'unconfirmed', 'candidate', 'contradicted', 'unknown', 'informational']);
  const status = String(value || '').trim().toLowerCase();
  if (['insufficient_evidence', 'not_confirmed', 'unverified', 'unsupported'].includes(status)) return 'unconfirmed';
  if (['conflict', 'conflicting', 'superseded'].includes(status)) return 'contradicted';
  return allowed.has(status) ? status : 'unknown';
}

function memoryCardsFromUpdate(update, turn) {
  const facts = asArray(update.facts);
  return facts.map((raw, index) => {
    const fact = asObject(raw);
    const entities = asArray(fact.entities).map(String).filter(Boolean);
    const evidenceIds = asArray(fact.evidence_ids).map(String).filter(Boolean);
    return {
      fact_id: `${turn.turn_ref}_F${index + 1}`,
      source_turn: turn.turn_ref,
      source_ts: turn.ts,
      subject: asString(fact.subject),
      relation: asString(fact.relation),
      value: fact.value ?? null,
      status: normalizeMemoryStatus(fact.status),
      entity_type: asString(fact.entity_type) || 'other',
      entities,
      numbers: asArray(fact.numbers),
      source_role: asString(fact.source_role) || 'assistant_output',
      evidence_ids: evidenceIds,
      evidence_grounded: evidenceIds.length > 0,
      note: asString(fact.note)
    };
  }).filter(card => card.subject || card.relation || card.value != null || card.entities.length);
}

// STRUCTURED_REQUIRED_INPUT_CARDS_V5
// Persist calculation inputs as atomic facts so anaphoric follow-ups can reuse
// the inventory without re-extracting broad nouns from answer prose.
function requiredInputInventoryCards(finalizer, turn) {
  return asArray(asObject(finalizer).required_inputs).map((raw, index) => {
    const item = typeof raw === 'string' ? { name: raw } : asObject(raw);
    const name = asString(item.name || item.input || item.variable);
    const evidenceIds = asArray(item.evidence_ids).map(String).filter(Boolean);
    if (!name || !evidenceIds.length) return null;
    return {
      fact_id: `${turn.turn_ref}_RI${index + 1}`,
      source_turn: turn.turn_ref,
      source_ts: turn.ts,
      subject: name,
      relation: 'required_input',
      value: name,
      status: 'confirmed',
      entity_type: 'variable',
      entities: [name],
      numbers: [],
      source_role: 'evidence',
      evidence_ids: evidenceIds,
      evidence_grounded: true,
      input_class: asString(item.input_class) || 'measured_process_variable',
      historian_relevance: asString(item.historian_relevance) || 'direct',
      aliases: asArray(item.aliases).map(String).filter(Boolean).slice(0, 8),
      note: asString(item.note)
    };
  }).filter(Boolean);
}


// STRUCTURED_TAG_STATUS_MEMORY_V5
function structuredTagStatusMemoryCards(turn) {
  const packet = nodeJson('Evidence Packet Builder');
  const rows = asArray(
    packet.tag_evidence_status ||
    asObject(packet.aggregated_payload).tag_evidence_status
  ).map(asObject);
  const cards = [];

  rows.forEach((row, index) => {
    const tag = asString(row.tag);
    if (!tag) return;
    const dataStatus = asString(row.data_status) || 'not_checked';
    const semanticStatus = asString(row.semantic_status) || 'unconfirmed';
    const description = asString(row.desc_cn || row.desc_en);
    const common = {
      source_turn: turn.turn_ref,
      source_ts: turn.ts,
      subject: tag,
      entity_type: 'tag',
      entities: [tag],
      numbers: [],
      source_role: 'structured_tool_evidence',
      evidence_ids: [],
      evidence_grounded: true
    };

    if (dataStatus !== 'not_checked') {
      cards.push({
        ...common,
        fact_id: `${turn.turn_ref}_TD${index + 1}`,
        relation: 'has_data_availability',
        value: dataStatus,
        status: 'confirmed',
        note: Number.isFinite(Number(row.count))
          ? `Structured historian status; count=${Number(row.count)}.`
          : 'Structured historian status.'
      });
    }

    cards.push({
      ...common,
      fact_id: `${turn.turn_ref}_TS${index + 1}`,
      relation: 'has_measurement_semantics',
      value: description || 'unconfirmed',
      process_factor: asString(row.process_factor || row.factor),
      status: /^confirmed_(?:by_|direct_match$)/i.test(semanticStatus) && description
        ? 'confirmed'
        : 'unconfirmed',
      note: description
        ? 'Measurement semantics preserved from structured catalog metadata.'
        : 'Structured catalog metadata has no measurement description.'
    });
  });

  return cards;
}

function mergeMemoryCards(previous, added) {
  const map = new Map();
  for (const card of normalizeFactCards(previous).concat(normalizeFactCards(added))) {
    const key = String(card.fact_id || `${card.source_turn}|${card.subject}|${card.relation}|${JSON.stringify(card.value)}`);
    map.set(key, card);
  }
  return Array.from(map.values()).slice(-160);
}

function buildMemoryEntityIndex(cards) {
  const out = {};
  for (const card of normalizeFactCards(cards)) {
    for (const entity of asArray(card.entities).map(String).filter(Boolean)) {
      const key = entity.toUpperCase();
      out[key] = asArray(out[key]).concat({
        fact_id: card.fact_id,
        source_turn: card.source_turn,
        status: card.status,
        entity_type: card.entity_type,
        evidence_grounded: card.evidence_grounded
      }).slice(-20);
    }
  }
  return out;
}

function updateMemoryTopics(previous, update, turn) {
  const out = normalizeTopicSummaries(previous);
  const topicKey = asString(update.topic_key) || turn.turn_ref;
  out[topicKey] = {
    topic_key: topicKey,
    latest_turn: turn.turn_ref,
    updated_at: turn.ts,
    summary: asString(update.topic_summary).slice(0, 1200),
    status: normalizeMemoryStatus(update.topic_status)
  };
  return Object.fromEntries(Object.entries(out).slice(-40));
}

function currentStructuredEventEvidence() {
  const builder = nodeJson('Evidence Packet Builder');
  const direct = asObject(builder.event_evidence_status);
  if (Object.keys(direct).length) return direct;
  return asObject(asObject(builder.aggregated_payload).event_evidence_status);
}

function structuredEventState(previous, update, turn) {
  const evidence = currentStructuredEventEvidence();
  const inheritedAnchor = asObject(evidence.inherited_event_anchor);
  const priorAtEntry = asObject(previous.event_status);
  const priorStatisticalAtEntry = asObject(priorAtEntry.statistical_anomaly);
  if (
    asString(evidence.status).toLowerCase() === 'confirmed' &&
    asString(inheritedAnchor.status).toLowerCase() === 'confirmed' &&
    asString(priorStatisticalAtEntry.status).toLowerCase() === 'confirmed'
  ) {
    // GENERIC_CONFIRMED_EVENT_FACT_V5
    // Characterization of a saved event cannot replace its event identity or
    // timestamp with the current query's data-coverage boundary.
    const prior = asObject(previous.event_status);
    const inheritedWindow = asObject(evidence.event_window);
    const priorWindow = asObject(prior.event_window);
    // ARCTIC_TIMEZONE_EVENT_ANCHOR_V5
    // STRONGEST_EVENT_ANCHOR_PRECEDENCE_V5
    // A computed strongest-event timestamp is more precise than either a
    // previously saved descriptive window or a parsed multi-day fact start.
    const strongestTimestamp = asString(
      asObject(asObject(prior.statistical_anomaly).strongest_event).timestamp
    );
    const eventWindow = strongestTimestamp
      ? {
          ...priorWindow,
          status: 'anchor_available',
          source: 'strongest_statistical_anomaly',
          anchor_timestamp: strongestTimestamp,
          anchor_timezone: 'UTC'
        }
      : (
          asString(priorWindow.anchor_timestamp)
            ? priorWindow
            : inheritedWindow
        );
    return {
      ...prior,
      status: 'confirmed',
      event_window: eventWindow,
      inherited_event_anchor: inheritedAnchor,
      source_turn: turn.turn_ref,
      source_turn_ts: turn.ts,
      reason: 'This turn characterizes a previously confirmed event; the inherited event identity and anchor remain authoritative.'
    };
  }

  const statistical = asObject(evidence.statistical_anomaly);
  if (asString(evidence.status) === 'confirmed' && asString(statistical.status) === 'confirmed') {
    // PRESERVE_EVENT_ANCHOR_V5
    const currentWindow = asObject(evidence.event_window);
    const previousWindow = asObject(asObject(previous.event_status).event_window);
    const eventWindow = asString(currentWindow.anchor_timestamp)
      ? currentWindow
      : previousWindow;
    return {
      status: 'confirmed',
      event_type: 'statistical_anomaly',
      event_window: eventWindow,
      statistical_anomaly: statistical,
      threshold_exceedance: asObject(evidence.threshold_exceedance),
      direction_reversal: asObject(evidence.direction_reversal),
      relationship_evidence: asObject(evidence.relationship_evidence),
      missing_requirements: asArray(evidence.missing_requirements).map(String).filter(Boolean),
      reason: 'Current structured ArcticDB analysis confirmed a statistical anomaly; threshold exceedance, reversal, and cause retain independent statuses.',
      source_turn: turn.turn_ref,
      source_turn_ts: turn.ts
    };
  }

  // PRESERVE_CONFIRMED_EVENT_OVER_LOCAL_NOT_FOUND_V5
  // A detector rerun with a different range, cadence, or baseline may return
  // no windows. That scoped negative result cannot erase a previously
  // confirmed statistical event.
  if (
    asString(priorAtEntry.status).toLowerCase() === 'confirmed' &&
    asString(priorStatisticalAtEntry.status).toLowerCase() === 'confirmed' &&
    /^(?:not_found|unknown|unconfirmed)$/.test(asString(statistical.status).toLowerCase())
  ) {
    return {
      ...priorAtEntry,
      latest_scoped_detection: {
        status: asString(statistical.status) || 'not_found',
        analysis_scopes: asArray(evidence.analysis_scopes),
        source_turn: turn.turn_ref,
        source_turn_ts: turn.ts
      },
      reason: 'A scoped detector rerun returned no event window; the previously confirmed statistical event remains authoritative.'
    };
  }

  const next = asObject(update.event_state);
  if (!Object.keys(next).length) return previous.event_status || null;

  const status = normalizeMemoryStatus(next.status);
  const missing = asArray(next.missing_requirements).map(String).filter(Boolean);
  const reason = asString(next.reason);
  const eventType = asString(next.event_type);
  const reasonLower = reason.toLowerCase();
  const saysNonEvent = /不涉及事件确认|未涉及事件确认|不是事件确认|非事件|not\s+(?:an?\s+)?event|no\s+event\s+confirmation|not\s+event\s+confirmation/.test(reasonLower);
  if (['unconfirmed', 'contradicted'].includes(status) && missing.length === 0 && (saysNonEvent || !eventType || eventType === 'event')) {
    return previous.event_status || null;
  }

  // PRESERVE_UNCONFIRMED_EVENT_STATE_V5
  const priorEvent = asObject(previous.event_status);
  if (
    status === 'unconfirmed' &&
    asString(priorEvent.status) === 'unconfirmed' &&
    Object.keys(priorEvent).length
  ) {
    return {
      ...priorEvent,
      event_type: eventType || asString(priorEvent.event_type),
      missing_requirements: Array.from(new Set(
        asArray(priorEvent.missing_requirements).map(String).filter(Boolean).concat(missing)
      )),
      reason: eventType && reason ? reason : asString(priorEvent.reason),
      latest_followup_turn: turn.turn_ref,
      latest_followup_ts: turn.ts
    };
  }

  return {
    status,
    event_type: eventType,
    missing_requirements: missing,
    reason,
    source_turn: turn.turn_ref,
    source_turn_ts: turn.ts
  };
}

function memoryUpdateToLegacyIndex(update, turn) {
  const out = defaultFactIndex();
  for (const fact of asArray(update.facts)) {
    const f = asObject(fact);
    const entities = asArray(f.entities).map(String).filter(Boolean);
    if (asString(f.entity_type) === 'tag') {
      for (const entity of entities) out.tags = pushUniqueFact(out.tags, { value: entity, normalized: entity.toUpperCase(), first_turn_ts: turn.ts, source_hint: normalizeMemoryStatus(f.status) }, ['normalized']);
    }
    if (asString(f.entity_type) === 'equipment') {
      for (const entity of entities) out.equipment = pushUniqueFact(out.equipment, { value: entity, turn_ts: turn.ts }, ['value']);
    }
    for (const number of asArray(f.numbers)) out.numbers = pushUniqueFact(out.numbers, { value: String(number), turn_ts: turn.ts, source_hint: normalizeMemoryStatus(f.status) }, ['value']);
    if (asString(f.entity_type) === 'event') out.events = pushUniqueFact(out.events, { summary: asString(f.note || f.value), turn_ts: turn.ts, source_hint: normalizeMemoryStatus(f.status) }, ['summary']);
  }
  return out;
}

function trimTurnsToMemoryBudget(turns) {
  const wf = nodeJson('Workflow Configuration');
  const rp = safeParse(wf.run_params) || {};
  const maxChars = Math.max(4000, Math.min(Number(rp?.memory?.recent_turn_char_budget || 14000), 30000));
  const source = asArray(turns).slice(-getRecentTurnLimit());
  const kept = [];
  let used = 0;
  for (let i = source.length - 1; i >= 0; i -= 1) {
    const size = JSON.stringify(source[i] || {}).length;
    if (kept.length >= 4 && used + size > maxChars) break;
    kept.unshift(source[i]);
    used += size;
  }
  return kept;
}

// ARCTIC_TARGET_INHERITANCE_V5
function normalizeArcticTargetRegistry(value) {
  const out = [];
  const seen = new Set();
  for (const raw of asArray(value)) {
    const item = asObject(raw);
    const tag = asString(item.tag || item.name);
    const library = asString(item.library);
    const symbol = asString(item.symbol);
    if (!tag || !library || !symbol) continue;
    const key = `${tag.toUpperCase()}|${library}|${symbol}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({
      tag,
      library,
      symbol,
      count: item.count !== null && item.count !== '' && Number.isFinite(Number(item.count)) ? Number(item.count) : null,
      data_status: asString(item.data_status || item.status),
      time_range: asArray(item.time_range).slice(0, 2),
      desc_cn: asString(item.desc_cn),
      desc_en: asString(item.desc_en),
      process_factor: asString(item.process_factor || item.factor),
      source_turn: asString(item.source_turn)
    });
  }
  return out.slice(-240);
}

function extractAggregatorArcticTargets(aggregator, sourceTurn) {
  // TARGET_SEMANTIC_PERSISTENCE_V5
  const out = [];
  const completed = asArray(asObject(aggregator).completed_units);
  const metadataByTag = new Map();
  for (const unit of completed) {
    const raw = asObject(unit.raw_result || asObject(unit.normalized_result).raw_result);
    for (const metaRaw of asArray(raw.tags)
      .concat(asArray(raw.selected_tags))
      .concat(asArray(unit.tag_selection_trace))) {
      const meta = asObject(metaRaw);
      const tag = asString(meta.tag || meta.name);
      if (!tag) continue;
      const key = tag.toUpperCase();
      const old = metadataByTag.get(key) || {};
      metadataByTag.set(key, {
        desc_cn: asString(meta.desc_cn || meta.description_cn) || asString(old.desc_cn),
        desc_en: asString(meta.desc_en || meta.description_en) || asString(old.desc_en),
        process_factor: asString(meta.process_factor || meta.factor) || asString(old.process_factor)
      });
    }
  }

  for (const statusRaw of asArray(asObject(aggregator).tag_evidence_status)) {
    const status = asObject(statusRaw);
    const tag = asString(status.tag);
    if (!tag) continue;
    const key = tag.toUpperCase();
    const old = metadataByTag.get(key) || {};
    metadataByTag.set(key, {
      ...old,
      desc_cn: asString(status.desc_cn) || asString(old.desc_cn),
      desc_en: asString(status.desc_en) || asString(old.desc_en),
      process_factor: asString(status.process_factor || status.factor) || asString(old.process_factor)
    });
  }

  const add = (meta, stat) => {
    const m = asObject(meta);
    const s = asObject(stat);
    const tag = asString(m.tag || m.name || s.tag || s.name);
    const library = asString(m.library || s.library);
    const symbol = asString(m.symbol || s.symbol);
    const count = Number(s.count ?? m.count);
    const dataStatus = asString(s.data_status || m.data_status || s.status || m.status);
    if (!tag || !library || !symbol || /^\$ref:/i.test(tag)) return;
    if (!(Number.isFinite(count) && count > 0) && !/^ok|usable|available$/i.test(dataStatus)) return;
    const semantic = metadataByTag.get(tag.toUpperCase()) || {};
    out.push({
      tag,
      library,
      symbol,
      count: Number.isFinite(count) ? count : null,
      data_status: dataStatus || 'ok',
      time_range: asArray(s.time_range || m.time_range).slice(0, 2),
      desc_cn: asString(m.desc_cn) || asString(semantic.desc_cn),
      desc_en: asString(m.desc_en) || asString(semantic.desc_en),
      process_factor: asString(m.process_factor || m.factor) || asString(semantic.process_factor),
      source_turn: asString(sourceTurn)
    });
  };

  for (const unit of completed) {
    const raw = asObject(unit.raw_result || asObject(unit.normalized_result).raw_result);
    for (const factor of asArray(raw.factor_results)) {
      const stats = asArray(asObject(factor).stats);
      for (const meta of asArray(asObject(factor).tags)) {
        const stat = stats.find(x => asString(asObject(x).tag).toUpperCase() === asString(asObject(meta).tag).toUpperCase());
        add(meta, stat || {});
      }
    }
    for (const meta of asArray(raw.selected_tags).concat(asArray(unit.tag_selection_trace))) add(meta, meta);
    const structuredStats = asObject(raw.column_stats);
    const statsParams = asObject(unit.params);
    for (const [tag, stat] of Object.entries(structuredStats)) {
      add({
        tag,
        library: asString(raw.library) || asString(statsParams.library),
        symbol: asString(raw.symbol) || asString(statsParams.symbol),
        // FULL_HISTORY_RANGE_PERSISTENCE_V5
        // Column statistics share the source symbol's measured coverage.
        time_range: asArray(raw.time_range).slice(0, 2)
      }, stat);
    }

    // BOUNDARY_PRESENCE_REGISTRY_V5
    // A positive historian presence probe is valid existence evidence even
    // when later full-range statistics only process columns that were null at
    // the symbol endpoints. Persist those confirmed columns independently.
    if (asString(unit.tool) === 'arctic_read') {
      const params = asObject(unit.params);
      const library = asString(raw.library || params.library);
      const symbol = asString(raw.symbol || params.symbol);
      for (const tag of asArray(raw.non_null_columns)) {
        const semantic = metadataByTag.get(asString(tag).toUpperCase()) || {};
        add({
          tag,
          library,
          symbol,
          time_range: asArray(raw.time_range).slice(0, 2),
          desc_cn: asString(semantic.desc_cn),
          desc_en: asString(semantic.desc_en),
          process_factor: asString(semantic.process_factor)
        }, {
          count: Math.max(1, Number(raw.row_count) || 1),
          data_status: 'ok',
          time_range: asArray(raw.time_range).slice(0, 2)
        });
      }
    }

    for (const resultTargetRaw of asArray(raw.targets)) {
      const resultTarget = asObject(resultTargetRaw);
      const returned = asArray(resultTarget.returned_columns).length
        ? asArray(resultTarget.returned_columns)
        : asArray(resultTarget.numeric_columns);
      for (const tag of returned) {
        add({
          tag,
          library: resultTarget.library,
          symbol: resultTarget.symbol
        }, {
          count: resultTarget.row_count,
          data_status: Number(resultTarget.row_count) > 0 ? 'ok' : ''
        });
      }
    }

    const successful = /^success|ok$/i.test(asString(unit.execution_status));
    if (successful && /^arctic_(?:analyze|stats|read)$/i.test(asString(unit.tool))) {
      const params = asObject(unit.params);
      const targets = asArray(params.targets).length ? asArray(params.targets) : [params];
      for (const target of targets) {
        const t = asObject(target);
        for (const tag of asArray(t.columns)) {
          add({ tag, library: t.library, symbol: t.symbol }, { data_status: 'ok' });
        }
      }
    }
  }
  return normalizeArcticTargetRegistry(out);
}

function mergeArcticTargetRegistry(previous, current) {
  const map = new Map();
  for (const item of normalizeArcticTargetRegistry(previous).concat(normalizeArcticTargetRegistry(current))) {
    const key = `${item.tag.toUpperCase()}|${item.library}|${item.symbol}`;
    const old = map.get(key) || {};
    map.set(key, {
      ...old,
      ...item,
      count: item.count != null ? item.count : old.count,
      time_range: item.time_range.length ? item.time_range : asArray(old.time_range),
      desc_cn: asString(item.desc_cn) || asString(old.desc_cn),
      desc_en: asString(item.desc_en) || asString(old.desc_en),
      process_factor: asString(item.process_factor) || asString(old.process_factor)
    });
  }
  return Array.from(map.values()).slice(-240);
}

function getPreviousState() {
  const capture = nodeJson('Capture context');
  const state = asObject(capture.conversation_state);
  return {
    turns: asArray(state.turns),
    turn_archive: asArray(state.turn_archive), // CONVERSATION_ARCHIVE_V7
    answer_fact_index: normalizeFactIndex(state.answer_fact_index),
    fact_cards: normalizeFactCards(state.fact_cards),
    topic_summaries: normalizeTopicSummaries(state.topic_summaries),
    entity_index: normalizeEntityIndex(state.entity_index),
    question_memory_cards: normalizeQuestionMemoryCards(state.question_memory_cards),
    arctic_target_registry: normalizeArcticTargetRegistry(state.arctic_target_registry),
    threshold_registry: asObject(state.threshold_registry), // THRESHOLD_REGISTRY_V7
    exceedance_episodes: asArray(state.exceedance_episodes), // EVENT_WINDOW_DRIVERS_V7
    alarm_table_majority: asObject(state.alarm_table_majority), // ALARM_TABLE_MAJORITY_V7
    turn_counter: Number(state.turn_counter) || 0, // TURN_COUNTER_V7
    event_status: state.event_status && typeof state.event_status === 'object' && !Array.isArray(state.event_status) ? state.event_status : null,
    latest_topic: asString(state.latest_topic),
    latest_resolved_question: asString(state.latest_resolved_question),
    latest_device_context: asObject(state.latest_device_context),
    updated_at: state.updated_at || null
  };
}

const finalOutput = String($json.output || '').trim();
const sessionId = getSessionId();
const originalQuestion = getOriginalQuestion();
const decompose = getDecomposeOutput();
const finalizer = getFinalizerOutput();
const aggregator = getAggregatorOutput();
const answerSource = bestAnswerText(finalizer, aggregator, finalOutput);
const answerOnly = cleanDisplayAnswer(compactText(stripEvidenceSections(answerSource), 8000));
const answerMode = getAnswerMode(decompose, finalizer, aggregator);
const saveAggPayload = asObject(aggregator.aggregated_payload);
const saveSourceStatus = asObject(saveAggPayload.source_status);
const directResponseUsedForOutput = String(saveSourceStatus.direct_response || '').toLowerCase() === 'used';
const displayOutput = directResponseUsedForOutput ? answerOnly : finalOutput;
// DEVICE_CONTEXT_BRIDGE_V6 — keeps the merged Device Context feature alive on the 5.0 memory layer
function getDeviceContext() {
  try {
    const parsed = nodeJson('Parse Device Context');
    const context = asObject(parsed.device_context);
    return context.schema_version === 'device_context_v1' ? context : {};
  } catch (e) {
    return {};
  }
}

const previous = getPreviousState();
const currentDeviceContext = getDeviceContext();
const convKey = `conversation_state:${sessionId || 'default'}`;
const captureAvailable = Object.keys(nodeJson('Capture context')).length > 0;
// INTENT_AND_STATE_BOUNDARY_V5
// Only a path that actually loaded conversation state may update the canonical
// session key. Early-response branches are isolated even when their reply is
// otherwise valid, so they cannot replace an existing multi-turn history.
let storeKey = captureAvailable
  ? convKey
  : `conversation_state_skip:${sessionId || 'default'}:${Date.now()}`;

let nextState = previous;
let memorySaved = false;
let memorySkipReason = '';

try {
  // ALWAYS_RECORD_TURN_V7
  // 原先 isBadMemoryAnswer 为真就整轮不入库。它用 s.includes('没有检索到')
  // 做全文子串匹配，于是 exec 136098 的 T7（2149 字，含 count=126721、
  // mean=20.5704 与 9 个带日期的异常点）因为中间一句局部说明被整段丢弃，
  // 下一轮 T8（exec 136279）继承到的状态里连一个时间戳都没有。
  // 会话状态是对话记录而非已验证事实库：断一轮，后续所有指代都悬空。
  // 因此一律记录，质量只做标记，由下游自行权衡。
  {
    const answerQuality = isBadMemoryAnswer(answerOnly, answerMode) ? 'no_answer' : 'ok';
    if (answerQuality !== 'ok') memorySkipReason = 'kept_but_flagged:' + answerQuality;
    const resolvedQuestion = getResolvedQuestion(
      decompose,
      finalizer,
      aggregator,
      originalQuestion
    );

    const turns = Array.isArray(previous.turns) ? previous.turns : [];
    // UNFULFILLED_DATA_TURN_V7：本轮计划了历史库取数（探测读数不算）却一条实测都没取到，也记为未答上
    // （declfix D1 exec 155448：位号查找 0 个、统计因依赖未满足没执行，回答「无法完成实测分析」，却因带着文档证据没被记下）。
    // 实测判据与补检环（Coverage Retry 的 __gotMeasured）相同。
    const __measuredState = (function () {
      try {
        const isHist = u => /^(?:arctic|mongo)_(?:read|stats|analyze|resolve_factors)$/.test(asString(asObject(u).tool)) && asObject(asObject(u).params).presence_probe !== true;
        const rawOf = u => { const d = asObject(asObject(u).raw_result); return Object.keys(d).length ? d : asObject(asObject(asObject(u).normalized_result).raw_result); };
        const planned = asArray(asObject(nodeJson('Normalize Execution Units')).units).some(isHist);
        const got = asArray(aggregator.completed_units).some(u => {
          if (!isHist(u)) return false;
          const r = rawOf(u);
          return Object.keys(asObject(r.column_stats)).length > 0 || asArray(r.period_profile).some(x => Number(asObject(x).count) > 0) ||
            asArray(r.records).length > 0 || asArray(r.factor_results).some(fr => asArray(asObject(fr).stats).length > 0);
        });
        return { planned, got };
      } catch (e) { return { planned: false, got: false }; }
    })();
    const turn = {
      // PRIOR_TURN_CLEARED_WHEN_CORRECTED_V7：本轮证据包列出的未答上轮次里，回答正文点名（「第 N 轮」）的那些；
      // 后续轮次据此不再列出它们（F138 用「后面有取到实测的轮次」代替，declfix D2 把 D1 提前清掉了）
      corrected_turns: (function () {
        try {
          const listed = asArray(asObject(asObject(nodeJson('Evidence Packet Builder')).finalizer_payload).prior_declined_turns);
          return listed.map(p => String(asObject(p).turn_ref || '').trim()).filter(r => /^\d+$/.test(r) && new RegExp('第\\s*' + r + '\\s*轮').test(String(answerOnly || '')));
        } catch (e) { return []; }
      })(),
      measured_data: __measuredState.got,
      ts: new Date().toISOString(),
      user_question: originalQuestion,
      resolved_question: resolvedQuestion,
      assistant_answer: answerOnly,
      answer_mode: answerMode,
      evidence_count: extractEvidenceCount(finalizer, aggregator),
      answer_quality: answerQuality,
      // PRIOR_DECLINED_TURN_CORRECTION_V7：本轮只有守卫直答（没有任何检索 / 取数）或被预校验按澄清终止时记下，
      // 后续轮次拿到证据时据此说明该轮回答作废（短链 T7 exec 155417 的拒答原先被记成 answer_quality=ok）
      declined_mode: (function () {
        try {
          const pv = asObject(nodeJson('Pre-Validator'));
          if (asString(pv.termination_type) === 'clarification') return 'clarification';
        } catch (e) {}
        try {
          const us = asArray(asObject(nodeJson('Normalize Execution Units')).units);
          if (us.length && us.every(u => asString(asObject(u).tool) === 'direct_response' && asObject(asObject(u).params).no_retrieval === true)) {
            const mode = asString(asObject(asObject(us[0]).params).mode);
            if (mode && mode !== 'conversation_summary') return mode;
          }
        } catch (e) {}
        if (__measuredState.planned && !__measuredState.got) return 'no_measured_data'; // UNFULFILLED_DATA_TURN_V7
        return null;
      })(),
      // TURN_COUNTER_V7：turns 会被裁剪到最近几轮，按长度编号会循环（T10 时出现 T5,T6,T7,T6,T6）；按已有最大编号递增。
      turn_ref: `T${Math.max(
        Number(previous.turn_counter) || 0,
        ...turns.concat(asArray(previous.turn_archive)).map(t => Number(String(asObject(t).turn_ref || '').replace(/^T/i, '')) || 0),
        ...asArray(previous.fact_cards).map(c => Number(String(asObject(c).source_turn || '').replace(/^T/i, '')) || 0),
        turns.length
      ) + 1}`
    };

    const last = turns[turns.length - 1] || {};
    const duplicate =
      last.user_question === turn.user_question &&
      last.assistant_answer === turn.assistant_answer;

    const nextTurns = duplicate ? turns : turns.concat(turn);

    const memoryUpdate = getMemoryUpdate(finalizer);
    const structuredTagCards = structuredTagStatusMemoryCards(turn);
    const structuredTagSubjects = new Set(
      structuredTagCards.map(card => asString(card.subject).toUpperCase()).filter(Boolean)
    );
    // STRUCTURED_TAG_MEMORY_AUTHORITY_V5
    // The current tool matrix is authoritative for tag semantics and data
    // status. LLM memory extraction may summarize prose, but cannot create a
    // second conflicting semantic fact for the same tag and turn.
    const generatedCards = memoryCardsFromUpdate(memoryUpdate, turn).filter(card => {
      const subject = asString(card.subject).toUpperCase();
      const tagFact = asString(card.entity_type).toLowerCase() === 'tag' ||
        asArray(card.entities).some(entity => structuredTagSubjects.has(asString(entity).toUpperCase()));
      return !(tagFact && structuredTagSubjects.has(subject));
    });
    const requiredInputCards = requiredInputInventoryCards(finalizer, turn);
    const addedCards = generatedCards.concat(requiredInputCards, structuredTagCards);
    const mergedCards = mergeMemoryCards(previous.fact_cards, addedCards);
    const nextEventStatus = structuredEventState(previous, memoryUpdate, turn);
    const questionMemoryCard = buildQuestionMemoryCard(turn, memoryUpdate, mergedCards, previous, nextEventStatus, aggregator);
    const scopedPreviousQuestionCards = applyDataScopeSupersession(previous.question_memory_cards, questionMemoryCard);
    nextState = {
      turns: trimTurnsToMemoryBudget(nextTurns),
      // CONVERSATION_ARCHIVE_V7：全部轮次原样存档（不裁剪）；turns 只是最近窗口。首次由现有 turns 播种。
      turn_archive: (function () {
        const base = asArray(previous.turn_archive).length ? asArray(previous.turn_archive) : asArray(previous.turns);
        if (duplicate) return base;
        return base.concat(turn);
      })(),
      answer_fact_index: mergeFactIndex(previous.answer_fact_index, memoryUpdateToLegacyIndex(memoryUpdate, turn)),
      fact_cards: mergedCards,
      topic_summaries: updateMemoryTopics(previous.topic_summaries, memoryUpdate, turn),
      entity_index: buildMemoryEntityIndex(mergedCards),
      question_memory_cards: mergeQuestionMemoryCards(scopedPreviousQuestionCards, questionMemoryCard),
      arctic_target_registry: mergeArcticTargetRegistry(previous.arctic_target_registry, questionMemoryCard.resolved_data_targets),
      // ALARM_TABLE_MAJORITY_V7：证据表格里有冲突的回路的多数定值，先到先得（阈值句平票时裁决用）
      // THRESHOLD_RESOLVER_V8：同一回路的表格观察保留总行数多的一次（持平沿用已存的）
      alarm_table_majority: (function () {
        const out = Object.assign({}, asObject(previous.alarm_table_majority));
        for (const [k, v] of Object.entries(asObject(nodeJson('Evidence Packet Builder').alarm_table_majority))) {
          const p = asObject(out[k]);
          if (!Object.keys(p).length || Number(asObject(v).total_rows) > Number(p.total_rows)) out[k] = v;
        }
        return out;
      })(),
      // EVENT_WINDOW_DRIVERS_V7：越限时段（F118 按日扫描）本轮有则替换，否则沿用，供后续轮次做关联变量扫描
      exceedance_episodes: (function () {
        const cur = asArray(nodeJson('Evidence Packet Builder').exceedance_episodes);
        return cur.length ? cur.slice(0, 8).map(e => Object.assign({}, e, { turn_ref: String(turn.turn_ref || '').replace(/^T/i, '') })) : asArray(previous.exceedance_episodes);
      })(),
      // THRESHOLD_REGISTRY_V7：每个回路每个标签只保留最早确立的值，量程同理
      threshold_registry: (function () {
        const out = JSON.parse(JSON.stringify(asObject(previous.threshold_registry)));
        const cur = asObject(nodeJson('Evidence Packet Builder').threshold_registry);
        for (const [k, raw] of Object.entries(cur)) {
          const r = asObject(raw);
          const turnsOf = asArray(r.turns).map(String);
          // THRESHOLD_RESOLVER_V8：裁决只在证据包节点一处；这里按回路整体保存它本轮的结果，不再另立「先到先得」
          // （原先已有值就不覆盖，登记错了改不回来：exec 154469 登记 45/42/12/10 而证据表格 12 行中 8 行是 38/37/10/9）
          if (!Object.keys(asObject(r.values)).length && !r.span && !r.span_rejected && !out[k]) continue;
          const o = out[k] ? asObject(out[k]) : { values: {}, span: null, turns: [] };
          o.values = Object.assign({}, asObject(r.values));
          if (r.span_rejected) o.span = null; else if (r.span) o.span = r.span;
          if (asArray(r.conflicts).length) o.conflicts = asArray(r.conflicts).slice(0, 8); else delete o.conflicts;
          o.turns = Array.from(new Set(asArray(o.turns).map(String).concat(turnsOf)));
          out[k] = o;
        }
        return out;
      })(),
      turn_counter: Number(String(turn.turn_ref).replace(/^T/i, '')) || 0,
      event_status: nextEventStatus,
      latest_topic: getLatestTopic(previous, decompose, resolvedQuestion, originalQuestion),
      latest_resolved_question: resolvedQuestion || previous.latest_resolved_question || '',
      latest_device_context: (currentDeviceContext.status === 'resolved' || currentDeviceContext.status === 'ambiguous')
        ? currentDeviceContext
        : asObject(previous.latest_device_context),
      updated_at: turn.ts
    };
    memorySaved = true;
  }
} catch (err) {
  memorySkipReason = String(err && err.message ? err.message : err);
}

return [
  {
    json: {
      ...$json,
      output: displayOutput,
      conversation_state_key: storeKey,
      conversation_state_next: nextState,
      memory_debug: {
        key: storeKey,
        intended_key: convKey,
        canonical_write_allowed: captureAvailable,
        saved: memorySaved,
        skip_reason: memorySkipReason,
        previous_turn_count: previous.turns.length,
        next_turn_count: asArray(nextState.turns).length,
        latest_topic: nextState.latest_topic,
        latest_resolved_question: nextState.latest_resolved_question,
        device_context_status: asString(asObject(nextState.latest_device_context).status) || 'none',
        event_status: nextState.event_status || null,
        fact_card_count: asArray(nextState.fact_cards).length,
        entity_count: Object.keys(asObject(nextState.entity_index)).length,
        question_memory_card_count: asArray(nextState.question_memory_cards).length,
        arctic_target_count: asArray(nextState.arctic_target_registry).length,
        latest_arctic_targets: asArray(nextState.arctic_target_registry).slice(-12).map(x => ({
          tag: x.tag,
          library: x.library,
          symbol: x.symbol,
          count: x.count,
          data_status: x.data_status
        })),
        latest_related_questions: asArray(asArray(nextState.question_memory_cards).slice(-1)[0]?.related_questions).map(x => x.question).slice(0, 5)
      }
    }
  }
];

const helperContext = this;

function readConfig(name, fallback = '') {
  try {
    if (typeof process !== 'undefined' && process.env && process.env[name]) return process.env[name];
  } catch (e) {}
  try {
    if (typeof $env !== 'undefined' && $env && $env[name]) return $env[name];
  } catch (e) {}
  try {
    if (typeof $vars !== 'undefined' && $vars && $vars[name]) return $vars[name];
  } catch (e) {}
  return fallback;
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function nonEmptyArray(value) {
  return Array.isArray(value) && value.length > 0;
}

function firstText(...values) {
  for (const value of values) {
    if (typeof value === 'string' && value.trim()) return value.trim();
  }
  return '';
}

function numericScore(chunk) {
  const candidates = [
    chunk.similarity,
    chunk.score,
    chunk.rank_score,
    chunk.rerank_score,
    chunk.vector_similarity,
  ];

  for (const value of candidates) {
    const n = Number(value);
    if (Number.isFinite(n)) return n;
  }

  return null;
}

function getPage(chunk, end = false) {
  const direct = end
    ? [chunk.page_end, chunk.end_page, chunk.page_to]
    : [chunk.page_start, chunk.start_page, chunk.page, chunk.page_num];

  for (const value of direct) {
    const n = Number(value);
    if (Number.isFinite(n)) return n;
  }

  if (Array.isArray(chunk.positions) && chunk.positions.length) {
    const pages = chunk.positions
      .map((p) => Number(p && (p.page_num ?? p.page ?? p[0])))
      .filter((n) => Number.isFinite(n));
    if (pages.length) return end ? Math.max(...pages) : Math.min(...pages);
  }

  return null;
}

function getChunkText(chunk) {
  for (const key of ['content', 'text', 'chunk', 'page_content', 'highlight']) {
    const value = chunk[key];
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (Array.isArray(value)) {
      const joined = value.filter((x) => typeof x === 'string').join(' ').trim();
      if (joined) return joined;
    }
  }

  const doc = chunk.document || chunk.doc;
  if (doc && typeof doc === 'object') {
    for (const key of ['content', 'text', 'name']) {
      const value = doc[key];
      if (typeof value === 'string' && value.trim()) return value.trim();
    }
  }

  return '';
}

function normalizeWhitespace(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function preview(value, maxLen = 700) {
  const text = normalizeWhitespace(value);
  return text.length > maxLen ? text.slice(0, maxLen - 3) + '...' : text;
}

function fingerprint(text) {
  const normalized = normalizeWhitespace(text).toLowerCase().slice(0, 900);
  let hash = 0;
  for (let i = 0; i < normalized.length; i += 1) {
    hash = ((hash << 5) - hash + normalized.charCodeAt(i)) | 0;
  }
  return String(hash);
}

// RAGFLOW_DOCUMENT_KEYWORD_NAME_V7
// RAGFlow /api/v1/retrieval 的片段用 document_keyword 携带文档名、dataset_id 携带数据集（实测）；
// 原先只认 document_name/doc_name/filename，展示区「文档」「数据集」因此一直为空。
let __datasetNameById = new Map();
function documentName(chunk) {
  const doc = chunk.document || chunk.doc || {};
  return firstText(
    chunk.document_name,
    chunk.document_keyword,
    chunk.docnm_kwd,
    chunk.doc_name,
    chunk.filename,
    chunk.name,
    doc.name,
    doc.filename,
  ) || null;
}

function documentId(chunk) {
  const doc = chunk.document || chunk.doc || {};
  return firstText(
    chunk.document_id,
    chunk.doc_id,
    chunk.documentId,
    doc.id,
  ) || null;
}

function datasetName(chunk) {
  const byName = firstText(
    chunk.dataset_name,
    chunk.kb_name,
    chunk.knowledgebase_name,
  );
  if (byName) return byName;
  const dsId = firstText(chunk.dataset_id, chunk.kb_id);
  if (dsId && __datasetNameById.has(dsId)) return __datasetNameById.get(dsId);
  return firstText(chunk.dataset) || null;
}

function sectionTitle(chunk) {
  return firstText(
    chunk.section_title,
    chunk.title,
    chunk.heading,
    chunk.section,
  ) || null;
}

function dedupeKey(candidate) {
  const chunk = candidate.chunk;
  const id = firstText(chunk.id, chunk.chunk_id, chunk.chunkId);
  if (id) return 'id:' + id;

  return [
    'fp',
    documentId(chunk) || documentName(chunk) || '',
    sectionTitle(chunk) || '',
    getPage(chunk, false) ?? '',
    fingerprint(candidate.text),
  ].join('|');
}

function buildPayload(params, variant) {
  const payload = {
    question: variant.question,
  };

  const settingNames = [
    'dataset_ids',
    'document_ids',
    'page',
    'page_size',
    'similarity_threshold',
    'vector_similarity_weight',
    'keyword',
    'top_k',
    'rerank_id',
    'highlight',
    'cross_languages',
    'metadata_condition',
    'use_kg',
    'toc_enhance',
  ];

  for (const name of settingNames) {
    const value = variant[name] ?? params[name];
    if (value === undefined || value === null) continue;
    if (Array.isArray(value) && value.length === 0) continue;
    if (value === '') continue;
    payload[name] = value;
  }

  // RETRIEVAL_WINDOW_FLOOR_V7
  // Match Tools 提示词把 page_size=8 写成默认值，规划器写出检索步骤时就带上 8/64，
  // 检索单元由后续节点补出时则不传（RAGFlow 用自身默认 30），窗口随规划器行为摆动。
  // 实测 exec 140030：含 PRCA3101/3102 的片段排在第 8 名之外未被取回。
  // 这里只抬高到 20/128（阈值类问题已在用的窗口），不压低；未传时保持不传。
  if (payload.page_size !== undefined && Number(payload.page_size) < 20) payload.page_size = 20;
  if (payload.top_k !== undefined && Number(payload.top_k) < 128) payload.top_k = 128;

  return payload;
}


function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function errorText(err) {
  if (!err) return 'Unknown error';
  if (typeof err === 'string') return err;
  const message = err.message || String(err);
  return normalizeWhitespace(message).slice(0, 1200);
}

function isRetriableRetrievalError(err) {
  const text = errorText(err).toLowerCase();
  return [
    'timeout',
    'timed out',
    'eof',
    'ssl',
    'connection',
    'connreset',
    'socket',
    'temporarily unavailable',
    'max retries',
    '502',
    '503',
    '504',
    'code":100',
    'code 100',
  ].some((needle) => text.includes(needle));
}

async function retrieveVariant(url, headers, payload, verifySsl, variant, options) {
  const maxAttempts = Math.max(1, Number(options.maxAttempts ?? 1));
  const baseDelayMs = Math.max(0, Number(options.baseDelayMs ?? 1000));
  const timeoutMs = Math.max(1000, Number(options.timeoutMs ?? 25000));
  let lastError = null;

  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      const response = await postJson(url, headers, payload, verifySsl, timeoutMs);
      if (response && response.code !== undefined && response.code !== 0) {
        const err = new Error(
          'RAGFlow retrieval error for ' +
            variant.variant_id +
            ': ' +
            JSON.stringify(response).slice(0, 1200)
        );
        err.ragflowPayload = response;
        throw err;
      }

      return { ok: true, response, attempts: attempt };
    } catch (err) {
      lastError = err;
      const shouldRetry = attempt < maxAttempts && isRetriableRetrievalError(err);
      if (!shouldRetry) break;
      await sleep(baseDelayMs * attempt);
    }
  }

  return {
    ok: false,
    attempts: maxAttempts,
    error: errorText(lastError),
  };
}

async function postJson(url, headers, body, verifySsl, timeoutMs) {
  const requestTimeoutMs = Math.max(1000, Number(timeoutMs || 25000));

  if (!verifySsl) {
    try {
      if (typeof process !== 'undefined' && process.env) {
        process.env.NODE_TLS_REJECT_UNAUTHORIZED = '0';
      }
    } catch (e) {}
  }

  if (helperContext && helperContext.helpers && helperContext.helpers.httpRequest) {
    return await helperContext.helpers.httpRequest({
      method: 'POST',
      url,
      headers,
      body,
      json: true,
      timeout: requestTimeoutMs,
      rejectUnauthorized: verifySsl,
      agentOptions: { rejectUnauthorized: verifySsl },
      skipSslCertificateValidation: !verifySsl,
    });
  }

  if (typeof fetch !== 'function') {
    throw new Error('No HTTP client is available in the Code node. Enable this.helpers.httpRequest or Node fetch.');
  }

  const fetchOptions = {
    method: 'POST',
    headers,
    body: JSON.stringify(body),
  };

  try {
    if (typeof AbortSignal !== 'undefined' && AbortSignal.timeout) {
      fetchOptions.signal = AbortSignal.timeout(requestTimeoutMs);
    }
  } catch (e) {}

  const response = await fetch(url, fetchOptions);
  const text = await response.text();
  if (!response.ok) {
    throw new Error('HTTP ' + response.status + ' from RAGFlow: ' + text.slice(0, 1000));
  }

  try {
    return JSON.parse(text);
  } catch (e) {
    throw new Error('RAGFlow returned non-JSON response: ' + text.slice(0, 1000));
  }
}

function extractChunks(payload) {
  const result = payload && payload.data !== undefined ? payload.data : payload;

  if (Array.isArray(result)) return result;
  if (!result || typeof result !== 'object') return [];

  for (const value of [result.chunks, result.records, result.items]) {
    if (Array.isArray(value)) return value;
  }

  return [];
}

function normalizeVariant(params, rawVariant, index) {
  const variant = rawVariant && typeof rawVariant === 'object' ? rawVariant : {};
  const question = firstText(variant.question, variant.query, params.question);
  return {
    ...variant,
    variant_id: firstText(variant.variant_id, variant.id) || 'variant_' + (index + 1),
    lang_variant: firstText(variant.lang_variant, variant.language, variant.lang) || null,
    question,
  };
}

async function mapWithConcurrency(items, concurrency, mapper) {
  const limit = Math.max(1, Math.min(items.length, Number(concurrency) || items.length || 1));
  const results = new Array(items.length);
  let nextIndex = 0;

  const workers = Array.from({ length: limit }, async () => {
    while (true) {
      const index = nextIndex;
      nextIndex += 1;
      if (index >= items.length) return;
      results[index] = await mapper(items[index], index);
    }
  });

  await Promise.all(workers);
  return results;
}

function rankStopwords() {
  return new Set([
    'the','and','for','with','that','this','from','into','onto','over','under','between','within','without',
    'what','when','where','which','while','does','did','had','has','have','been','being','were','was','are','is',
    'how','why','can','could','would','should','shall','will','may','might','about','into','than','then',
    'operating','operation','conditions','condition','parameter','parameters','effect','effects','affect','affected',
    'question','query','answer','evidence','retrieval','ragflow','analysis','during','period','ideal','target'
  ]);
}

function tokenizeRankText(value) {
  const stop = rankStopwords();
  const text = String(value || '');
  const out = [];
  const seen = new Set();

  function add(token) {
    const t = String(token || '').toLowerCase().replace(/^[-_.:/]+|[-_.:/]+$/g, '');
    if (!t || t.length < 2 || stop.has(t)) return;
    if (/^\d+$/.test(t) && t.length < 4) return;
    if (seen.has(t)) return;
    seen.add(t);
    out.push(t);
  }

  const tagMatches = text.match(/\b[A-Z]{1,8}[A-Z0-9_]*\d+[A-Z0-9_]*(?:\.PV)?\b|\bEcat[A-Za-z0-9_]+\b|\bLCO\d{2}_D86V\d{3}\b/g) || [];
  for (const tag of tagMatches) add(tag);

  const latin = text
    .toLowerCase()
    .replace(/[^\w.%/°℃-]+/g, ' ')
    .split(/\s+/)
    .filter(Boolean);
  for (const token of latin) add(token);

  const cjkSegments = text.match(/[\u4e00-\u9fff]{2,}/g) || [];
  for (const segment of cjkSegments) {
    if (segment.length <= 6) add(segment);
    for (let i = 0; i < segment.length - 1; i += 1) add(segment.slice(i, i + 2));
    for (let i = 0; i < segment.length - 2; i += 1) add(segment.slice(i, i + 3));
  }

  return out;
}

function weightedTokenMap(tokens, weight) {
  const map = new Map();
  for (const token of tokens || []) {
    if (!token) continue;
    map.set(token, Math.max(map.get(token) || 0, weight));
  }
  return map;
}

function addWeightedTokens(map, tokens, weight) {
  for (const token of tokens || []) {
    if (!token) continue;
    map.set(token, Math.max(map.get(token) || 0, weight));
  }
}

function intentRankTerms(questionPart) {
  const part = String(questionPart || '').trim();
  const profiles = {
    factor_identification: 'factor cause causes mechanism influence increases decreases drives relationship parameter variable operating condition sensitivity',
    target_or_ideal_range: 'target range recommended ideal optimum benchmark limit constraint specification setpoint operating window',
    period_verification: 'trend actual observed during period date month compare deviation stable unstable above below average minimum maximum',
    cause_diagnosis: 'cause root cause mechanism symptom consequence indication diagnosis reason failure abnormal issue',
    event_retrieval: 'incident event case trip failure upset historical occurred date consequence recovery',
    comparison: 'compare difference higher lower before after versus baseline benchmark',
    trend_or_change_analysis: 'trend increase decrease change shift movement ramp step before after',
    correlation_or_dependency_analysis: 'correlation dependency relationship coupled associated lag response sensitivity',
    anomaly_or_exceedance: 'anomaly exceedance abnormal limit threshold outlier excursion high low',
    measurement_lookup: 'measurement tag signal value observed reading data trend',
    tag_or_signal_discovery: 'tag signal measurement instrument transmitter controller indicator',
    data_quality_or_availability: 'missing flatline constant zero bad data availability quality unreliable gap',
    procedure_or_action: 'procedure action mitigation adjustment troubleshooting operation control response',
    recommendation_or_optimization: 'recommend optimize improve adjustment priority action tradeoff constraint',
    definition_or_explanation: 'definition explanation principle mechanism process basis'
  };
  return tokenizeRankText(profiles[part] || '');
}

function buildRankContext(params, unit, item, variants) {
  const weighted = new Map();
  const coreTexts = [
    item && item.originalUserMessage,
    item && item.original_question,
    params && params.question,
    params && params.question_en,
    params && params.question_zh,
    params && params.resolved_question,
    params && params.question_literal,
    unit && unit.question_part,
    ...(Array.isArray(unit && unit.required_evidence_types) ? unit.required_evidence_types : []),
    ...(Array.isArray(unit && unit.optional_evidence_types) ? unit.optional_evidence_types : []),
  ];

  for (const text of coreTexts) addWeightedTokens(weighted, tokenizeRankText(text), 2.0);
  for (const variant of variants || []) addWeightedTokens(weighted, tokenizeRankText(variant && variant.question), 1.2);
  addWeightedTokens(weighted, intentRankTerms(unit && unit.question_part), 1.4);

  const totalWeight = [...weighted.values()].reduce((sum, value) => sum + value, 0) || 1;
  return {
    weighted,
    totalWeight,
    tokens: [...weighted.keys()],
    question_part: String(unit && unit.question_part || '').trim(),
  };
}

function tokenSetForCandidate(candidate) {
  if (candidate._rank_token_set) return candidate._rank_token_set;
  const chunk = candidate.chunk || {};
  const parts = [
    candidate.text,
    documentName(chunk),
    datasetName(chunk),
    sectionTitle(chunk),
    candidate.variant && candidate.variant.question,
  ];
  candidate._rank_token_set = new Set(tokenizeRankText(parts.filter(Boolean).join(' ')));
  return candidate._rank_token_set;
}

function normalizedRagScore(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return 0;
  if (n <= 1) return Math.max(0, Math.min(1, n));
  if (n <= 100) return Math.max(0, Math.min(1, n / 100));
  return Math.max(0, Math.min(1, Math.log10(n + 1) / 4));
}

function candidateRankFeatures(candidate, rankContext) {
  const tokens = tokenSetForCandidate(candidate);
  let matchedWeight = 0;
  let hits = 0;
  for (const [token, weight] of rankContext.weighted.entries()) {
    if (tokens.has(token)) {
      matchedWeight += weight;
      hits += 1;
    }
  }

  const tokenCoverage = Math.min(1, matchedWeight / rankContext.totalWeight);
  const score = normalizedRagScore(numericScore(candidate.chunk));
  const textLength = Math.min(1, normalizeWhitespace(candidate.text).length / 1800);
  const docMetaText = [documentName(candidate.chunk), datasetName(candidate.chunk), sectionTitle(candidate.chunk)].filter(Boolean).join(' ');
  const metaTokens = new Set(tokenizeRankText(docMetaText));
  let metaHits = 0;
  for (const token of rankContext.tokens) {
    if (metaTokens.has(token)) metaHits += 1;
  }
  const metaCoverage = Math.min(1, metaHits / 8);

  const finalScore =
    score * 0.50 +
    tokenCoverage * 0.34 +
    metaCoverage * 0.08 +
    textLength * 0.04 +
    Math.max(0, 1 - candidate.order / 10000) * 0.04;

  candidate._rank_features = {
    final_score: Number(finalScore.toFixed(6)),
    rag_score_normalized: Number(score.toFixed(6)),
    query_token_coverage: Number(tokenCoverage.toFixed(6)),
    query_token_hits: hits,
    metadata_token_coverage: Number(metaCoverage.toFixed(6)),
  };

  return candidate._rank_features;
}

function tokenSimilarity(a, b) {
  const setA = tokenSetForCandidate(a);
  const setB = tokenSetForCandidate(b);
  if (!setA.size || !setB.size) return { jaccard: 0, containment: 0 };

  let intersection = 0;
  for (const token of setA) {
    if (setB.has(token)) intersection += 1;
  }

  const union = setA.size + setB.size - intersection;
  return {
    jaccard: union > 0 ? intersection / union : 0,
    containment: intersection / Math.min(setA.size, setB.size),
  };
}

function sameDocumentOrSection(a, b) {
  const aDoc = documentId(a.chunk) || documentName(a.chunk) || '';
  const bDoc = documentId(b.chunk) || documentName(b.chunk) || '';
  if (aDoc && bDoc && aDoc === bDoc) return true;
  const aSection = sectionTitle(a.chunk) || '';
  const bSection = sectionTitle(b.chunk) || '';
  return !!(aSection && bSection && aSection === bSection);
}

function isNearDuplicate(candidate, selected, threshold) {
  if (/<table\b/i.test(candidate.text || '')) return false;
  for (const existing of selected) {
    const sim = tokenSimilarity(candidate, existing);
    if (sim.jaccard >= threshold) return true;
    if (sameDocumentOrSection(candidate, existing) && sim.containment >= 0.82) return true;
    if (sim.containment >= 0.93 && Math.min(candidate.text.length, existing.text.length) > 220) return true;
  }
  return false;
}

function selectedEvidence(candidates, maxEvidence, rankContext, options = {}) {
  const byKey = new Map();
  const stats = {
    ranker_version: 'post_rag_deterministic_ranker_v2',
    input_candidate_count: candidates.length,
    exact_duplicate_replaced_count: 0,
    exact_deduped_candidate_count: 0,
    near_duplicate_skipped_count: 0,
    document_soft_cap_skipped_count: 0,
    selected_count: 0,
  };

  for (const candidate of candidates) {
    if (!candidate.text) continue;
    const key = dedupeKey(candidate);
    candidateRankFeatures(candidate, rankContext);
    const existing = byKey.get(key);

    if (!existing) {
      byKey.set(key, candidate);
      continue;
    }

    const existingRank = candidateRankFeatures(existing, rankContext).final_score;
    const candidateRank = candidate._rank_features.final_score;
    const betterRank = candidateRank > existingRank;
    const betterText = candidateRank === existingRank && candidate.text.length > existing.text.length;
    if (betterRank || betterText) {
      byKey.set(key, candidate);
      stats.exact_duplicate_replaced_count += 1;
    }
  }

  const ranked = [...byKey.values()]
    .sort((a, b) => {
      const rankA = candidateRankFeatures(a, rankContext).final_score;
      const rankB = candidateRankFeatures(b, rankContext).final_score;
      if (rankA !== rankB) return rankB - rankA;

      const scoreA = normalizedRagScore(numericScore(a.chunk));
      const scoreB = normalizedRagScore(numericScore(b.chunk));
      if (scoreA !== scoreB) return scoreB - scoreA;

      const docA = documentName(a.chunk) || '';
      const docB = documentName(b.chunk) || '';
      if (docA !== docB) return docA.localeCompare(docB);

      return a.order - b.order;
    });

  stats.exact_deduped_candidate_count = ranked.length;

  const selected = [];
  const docCounts = new Map();
  const variantCounts = new Map();
  const nearDuplicateThreshold = Number(options.nearDuplicateThreshold ?? 0.74);
  const maxPerDocument = Number(options.maxPerDocument ?? 90);
  const maxPerVariant = Number(options.maxPerVariant ?? 120);
  const finiteLimit = Number.isFinite(maxEvidence) && maxEvidence > 0 ? maxEvidence : Infinity;

  for (const candidate of ranked) {
    if (selected.length >= finiteLimit) break;

    const docKey = documentId(candidate.chunk) || documentName(candidate.chunk) || 'unknown_document';
    const variantKey = candidate.variant && candidate.variant.variant_id || 'unknown_variant';
    const docCount = docCounts.get(docKey) || 0;
    const variantCount = variantCounts.get(variantKey) || 0;

    if (Number.isFinite(maxPerDocument) && maxPerDocument > 0 && docCount >= maxPerDocument) {
      stats.document_soft_cap_skipped_count += 1;
      continue;
    }

    if (Number.isFinite(maxPerVariant) && maxPerVariant > 0 && variantCount >= maxPerVariant) {
      stats.document_soft_cap_skipped_count += 1;
      continue;
    }

    if (isNearDuplicate(candidate, selected, nearDuplicateThreshold)) {
      stats.near_duplicate_skipped_count += 1;
      continue;
    }

    candidate._post_rag_rank = selected.length + 1;
    selected.push(candidate);
    docCounts.set(docKey, docCount + 1);
    variantCounts.set(variantKey, variantCount + 1);
  }

  stats.selected_count = selected.length;
  stats.unique_document_count = docCounts.size;
  stats.unique_variant_count = variantCounts.size;
  stats.max_evidence_limit = finiteLimit === Infinity ? 'all' : finiteLimit;
  stats.near_duplicate_threshold = nearDuplicateThreshold;
  stats.max_chunks_per_document = maxPerDocument;
  stats.max_chunks_per_variant = maxPerVariant;
  selectedEvidence.lastStats = stats;

  return selected;
}


function evidenceObjects(selected) {
  const evidence_summary = [];
  const evidence_digest = [];

  selected.forEach((candidate, index) => {
    const chunk = candidate.chunk;
    const evidenceId = 'E' + (index + 1);
    const snippet = /<table\b/i.test(candidate.text || '')
  ? candidate.text
  : preview(candidate.text, 700);
    const docName = documentName(chunk);
    const dsName = datasetName(chunk);
    const pageStart = getPage(chunk, false);
    const pageEnd = getPage(chunk, true);
    const score = numericScore(chunk);

    evidence_summary.push({
      evidence_id: evidenceId,
      document_id: documentId(chunk),
      document_name: docName,
      dataset_name: dsName,
      page_start: pageStart,
      page_end: pageEnd,
      section_title: sectionTitle(chunk),
      snippet,
      retrieval_score: score,
      source_type: 'ragflow',
      variant_id: candidate.variant.variant_id,
      lang_variant: candidate.variant.lang_variant,
      retrieval_query: candidate.variant.question,
      post_rag_rank: candidate._post_rag_rank || index + 1,
      post_rag_rank_score: candidate._rank_features ? candidate._rank_features.final_score : null,
      query_token_coverage: candidate._rank_features ? candidate._rank_features.query_token_coverage : null,
      query_token_hits: candidate._rank_features ? candidate._rank_features.query_token_hits : null,
    });

    evidence_digest.push({
      evidence_id: evidenceId,
      document_name: docName,
      dataset_name: dsName,
      page_start: pageStart,
      page_end: pageEnd,
      section_title: sectionTitle(chunk),
      content_summary: snippet,
      key_points: [],
      key_values: [],
      operational_actions: [],
      limitations: [],
      // 原为 'Retrieved for grouped query variant: ' + variant_id 的占位，展示区会原样当作「答案用途」显示。
      // 答案用途改由展示节点按最终回答中引用该证据的句子生成，这里置空。
      relevance_to_question: '',
      snippet,
      variant_id: candidate.variant.variant_id,
      lang_variant: candidate.variant.lang_variant,
      retrieval_query: candidate.variant.question,
      post_rag_rank: candidate._post_rag_rank || index + 1,
      post_rag_rank_score: candidate._rank_features ? candidate._rank_features.final_score : null,
      query_token_coverage: candidate._rank_features ? candidate._rank_features.query_token_coverage : null,
    });
  });

  return { evidence_summary, evidence_digest };
}

const defaultBaseUrl =
  readConfig('RAGFLOW_BASE_URL') ||
  readConfig('RAGFLOW_URL') ||
  "https://<HOST>:8091";

const defaultApiKey =
  readConfig('RAGFLOW_API_KEY') ||
  readConfig('RAGFLOW_TOKEN') ||
  "<RAGFLOW_API_KEY>";

const defaultVerifySslValue = readConfig('RAGFLOW_TLS_VERIFY', 'false');

const outputItems = [];

for (const inputItem of $input.all()) {
  const item = inputItem.json || {};
  const unit = item.unit || {};
  const params = unit.params || {};

  const baseUrl = firstText(params.ragflow_base_url, params.ragflow_url, defaultBaseUrl);
  const apiKey = firstText(params.ragflow_api_key, params.ragflow_token, defaultApiKey);

  if (!baseUrl) {
    throw new Error('RAGFLOW_BASE_URL environment variable is required for deterministic grouped RAG retrieval.');
  }

  if (!apiKey) {
    throw new Error('RAGFLOW_API_KEY environment variable is required for deterministic grouped RAG retrieval.');
  }

  const verifySslRaw = params.ragflow_tls_verify ?? params.verify_ssl ?? defaultVerifySslValue;
  const verifySslValue = String(verifySslRaw).toLowerCase();
  const verifySsl = !['0', 'false', 'no', 'off'].includes(verifySslValue);
  const retrievalUrl = baseUrl.replace(/\/+$/, '') + '/api/v1/retrieval';
  const headers = {
    Authorization: 'Bearer ' + apiKey,
    'Content-Type': 'application/json',
  };

  const rawVariants = nonEmptyArray(params.query_variants)
    ? params.query_variants
    : [{ question: params.question, variant_id: 'single_query', lang_variant: params.lang_variant || null }];

  const variants = rawVariants
    .map((variant, index) => normalizeVariant(params, variant, index))
    .filter((variant) => variant.question);

  if (!variants.length) {
    // NO_QUERY_PASSTHROUGH_V6 — a direct/no-retrieval unit has no query by design.
    // Emit an empty retrieval result instead of failing the whole execution.
    return {
      ...params,
      chunks: [],
      total_chunks: 0,
      variant_chunk_counts: [],
      variant_failures: [],
      retrieval_skipped: true,
      retrieval_skip_reason: 'no_query_direct_unit',
    };
  }

  const variantChunkCounts = [];
  const variantFailures = [];
  const candidates = [];
  let totalChunks = 0;
  let order = 0;

  const retryOptions = {
    maxAttempts: params.ragflow_retry_attempts ?? params.retry_attempts ?? 1,
    baseDelayMs: params.ragflow_retry_delay_ms ?? params.retry_delay_ms ?? 1000,
    timeoutMs: params.ragflow_request_timeout_ms ?? params.request_timeout_ms ?? 30000,
  };
  // RAG_VARIANT_DEDUP_PARALLEL_V7：同一次执行里前面的检索单元已请求过的变体（问句 + 数据集相同）不再重复请求，
  // 其余变体并发请求。MT25 T10 exec 154594：5 个按子问题类型克隆的检索单元共 30 个变体，14 个完全重复，
  // 且逐个串行（每个约 7 秒），检索合计 240 秒。
  const variantConcurrency = 3;
  const groupStartMs = Date.now();
  const groupTimeoutMs = Math.max(5000, Number(params.ragflow_group_timeout_ms ?? params.group_timeout_ms ?? 56000));
  const __variantKey = (p, v) => String((v && v.question) || '').replace(/\s+/g, ' ').trim() + '|' +
    JSON.stringify((Array.isArray(v && v.dataset_ids) && v.dataset_ids.length ? v.dataset_ids : (Array.isArray(p && p.dataset_ids) ? p.dataset_ids : [])).map(String).sort());
  const __doneKeys = new Set();
  try {
    const ri = typeof $runIndex === 'number' ? $runIndex : 0;
    for (let r = 0; r < ri; r += 1) {
      const prev = $('Grouped RAGFlow Retrieval').all(0, r)[0];
      const pp = (prev && prev.json && prev.json.unit && prev.json.unit.params) || {};
      for (const v of (Array.isArray(pp.query_variants) ? pp.query_variants : [])) __doneKeys.add(__variantKey(pp, v));
    }
  } catch (e) {}
  const __fresh = [], __dups = [];
  variants.forEach((variant, variantIndex) => { (__doneKeys.has(__variantKey(params, variant)) ? __dups : __fresh).push({ variant, variantIndex }); });
  if (!__fresh.length && __dups.length) __fresh.push(__dups.shift()); // 至少请求 1 个变体
  for (const d of __dups) {
    variantChunkCounts.push({ variant_id: d.variant.variant_id, lang_variant: d.variant.lang_variant, question: d.variant.question,
      status: 'skipped_already_retrieved_by_earlier_unit', chunk_count: 0 });
  }
  const retrievalResults = await mapWithConcurrency(__fresh, variantConcurrency, async ({ variant, variantIndex }) => {
    const elapsedMs = Date.now() - groupStartMs;
    const remainingMs = groupTimeoutMs - elapsedMs - 1000;

    if (remainingMs <= 1000) {
      return {
        variant,
        variantIndex,
        retrieval: {
          ok: false,
          attempts: 0,
          error: 'Skipped because grouped retrieval time budget was exhausted before this variant.',
        },
        chunks: [],
      };
    }

    const payload = buildPayload(params, variant);
    const perVariantOptions = {
      ...retryOptions,
      timeoutMs: Math.max(1000, Math.min(Number(retryOptions.timeoutMs || 20000), remainingMs)),
    };
    const retrieval = await retrieveVariant(retrievalUrl, headers, payload, verifySsl, variant, perVariantOptions);
    return {
      variant,
      variantIndex,
      retrieval,
      chunks: retrieval.ok ? extractChunks(retrieval.response) : [],
    };
  });

  for (const retrievalResult of retrievalResults) {
    const variant = retrievalResult.variant;
    const retrieval = retrievalResult.retrieval;

    if (!retrieval.ok) {
      const failure = {
        variant_id: variant.variant_id,
        lang_variant: variant.lang_variant,
        question: variant.question,
        status: 'failed',
        attempts: retrieval.attempts,
        error: retrieval.error,
      };
      variantFailures.push(failure);
      variantChunkCounts.push({
        ...failure,
        chunk_count: 0,
      });
      continue;
    }

    const chunks = retrievalResult.chunks;
    totalChunks += chunks.length;
    variantChunkCounts.push({
      variant_id: variant.variant_id,
      lang_variant: variant.lang_variant,
      question: variant.question,
      status: 'ok',
      attempts: retrieval.attempts,
      chunk_count: chunks.length,
    });

    for (const chunk of chunks) {
      const text = getChunkText(chunk);
      if (!text) continue;
      candidates.push({
        chunk,
        text,
        variant,
        order,
      });
      order += 1;
    }
  }

  if (!candidates.length && variantFailures.length) {
    candidates.push({
      chunk: {
        document_name: 'RAGFlow retrieval status',
        dataset_name: 'RAGFlow',
        content: 'No RAGFlow chunks were retrieved for this query group because all query variants failed or timed out: ' +
          variantFailures.map((f) => f.variant_id + ': ' + f.error).join(' | ').slice(0, 1600),
        score: 0,
      },
      text: 'No RAGFlow chunks were retrieved for this query group because all query variants failed or timed out: ' +
        variantFailures.map((f) => f.variant_id + ': ' + f.error).join(' | ').slice(0, 1600),
      variant: {
        variant_id: 'retrieval_group_failure',
        lang_variant: 'status',
        question: params.question || '',
      },
      order,
      retrieval_status_only: true,
    });
    order += 1;
  }

  // DOC_TAG_MATCH_REMOVED_V1（11-13）：原 TAG_IDENTITY_PROBE_V7 按位号补查身份已删除——74 次执行触发 6 次、5 次位号与问题无关、
  // 进证据包 1 段、被引用 0 次；位号身份原文由位号资料检索单元（TAG_DOCUMENT_RETRIEVAL_V7，按「位号.PV」查）取回。

  const maxEvidenceRaw = params.max_grouped_evidence_chunks ?? params.max_evidence_chunks ?? params.post_rag_max_evidence_chunks ?? 80;
  const maxEvidenceText = String(maxEvidenceRaw).trim().toLowerCase();
  const unlimitedEvidence =
    maxEvidenceRaw === undefined ||
    maxEvidenceRaw === null ||
    maxEvidenceText === '' ||
    ['all', 'unlimited', 'none', '0'].includes(maxEvidenceText);
  const maxEvidence = Number(maxEvidenceRaw);
  const selectedLimit =
    unlimitedEvidence || !(Number.isFinite(maxEvidence) && maxEvidence > 0)
      ? Infinity
      : maxEvidence;
  const rankContext = buildRankContext(params, unit, item, variants);
  // RAGFLOW_DOCUMENT_KEYWORD_NAME_V7：数据集 id→名称 取自目录
  __datasetNameById = new Map();
  try {
    const __ds = (((item.catalog || {}).ragflow || {}).datasets) || [];
    for (const d of __ds) {
      if (d && d.id && d.name) __datasetNameById.set(String(d.id), String(d.name));
    }
  } catch (e) {}
  const __chunkFieldNames = (() => {
    const first = candidates.find(c => c && c.chunk && !c.retrieval_status_only);
    return first ? Object.keys(first.chunk).filter(k => !/^(content|content_ltks|content_with_weight|vector|highlight)$/.test(k)) : [];
  })();
  const selected = selectedEvidence(candidates, selectedLimit, rankContext, {
    nearDuplicateThreshold: params.post_rag_near_duplicate_threshold ?? 0.74,
    maxPerDocument: params.post_rag_max_chunks_per_document ?? 20,
    maxPerVariant: params.post_rag_max_chunks_per_variant ?? 40,
  });
  const postRagRankerStats = selectedEvidence.lastStats || {};
  const { evidence_summary, evidence_digest } = evidenceObjects(selected);

  const noEvidence = evidence_summary.length === 0;
  const result = {
    tool: 'ragflow_retrieval',
    status: 'ok',
    raw_result: {
      retrieval_mode: 'deterministic_grouped_http',
      chunk_count: totalChunks,
      candidate_text_chunk_count: candidates.length,
      deduped_selected_chunk_count: evidence_summary.length,
      variant_count: variants.length,
      variant_chunk_counts: variantChunkCounts,
      variant_failures: variantFailures,
      failed_variant_count: variantFailures.length,
      retry_attempts: Number(retryOptions.maxAttempts || 1),
      request_timeout_ms: Number(retryOptions.timeoutMs || 30000),
      group_timeout_ms: groupTimeoutMs,
      variant_concurrency: variantConcurrency,
      max_evidence_chunks: selectedLimit === Infinity ? 'all' : selectedLimit,
      post_rag_ranker: postRagRankerStats,
      chunk_field_names: __chunkFieldNames,
    },
    answer: noEvidence
      ? 'NO_EVIDENCE'
      : 'Retrieved and combined RAGFlow evidence across ' + variants.length + ' query variant(s); deterministically ranked, near-deduplicated, and selected ' + evidence_summary.length + ' chunk(s) for synthesis.',
    evidence_summary,
    evidence_digest,
    analysis_notes: [
      {
        note_type: 'retrieval_group',
        text: 'Deterministic grouped retrieval ran all query variants first, retried transient retrieval failures, continued past failed variants when other variants returned evidence, combined chunks, exact- and near-deduplicated them, ranked them deterministically by query-token coverage plus RAGFlow score, and passed the selected evidence to the deterministic normalizer and one final answer pass.',
        related_evidence_indices: [],
        related_claim_indices: [],
      },
    ],
  };

  outputItems.push({
    json: {
      ...item,
      output: JSON.stringify(result),
    },
    pairedItem: inputItem.pairedItem,
  });
}

return outputItems;

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function asObject(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function asString(value) {
  return typeof value === 'string' ? value.trim() : '';
}

function cleanText(value, maxLength = 4000) {
  const text = String(value == null ? '' : value)
    .replace(/\s+/g, ' ')
    .trim();
  return text.length > maxLength ? text.slice(0, maxLength) : text;
}

function parseRequestedDateRange(question) {
  const text = String(question || '');
  const lower = text.toLowerCase();
  const months = {
    january: 1, jan: 1, february: 2, feb: 2, march: 3, mar: 3,
    april: 4, apr: 4, may: 5, june: 6, jun: 6, july: 7, jul: 7,
    august: 8, aug: 8, september: 9, sept: 9, sep: 9,
    october: 10, oct: 10, november: 11, nov: 11, december: 12, dec: 12
  };


  // --- Chinese date expressions (added 2026-08-10) ---
  // Without these the parser returned null for every Chinese question, so
  // should_resolve_factors was always false and factor resolution never ran.
  const cnFull = text.match(
    /(20\d{2})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日?\s*(?:至|到|~|-|—|–)\s*(?:(20\d{2})\s*年\s*)?(?:(\d{1,2})\s*月\s*)?(\d{1,2})\s*日/
  );
  if (cnFull) {
    const sy = Number(cnFull[1]);
    const sm = Number(cnFull[2]);
    const sd = Number(cnFull[3]);
    const ey = Number(cnFull[4] || cnFull[1]);
    const em = Number(cnFull[5] || cnFull[2]);
    const ed = Number(cnFull[6]);
    const pad = (n) => String(n).padStart(2, '0');
    return [
      `${sy}-${pad(sm)}-${pad(sd)} 00:00:00`,
      `${ey}-${pad(em)}-${pad(ed)} 23:59:59`
    ];
  }

  // SINGLE_DAY_PERIOD_V8：写到具体某一天（2025年5月7日 / 5月7号 / 2025-05-07）时按天取数；原先落到下面的整月分支，
  // 问 5 月 7 日拿到整个 5 月的统计（10-21 答案反馈 Q3；exec 175454 证据 E4 均值 17.4426、样本 44640）。几个日期时取最早到最晚。
  const cnDays = Array.from(text.matchAll(/(20\d{2})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*[日号]|(20\d{2})-(\d{1,2})-(\d{1,2})(?!\d)/g))
    .map(m => ({ y: Number(m[1] || m[4]), m: Number(m[2] || m[5]), d: Number(m[3] || m[6]) }))
    .filter(x => x.m >= 1 && x.m <= 12 && x.d >= 1 && x.d <= new Date(Date.UTC(x.y, x.m, 0)).getUTCDate())
    .sort((a, b) => (a.y * 400 + a.m * 32 + a.d) - (b.y * 400 + b.m * 32 + b.d));
  if (cnDays.length) {
    const a = cnDays[0], b = cnDays[cnDays.length - 1];
    const pad = n => String(n).padStart(2, '0');
    return [`${a.y}-${pad(a.m)}-${pad(a.d)} 00:00:00`, `${b.y}-${pad(b.m)}-${pad(b.d)} 23:59:59`];
  }

  // MONTH_RANGE_PERIOD_V1：「2025年1月至3月」「2025年1-3月」「2025年11月到2026年2月」按整段月份取数（原先只认到第一个「YYYY年M月」，196018 只取了 1 月）
  const cnMonthRange = text.match(/(20\d{2})\s*年\s*(\d{1,2})\s*月?\s*(?:至|到|~|-|—|–)\s*(?:(20\d{2})\s*年\s*)?(\d{1,2})\s*月/);
  if (cnMonthRange) {
    const sy = Number(cnMonthRange[1]), sm = Number(cnMonthRange[2]);
    const ey = Number(cnMonthRange[3] || cnMonthRange[1]), em = Number(cnMonthRange[4]);
    if (sm >= 1 && sm <= 12 && em >= 1 && em <= 12 && ey * 12 + em >= sy * 12 + sm) {
      const pad = n => String(n).padStart(2, '0');
      const last = String(new Date(Date.UTC(ey, em, 0)).getUTCDate()).padStart(2, '0');
      return [`${sy}-${pad(sm)}-01 00:00:00`, `${ey}-${pad(em)}-${last} 23:59:59`];
    }
  }

  // DOCUMENT_PERIOD_RELATION_V7：问句含多个「YYYY年M月」时取最早到最晚的整月区间（report8 Q8「2025年1月和2025年2月」原只取到 1 月）。
  const cnMonths = Array.from(text.matchAll(/(20\d{2})\s*年\s*(\d{1,2})\s*月/g))
    .map(m => ({ y: Number(m[1]), m: Number(m[2]) }))
    .filter(x => x.m >= 1 && x.m <= 12)
    .sort((a, b) => (a.y * 12 + a.m) - (b.y * 12 + b.m));
  if (cnMonths.length) {
    const a = cnMonths[0], b = cnMonths[cnMonths.length - 1];
    const pad = n => String(n).padStart(2, '0');
    const last = String(new Date(Date.UTC(b.y, b.m, 0)).getUTCDate()).padStart(2, '0');
    return [`${a.y}-${pad(a.m)}-01 00:00:00`, `${b.y}-${pad(b.m)}-${last} 23:59:59`];
  }

  if (/上个?月|上月/.test(text)) {
    const prior = new Date();
    prior.setUTCDate(1);
    prior.setUTCHours(0, 0, 0, 0);
    prior.setUTCMonth(prior.getUTCMonth() - 1);
    const y = prior.getUTCFullYear();
    const m = prior.getUTCMonth() + 1;
    const mm = String(m).padStart(2, '0');
    const last = String(new Date(Date.UTC(y, m, 0)).getUTCDate()).padStart(2, '0');
    return [`${y}-${mm}-01 00:00:00`, `${y}-${mm}-${last} 23:59:59`];
  }

  if (/近一个月|最近一个月|过去一个月|近30天|最近30天/.test(text)) {
    const end = new Date();
    const start = new Date(end.getTime() - 30 * 24 * 60 * 60 * 1000);
    const fmt = (d) =>
      `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}-${String(d.getUTCDate()).padStart(2, '0')}`;
    return [`${fmt(start)} 00:00:00`, `${fmt(end)} 23:59:59`];
  }

  const explicitRange = text.match(/\b(20\d{2})-(\d{1,2})-(\d{1,2})\b\s*(?:to|through|until|[-–—])\s*\b(20\d{2})-(\d{1,2})-(\d{1,2})\b/i);
  if (explicitRange) {
    const start = `${explicitRange[1]}-${String(explicitRange[2]).padStart(2, '0')}-${String(explicitRange[3]).padStart(2, '0')} 00:00:00`;
    const end = `${explicitRange[4]}-${String(explicitRange[5]).padStart(2, '0')}-${String(explicitRange[6]).padStart(2, '0')} 23:59:59`;
    return [start, end];
  }

  let year = null;
  let month = null;
  const named = lower.match(/\b(january|jan|february|feb|march|mar|april|apr|may|june|jun|july|jul|august|aug|september|sept|sep|october|oct|november|nov|december|dec)\s+(20\d{2})\b/i);
  if (named) {
    month = months[named[1].toLowerCase()];
    year = Number(named[2]);
  }

  if (!year || !month) {
    const isoMonth = lower.match(/\b(20\d{2})[-/](0?[1-9]|1[0-2])\b/);
    if (isoMonth) {
      year = Number(isoMonth[1]);
      month = Number(isoMonth[2]);
    }
  }

  if (!year || !month) {
    if (/last\s+month/i.test(lower)) {
      const prior = new Date();
      prior.setUTCDate(1);
      prior.setUTCHours(0, 0, 0, 0);
      prior.setUTCMonth(prior.getUTCMonth() - 1);
      year = prior.getUTCFullYear();
      month = prior.getUTCMonth() + 1;
    }
  }

  if (!year || !month) return null;
  const mm = String(month).padStart(2, '0');
  const lastDay = String(new Date(Date.UTC(year, month, 0)).getUTCDate()).padStart(2, '0');
  return [`${year}-${mm}-01 00:00:00`, `${year}-${mm}-${lastDay} 23:59:59`];
}

function compactRagUnit(unit) {
  const normalized = asObject(unit.normalized_result);
  const raw = asObject(unit.raw_result);
  const claims = asArray(unit.claims).length ? asArray(unit.claims) : asArray(normalized.claims);
  const answerItems = asArray(unit.answer_items).length ? asArray(unit.answer_items) : asArray(normalized.answer_items);
  const digest = asArray(unit.evidence_digest).length ? asArray(unit.evidence_digest) : asArray(normalized.evidence_digest);

  return {
    unit_id: unit.unit_id,
    question_part: unit.question_part || 'other',
    query: cleanText(asObject(unit.params).question || asObject(unit.params).query || '', 1000),
    answer: cleanText(unit.answer || normalized.answer || '', 5000),
    claims: claims.slice(0, 40),
    answer_items: answerItems.slice(0, 40),
    evidence_digest: digest.slice(0, 40),
    retrieval_metadata: {
      chunk_count: raw.chunk_count == null ? null : raw.chunk_count,
      variant_count: raw.variant_count == null ? null : raw.variant_count
    }
  };
}

const item = $input.first().json || {};
const units = asArray(item.completed_units);
const originalQuestion = asString(item.originalUserMessage);
// FOLLOWUP_RESOLVED_PERIOD_V1：追问原话常不带完整日期（「那3月的回炼比呢？」「计算当天…的压降」），原先只解析原话，
// 时段为空 → 因子解析不跑、Coverage Retry 按默认近 90 天取数（副本 196521 回炼比算成 9–12 月，196524 压降没算，196517 新鲜进料没走知识库）。
// 原话没有时段时依次用：拆题给出的 resolved_question；拆题认定所接那一轮（memory_resolution.matched_turns）的取数时段（问题卡 data_scope.windows）。
let dateRange = parseRequestedDateRange(originalQuestion);
let __periodSource = dateRange ? 'question' : null;
if (!dateRange) {
  try {
    const __raw = $('Decompose Question').first().json || {};
    let __d = __raw.output !== undefined ? __raw.output : __raw;
    if (typeof __d === 'string') { const a = __d.indexOf('{'), b = __d.lastIndexOf('}'); __d = a >= 0 && b > a ? JSON.parse(__d.slice(a, b + 1)) : {}; }
    __d = asObject(__d);
    const __bind = asObject(__d.context_binding), __mem = asObject(__d.memory_resolution);
    if (__d.is_follow_up === true || __bind.used_history === true || __mem.depends_on_history === true) {
      dateRange = parseRequestedDateRange(asString(__d.resolved_question));
      if (dateRange) __periodSource = 'resolved_question';
      if (!dateRange) {
        const __matched = asArray(__mem.matched_turns).map(x => asString(x));
        const __recent = asArray(asObject(($('Relevant Memory Retriever').first().json || {}).retrieval_state).recent_turns);
        const __t = __recent.find(t => __matched.includes(asString(asObject(t).turn_ref)) && asArray(asObject(t).data_period).length);
        const __w = __t ? asArray(asArray(__t.data_period)[0]) : [];
        if (__w.length === 2 && __w.every(x => !Number.isNaN(Date.parse(asString(x).replace(' ', 'T'))))) {
          dateRange = [asString(__w[0]), asString(__w[1])];
          __periodSource = 'previous_turn_period:' + asString(__t.turn_ref);
        }
      }
    }
  } catch (e) {}
}
const alreadyResolved =
  item.factor_resolution_completed === true ||
  units.some(unit =>
    unit &&
    ['arctic_resolve_factors', 'mongo_resolve_factors']
      .includes(asString(unit.tool).toLowerCase())
  );
const isConversationSummary = String(item.answer_mode || '').toLowerCase() === 'conversation_summary';
const hasFactorIntent = units.some(unit => unit && unit.question_part === 'factor_identification');
const hasRangeIntent = units.some(unit => unit && unit.question_part === 'target_or_ideal_range');
const hasPeriodIntent = units.some(unit => unit && unit.question_part === 'period_verification');
const ragUnits = units.filter(unit =>
  unit &&
  unit.tool === 'ragflow_retrieval' &&
  (unit.execution_status === 'SUCCESS' || unit.answer || asArray(asObject(unit.normalized_result).claims).length)
);

// HISTORIAN_GAP_FACTOR_RESOLUTION_V7：规划器排了按期核验的取数单元、整轮却没有任何实测数据时，
// 同样走因子解析——从检索证据里找出要核验的量及其位号，再去历史库取数（报告题 Q5 exec 149351：
// 规程写明「反应压力指沉降器顶部压力 PR3112」，位号检索却以原问句措辞落空，整轮零实测）。
const __rawOf = unit => {
  const direct = asObject(asObject(unit).raw_result);
  return Object.keys(direct).length ? direct : asObject(asObject(asObject(unit).normalized_result).raw_result);
};
const __plannedData = units.some(unit =>
  unit && unit.question_part === 'period_verification' && asString(unit.tool) !== 'ragflow_retrieval'
);
const __gotMeasured = units.some(unit => {
  const r = __rawOf(unit);
  return Object.keys(asObject(r.column_stats)).length > 0 ||
    asArray(r.period_profile).length > 0 ||
    asArray(r.records).length > 0;
});
const historianGap = __plannedData && !__gotMeasured;

const shouldResolveFactors = Boolean(
  !alreadyResolved &&
  !isConversationSummary &&
  dateRange &&
  hasPeriodIntent &&
  (hasFactorIntent || hasRangeIntent || historianGap) &&
  ragUnits.length
);

return [{
  json: {
    ...item,
    should_resolve_factors: shouldResolveFactors,
    factor_resolution_date_range: dateRange,
    factor_resolution_period_source: __periodSource,
    factor_resolution_trigger: shouldResolveFactors ? (historianGap && !(hasFactorIntent || hasRangeIntent) ? 'historian_gap' : 'factor_or_range_intent') : null,
    factor_resolution_reason: shouldResolveFactors
      ? (historianGap && !(hasFactorIntent || hasRangeIntent)
        ? 'Data units were planned for an explicit period but returned no measured data; resolving the quantities named in the evidence.'
        : 'RAG factor/range evidence and an explicit verification period are available.')
      : alreadyResolved
        ? 'Factor resolution has already completed.'
        : !dateRange
          ? 'No explicit month or date range was found.'
          : 'The execution did not contain the required factor, range, period, and RAG evidence combination.',
    // UNIT_TRANSPORT_SLIM_V7b：只在要做因子解析时附带（约 1.7MB，只有 Factor Extractor LLM 读）
    ...(shouldResolveFactors ? { factor_extraction_packet: {
      original_question: originalQuestion,
      date_range: dateRange,
      instructions: 'Extract only measurable operating factors and their documented targets/ranges from this evidence.',
      rag_units: ragUnits.map(compactRagUnit)
    } } : {})
  }
}];

