// GENERIC_FACTOR_RECOVERY_V1
function cleanJsonText(value) {
  if (typeof value !== 'string') return '';
  const fence = String.fromCharCode(96).repeat(3);
  let cleaned = value.trim();
  if (cleaned.toLowerCase().startsWith(fence + 'json')) cleaned = cleaned.slice(fence.length + 4).trim();
  else if (cleaned.startsWith(fence)) cleaned = cleaned.slice(fence.length).trim();
  if (cleaned.endsWith(fence)) cleaned = cleaned.slice(0, -fence.length).trim();
  return cleaned;
}

function safeParse(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  const cleaned = cleanJsonText(value);
  if (!cleaned) return {};
  try { return JSON.parse(cleaned); } catch {}
  const first = cleaned.indexOf('{');
  const last = cleaned.lastIndexOf('}');
  if (first >= 0 && last > first) {
    try { return JSON.parse(cleaned.slice(first, last + 1)); } catch {}
  }
  return {};
}

function recoverFactorObjects(value) {
  const cleaned = cleanJsonText(value);
  const keyMatch = /"factors"\s*:\s*\[/i.exec(cleaned);
  if (!keyMatch) return { factors: [], rejected: 0 };
  const arrayStart = keyMatch.index + keyMatch[0].lastIndexOf('[') + 1;
  const factors = [];
  let rejected = 0;
  let objectStart = -1;
  let depth = 0;
  let inString = false;
  let escaped = false;

  for (let i = arrayStart; i < cleaned.length; i++) {
    const ch = cleaned[i];
    if (inString) {
      if (escaped) escaped = false;
      else if (ch === '\\') escaped = true;
      else if (ch === '"') inString = false;
      continue;
    }
    if (ch === '"') {
      inString = true;
      continue;
    }
    if (ch === '{') {
      if (depth === 0) objectStart = i;
      depth++;
      continue;
    }
    if (ch === '}' && depth > 0) {
      depth--;
      if (depth === 0 && objectStart >= 0) {
        const candidate = cleaned.slice(objectStart, i + 1);
        try {
          const parsed = JSON.parse(candidate);
          if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) factors.push(parsed);
          else rejected++;
        } catch {
          rejected++;
        }
        objectStart = -1;
      }
      continue;
    }
    if (ch === ']' && depth === 0) break;
  }
  if (objectStart >= 0 || depth !== 0) rejected++;
  return { factors, rejected };
}
function latestNodeJson(name) {
  try {
    const items = $(name).all();
    return items.length ? (items[items.length - 1].json || {}) : {};
  } catch {
    return {};
  }
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function asString(value) {
  return typeof value === 'string' ? value.trim() : '';
}

const base = latestNodeJson('Prepare Factor Resolution');
const extractorValue = ($input.first().json || {}).output || $input.first().json || {};
const parsed = safeParse(extractorValue);
const recovered = asArray(parsed.factors).length
  ? { factors: asArray(parsed.factors), rejected: 0 }
  : recoverFactorObjects(extractorValue);
const factorInputs = asArray(parsed.factors).length ? asArray(parsed.factors) : recovered.factors;
const seen = new Set();
const factors = [];

for (const raw of factorInputs) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) continue;
  const name = asString(raw.name || raw.factor || raw.condition);
  if (!name) continue;
  const key = name.toLowerCase().replace(/\s+/g, ' ');
  if (seen.has(key)) continue;
  seen.add(key);
  factors.push({
    ...raw,
    factor_id: asString(raw.factor_id || raw.id) || `F${factors.length + 1}`,
    name,
    evidence_ids: asArray(raw.evidence_ids).map(String).filter(Boolean).slice(0, 12)
  });
  if (factors.length >= 20) break;
}

const existingIds = asArray(base.completed_units)
  .map(unit => Number(unit && unit.unit_id))
  .filter(Number.isFinite);
const unitId = (existingIds.length ? Math.max(...existingIds) : 0) + 1;

return [{
  json: {
    ...base,
    factor_resolution_ready: factors.length > 0,
    factor_resolution_skip_reason: factors.length ? '' : 'The Factor Extractor returned no evidence-supported measurable factors.',
    extracted_factors: factors,
    factor_extractor_trace: parsed,
    factor_extractor_parse: {
      mode: asArray(parsed.factors).length ? 'full_json' : (recovered.factors.length ? 'factor_recovery' : 'failed'),
      recovered_factor_count: asArray(parsed.factors).length ? 0 : recovered.factors.length,
      rejected_factor_count: recovered.rejected
    },
    unit: {
      unit_id: unitId,
      tool: 'arctic_resolve_factors',
      params: {
        factors,
        date_range: base.factor_resolution_date_range
      },
      depends_on: [],
      question_part: 'period_verification',
      required_evidence_types: ['measured_verification'],
      optional_evidence_types: ['tag_or_signal_discovery', 'data_quality_or_availability'],
      allow_synthesis: true
    }
  }
}];

function safeParse(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  if (typeof value !== 'string') return {};

  const cleaned = value
    .trim()
    .replace(/^\`\`\`json\s*/i, '')
    .replace(/^\`\`\`\s*/i, '')
    .replace(/\`\`\`$/i, '')
    .trim();

  try {
    return asObject(JSON.parse(cleaned));
  } catch {}

  const first = cleaned.indexOf('{');
  const last = cleaned.lastIndexOf('}');

  if (first >= 0 && last > first) {
    try {
      return asObject(JSON.parse(cleaned.slice(first, last + 1)));
    } catch {}
  }

  return {};
}

function latestNodeJson(name) {
  try {
    const items = $(name).all();

    return items.length
      ? asObject(items[items.length - 1]?.json)
      : {};
  } catch {
    return {};
  }
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function asObject(value) {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? value
    : {};
}

function asString(value) {
  return typeof value === 'string' ? value.trim() : '';
}

// Compare both public MongoDB names and legacy internal names consistently.
function internalTool(value) {
  const tool = asString(value).toLowerCase();

  const aliases = {
    mongo_find_tags: 'arctic_find_tags',
    mongo_stats: 'arctic_stats',
    mongo_read: 'arctic_read',
    mongo_analyze: 'arctic_analyze',
    mongo_describe: 'arctic_describe',
    mongo_resolve_factors: 'arctic_resolve_factors'
  };

  return aliases[tool] || tool;
}

function compact(value, maxLength = 1600) {
  const text = typeof value === 'string'
    ? value
    : JSON.stringify(value == null ? '' : value);

  const cleaned = String(text ?? '').replace(/\s+/g, ' ').trim();

  return cleaned.length > maxLength
    ? cleaned.slice(0, maxLength)
    : cleaned;
}

function factorName(result, index) {
  const factor = asObject(result.factor);

  return asString(
    factor.name ||
    factor.factor ||
    factor.condition ||
    result.name
  ) || `Factor ${index + 1}`;
}

function statSummary(stat) {
  const name = asString(stat.tag) || 'unknown tag';
  const status = asString(stat.data_status) || 'unknown';
  const pieces = [`${name} (${status})`];

  for (const key of ['mean', 'min', 'max', 'latest', 'count', 'std']) {
    if (stat[key] != null) {
      pieces.push(`${key}=${stat[key]}`);
    }
  }
  // UNIT_CONFIRM_V1：写上单位与来源（推断的标明把握）
  if (stat.unit) {
    const src = { plant_knowledge: '装置知识库', dictionary: '同义词库', inferred: '推断' }[asString(stat.unit_source)];
    pieces.push('unit=' + stat.unit + (src ? '（' + src + (asString(stat.unit_source) === 'inferred' && asString(stat.unit_confidence) !== 'high' ? '，把握不大' : '') + '）' : ''));
  }

  return pieces.join(', ');
}

// COVERAGE_RETRY_V7：解析请求可能来自首轮因子抽取，也可能来自覆盖补检；以单元编号较大的（最近构建的）为准
// DERIVED_QUANTITY_CHECK_V8：两路送进解析服务前都经过 Apply Derived Quantities（计算量已换成构成量），以它为准；取不到时按原来的取法
const __applied = latestNodeJson('Apply Derived Quantities');
const base = (__applied.factor_resolution_ready && asObject(__applied.unit).unit_id != null ? __applied : null) || [latestNodeJson('Build Factor Resolution Unit'), latestNodeJson('Coverage Retry')]
  .filter(x => x && x.factor_resolution_ready && asObject(x.unit).unit_id != null)
  .sort((a, b) => Number(asObject(b.unit).unit_id) - Number(asObject(a.unit).unit_id))[0] || latestNodeJson('Build Factor Resolution Unit');
const __coverageRetry = asObject(asObject(base.unit).params).coverage_retry === true;
const executorItem = asObject($input.first()?.json);

// Prefer structured results over prose. Every candidate is object-guarded.
const resolverCandidates = [
  executorItem,
  safeParse(executorItem.body),
  safeParse(executorItem.output),
  safeParse(executorItem.answer)
];

function hasResolverError(candidate) {
  return Boolean(candidate.error) ||
    asString(candidate.status).toLowerCase() === 'error';
}

const parsed = resolverCandidates.find(candidate =>
  Array.isArray(candidate.factor_results) ||
  Array.isArray(asObject(candidate.raw_result).factor_results)
) || resolverCandidates.find(hasResolverError) || {
  status: 'error',
  error: {
    code: 'INVALID_FACTOR_RESOLVER_RESPONSE',
    message: 'The resolver returned neither a factor_results array nor a recognized error.'
  },
  answer: 'Factor resolution could not be verified because the response had an unexpected format.'
};

// Keep an outer error even when an inner response contains partial results.
const errorEnvelope = resolverCandidates.find(hasResolverError) ||
  (hasResolverError(parsed) ? parsed : null);

const resolverError = errorEnvelope
  ? (
      errorEnvelope.error ||
      asString(errorEnvelope.answer) ||
      'The factor resolver reported an error.'
    )
  : null;

const rawResult = asObject(parsed.raw_result);

let factorResults = (
  asArray(rawResult.factor_results).length
    ? asArray(rawResult.factor_results)
    : asArray(parsed.factor_results)
).filter(result =>
  result &&
  typeof result === 'object' &&
  !Array.isArray(result)
);

// HISTORIAN_SUCCESS_FALLBACK_V2
// The batch resolver is an enrichment path. If it fails, never discard exact
// tags and period statistics already returned successfully by the main loop.
function catalogKey(tag, params) {
  return JSON.stringify([
    asString(params.library) || asString(params.database),
    asString(params.symbol) || asString(params.collection),
    tag
  ]);
}

function parseLegacyTagCatalog(units) {
  const metadata = new Map();

  for (const entry of units) {
    if (internalTool(entry && entry.tool) !== 'arctic_find_tags') continue;
    if (asString(entry.execution_status).toUpperCase() !== 'SUCCESS') continue;

    const params = asObject(entry.params);

    for (const line of asString(entry.answer).split(/\r?\n/)) {
      const match = line.match(
        /^\s*\d+\.\s*([^|]+?)\s*\|\s*([^|]*)\|\s*(.*)$/
      );

      if (!match) continue;

      const tag = match[1].trim();
      if (!tag) continue;

      metadata.set(catalogKey(tag, params), {
        tag,
        desc_cn: match[2].trim(),
        desc_en: match[3].trim(),
        library: asString(params.library) || asString(params.database),
        symbol: asString(params.symbol) || asString(params.collection)
      });
    }
  }

  return metadata;
}

const NUMBER_PATTERN = '[+-]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)(?:[eE][+-]?\\d+)?';

function numberAfter(line, key) {
  const pattern = new RegExp(
    '(?:^|[^A-Za-z0-9_])' +
    key +
    '\\b\\s*(?:=|:)?\\s*(' +
    NUMBER_PATTERN +
    ')',
    'i'
  );

  const match = line.match(pattern);
  const value = match ? Number(match[1]) : NaN;

  return Number.isFinite(value) ? value : null;
}

function unitAfterMean(line) {
  const pattern = new RegExp(
    '\\bmean\\s*(?:=|:)?\\s*' +
    NUMBER_PATTERN +
    '\\s*([^,;\\s]+)?',
    'i'
  );

  const match = line.match(pattern);
  const unit = match && match[1] ? match[1].trim() : '';

  return /^(?:°C|℃|%|kPa|MPa|ppm|t\/h|kg\/h|m3\/h|m³\/h)$/i.test(unit)
    ? unit
    : '';
}

function buildLegacyFactorResults(units) {
  const metadata = parseLegacyTagCatalog(units);
  const results = [];

  for (const entry of units) {
    if (internalTool(entry && entry.tool) !== 'arctic_stats') continue;
    if (asString(entry.execution_status).toUpperCase() !== 'SUCCESS') continue;

    const raw = asObject(entry.raw_result);
    const normalized = asObject(entry.normalized_result);
    const normalizedRaw = asObject(normalized.raw_result);

    const columns = asArray(raw.columns_analyzed).length
      ? asArray(raw.columns_analyzed)
      : asArray(normalizedRaw.columns_analyzed);

    const lines = (
      asString(entry.answer) ||
      asString(normalized.answer)
    ).split(/\r?\n/);

    const params = asObject(entry.params);

    for (const column of columns) {
      const tag = asString(column);
      if (!tag) continue;

      const escaped = tag.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

      const line = lines.find(value =>
        new RegExp(
          '^\\s*-?\\s*' + escaped + '(?:\\s|\\(|:)',
          'i'
        ).test(value)
      ) || '';

      const noData = /all\s+null|no\s+data|zero\s+non-null/i.test(line);

      const meta = metadata.get(catalogKey(tag, params)) || {
        tag,
        desc_cn: '',
        desc_en: '',
        library: asString(params.library) || asString(params.database),
        symbol: asString(params.symbol) || asString(params.collection)
      };

      const unit = unitAfterMean(line);

      const stat = {
        tag,
        description: meta.desc_en || meta.desc_cn || tag,
        mean: noData ? null : numberAfter(line, 'mean'),
        min: noData ? null : numberAfter(line, 'min'),
        max: noData ? null : numberAfter(line, 'max'),
        latest: noData ? null : numberAfter(line, 'latest'),
        count: noData ? 0 : numberAfter(line, 'count'),
        data_status: noData ? 'no_data' : 'ok',
        time_range: asArray(raw.time_range).length
          ? asArray(raw.time_range)
          : asArray(normalizedRaw.time_range),
        warnings: noData
          ? ['No non-null values were returned for the requested period.']
          : []
      };

      // Only preserve rows backed by a parsed statistic or explicit no-data.
      if (
        !noData &&
        [stat.mean, stat.min, stat.max, stat.latest, stat.count]
          .every(value => value == null)
      ) {
        continue;
      }

      results.push({
        factor_id: `LEGACY_${entry.unit_id || 'STAT'}_${results.length + 1}`,
        factor: {
          factor_id: `LEGACY_${entry.unit_id || 'STAT'}_${results.length + 1}`,
          name: meta.desc_en || meta.desc_cn || tag,
          effect: '',
          ideal_range: null,
          unit,
          evidence_ids: []
        },
        tags: [{
          ...meta,
          relation: 'direct',
          confidence: 'high'
        }],
        stats: [stat],
        gap: noData
          ? 'Tag resolved, but no non-null values were returned for the requested period.'
          : '',
        selection_status: 'legacy_success_fallback'
      });
    }
  }

  return results;
}

const resolverHasTags = factorResults.some(row =>
  asArray(asObject(row).tags).length > 0
);

let legacyFallbackUsed = false;

if (!resolverHasTags && !__coverageRetry) {
  const legacyResults = buildLegacyFactorResults(
    asArray(base.completed_units)
  );

  if (legacyResults.length) {
    factorResults = legacyResults;
    legacyFallbackUsed = true;
  }
}

const evidenceSummary = [];
const claims = [];
const answerLines = [];
let usableFactorCount = 0;

factorResults.forEach((result, index) => {
  const row = asObject(result);
  const factor = asObject(row.factor);
  const name = factorName(row, index);
  const tags = asArray(row.tags);
  const stats = asArray(row.stats);

  const usableStats = stats.filter(stat =>
    asString(stat && stat.data_status).toLowerCase() === 'ok'
  );

  if (usableStats.length) {
    usableFactorCount += 1;
  }

  const target =
    factor.ideal_range ??
    factor.target_range ??
    factor.recommended_range ??
    null;

  const tagNames = tags
    .map(tag => asString(tag && tag.tag))
    .filter(Boolean);

  const measurements = stats
    .map(stat => statSummary(asObject(stat)))
    .join('; ');

  const gap = asString(row.gap);

  const statement = [
    name,
    asString(row.kb_note),  // PLANT_KB_FE_AND_DIRECT_V1：知识库口径写在量名之后，不被截短
    asString(row.sum_series_note),  // POINT_SERIES_STATS_V1：几表合计逐点算出的最小、最大、最新、累计，紧跟知识库口径
    target != null
      ? `documented target/range=${compact(target, 500)}`
      : 'no documented numeric target/range',
    tagNames.length
      ? `selected tags=${tagNames.join(', ')}`
      : 'no matching tag selected',
    measurements || 'no period statistics returned',
    gap ? `gap=${gap}` : ''
  ].filter(Boolean).join('; ');

  evidenceSummary.push({
    document_name: 'ArcticDB measured period data',
    dataset_name: 'ArcticDB',
    section_title: name,
    content_summary: compact(statement, 2200),
    key_points: [
      compact(measurements || gap || 'No usable period statistics.', 1200)
    ],
    key_values: stats
      .flatMap(stat =>
        ['mean', 'min', 'max', 'latest', 'count'].map(key =>
          stat && stat[key] != null
            ? `${stat.tag} ${key}=${stat[key]}`
            : ''
        )
      )
      .filter(Boolean)
      .slice(0, 20),
    limitations: gap ? [compact(gap, 800)] : [],
    relevance_to_question: `Measured-period tag resolution and statistics for ${name}.`,
    source_type: 'arcticdb'
  });

  claims.push({
    claim_text: statement,
    evidence_type: 'measured_verification',
    scope: 'measured_period_verification',
    supports_question_part: 'period_verification',
    inferential_use: 'period_evidence',
    analysis_note: legacyFallbackUsed
      ? 'Recovered tags and statistics from previously successful historian units; no new resolver measurement is claimed.'
      : 'The factor-resolution service returned the tag selections and period statistics summarized here.',
    supported_by_evidence_indices: [index + 1]
  });

  answerLines.push(statement);
});

// DERIVED_QUANTITY_COMPUTE_V8：计算量结果（Compute Derived Quantities 由代码算出，或 Prepare Derived Binding 列为未算）放在最前，
// 历史库证据条目正文会被截短，放后面会丢；同一份结构化结果写进 raw_result，终稿与核对模型的实测结果里都能看到。
// 公式与常数在前面已核对好，这里只负责写成文字。
const __derivedResults = asArray(executorItem.derived_quantity_results).concat(asArray(executorItem.derived_not_computed)).filter(x => x && typeof x === 'object');
function __psText(st) {
  if (!st) return '';
  return '按' + st.resolution + '读数逐点算（' + st.points + ' 个时刻' + (st.missing_points ? '，另有 ' + st.missing_points + ' 个时刻输入不全未计' : '') +
    (st.out_of_bounds_points ? '，' + st.out_of_bounds_points + ' 个时刻超出定义范围未计' : '') + '）：最小 ' + st.min + '（' + st.min_time + '）、最大 ' + st.max + '（' + st.max_time + '）、最新 ' + st.latest + '（' + st.latest_time + '）、逐点均值 ' + st.mean + '、标准差 ' + st.std +
    (st.cumulative != null ? '、全时段累计 ' + st.cumulative + ' ' + st.cumulative_unit + '（只计有数的时刻）' : '');
}

const __derivedLines = __derivedResults.map(d => {
  const label = asString(d.source_label || d.name)+(d.result_unit ? ' ('+d.result_unit+')' : '');
  if (d.status !== 'computed') return '计算量 '+label+' 未计算：'+asString(d.reason)+(d.expression ? '；公式 '+d.expression : '');
  const point = d.method === 'point_sample_substitution';
  const basis = point ? '指定时刻单点值' : '时段均值';
  const statics = asArray(d.constants).map(c => c.symbol+'='+c.value+' '+asString(c.unit)+
    (c.source === 'plant_model' ? ' [Plant Model '+c.equipment_tag+'.'+c.field_path+'; status='+c.status+'; '+asString(c.note)+']' : ' [physical constant]'));
  const rows = asArray(d.results).map(r => asArray(r.inputs).map(i =>
    i.symbol+'='+asArray(i.tags).join('+')+' '+(i.value ?? i.period_mean)+' '+asString(i.unit)+(i.unit_note ? '（'+i.unit_note+'）' : '')+
      (point ? ' @ '+asArray(i.timestamps).join(',') : '')).join('; ')+' → '+r.value_rounded+
    // POINT_SERIES_STATS_V1：同一取法逐点代入的最小、最大、最新、累计
    (r.point_series ? '（'+__psText(r.point_series)+'）' : r.point_series_error ? '（逐点未算：'+r.point_series_error+'）' : ''));
  // FORMULA_SOURCE_NOTE_V1：写明公式来源；通用定义（本装置文件没给）的标明请用户确认（用户 11-10：可用通用知识找公式、数据核对、最后用户确认）
  const __fs = asString(d.formula_source) === 'standard_definition' ? '公式来源：通用定义（非本装置文件给出），请用户确认'
    : '公式来源：' + (asString(d.formula_source_doc) || asString(d.formula_source) || '未注明');
  return '计算量 '+label+' = '+d.expression+'（'+__fs+'），由代码按'+basis+'代入计算；请求范围 '+asArray(d.date_range).join(' ~ ')+
    (point ? '；时间基准为历史库时钟标签，未进行时区换算' : '')+
    (statics.length ? '；静态输入 '+statics.join('; ') : '')+'；'+rows.join('; ')+
    (asArray(d.parts_sum_rejected).length ? '；未采用的分支加总：'+asArray(d.parts_sum_rejected).join('; ') : '')+
    // SAME_METER_TWO_INPUTS_V1：被去掉的取法写出来，回答不得再用这种取法另算
    (asArray(d.same_meter_rejected).length ? '；未采用的取法（同一块表不能同时当两个量）：'+asArray(d.same_meter_rejected).join('; ') : '')+
    // COMMON_SENSE_CHECK_V1：常识检查标出的疑点随结果写出；使用该值的回答须同时说明疑点，并以证据核实
    (asArray(asObject(d.common_sense_check).flags).length ? '；常识检查疑点（待核实；使用该值时须同时说明并以证据核实）：'+asArray(asObject(d.common_sense_check).flags).join('；') : '')+
    // FORMULA_SUM_CHECK_V1：同一物流相加时的「只取其一」备选值；结论处与原值并列，不替用户择一
    (asArray(asObject(d.common_sense_check).alternatives).length ? '；若相加的几项是同一物流、只取其一：'+asArray(asObject(d.common_sense_check).alternatives).join('；')+'（结论处须把这些取值与上面的值并列给出并说明疑点，不得只给上面的值）' : '');
});
if (__derivedLines.length) {
  evidenceSummary.unshift({
    document_name: 'ArcticDB measured period data',
    dataset_name: 'ArcticDB',
    section_title: '计算量（Plant Model 静态输入与历史库实测输入）',
    content_summary: compact(__derivedLines.join('\n'), 2200),
    key_points: __derivedLines.map(l => compact(l, 600)).slice(0, 6),
    key_values: [],
    limitations: [],
    relevance_to_question: 'Quantities computed in code from validated static inputs and the reported historian sampling basis.',
    source_type: 'arcticdb'
  });
  claims.unshift({
    claim_text: compact(__derivedLines.join('\n'), 2200),
    evidence_type: 'measured_verification',
    scope: 'measured_period_verification',
    supports_question_part: 'period_verification',
    inferential_use: 'period_evidence',
    analysis_note: 'Computed in code from validated Plant Model references and historian inputs; the reported method distinguishes point samples from period means.',
