  ? answerLines.join('\n')
  : asString(parsed.answer) || 'No factor-resolution result was returned.';

const resolutionRawResult = {
  ...rawResult,
  factor_results: factorResults,
  usable_factor_count: usableFactorCount,
  legacy_fallback_used: legacyFallbackUsed,
  ...(__derivedResults.length ? { derived_quantity_results: __derivedResults } : {}), // DERIVED_QUANTITY_COMPUTE_V8
  ...(resolverError ? { resolver_error: resolverError } : {})
};

const unit = asObject(base.unit);

const newEntry = {
  unit_id: unit.unit_id,

  // Keep the existing internal schema. Result Aggregator publishes mongo_*.
  tool: 'arctic_resolve_factors',

  execution_status: executionStatus,
  source_type: 'sensor_data',
  answer,
  claims,
  answer_items: [],
  analysis_notes: asArray(parsed.analysis_notes),
  evidence_summary: evidenceSummary,
  evidence_digest: evidenceSummary,
  raw_result: resolutionRawResult,
  normalized_result: {
    answer,
    claims,
    analysis_notes: asArray(parsed.analysis_notes),
    evidence_summary: evidenceSummary,
    evidence_digest: evidenceSummary,
    raw_result: resolutionRawResult
  },
  question_part: 'period_verification',
  required_evidence_types: ['measured_verification'],
  optional_evidence_types: [
    'tag_or_signal_discovery',
    'data_quality_or_availability'
  ],
  params: asObject(unit.params),
  depends_on: [],
  allow_synthesis: true
};

// Replace older resolver entries under either name. Retain successful
// historian evidence and preserve the existing failed-unit cleanup policy.
const completed = asArray(base.completed_units)
  .filter(entry => {
    if (
      !entry ||
      typeof entry !== 'object' ||
      Array.isArray(entry)
    ) {
      return false;
    }

    const legacyTool = [
      'arctic_find_tags',
      'arctic_stats',
      'arctic_read',
      'arctic_analyze'
    ].includes(internalTool(entry.tool));

    const legacyFailure = [
      'DEPENDENCY_BLOCKED',
      'TAG_DISCOVERY_FAILED',
      'NO_EVIDENCE'
    ].includes(asString(entry.execution_status).toUpperCase());

    return !(
      legacyTool &&
      legacyFailure &&
      entry.question_part === 'period_verification'
    );
  })
  .filter(entry =>
    internalTool(entry.tool) !== 'arctic_resolve_factors' ||
    Number(entry.unit_id) !== Number(unit.unit_id)
  );

completed.push(newEntry);

return [{
  json: {
    ...base,
    completed_units: completed,
    factor_resolution_completed: true,
    factor_resolution_status: executionStatus,
    factor_resolution_result: newEntry
  }
}];

