// Shared source used to build self-contained n8n replacement code.
function pmObj(v) { return v && typeof v === 'object' && !Array.isArray(v) ? v : {}; }
function pmArr(v) { return Array.isArray(v) ? v : []; }
function pmStr(v) { return typeof v === 'string' ? v.trim() : ''; }
function pmUnit(v) { return pmStr(v).replace(/³/g, '3').replace(/²/g, '2').replace(/\^([23])/g, '$1').replace(/\s+/g, '').toLowerCase(); }
function pmRef(v) {
  const x = pmObj(v);
  return { equipment_tag: pmStr(x.equipment_tag), field_path: pmStr(x.field_path) };
}
function pmKey(v) { const r = pmRef(v); return r.equipment_tag + '|' + r.field_path; }
function pmNormalizeFacts(values) {
  const out = new Map(), conflicts = new Set();
  for (const raw of pmArr(values).slice(0, 24)) {
    const v = pmObj(raw), e = pmObj(v.evidence_envelope);
    const ref = pmRef(v);
    const value = Object.prototype.hasOwnProperty.call(e, 'value') ? e.value : v.value;
    const unit = pmStr(e.unit || v.unit);
    const status = pmStr(e.status || v.status);
    if (!ref.equipment_tag || !/^[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z0-9_]+)*$/.test(ref.field_path)) continue;
    if (!['plant_trace', 'plant_equipment'].includes(v.retrieval_tool) || v.found !== true || typeof value !== 'number' || !Number.isFinite(value) || !unit) continue;
    if (!['source_bound', 'derived', 'field_confirm', 'conflict'].includes(status)) continue;
    const f = { ...ref, value, unit, status, retrieval_tool: v.retrieval_tool, found: true,
      source: pmStr(e.source || v.source), locator: pmStr(e.locator || v.locator),
      note: pmStr(e.note || v.note), grade: e.grade ?? v.grade ?? null,
      quantity: pmStr(v.quantity), section: pmStr(v.section),
      interpretation_basis: pmStr(v.interpretation_basis),
      usable_for_calculation: status === 'source_bound' || status === 'derived' };
    for (const key of ['derivation', 'inputs']) {
      if (Object.prototype.hasOwnProperty.call(e, key)) f[key] = e[key];
      else if (Object.prototype.hasOwnProperty.call(v, key)) f[key] = v[key];
    }
    const key = pmKey(f), old = out.get(key);
    if (old && (old.value !== f.value || pmUnit(old.unit) !== pmUnit(f.unit) || old.status !== f.status)) conflicts.add(key);
    else out.set(key, f);
  }
  return [...out.entries()].filter(([key]) => !conflicts.has(key)).map(([, v]) => v);
}
function pmCurrentFacts(extra) {
  let context = {};
  try { context = pmObj($('Parse Device Context').first().json.device_context); } catch {}
  return pmNormalizeFacts([...pmArr(context.engineering_facts), ...pmArr(extra)]);
}
function pmResolveFact(ref, facts, requestedUnit) {
  const key = pmKey(ref), f = pmArr(facts).find(v => pmKey(v) === key);
  if (!f || !f.usable_for_calculation) return null;
  if (requestedUnit && pmUnit(requestedUnit) !== pmUnit(f.unit)) return null;
  return f;
}
function pmDictionaryUnit(tag) {
  let dictionary = {};
  try { dictionary = pmObj($('Load aliases').first().json.fcc_dictionary); } catch {}
  const normalizeTag = v => pmStr(v).toUpperCase().replace(/\.PV$/, '');
  const wanted = normalizeTag(tag), matches = [];
  for (const row of pmArr(dictionary.tag_groups)) {
    if (pmStr(row['置信度']).toUpperCase() !== 'HIGH') continue;
    const names = [row['规范化位号'],row['代表位号'],...pmStr(row['源位号写法']).split(/[;；,，]/)].map(normalizeTag).filter(Boolean);
    const unit = pmStr(row['工程单位']);
    if (wanted && names.includes(wanted) && unit) matches.push({unit,group_id:pmStr(row['组ID'])});
  }
  const units = new Set(matches.map(m => pmUnit(m.unit)));
  return units.size === 1 ? {unit:matches[0].unit,source:'loaded_dictionary',group_ids:matches.map(m => m.group_id)} : null;
}
function pmTimestampLabel(value) {
  const s = pmStr(value).replace('T', ' ');
  const m = s.match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2})(?::(\d{2}))?/);
  return m ? m[1] + '-' + m[2] + '-' + m[3] + ' ' + m[4] + ':' + m[5] + ':' + (m[6] || '00') : '';
}
function pmPointContract(question) {
  const s = pmStr(question).replace(/：/g, ':');
  const pattern = /(\d{4})(?:年|-|\/)(\d{1,2})(?:月|-|\/)(\d{1,2})(?:日|号)?\s*(?:T|at\s+)?(\d{1,2}):(\d{2})(?::(\d{2}))?/g;
  const found = new Set();
  for (const m of s.matchAll(pattern)) {
    const nums = m.slice(1).map(v => Number(v || 0));
    const [y, mo, d, h, mi, se] = nums;
    const dt = new Date(Date.UTC(y, mo - 1, d, h, mi, se));
    if (dt.getUTCFullYear() !== y || dt.getUTCMonth() + 1 !== mo || dt.getUTCDate() !== d || h > 23 || mi > 59 || se > 59) continue;
    const pad = n => String(n).padStart(2, '0');
    found.add(y + '-' + pad(mo) + '-' + pad(d) + ' ' + pad(h) + ':' + pad(mi) + ':' + pad(se));
  }
  if (found.size !== 1 || /\b(?:UTC|GMT)\b|[+-]\d\d:\d\d|时区|timezone/i.test(s)) return null;
  return { mode: 'point', requested_timestamp: [...found][0],
    timestamp_basis: 'historian_clock_no_timezone_conversion',
    policy: 'Require one non-null sample at the requested historian clock label; retain its original timestamp and offset.' };
}

function asObject(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function asString(value, limit = 500) {
  const text = typeof value === 'string' ? value.replace(/\s+/g, ' ').trim() : '';
  return text.slice(0, limit);
}

function asStringList(value, limit = 20) {
  const values = Array.isArray(value) ? value : [];
  return Array.from(new Set(values.map(v => asString(v, 200)).filter(Boolean))).slice(0, limit);
}

function safeParse(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  if (typeof value !== 'string') return {};
  const text = value.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  if (!text) return {};
  try { return JSON.parse(text); } catch {}
  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  if (first >= 0 && last > first) {
    try { return JSON.parse(text.slice(first, last + 1)); } catch {}
  }
  return {};
}

function compactEvidence(value) {
  const list = Array.isArray(value) ? value : [];
  return list.slice(0, 12).map(entry => {
    const item = asObject(entry);
    return {
      document_id: asString(item.document_id, 200) || null,
      document_name: asString(item.document_name, 300) || null,
      dataset_name: asString(item.dataset_name, 300) || null,
      page_start: item.page_start != null && Number.isFinite(Number(item.page_start)) ? Number(item.page_start) : null,
      page_end: item.page_end != null && Number.isFinite(Number(item.page_end)) ? Number(item.page_end) : null,
      snippet: asString(item.snippet || item.content_summary, 600) || null
