  }).filter(entry => entry.document_name || entry.snippet);
}

// DEVICE_CONTEXT_ENVELOPE_RESTORE_V1
function upstreamEnvelope() {
  try { return $('Relevant Memory Retriever').first().json || {}; } catch {}
  try { return $('Capture context').first().json || {}; } catch {}
  return {};
}

return $input.all().map(item => {
  const upstream = upstreamEnvelope();
  const source = item.json || {};
  const parsed = safeParse(source.output || source.device_context || source);
  const candidate = asObject(parsed.device);
  const engineeringFacts = pmNormalizeFacts(parsed.engineering_facts);
  const evidence = compactEvidence([
    ...(Array.isArray(parsed.evidence) ? parsed.evidence : []),
    ...engineeringFacts.map(f => ({document_name:'Plant Model '+f.retrieval_tool+' '+f.equipment_tag+'.'+f.field_path,
      snippet:f.value+' '+f.unit+'; status='+f.status+'; '+f.note+
        (f.interpretation_basis ? '; interpretation_basis='+f.interpretation_basis : '')}))
  ]);
  const requested = parsed.status !== 'not_applicable';
  const retrievalPerformed = parsed.retrieval_performed === true;
  const hasDevice = Boolean(
    asString(candidate.canonical_name) ||
    asStringList(candidate.identifiers).length ||
    asStringList(candidate.aliases).length
  );
  const allowedStatuses = new Set(['resolved', 'ambiguous', 'not_found', 'not_applicable', 'unavailable', 'error']);
  let status = asString(parsed.status, 40).toLowerCase();
  if (!allowedStatuses.has(status)) status = 'error';
  if ((status === 'resolved' || status === 'ambiguous') && (!hasDevice || !evidence.length)) status = 'error';

  const deviceContext = {
    schema_version: 'device_context_v2',
    engineering_facts: engineeringFacts,
    requested,
    status,
    retrieval_performed: retrievalPerformed,
    retrieval_query: asString(parsed.retrieval_query, 1000) || null,
    device: hasDevice ? {
      canonical_name: asString(candidate.canonical_name, 300) || null,
      identifiers: asStringList(candidate.identifiers),
      aliases: asStringList(candidate.aliases),
      unit: asString(candidate.unit, 300) || null,
      description: asString(candidate.description, 800) || null
    } : null,
    evidence,
    note: asString(parsed.note, 500) || null
