  return {
    json: {
      ...upstream,
      ...source,
      device_context: deviceContext,
      engineering_facts: engineeringFacts,
      device_resolution_debug: {
        status,
        retrieval_performed: retrievalPerformed,
        evidence_count: evidence.length,
        has_device: hasDevice
      }
    }
  };
});

const input = $input.first().json || {};

function asArray(value) { return Array.isArray(value) ? value : []; }
function asObject(value) { return value && typeof value === 'object' && !Array.isArray(value) ? value : {}; }
function text(value, limit = 1200) {
  const result = String(value || '').replace(/\s+/g, ' ').trim();
  return result.length <= limit ? result : result.slice(0, limit).trim() + '...';
}
function unique(values, limit = 40) {
  const seen = new Set();
  const result = [];
  for (const value of values || []) {
    const item = text(value, 160);
    const key = item.toLowerCase();
    if (!item || seen.has(key)) continue;
    seen.add(key); result.push(item);
    if (result.length >= limit) break;
  }
  return result;
}
function taskType(question) {
  if (/历史|实时数据库|有(?:效)?数据|存在性|非空|缺失|候选|available|historian/i.test(question)) return 'data_availability';
  if (/趋势|异常|峰值|相关|滞后|基线|z[- ]?score|historical.*event/i.test(question)) return 'data_analysis';
  if (/计算|公式|输入|参数|静压头|压降|calculate|formula/i.test(question)) return 'calculation';
  if (/联锁|报警|控制|执行机构|风险|override|interlock/i.test(question)) return 'control_and_risk';
  return 'general';
}
function queryTerms(question) {
  const tags = question.match(/\b[A-Z][A-Z0-9_]{1,20}(?:\.(?:PV|SP|OP|MV|SV|CV))?\b/gi) || [];
  const phrases = question
    .replace(/[，。；：、！？,.!?;:()（）\[\]]/g, ' ')
    .split(/\s+/)
    .filter(value => value.length >= 2 && !/^(这些|上述|前面|这个|那个|当前|是否|哪些|如何|什么|一下|进行|需要)$/.test(value));
  return unique(tags.concat(phrases), 24);
}
function cardSearchText(card) {
  return [
    card.current_question, card.resolved_question, card.current_answer_summary,
    ...asArray(card.entities), ...asArray(card.confirmed_facts),
    ...asArray(card.candidate_facts), ...asArray(card.missing_requirements)
  ].join(' ').toLowerCase();
}
function scoreCard(card, index, total, question, terms, followUp) {
  const body = cardSearchText(card);
  let score = Math.max(0, 1 - (total - 1 - index) * 0.08);
  for (const term of terms) {
    const key = term.toLowerCase();
    if (key && body.includes(key)) score += key.length >= 6 ? 3 : 1.5;
  }
  if (question && body.includes(question.toLowerCase())) score += 5;
  if (followUp && index === total - 1) score += 8;
  if (followUp && index === total - 2) score += 3;
  return score;
}
function projectCard(card, mode) {
  const base = {
    question: text(card.current_question || card.resolved_question, 300),
    resolved_question: text(card.resolved_question, 360),
    status: text(card.status, 40),
    keywords: unique(asArray(card.entities), 18),
    confirmed_facts: asArray(card.confirmed_facts).map(value => text(value, 260)).slice(0, 12),
    candidate_facts: asArray(card.candidate_facts).map(value => text(value, 260)).slice(0, 8),
    unresolved: asArray(card.missing_requirements).map(value => text(value, 220)).slice(0, 10),
    turn_ref: text(asObject(card.internal).turn_ref || card.turn_ref, 30)
  };
  if (mode === 'data_availability' || mode === 'data_analysis') {
    base.data_targets = asArray(card.resolved_data_targets).slice(0, 30).map(target => ({
      tag: text(target.tag, 80), library: text(target.library, 100), symbol: text(target.symbol, 120),
      count: Number.isFinite(Number(target.count)) ? Number(target.count) : null,
      status: text(target.data_status || target.status, 40),
      time_range: asArray(target.time_range).slice(0, 2),
      description: text(target.desc_cn || target.desc_en, 240)
    }));
    base.data_scope = asObject(card.data_scope);
    base.analysis_results = asArray(card.data_analysis_results).map(value => text(value, 300)).slice(0, 12);
  }
  if (mode === 'calculation' || mode === 'control_and_risk') {
    base.summary = text(card.current_answer_summary, 1200);
