}
function compactFact(card) {
  return {
    subject: text(card.subject, 180), relation: text(card.relation, 100),
    value: card.value == null ? null : text(card.value, 360), status: text(card.status, 40),
    entities: unique(asArray(card.entities), 12), source_turn: text(card.source_turn, 30),
    evidence_grounded: card.evidence_grounded === true
  };
}

const state = asObject(input.conversation_state);
const question = text(input.originalUserMessage, 1200);
const mode = taskType(question);
const terms = queryTerms(question);
const followUp = /这些|上述|前面|上面|刚才|继续|其中|该(?:项|问题|参数|事件)|按照前|基于前|历史回答|previous|above|those|these|continue/i.test(question);
const cards = asArray(state.question_memory_cards);
const rankedAll = cards
  .map((card, index) => ({ card: asObject(card), index, score: scoreCard(asObject(card), index, cards.length, question, terms, followUp) }))
  .filter(row => row.score > 0.5)
  .sort((a, b) => b.score - a.score || b.index - a.index);
const scoreFloor = rankedAll.length
  ? (followUp ? Math.max(1.5, rankedAll[0].score - 4) : 1.5)
  : Number.POSITIVE_INFINITY;
const ranked = rankedAll
  .filter(row => row.score >= scoreFloor)
  .slice(0, mode === 'data_analysis' ? 8 : 6);
const selectedCards = ranked.map(row => projectCard(row.card, mode));
const selectedTurns = new Set(selectedCards.map(card => card.turn_ref).filter(Boolean));
const selectedQuestions = new Set(selectedCards.map(card => card.question).filter(Boolean));

const facts = asArray(state.fact_cards)
  .filter(card => {
    const value = asObject(card);
    const body = [value.subject, value.relation, value.value, ...asArray(value.entities)].join(' ').toLowerCase();
    return selectedTurns.has(text(value.source_turn, 30)) || terms.some(term => body.includes(term.toLowerCase()));
  })
  .map(compactFact)
  .slice(0, 36);

const targets = asArray(state.arctic_target_registry)
  .filter(target => {
    const value = asObject(target);
    const body = [value.tag, value.desc_cn, value.desc_en].join(' ').toLowerCase();
    return terms.some(term => body.includes(term.toLowerCase())) ||
      selectedTurns.has(text(value.source_turn, 30));
  })
  .slice(0, 40)
  .map(target => ({
    tag: text(target.tag, 80), library: text(target.library, 100), symbol: text(target.symbol, 120),
    count: Number.isFinite(Number(target.count)) ? Number(target.count) : null,
    data_status: text(target.data_status, 40), time_range: asArray(target.time_range).slice(0, 2),
    desc_cn: text(target.desc_cn, 240), desc_en: text(target.desc_en, 240),
    source_turn: text(target.source_turn, 30)
  }));

const needsHistory = followUp && selectedCards.some(card =>
  !card.confirmed_facts.length && !card.data_targets?.length && !card.analysis_results?.length
);
const history = needsHistory
  ? (asArray(state.turn_archive).length ? asArray(state.turn_archive) : asArray(state.turns)) // CONVERSATION_ARCHIVE_V7：检索命中的轮次从存档取原文
      .filter(turn => selectedTurns.has(text(turn.turn_ref, 30)) || selectedQuestions.has(text(turn.user_question, 300)))
      .slice(-4)
      .map(turn => ({
        question: text(turn.user_question, 360), resolved_question: text(turn.resolved_question, 420),
        answer_excerpt: text(turn.assistant_answer, 2200), turn_ref: text(turn.turn_ref, 30)
      }))
  : [];

// RECENT_TURNS_CONTEXT_V1：最近 3 轮（新的在前）的问句、完整问句、取数时段和回答开头，不靠关键词命中。
// 来由：上面按空格切词，中文问句整句成一个词，多轮第 3 轮（196365/196366/196367）选中的卡片全是 0，
// 拆题只剩 latest_resolved_question 一句，没继承时段；结构化时段就在问题卡 data_scope.windows 里。
const recentTurns = (function () {
  try {
    return cards.map((card, index) => ({ card: asObject(card), index }))
      .map(row => ({ ...row, ts: Date.parse(text(asObject(row.card.internal).ts, 40)) || 0 }))
      .sort((a, b) => (b.ts - a.ts) || (b.index - a.index))
      .slice(0, 3)
      .map(({ card }) => ({
        turn_ref: text(asObject(card.internal).turn_ref || card.turn_ref, 30),
        question: text(card.current_question, 300),
        resolved_question: text(card.resolved_question, 360),
        data_period: Array.from(new Set(asArray(asObject(card.data_scope).windows)
          .filter(w => Array.isArray(w) && w.length === 2).map(w => JSON.stringify(w.map(x => text(x, 40))))))
          .slice(0, 3).map(s => JSON.parse(s)),
        answer_head: text(card.current_answer_summary, 400)
      }));
  } catch (e) { return []; }
})();

const retrievalState = {
  mode,
  query_keywords: terms,
  question_memory_cards: selectedCards,
  fact_cards: facts,
  arctic_target_registry: targets,
  retrieved_history: history,
  latest_topic: text(state.latest_topic, 240),
  latest_resolved_question: text(state.latest_resolved_question, 420),
  recent_turns: recentTurns
};

const {
  conversation_state, conversation_state_for_llm, conversation_state_for_decompose,
  conversation_state_for_planner, conversation_state_debug, catalog, propertyName, ...rest
} = input;

return [{ json: {
  ...rest,
  catalog_for_llm: asObject(input.catalog_for_llm),
  retrieval_state: retrievalState,
  memory_retrieval_debug: {
    mode, keyword_count: terms.length, selected_card_count: selectedCards.length,
    selected_fact_count: facts.length, selected_target_count: targets.length,
    history_retrieved: history.length > 0, history_excerpt_count: history.length
  }
} }];

// EVIDENCE_KEY_VALUES_KEPT_V1：正文截短后，补列本条结构化字段值（key_values）里正文没出现的项。
// 来由：exec 189081 R1102 记录正文截到 900 字，稀相段上界 top_el_mm=39650 被截掉，回答说没有；key_values 里一直有。
function __kvTail(row, shown, cap) {
  const kv = (Array.isArray(row && row.key_values) ? row.key_values : []).map(v => String(v == null ? '' : v).replace(/\s+/g, ' ').trim()).filter(Boolean);
  if (!kv.length) return '';
  const flat = String(shown || '').replace(/\s+/g, '');
  const miss = kv.filter(v => !flat.includes(v.replace(/\s+/g, '')));
  if (!miss.length) return '';
  const out = []; let n = 0;
  for (const v of miss) { const t = v.length > 300 ? v.slice(0, 300) + '…' : v; if (n + t.length > (cap || 1500)) break; out.push(t); n += t.length + 1; }
  if (!out.length) return '';
  return ' 〔本条结构化字段值（正文截短未显示的部分）：' + out.join('；') + (out.length < miss.length ? '；另 ' + (miss.length - out.length) + ' 项未列' : '') + '〕';
}
const input = $input.first().json || {};

function asArray(value) { return Array.isArray(value) ? value : []; }
function asObject(value) { return value && typeof value === 'object' && !Array.isArray(value) ? value : {}; }
function text(value, limit = 1200) {
  const result = String(value || '').replace(/\s+/g, ' ').trim();
  return result.length <= limit ? result : result.slice(0, limit).trim() + '...';
}
// DOCUMENT_PERIOD_RELATION_V7：时段标注由 Evidence Packet Builder 计算（DOCUMENT_PERIOD_PRIORITY_V7），这里只透传
function __periodPass(row) {
  const out = {};
  for (const k of ['document_period', 'period_relation', 'requested_period_mentioned', 'citable']) if (row[k] !== undefined) out[k] = row[k];
  return out;
}
function compactEvidence(value, index) {
  const row = asObject(value);
  return {
    ...__periodPass(row),
    evidence_id: text(row.evidence_id || row.id || `E${index + 1}`, 30),
    // compactEvidence 是白名单式的，不列出就会丢；覆盖校验要靠它做 id 连接
    source_unit_id: row.source_unit_id ?? null,
    source_required_types: asArray(row.source_required_types).slice(0, 8),
    document_name: text(row.document_name, 220), dataset_name: text(row.dataset_name, 160),
    section_title: text(row.section_title, 220), source_type: text(row.source_type, 60),
    // SOURCE_TIER_V7：来源分级必须过白名单，否则到不了 finalizer（db_meta 当初就卡在这里）
    source_tier: Number(row.source_tier) || null,
    source_tier_label: text(row.source_tier_label, 40),
    snippet: /<table\b/i.test(row.snippet || row.content_summary || '')
  ? (row.snippet || row.content_summary)
  : (() => { const __s = text(row.snippet || row.content_summary, 900); return __s + __kvTail(row, __s, 1500); })(), // EVIDENCE_KEY_VALUES_KEPT_V1
    page_start: row.page_start ?? null, page_end: row.page_end ?? null
  };
}
function compactClaim(value) {
  const row = asObject(value);
  const claimText = String(row.claim_text || row.text || '');
  const ids = asArray(row.supported_by_evidence_ids).slice(0, 12);
  return {
    claim_id: text(row.claim_id || row.id, 40), claim_text: text(claimText, 900),
    status: text(row.status, 40), supported_by_evidence_ids: ids,
    ...__periodPass(row),
    source_role: text(row.source_role, 60)
  };
}
function compactTag(value) {
  const row = asObject(value);
  return {
    factor_id: text(row.factor_id, 80), factor: text(row.factor || row.factor_name, 180),
    tag: text(row.tag || row.name, 80), status: text(row.status || row.data_status, 50),
    match_type: text(row.match_type, 50), selected: row.selected === true,
    has_non_null_data: row.has_non_null_data === true,
    count: Number.isFinite(Number(row.count)) ? Number(row.count) : null,
    time_range: asArray(row.time_range).slice(0, 2),
    description: text(row.desc_cn || row.description_cn || row.desc_en || row.description_en, 260)
  };
}
function compactFactor(value) {
  const row = asObject(value);
  const direct = asArray(row.selected_tags || row.direct_tags).map(value => text(value, 80)).filter(Boolean).slice(0, 12);
  const candidates = asArray(row.candidate_tags || row.candidates).slice(0, 5).map(candidate => {
    const item = asObject(candidate);
    return { tag: text(item.tag || item.name, 80), description: text(item.desc_cn || item.desc_en || item.description, 220) };
  });
  const status = direct.length ? 'confirmed_mapping' : candidates.length ? 'candidate_only' : 'unresolved';
  return {
    factor_id: text(row.factor_id || row.id, 80), factor: text(row.factor || row.name, 180),
    status, selected_tags: direct, candidates,
    missing_reason: text(row.missing_reason || row.reason, 260)
  };
}

const payload = asObject(input.finalizer_payload || input.aggregated_payload);
const sourceStatus = asObject(payload.source_status);
const factorResolution = asArray(payload.factor_resolution || payload.factor_results).map(compactFactor).slice(0, 80);
const tagStatus = asArray(input.tag_evidence_status || payload.tag_evidence_status || payload.tag_selection_trace)
  .map(compactTag).slice(0, 100);
// PROJECTOR_EVIDENCE_CAP_FOLLOWS_PACKET_V7
// 条数以 Evidence Packet Builder 为准（24 席 + 位号类轮次追加席）；原先这里再截 24，追加席到不了 finalizer。
// 48 只是上游异常时的保护值，远高于装包上限。
const evidence = asArray(input.evidence_packet || payload.evidence_summary).map(compactEvidence).slice(0, 48);
// REQUIRED_TYPES_PASSTHROUGH_V7
// 规划器在执行单元上已经判出本轮的必答项（exec 136224 的 T4：
// required_evidence_types = ['anomaly_or_exceedance','处置措施','操作步骤']），
// 但这里原先不放行，finalizer 与 Compose Guard 都看不到，漏项因此不算违规。
const __units = asArray(input.completed_units);
const requiredTypes = (function () {
  const seen = new Set();
  for (const u of __units) {
    for (const t of asArray(asObject(u).required_evidence_types)) {
      const v = text(t, 60);
      if (v) seen.add(v);
    }
  }
  return Array.from(seen).slice(0, 12);
})();
const questionParts = (function () {
  const seen = new Set();
  for (const u of __units) {
    const v = text(asObject(u).question_part, 60);
    if (v) seen.add(v);
  }
  return Array.from(seen).slice(0, 8);
})();

// 证据正文已在 evidence_packet 里给过一遍；与之重复的 claim 只是加个英文前缀
// 重贴原始 chunk（实测 32 条全是 "Retrieved evidence N:"），白占提示词。
const __evBlob = asArray(input.evidence_packet || payload.evidence_summary)
  .map(e => String(asObject(e).snippet || asObject(e).content_summary || '').replace(/\s+/g, ''))
  .join(' ');
function __claimDuplicatesEvidence(row) {
  const t = String(row.claim_text || '').replace(/^Retrieved evidence\s*\d+\s*[:：]\s*/i, '');
  const probe = t.replace(/\s+/g, '').slice(0, 50);
  return probe.length >= 24 && __evBlob.indexOf(probe) >= 0;
}
const claims = asArray(payload.claim_blocks).map(compactClaim)
  .filter(row => row.claim_text)
  .filter(row => !__claimDuplicatesEvidence(row))
  .slice(0, 48);

const compactPayload = {
  draft_answer: String(payload.draft_answer || input.answer || '').trim(),
  answer_mode: text(input.answer_mode || payload.answer_mode, 60),
  claim_blocks: claims,
  dependency_explanations: asArray(payload.dependency_explanations).map(value => text(value, 600)).slice(0, 16),
  source_status: sourceStatus,
  missing_evidence_flags: asArray(payload.missing_evidence_flags).map(value => text(value, 300)).slice(0, 24),
  factor_resolution: factorResolution,
  tag_evidence_status: tagStatus,
  // F32：这里曾在 packet 非空时置空以省提示词，实测把引用改坏了——
  // 该字段还是 Code in JavaScript 里 evidenceById 的来源之一
  // （pickArray 的第二级），置空后 finalizer 写出的 8 处 [E#] 全被
  // rewriteEvidenceRefsWithDisplayIds 当作无效引用删除（exec 136315）。
  // 它不只是副本，还是引用注册表，必须原样保留。
  evidence_summary: evidence,
  analysis_notes: asArray(payload.analysis_notes).map(value => text(value, 700)).slice(0, 30),
  cross_evidence_analysis: asObject(payload.cross_evidence_analysis),
  authoritative_measured_results: asArray(payload.authoritative_measured_results).slice(0, 80),
  historical_calculation_capability_boundary: asObject(payload.historical_calculation_capability_boundary),
  current_calculation_status: asObject(payload.current_calculation_status),
  event_evidence_status: asObject(payload.event_evidence_status),
  // EVENT_LINKING_V7
  event_links: asArray(payload.event_links).slice(0, 12),
    // PRIOR_DECLINED_TURN_CORRECTION_V7
    prior_declined_turns: asArray(payload.prior_declined_turns).slice(0, 3),
  conversation_consistency_context: asObject(payload.conversation_consistency_context),
  required_evidence_types: requiredTypes,
  question_parts: questionParts
};

return [{ json: {
  // ANSWER_EDIT_ROUND_V8：本次运行是否处在反查环的修改轮（上一稿被反查标出了问题）。是则由 Draft Mode Gate 送去修改上一稿，不再让终稿模型重写；
  // 反查结论由 Prepare Answer Edit 直接从 Build Verification Retry 读取，不再经终稿模型的输入传递。
  answer_edit_round: (() => { try { return (($('Build Verification Retry').last().json || {}).verification_action === 'redraft'); } catch (e) { return false; } })(),
  // CROSS_TURN_ESTABLISHED_THRESHOLDS_V7：必须过白名单，否则到不了 finalizer
  // THRESHOLD_RESOLVER_V8：本轮计算句（turn_ref 为 computed，最多 5 条）排在最前，原先统一截前 8 条会把前序轮次的阈值原句挤掉；
  // 计算句全留，前序原句留前 8 条
  established_thresholds: (function () {
    const all = asArray(($input.first()?.json || {}).established_thresholds);
    const isComputed = x => String(asObject(x).turn_ref) === 'computed';
    return all.filter(isComputed).slice(0, 6).concat(all.filter(x => !isComputed(x)).slice(0, 8));
  })(),
  originalUserMessage: input.originalUserMessage,
  chatSessionId: input.chatSessionId,
  answer: String(input.answer || payload.draft_answer || '').trim(),
  answer_mode: input.answer_mode || payload.answer_mode || '',
  finalizer_payload: compactPayload,
  aggregated_payload: compactPayload,
  evidence_packet: evidence,
  tag_evidence_status: tagStatus,
  required_evidence_types: requiredTypes,
  question_parts: questionParts,
  result_projection_debug: {
    input_chars: JSON.stringify(input).length,
    output_chars: JSON.stringify(compactPayload).length,
    claim_count: claims.length,
    evidence_count: evidence.length,
    factor_count: factorResolution.length,
    tag_count: tagStatus.length,
    required_type_count: requiredTypes.length,
    claim_dropped_as_duplicate: asArray(payload.claim_blocks).length - claims.length
  }
} }];

const body =
  $json.body && typeof $json.body === 'object'
    ? $json.body
    : $json;

// 1. Validate the question
const rawInput =
  body.chatInput ??
  body.message ??
  body.question ??
  body.input;

if (typeof rawInput !== 'string' || !rawInput.trim()) {
  throw new Error('DEBUG_API_BAD_REQUEST: A non-empty question is required.');
}

const chatInput = rawInput.trim();

// 2. Validate and isolate the session ID
const rawSession =
  body.sessionId ??
  body.session_id ??
  body.chatSessionId;

let debugSessionId;

if (rawSession == null || rawSession === '') {
  debugSessionId =
    `auto-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
} else {
  if (typeof rawSession !== 'string') {
    throw new Error(
      'DEBUG_API_BAD_REQUEST: sessionId must be a string.'
    );
  }

  debugSessionId = rawSession.trim().replace(/^debug:/i, '');

  if (
    !debugSessionId ||
    debugSessionId.length > 128 ||
    !/^[A-Za-z0-9._:-]+$/.test(debugSessionId)
  ) {
    throw new Error(
      'DEBUG_API_BAD_REQUEST: sessionId contains invalid characters.'
    );
  }
}

// Debug sessions can no longer collide with normal chat sessions.
const sessionId = `debug:${debugSessionId}`;

return [{
  json: {
    chatInput,
    sessionId,
    inputSource: 'debug_api'
  }
}];

// SHARED_CATALOG_CACHE_V5
// CONFIGURED_ARCTIC_TARGET_CACHE_NAMESPACE_V5
const input = $input.first()?.json || {};
let raw = input.propertyName ?? input.value ?? input.data ?? null;
if (raw == null) {
  const candidate = Object.values(input).find(v => typeof v === 'string' && v.trim().startsWith('{'));
  raw = candidate ?? null;
}
let record = null;
try { record = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch { record = null; }
let ttlSec = 1800;
try {
  const rpRaw = $('Workflow Configuration').first().json.run_params;
  const rp = typeof rpRaw === 'string' ? JSON.parse(rpRaw) : (rpRaw || {});
  ttlSec = Number(rp?.catalog_cache?.ttl_sec || ttlSec);
} catch {}
const cachedAt = Number(record?.cached_at || 0);
const ageSec = cachedAt > 0 ? Math.max(0, Math.round((Date.now() - cachedAt) / 1000)) : null;
// NONEMPTY_CATALOG_CACHE_GUARD_V6
// A structurally-valid but EMPTY catalog must not count as a usable cache hit,
// otherwise one failed refresh poisons every later turn for the whole TTL
// (0 dataset ids -> Match Tools NO_MATCH -> direct_response -> no retrieval).
function catalogEntryCount(node, depth) {
  if (depth > 6 || node == null) return 0;
  if (Array.isArray(node)) {
    let n = node.length;
    for (const item of node) n += catalogEntryCount(item, depth + 1);
    return n;
  }
  if (typeof node === 'object') {
    let n = 0;
    for (const [key, value] of Object.entries(node)) {
      if (key === 'updated_at') continue;
      n += catalogEntryCount(value, depth + 1);
    }
    return n;
  }
  return 0;
}
// NONEMPTY_CATALOG_CACHE_GUARD_V6b
// Counting structural keys was too loose: an empty catalog still scored 33.
// What actually matters is whether the catalog carries real resource ids.
function catalogResourceIdCount(node) {
  const blob = JSON.stringify(node || {});
  const ids = blob.match(/[0-9a-f]{24,34}/g) || [];
  return new Set(ids).size;
}
const catalogEntries = record && record.catalog ? catalogResourceIdCount(record.catalog) : 0;
const usable = !!(record?.catalog && typeof record.catalog === 'object') && catalogEntries > 0;
const fresh = usable && ageSec !== null && ageSec <= ttlSec;
return [{ json: {
  __catalog_cache_hit: fresh,
  __catalog_cache_usable: usable,
  __catalog_cache_entries: catalogEntries,
  __catalog_cache_age_sec: ageSec,
  __catalog_cache_ttl_sec: ttlSec,
  catalog_cache_record: usable ? record : null
} }];

