parameters.jsCode:
// FREE_INSIGHT_GUARD_V6
// 自由线没有证据支撑，因此在进入合成前做确定性清洗：凡是看起来像
// 事实性定量断言的内容一律删除，只保留定性解读。
// 网关走"跳过"分支时本节点同样会被执行，此时产出空 insight。
const item = $input.first()?.json || {};
let text = String(item.output || item.text || item.insight || '').trim();

// 去掉可能的代码块围栏与 JSON 包装
text = text.replace(/^```[a-z]*\s*|\s*```$/gi, '').trim();
try {
  const parsed = JSON.parse(text);
  if (parsed && typeof parsed === 'object' && typeof parsed.output === 'string') text = parsed.output;
} catch (e) {}

const DROP = [
  /\[E\d+\]/,                                   // 伪造引用
  /\b[A-Z]{2,6}\d{3,5}[A-Z]?(?:\.[A-Z]{2,4})?\b/, // 位号
  /\d+(?:\.\d+)?\s*(?:kPa|MPa|Pa|℃|°C|%|t\/h|m3|Nm3|mg\/m3|μm|um|小时|分钟)/i, // 数值+单位
  /(?:高高报|高报|低低报|低报|联锁值|设定值|报警值|控制范围)\s*[为是:：]?\s*[-+]?\d/,   // 阈值断言
  /(?:确认|检测到|已发生|已触发|记录到)[^。！？]{0,20}(?:超标|越限|报警|联锁|事件)/,      // 事件断言
  /\.(?:docx?|xlsx?|pdf)\b/i,                   // 文档名
];
const kept = [];
let dropped = 0;
for (const sentence of text.split(/(?<=[。！？\n])/)) {
  const t = sentence.trim();
  if (!t) continue;
  if (DROP.some(re => re.test(t))) { dropped++; continue; }
  kept.push(t);
}
let insight = kept.join('').trim();
if (insight.length < 40) insight = '';   // 清洗后剩不下什么就当没有

return [{ json: {
  insight,
  insight_dropped_sentences: dropped,
  insight_enabled: insight.length > 0,
  insight_revision: item.insight_revision || null // INSIGHT_SELF_REVISION_V1
} }];

