// FREE_PARAGRAPH_BUDGET_V6
// 自由段在合成时挤占证据正文：MT05 T2 开头近三分之一、MT25 T2 中间两段
// 均为无引用的纯发挥，读起来「一段查的、一段聊的」。提示词约束已验证无效，
// 因此按确定性规则限额——无引用的自然段最多保留一个，且优先保留末段（结论位）。
// 仅在原证据正文本身有引用时生效；证据正文本就无引用的轮次不受影响。
function bossApplyFreeParagraphBudget(composed, originalBody) {
  const text = String(composed || '');
  if (!/\[E\d+\]/.test(String(originalBody || ''))) return text;   // 原文无引用则不限
  const paras = text.split(/\n{2,}/).map(p => p.trim()).filter(Boolean);
  if (paras.length <= 2) return text;
  // GUARD_KEEPS_BODY_PARAGRAPHS_V7：原样来自证据正文的段落（编号列表、表格等）不是 Composer 的发挥，不计入限额（exec 148617 删掉了 6 条处置步骤）。
  const __norm = x => String(x || '').replace(/\s+/g, '');
  const __body = __norm(originalBody);
  // Standalone headings are structure, not unsupported engineering commentary.
  // COMPOSER_REWRITE_NOT_FREE_V7：合成器对原文段落的改写（字符二元组 ≥50% 来自原文某一段）不是自由发挥。
  // exec 153332 / 153344：结论段总括全文、无引用，合成器稍改措辞后覆盖率 0.58，被当自由段删去，「## 结论」下为空；
  // 真正的工程发挥段覆盖率 0.05–0.18。
  const __bigrams = x => { const t = __norm(x); const set = new Set(); for (let i = 0; i + 1 < t.length; i++) set.add(t.slice(i, i + 2)); return set; };
  const __origParas = String(originalBody || '').split(/\n{2,}/).map(x => x.trim()).filter(Boolean).map(__bigrams);
  const __rewrite = p => {
    const b = __bigrams(p); if (b.size < 8) return false;
    for (const o of __origParas) { let hit = 0; for (const g of b) if (o.has(g)) hit++; if (hit / b.size >= 0.5) return true; }
    return false;
  };
  const cited = paras.map(p =>
    /\[E\d+\]/.test(p) ||
    (__norm(p).length > 0 && __body.indexOf(__norm(p)) >= 0) ||
    __rewrite(p) ||
