// SENTENCE_COUNT_COMPLIANCE_V7
// 「概括成三句话」是用户写死的格式要求，不该交给模型自觉遵守。
// MT25 T5 实测：给完三句后又展开一大段，297 -> 596 字。
// 与 FREE_PARAGRAPH_BUDGET_V6 同思路做确定性裁剪。
function bossRequestedSentenceCountV7(question) {
  const q = String(question || '');
  const CN = { '一': 1, '两': 2, '二': 2, '三': 3, '四': 4, '五': 5, '六': 6, '七': 7, '八': 8, '九': 9, '十': 10 };
  let m = q.match(/([一二两三四五六七八九十]|\d{1,2})\s*句(?:话)?/);
  if (m) {
    const raw = m[1];
    const n = /^\d+$/.test(raw) ? Number(raw) : CN[raw];
    if (n >= 1 && n <= 10) return n;
  }
  m = q.match(/\bin\s+(\d{1,2}|one|two|three|four|five|six|seven|eight|nine|ten)\s+sentences?\b/i);
  if (m) {
    const W = { one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10 };
    const raw = String(m[1]).toLowerCase();
    const n = /^\d+$/.test(raw) ? Number(raw) : W[raw];
    if (n >= 1 && n <= 10) return n;
  }
  return 0;
}
function bossTrimToSentenceCountV7(text, n) {
  const body = String(text || '');
  if (!n || !body.trim()) return body;
  // 句末标点后切分，保留标点；序号「第一，」「①」不算句末
  const parts = body.match(/[^。！？!?\n]+[。！？!?]+|[^。！？!?\n]+$/g) || [];
  if (parts.length <= n) return body;
  const kept = parts.slice(0, n).join('').trim();
  return kept || body;
}

function bossStripTrailingHedge(text) {
  const HEDGE = [
    /来自通识性|通识性(?:FCC)?资料|一般构型下的/,
    /属于通用(?:资料|原理|说明)/,
    /需(?:另行|进一步)?依据操作规程[、和及]?P&ID/,
    /没有标准答案/,
    /每(?:个|台|套)装置.{0,24}(?:都)?不(?:一样|同)/,
    /真要(?:往下|深入|细)/,
    /还得(?:把|将).{0,30}(?:趋势|曲线|数据).{0,12}(?:调|拉|取|翻)出来/,
    /还(?:得|需要)分清(?:是否|是)/,
    /与.{0,16}日常操作习惯有关/,
    /因装置而异|视具体情况而定|因(?:厂|地)而异/,
    /仅供参考[，,。]?$/
  ];
  // V6b：具体缺失声明必须点名对象（带位号或数值），由下面两条自然保护；
  // 「未检索到针对具体装置的具体设定值」这类泛指不再豁免。
  const KEEP = [
    /\[E\d+\]/,                                   // 带引用的一律保留
    /[0-9]+(?:\.[0-9]+)?\s*(?:kPa|MPa|℃|°C|%|t\/h)/i,  // 带具体数值
    /[A-Z]{2,6}\d{3,5}/                           // 带位号
  ];
  const raw = String(text || '');
  if (!raw.trim()) return raw;
  const paras = raw.split(/\n{2,}/);
  const outParas = [];
  for (let pi = 0; pi < paras.length; pi++) {
    const isLast = pi >= paras.length - 1;
    if (!isLast) { outParas.push(paras[pi]); continue; }
    // 仅对最后一段逐句判定
    const kept = [];
    let dropped = 0;
    for (const sentence of paras[pi].split(/(?<=[。！？!?])/)) {
      const t = sentence.trim();
      if (!t) continue;
      const protectedSentence = KEEP.some(re => re.test(t));
      const hedge = HEDGE.some(re => re.test(t));
      if (hedge && !protectedSentence) { dropped++; continue; }
      kept.push(sentence);
    }
    const merged = kept.join('').trim();
    // 整段都被判为找补时直接丢掉该段；否则保留剩余句子
    if (merged) outParas.push(merged);
    else if (!dropped) outParas.push(paras[pi]);
  }
  return outParas.join('\n\n').trim();
}

