  merged.completed_windows = ok.map(x => x.label);
  merged.failed_windows = failed;
  merged.analysis_completed = failed.length === 0;
  const full = unit.full_available_range === true && Array.isArray(windows) && windows.length > 1;
  merged.data_scope = full ? 'full_available_range_analysis' : (merged.data_scope || 'bounded_range_analysis');
  merged.global_conclusion_allowed = full && failed.length === 0;
}
if (kind === 'stats') {
  merged.data_scope = p.date_range_bounded_by_default ? 'bounded_range_analysis' : (merged.data_scope || 'requested_range');
  merged.global_conclusion_allowed = !p.date_range_bounded_by_default && failed.length === 0;
}
merged.deterministic_execution = { policy: 'HISTORIAN_DETERMINISTIC_EXECUTION_V7', calls: calls.length, completed: ok.length, failed: failed.length };

// READ_STATS_FROM_RECORDS_V1：读数结果由代码按列算统计量，写成与「历史库统计」同一格式的证据。
// 来由：exec 188547 / 186507 首轮读回 DR3110.PV 全天 1440 行，证据只写行数，自查环判为已覆盖，首稿因此「无法计算」。
if (kind === 'read' && Array.isArray(merged.records) && merged.records.length && !(merged.column_stats && Object.keys(merged.column_stats).length)) {
  const __cs = {};
  for (const col of (Array.isArray(merged.columns) ? merged.columns : [])) {
    let n = 0, s = 0, s2 = 0, mn = Infinity, mx = -Infinity, last = null, lastT = '';
    for (const r of merged.records) {
      const v = r ? r[col] : null;
      if (typeof v !== 'number' || !Number.isFinite(v)) continue;
      n++; s += v; s2 += v * v; if (v < mn) mn = v; if (v > mx) mx = v; last = v; lastT = String((r && (r.time || r.timestamp || r.index)) || '');
    }
    if (n) { const mean = s / n; __cs[col] = { count: n, mean, min: mn, max: mx, latest: last, latest_timestamp: lastT, std: Math.sqrt(Math.max(0, s2 / n - mean * mean)), source: 'computed_from_read_records' }; }
  }
  if (Object.keys(__cs).length) { merged.column_stats = __cs; merged.column_stats_source = 'read_records'; }
}
// 证据摘要：统计量逐列、分析的异常点（按 |z| 排序）
const ev = [];
const fmt = v => (typeof v === 'number' ? String(Math.round(v * 10000) / 10000) : String(v));
if (merged.column_stats && typeof merged.column_stats === 'object') {
  for (const [col, st] of Object.entries(merged.column_stats)) {
    const s = st || {};
    ev.push('MongoDB 历史库统计 ' + (p.database || '') + '/' + (p.collection || '') + ' ' + (merged.date_range || []).join(' ~ ') + '：' + col +
      ' 样本 ' + fmt(s.count) + '，均值 ' + fmt(s.mean) + '，最小 ' + fmt(s.min) + '，最大 ' + fmt(s.max) + '，最新 ' + fmt(s.latest) + (s.latest_timestamp ? '（' + s.latest_timestamp + '）' : ''));
  }
}
if (Array.isArray(merged.anomaly_windows)) {
  const top = merged.anomaly_windows.slice().filter(a => a && typeof a === 'object')
    .sort((a, b) => Math.abs(Number(b.zscore) || 0) - Math.abs(Number(a.zscore) || 0)).slice(0, 12);
  for (const a of top) ev.push('MongoDB 历史库统计异常：' + (a.column || '') + ' ' + (a.timestamp || '') + ' 值 ' + fmt(a.value) + '，z ' + fmt(a.zscore) + (a.direction ? '（' + a.direction + '）' : ''));
}
if (kind === 'read' && merged.time_range) ev.push('MongoDB 历史库读数：' + (p.columns || []).join('、') + ' 行数 ' + merged.row_count + '，时间 ' + merged.time_range.join(' ~ ') + '，非空列 ' + (merged.non_null_columns || []).join('、'));
const answer = '确定性执行 ' + plan.tool + '：' + calls.length + ' 次调用，成功 ' + ok.length + '，失败 ' + failed.length +
  (merged.date_range ? '；区间 ' + merged.date_range.join(' ~ ') : '') + (failed.length ? '；失败：' + failed.map(f => f.label + '（' + f.error + '）').join('；') : '') +
  (__retried.length ? '；其中 ' + __retried.length + ' 次调用因参数被服务端拒绝（' + Array.from(new Set(__retried.flatMap(x => x.removed))).join('、') + '），去掉该参数后重试成功' : '');
const out = {
  tool: plan.tool,
  status: ok.length ? 'ok' : 'error',
  raw_result: merged,
  answer,
  evidence_summary: ev.length ? ev : [answer]
};
return [{ json: { output: JSON.stringify(out) } }];

// COVERAGE_RETRY_V7：作答前核对「问题要求的每项信息是否已被证据直接覆盖」，缺口改写查询补检一轮。
// report8 Q1（exec 149335）：教材「操作窗」「操作变量影响柴油产率」只取到目录行；当月柴油收率在月报里有却无针对查询。
// 计划按问句一次性生成、检索结果不反馈修正查询，这类缺口只能靠作答前的覆盖检查发现。
const item = $input.first().json || {};
const asArray = v => Array.isArray(v) ? v : [];
const asObject = v => v && typeof v === 'object' && !Array.isArray(v) ? v : {};
const asString = v => typeof v === 'string' ? v.trim() : '';
const cut = (v, n) => String(v == null ? '' : v).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n);

const units = asArray(item.completed_units);
// COVERAGE_ONCE_PER_EXECUTION_V7：以本执行中 Coverage Retry 是否已运行为准。原先靠 item 标记与补检单元判断，
// 标记经 Result Aggregator 重建后丢失，补检无新片段时也没有补检单元，MT25 T1 exec 152400 因此转了 27 圈。
let __retryRan = false;
try { __retryRan = $('Coverage Retry').all().length > 0; } catch (e) { __retryRan = false; }
const alreadyChecked = __retryRan || item.coverage_check_done === true || units.some(u => asObject(asObject(u).params).coverage_retry === true);
const failed = u => /BLOCK|FAIL|ERROR|SKIP/i.test(asString(asObject(u).execution_status));
const digestOf = u => {
  const d = asArray(u.evidence_digest);
  return d.length ? d : asArray(asObject(u.normalized_result).evidence_digest).length
    ? asArray(asObject(u.normalized_result).evidence_digest) : asArray(u.evidence_summary);
};
const HIST = /^(?:arctic|mongo)_(read|stats|analyze|find_tags|resolve_factors)$/;
const ragUnits = units.filter(u => asString(u.tool) === 'ragflow_retrieval' && !failed(u));
const histUnits = units.filter(u => HIST.test(asString(u.tool)));

const questionParts = Array.from(new Set(units.map(u => asString(u.question_part)).filter(Boolean)));
const evidence = ragUnits.map(u => {
  const p = asObject(u.params);
  const queries = asArray(p.query_variants).map(v => cut(asObject(v).question, 160)).filter(Boolean);
  return {
    unit: 'U' + u.unit_id,
    question_part: asString(u.question_part),
    queries_run: (queries.length ? queries : [cut(p.question, 160)]).slice(0, 5),
    items: digestOf(u).slice(0, 10).map((d, i) => {
      const x = asObject(d);
      return {
        ref: 'U' + u.unit_id + '#' + (asString(x.evidence_id) || 'E' + (i + 1)),
        doc: cut(x.document_name, 70),
        page: x.page_start ?? null,
        text: cut(x.content_summary || x.snippet, 260)
      };
    })
  };
});
const historian = histUnits.map(u => ({
  unit: 'U' + u.unit_id,
  tool: asString(u.tool).replace(/^arctic_/, 'mongo_'),
  status: asString(u.execution_status),
  result: cut(u.answer || asObject(u.normalized_result).answer, 900)
}));

const shouldCheck = Boolean(!alreadyChecked && ragUnits.length);
// HISTORIAN_FALLBACK_NO_PERIOD_V8：计划里有没有排取数（统计 / 分析 / 读数，探测读数不算），目前有没有任何实测——交给覆盖检查决定题面没给时段时要不要补因子
const __rawOf = u => { const d = asObject(asObject(u).raw_result); return Object.keys(d).length ? d : asObject(asObject(asObject(u).normalized_result).raw_result); };
const __dataUnit = u => /^(?:arctic|mongo)_(?:read|stats|analyze|resolve_factors)$/.test(asString(asObject(u).tool)) && asObject(asObject(u).params).presence_probe !== true;
const __plannedHistorian = units.some(__dataUnit);
const __measuredSoFar = units.some(u => {
  if (!__dataUnit(u)) return false;
  const r = __rawOf(u);
  return Object.keys(asObject(r.column_stats)).length > 0 || asArray(r.period_profile).some(x => Number(asObject(x).count) > 0) ||
    asArray(r.records).length > 0 || asArray(r.factor_results).some(fr => asArray(asObject(fr).stats).length > 0);
});
return [{
  json: {
    ...item,
    should_check_coverage: shouldCheck,
    coverage_packet: shouldCheck ? {
      question: asString(item.originalUserMessage),
      date_range: item.factor_resolution_date_range || null,
      question_parts: questionParts,
      evidence,
      historian,
      planned_historian_without_measurements: __plannedHistorian && !__measuredSoFar
    } : null
  }
}];

