// ANSWER_EDIT_ROUND_V8：把修改模型给出的替换逐条落到上一稿成稿上。模型只说「把哪一段换成什么」，定位和替换在这里做，
// 所以没被点到的文字一个字符都不会变。定位不上、不唯一、引用了证据包里没有的编号、越过段落或碰到证据卡片区的替换一律不做，并记下原因。
const asArray = v => Array.isArray(v) ? v : [];
const asObject = v => v && typeof v === 'object' && !Array.isArray(v) ? v : {};
function safeParse(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  const text = String(value || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
  try { return asObject(JSON.parse(text)); } catch (e) {}
  const a = text.indexOf('{'), b = text.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return asObject(JSON.parse(text.slice(a, b + 1))); } catch (e) {} }
  return {};
}
const llm = $input.first().json || {};
let prep = {};
try { prep = $('Prepare Answer Edit').last().json || {}; } catch (e) { prep = {}; }
const original = String(prep.answer_edit_draft || '');
let text = original;
const known = new Set(asArray(prep.answer_edit_known_ids).map(x => String(x).toUpperCase()));
for (const m of original.match(/\[E\d+\]/gi) || []) known.add(m.slice(1, -1).toUpperCase());
