  const row = { finding: e.finding, find: find.slice(0, 160), replace: rep == null ? null : rep.slice(0, 160) };
  const skip = reason => report.push({ ...row, applied: false, reason });
  if (!find.trim() || rep === null) { skip('malformed'); continue; }
  if (/\n[ \t]*\n/.test(find.trim()) || /\n[ \t]*\n/.test(rep.trim())) { skip('spans_paragraphs'); continue; }
  if (__kinds.get(String(e.finding)) === 'citation' && __bare(find) !== __bare(rep)) { skip('citation_only_changes_text'); continue; }
