  if (!src || kinds.get(rep) !== 'computed') {
    // 只收模型明确标为新目标（replaces 为空）的定义；编号对不上的照旧不收——
    // 离线重放 186501 / 186502：模型另起一套编号时，对不上的定义里有量纲不对的中间量（截面积 × 液位百分数当体积）和题目没问的量
