  const expr = asString(raw.expression);
  const problems = [], vars = [], pending = [];
  if (raw.dependency_error) problems.push(asString(raw.dependency_error));
  if (!expr || !/^[A-Za-z0-9_Ͱ-Ͽ+\-*/^().\s]+$/.test(expr)) problems.push('算式为空或含四则运算以外的字符');
  for (const v of asArray(raw.variables).map(asObject)) {
    const symbol = asString(v.symbol);
    if (!symbol) { problems.push('有变量没有符号'); continue; }
    if (Object.keys(asObject(v.plant_model_ref)).length) {
      const fact = pmResolveFact(v.plant_model_ref,engineeringFacts,asString(v.unit));
      if (!fact) problems.push('Plant Model reference '+symbol+' is missing, unusable or has incompatible units');
      else vars.push({symbol,plant_model_ref:pmRef(fact),unit:fact.unit});
    } else if (asString(v.factor_id)) {
