    missing: asArray(raw.missing).map(m => typeof m === 'string' ? m : asString(asObject(m).name || asObject(m).input)).filter(Boolean),
    // MISSING_ITEM_SYMBOL_V1：缺项指向本定义哪个变量（模型给的 symbol）原样留下，Prepare Derived Binding 按该变量查到没有来判；展开过依赖的定义缺项已是文字，没有这一项
    missing_symbols: asArray(raw.missing).filter(m => m && typeof m === 'object' && !Array.isArray(m) && Object.prototype.hasOwnProperty.call(m, 'symbol'))
