  ...rest,
  engineering_facts: engineeringFacts,
  unit: { ...unit, params: { ...params, factors: newFactors, ...(derived.length ? { derived_quantities: derived } : {}) } },
  derived_quantity_check: {
    status: 'ok',
    kinds: Object.fromEntries(kinds),
    derived: derived.map(d => (d.source_label || d.name) + ' = ' + d.expression + (d.status ? ' [' + d.reason + ']' : '')),
    replaced: Array.from(replaced),
