const factorById = new Map(asArray(params.factors).map(asObject).map(f => [asString(f.factor_id), f]));
const results = asArray(resolver.factor_results).map(asObject);
const fid = r => asString(r.factor_id || asObject(r.factor).factor_id);
const compIds = new Set();
for (const d of asArray(params.derived_quantities).map(asObject)) {
  if (d.status === 'invalid') continue;
  for (const v of asArray(d.variables).map(asObject)) if (asString(v.factor_id)) compIds.add(asString(v.factor_id));
}
const hasDirect = r => {
  const ok = new Set(asArray(r.stats).map(asObject).filter(s => asString(s.data_status).toLowerCase() === 'ok').map(s => asString(s.tag)));
  return asArray(r.tags).map(asObject).some(t => asString(t.relation) === 'direct' && ok.has(asString(t.tag)));
