if (kbText) for (const r of results) { const id = fid(r); if (compIds.has(id) || !hasDirect(r) || ['design', 'not_quantity', 'computed'].includes(asString(kinds[id]))) continue; kbChecks.push({ r, why: 'kb_check' }); }
if (!Object.keys(screens).length || !(targets.length || kbChecks.length)) return [{ json: { ...resolver, dcs_selection_needed: false } }];

