    (asString(k.unit) || asString(f.unit) || '未给') + '，用途：' + (asString(k.search_context) || asString(f.search_context));
};
return targets.slice(0, MAX_TARGETS).concat(kbChecks.slice(0, MAX_TARGETS)).map(({ r, why }, i) => ({ json: {
  dcs_selection_needed: true, i, factor_id: fid(r), why, question_text: questionText(r),
