  asArray(dict['设备别名']).map(asObject).map(e => asString(e['规范设备名称']) + ' ' + asString(e['设备ID']) + '：' + asString(e['设备别名'])).join('\n') + '\n' +
  asArray(dict['位号别名组']).map(asObject).filter(g => asString(g['其他描述'])).map(g => asString(g['代表位号']) + ' ' + asString(g['规范描述']) + '：' + asString(g['其他描述'])).join('\n');
