  tags: asArray(r.tags).map(asObject).map(t => { const u = units.get(normTag(t.tag)); return u && !asString(t.unit) ? { ...t, unit: u.unit, unit_source: u.source, unit_confidence: u.confidence, ...(u.basis ? { unit_basis: u.basis } : {}) } : t; }),
  stats: asArray(r.stats).map(asObject).map(s => { const u = units.get(normTag(s.tag)); return u && !asString(s.unit) ? { ...s, unit: u.unit, unit_source: u.source, unit_confidence: u.confidence } : s; }) }));

const resolver = asObject($input.first().json);
let dict = {};
try { dict = asObject($('Load aliases').first().json.fcc_dictionary); } catch (e) { dict = {}; }
const dictUnits = new Map();   // 位号 → Map(单位键 → {unit, conf})
const byPrefix = new Map();    // 位号前缀 → Map(单位 → 个数)；只用 HIGH 置信度的记录
const prefixOf = t => (normTag(t).match(/^[A-Z]+/) || [''])[0];
const numOf = t => Number((normTag(t).match(/\d+/) || ['0'])[0]);
const known = [];
for (const g of asArray(dict.tag_groups).map(asObject)) {
  const unit = firstUnit(g['工程单位']); if (!unit) continue;
  const conf = asString(g['置信度']).toUpperCase();
  const names = [g['规范化位号'], g['代表位号'], ...asString(g['源位号写法']).split(/[;；,，]/)].map(normTag).filter(Boolean);
  for (const n of names) { if (!dictUnits.has(n)) dictUnits.set(n, new Map()); dictUnits.get(n).set(unitKey(unit) + '|' + conf, { unit, conf }); }
