let kb = {};
try { kb = asObject($('Plant Knowledge Base').first().json.plant_knowledge); } catch (e) { kb = {}; }
const kbUnit = new Map();
for (const e of asArray(kb.entries).map(asObject)) for (const op of asArray(e.options).map(asObject)) for (const t of asArray(op.tags)) if (asString(e.unit)) kbUnit.set(normTag(t), { unit: asString(e.unit), entry: asString(e.id) });
