try { for (const rows of Object.values(asObject(asObject($('DCS Screen Tag Table').first().json.dcs_table).screens))) for (const r of asArray(rows)) { const t = normTag(asArray(r)[0]); if (t && !desc.has(t)) desc.set(t, asString(asArray(r)[1])); } } catch (e) {}
