    if (meta) { units.set(k, { unit: meta, source: asString(t.unit_source) || 'historian_metadata', confidence: asString(t.unit_confidence) || 'high' }); continue; }
    const kbu = kbUnit.get(k);
    if (kbu) { units.set(k, { unit: kbu.unit, source: 'plant_knowledge', confidence: 'high', basis: '装置知识库 ' + kbu.entry }); continue; }
    const recs = [...(dictUnits.get(k) || new Map()).values()];
    const high = recs.filter(x => x.conf === 'HIGH'), highKeys = new Set(high.map(x => unitKey(x.unit)));
