const fmt = v => (v == null || v === '') ? '?' : String(v);
const line = x => {
  const p = prefixOf(x.tag), conv = [...(byPrefix.get(p) || new Map()).entries()].sort((a, b) => b[1] - a[1]).slice(0, 4).map(([u, n]) => u + '×' + n).join('、');
  const near = known.filter(y => prefixOf(y.tag) === p && y.tag !== x.tag).sort((a, b) => Math.abs(numOf(a.tag) - numOf(x.tag)) - Math.abs(numOf(b.tag) - numOf(x.tag))).slice(0, 3)
    .map(y => y.tag + ' ' + (desc.get(y.tag) || y.desc).slice(0, 14) + '（' + y.unit + '）').join('、');
  const s = x.stat;
  return '- ' + x.tag + '｜描述：' + (x.desc || '无') + '｜时段统计：' + (s.mean != null ? '均值 ' + fmt(s.mean) + '，最小 ' + fmt(s.min) + '，最大 ' + fmt(s.max) : '无') +
    '｜本厂同类（' + p + '）已记单位：' + (conv || '无') + '｜相邻同类：' + (near || '无') + (x.hint ? '｜同义词库记录：' + x.hint : '');
};
const list = [...need.values()], items = [];
for (let i = 0; i < list.length; i += 25) items.push(list.slice(i, i + 25));
return items.map((ch, i) => ({ json: { unit_check_needed: true, tags: ch.map(x => x.tag), hint_keys: Object.fromEntries(ch.filter(x => x.hint).map(x => [x.tag, [...(dictUnits.get(x.tag) || new Map()).values()].map(r => unitKey(r.unit))])), prompt: '要确认单位的位号：\n' + ch.map(line).join('\n'),
  ...(i === 0 ? { resolver: { ...resolver, factor_results: results }, unit_check: summary } : {}) } }));

// UNIT_CONFIRM_V1：把模型推断的单位并回。推断的单位要与位号首字母的类别对得上（F 流量、T 温度、P 压力、L 液位、D 密度），对不上就当没确认。
const asArray = v => Array.isArray(v) ? v : [];
const asObject = v => v && typeof v === 'object' && !Array.isArray(v) ? v : {};
const asString = v => typeof v === 'string' ? v.trim() : (v == null ? '' : String(v).trim());
const normTag = t => asString(t).toUpperCase().replace(/\.PV$/i, '');
const firstUnit = u => asString(u).split(/[;；]/)[0].trim();
const unitKey = u => firstUnit(u).normalize('NFKC').replace(/³/g, '3').replace(/\s+/g, '').toLowerCase();
// 单位写到位号与统计上（只写还没有单位的）
const writeUnits = (results, units) => results.map(r => ({ ...r,
  tags: asArray(r.tags).map(asObject).map(t => { const u = units.get(normTag(t.tag)); return u && !asString(t.unit) ? { ...t, unit: u.unit, unit_source: u.source, unit_confidence: u.confidence, ...(u.basis ? { unit_basis: u.basis } : {}) } : t; }),
  stats: asArray(r.stats).map(asObject).map(s => { const u = units.get(normTag(s.tag)); return u && !asString(s.unit) ? { ...s, unit: u.unit, unit_source: u.source, unit_confidence: u.confidence } : s; }) }));
const safeParse = v => {
  if (v && typeof v === 'object') return asObject(v);
  const t = String(v || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
  try { return asObject(JSON.parse(t)); } catch (e) {}
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return asObject(JSON.parse(t.slice(a, b + 1))); } catch (e) {} }
  return {};
};
const kindOfUnit = u => { const s = unitKey(u);
  if (/\/(h|hr|d|day|s|min)$/.test(s)) return 'F';
  if (/^(°c|℃|c|degc|k)$/.test(s)) return 'T';
  if (/^(pa|kpa|mpa|bar|atm|mmh2o)(\(g\)|\(a\))?$/.test(s)) return 'P';
  if (/^(%|mm|m)$/.test(s)) return 'L';
  if (/^(kg\/m3|g\/cm3|g\/ml)$/.test(s)) return 'D';
  return ''; };
const items = $('Prepare Unit Check').all();
const first = asObject(asObject(items[0]).json);
const resolver = asObject(first.resolver);
let outs = [];
try { outs = $('Unit Infer LLM').all(); } catch (e) { outs = []; }
const units = new Map(), dropped = [];
items.forEach((it, i) => {
  const want = new Set(asArray(asObject(it.json).tags).map(normTag));
  for (const x of asArray(safeParse(asObject(asObject(outs[i]).json).output).units).map(asObject)) {
    const k = normTag(x.tag), unit = firstUnit(x.unit);
    if (!want.has(k) || !unit || units.has(k)) continue;
    // 只对常规仪表位号（字母 + 三位以上数字，如 FRC3205）按首字母核类别；化验分析位号（LCO04_FLASHPOINTASTM 等）不按首字母
    const letter = /^[A-Z]{1,6}\d{3,}/.test(k) ? k.charAt(0) : '', kind = kindOfUnit(unit);
    if (letter && 'FTPLD'.includes(letter) && kind && kind !== letter && !(letter === 'P' && k.startsWith('PD') && kind === 'P')) { dropped.push(k + ' ' + unit); continue; }
    if (letter && 'FTPD'.includes(letter) && !kind) { dropped.push(k + ' ' + unit); continue; }
    const c = asString(x.confidence).toLowerCase();
    // 同义词库有这个位号的中低置信度记录、且与推断一致：算确认（两处来源互相印证）
    if (asArray(asObject(asObject(it.json).hint_keys)[k]).includes(unitKey(unit))) { units.set(k, { unit, source: 'dictionary', confidence: 'high', basis: '同义词库记录与推断一致' }); continue; }
    units.set(k, { unit, source: 'inferred', confidence: ['high', 'medium', 'low'].includes(c) ? c : 'low', basis: asString(x.basis).slice(0, 120) });
  }
});
const results = writeUnits(asArray(resolver.factor_results).map(asObject), units);
const inferred = [...units.entries()].map(([t, u]) => t + ' ' + u.unit + '（' + u.confidence + '）');
return [{ json: { ...resolver, factor_results: results,
  unit_check: { ...asObject(first.unit_check), inferred: inferred.length, inferred_units: inferred.slice(0, 60), ...(dropped.length ? { inference_dropped: dropped } : {}) } } }];

// EVIDENCE_RECALL_V1：证据包放不下的条目留一份索引（编号 | 文档 > 章节 | 正文开头），条目多于证据包席位时交模型点选回答要用的，
// Evidence Packet Builder 按点选结果追加席位。条目来源与 Evidence Packet Builder 收条目的范围一致：各单元 evidence_digest、汇总 evidence_digest。
const item = $input.first().json || {};
const asA = x => Array.isArray(x) ? x : [];
const asO = x => x && typeof x === 'object' && !Array.isArray(x) ? x : {};
const pay = asO(item.aggregated_payload);
const units = asA(item.completed_units || pay.completed_units || item.units || []);
const SEATS = 24; // 与 Evidence Packet Builder 的 MAX_PACKET_ITEMS 相同
const clean = t => String(t || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const rows = [], seen = new Set();
const add = (loc, d) => {
  const o = asO(d);
  const key = clean(o.content_summary || o.snippet).slice(0, 400);
  if (!key || seen.has(key)) return;
  seen.add(key);
  const doc = clean(o.document_name).slice(0, 60), sec = clean(o.section_title).slice(0, 50);
  rows.push({ id: 'R' + (rows.length + 1), loc, line: doc + (sec ? ' > ' + sec : '') + ' | ' + clean(o.content_summary || o.snippet || o.summary).slice(0, 150) });
};
units.forEach((u, k) => {
  asA(asO(u).evidence_digest).forEach((d, i) => add('u:' + k + ':d:' + i, d));
  asA(asO(asO(u).normalized_result).evidence_digest).forEach((d, i) => add('u:' + k + ':n:' + i, d));
});
asA(item.evidence_digest).forEach((d, i) => add('i:d:' + i, d));
asA(pay.evidence_digest).forEach((d, i) => add('p:d:' + i, d));
const q = String(item.originalUserMessage || item.chatInput || '').trim();
const parts = [];
for (const u of units) for (const p of [asO(u).question_part].concat(asA(asO(u).required_evidence_types))) {
  const v = String(p || '').trim(); if (v && parts.indexOf(v) < 0) parts.push(v);
}
const needed = Boolean(q) && rows.length > SEATS;
const prompt = needed ? ('User question:\n' + q + '\n\nQuestion parts the plan identified:\n' + (parts.slice(0, 12).map(p => '- ' + p).join('\n') || '- (none)') +
  '\n\nEvidence index (one line per retrieved entry; id | document > section | opening text):\n' + rows.map(r => r.id + ' | ' + r.line).join('\n')) : '';
const locs = {};
for (const r of rows) locs[r.id] = r.loc;
return [{ json: { ...item, evidence_recall_needed: needed, evidence_recall_prompt: prompt, evidence_recall_locs: locs, evidence_recall_index_rows: rows.length } }];

// EVIDENCE_RECALL_V1：点选结果（编号）换成条目位置，随原输入交给 Evidence Packet Builder。没点或没跑时照原样往下走。
const base = $('Build Evidence Index').first().json || {};
const inp = $input.first().json || {};
const locs = base.evidence_recall_locs && typeof base.evidence_recall_locs === 'object' ? base.evidence_recall_locs : {};
let status = base.evidence_recall_needed ? 'unparsed' : 'not_needed';
let picks = [];
if (base.evidence_recall_needed) {
  const t = String(inp.output || inp.text || '').replace(/^```(?:json)?\s*|\s*```$/gi, '').trim();
  let j = null;
  try { j = JSON.parse(t); } catch (e) { const a = t.indexOf('{'), b = t.lastIndexOf('}'); try { j = JSON.parse(t.slice(a, b + 1)); } catch (e2) {} }
  if (j && Array.isArray(j.picks)) {
    status = 'ok';
    const used = new Set();
    for (const p of j.picks) {
      const id = String((p && p.id) || '').trim().toUpperCase();
      if (!locs[id] || used.has(id)) continue;
      used.add(id);
      picks.push({ id, loc: locs[id], need: String((p && p.need) || '').slice(0, 200) });
      if (picks.length >= 10) break;
    }
  }
}
const out = { ...base };
delete out.evidence_recall_needed; delete out.evidence_recall_prompt; delete out.evidence_recall_locs; delete out.evidence_recall_index_rows;
out.evidence_recall = { status, index_rows: base.evidence_recall_index_rows || 0, picks };
return [{ json: out }];

// INSIGHT_SELF_REVISION_V1：审读不通过时准备改写输入；通过、没稿或审读没跑成时原稿照旧往下走。
const draft = String((($('Free Insight LLM').first() || {}).json || {}).output || '').trim();
const g = $('Free Insight Gate').first().json || {};
const q = String(g.originalUserMessage || g.chatInput || '').trim();
const t = String(($input.first().json || {}).output || '').replace(/^```(?:json)?\s*|\s*```$/gi, '').trim();
let c = null;
try { c = JSON.parse(t); } catch (e) { const a = t.indexOf('{'), b = t.lastIndexOf('}'); try { c = JSON.parse(t.slice(a, b + 1)); } catch (e2) {} }
const issues = c && Array.isArray(c.issues) ? c.issues.slice(0, 6) : [];
let status = 'kept';
if (!draft) status = 'no_draft';
else if (!c) status = 'critic_unparsed';
else if (c.pass === false && issues.length) status = 'revise';
let ctx = '';
try {
  const cs = g.conversation_state || {};
  const turns = (Array.isArray(cs.turns) ? cs.turns : []).slice(-3).map(x => String(x.resolved_question || x.user_question || '').trim()).filter(x => x.length > 1).map(x => '- ' + x);
  if (turns.length) ctx = '\n\n本次对话前几轮在讨论（只用于理解当前问题所指，不要复述）：\n' + turns.join('\n') + (cs.latest_topic ? '\n当前主题：' + cs.latest_topic : '');
} catch (e) {}
const prompt = status === 'revise'
  ? '用户问题：\n' + q + ctx + '\n\n你此前写的一稿解读：\n' + draft + '\n\n审读意见：\n' + JSON.stringify(issues, null, 1)
  : '';
return [{ json: { output: draft, insight_revision_needed: status === 'revise', insight_revision_prompt: prompt,
  insight_revision: { status, critic_pass: c ? c.pass : null, issues: issues.map(x => ({ type: x && x.type, quote: String((x && x.quote) || '').slice(0, 80), problem: String((x && x.problem) || '').slice(0, 160) })), draft_chars: draft.length } } }];

// INSIGHT_SELF_REVISION_V1：有改写稿就用改写稿，否则用原稿；之后照旧由 Free Insight Guard 清洗。
const base = $('Prepare Insight Revision').first().json || {};
const rev = Object.assign({}, base.insight_revision || {});
let output = String(base.output || '');
if (base.insight_revision_needed) {
  const t = String(($input.first().json || {}).output || '').replace(/^```[a-z]*\s*|\s*```$/gi, '').trim();
  if (t.length >= 40) { output = t; rev.status = 'rewritten'; rev.rewrite_chars = t.length; rev.draft = String(base.output || '').slice(0, 1500); }
  else rev.status = 'rewrite_empty';
}
return [{ json: { output, insight_revision: rev } }];

// COMMON_SENSE_CHECK_V1：已算出的计算量交模型做常识检查（模型不看数值）；数值留在这里，由 Apply Common Sense Check 对照。
const item = $input.first().json || {};
const asArray = v => Array.isArray(v) ? v : [];
const asObject = v => v && typeof v === 'object' && !Array.isArray(v) ? v : {};
const asString = v => typeof v === 'string' ? v.trim() : (v == null ? '' : String(v).trim());
let __kb = {};
try { __kb = asObject($('Plant Knowledge Base').first().json.plant_knowledge); } catch (e) { __kb = {}; }
const kbText = asArray(__kb.entries).map(asObject).map(e => e.id + ' ' + asString(e.name) + '（又叫：' + asArray(e.aliases).join('、') + '；单位 ' + asString(e.unit) + '）：' +
  asString(e.meaning) + (asString(e.not_this) ? ' 注意：' + asString(e.not_this) : '') +
  (asArray(e.options).length ? ' 本装置位号组：' + asArray(e.options).map(o => asArray(asObject(o).tags).join('+') + (asString(asObject(o).note) ? '（' + asString(asObject(o).note) + '）' : '')).join(' 或 ') : '')).join('\n');
// FORMULA_SUM_CHECK_V1：输入附 DCS 画面位号表里的描述，供判断物料是否与变量相符、相加的几项是否同一物流
const __desc = new Map();
try { for (const rows of Object.values(asObject(asObject($('DCS Screen Tag Table').first().json.dcs_table).screens))) for (const r of asArray(rows)) { const t = asString(asArray(r)[0]); if (t && !__desc.has(t)) __desc.set(t, asString(asArray(r)[1])); } } catch (e) {}
const __d = tags => asArray(tags).map(t => { const k = asString(t).replace(/\.PV$/i, ''); return __desc.get(k) ? k + '：' + __desc.get(k) : ''; }).filter(Boolean).join('；');
let q = '';
try { const g = $('Capture context').first().json || {}; q = asString(g.originalUserMessage || g.chatInput); } catch (e) {}
if (!q) q = asString(item.originalUserMessage);
const cases = [], parts = [];
asArray(item.derived_quantity_results).forEach((d0, di) => {
  const d = asObject(d0);
  if (d.status !== 'computed') return;
  const rows = asArray(d.results).slice(0, 3).map(asObject);
  if (!rows.length) return;
  const id = 'R' + (cases.length + 1);
  const ins = asArray(rows[0].inputs).map(asObject);
  const cons = asArray(d.constants).map(asObject);
  const lines = ins.map((x, k) => 'in' + (k + 1) + ': ' + (asString(x.quantity) || asString(x.symbol)) + ' (' + asString(x.symbol) + ') [' + (asString(x.unit) || '?') + '] tags=' + (asArray(x.tags).join('+') || '?') + (__d(x.tags) ? ' (DCS: ' + __d(x.tags) + ')' : ''))
    .concat(cons.map((c, k) => 'in' + (ins.length + k + 1) + ': ' + asString(c.symbol) + ' [' + (asString(c.unit) || '?') + '] ' +
      (c.source === 'plant_model' ? 'static Plant Model ' + asString(c.equipment_tag) + '.' + asString(c.field_path) + ' status=' + asString(c.status) : 'physical constant')));
  parts.push(id + '.result: ' + (asString(d.source_label) || asString(d.name)) + ' [' + (asString(d.result_unit) || 'dimensionless') + '] = ' + asString(d.expression) + '\n  inputs: ' + lines.join('; '));
  cases.push({ id, di, rows: rows.map(r => ({ result: r.value_rounded ?? r.value, inputs: asArray(r.inputs).map(x => asObject(x).value ?? asObject(x).period_mean) })),
    expr: asString(d.expression), symbols: ins.map(x => asString(x.symbol)).concat(cons.map(c => asString(c.symbol))), // FORMULA_SUM_CHECK_V1
    constants: cons.map(c => c.value), labels: ins.map(x => asString(x.symbol) + (asArray(x.tags).length ? '=' + asArray(x.tags).join('+') : '')).concat(cons.map(c => asString(c.symbol))) });
});
const prompt = cases.length ? 'User question:\n' + q + '\n\nPlant knowledge base:\n' + (kbText || '(none)') + '\n\nComputed quantities (no values shown):\n' + parts.join('\n') : '';
return [{ json: { ...item, common_sense_needed: cases.length > 0, common_sense_prompt: prompt, common_sense_cases: cases } }];

options.systemMessage:
You are an experienced FCC (fluid catalytic cracking) process engineer doing a common-sense check before seeing any results. You are given the user's question, this plant's knowledge base (meanings and measurement bases of some quantities as confirmed by the plant; no values), and, for each computed quantity, its name, its formula, and the name, unit and historian tag(s) of each input. You are NOT given any numerical values.

Part 1, ranges. For each computed result and each input, state the range of values that would be physically plausible for an industrial FCC unit in the stated unit: wide enough that a value outside it would genuinely surprise you (an order-of-magnitude slip, a wrong unit, a wrong basis), not a tight operating target. If a quantity can legitimately take very different magnitudes, make the range wide. If you cannot judge a quantity, set "judge": false.

Part 2, definitions. For each result, first write its standard definition in one line (where the knowledge base defines the quantity or one of its inputs, use the plant's basis), then compare the formula with it and report only clear problems:
- terms missing or extra compared with the standard definition (for example a conversion that leaves out part of the unconverted products);
- a basis different from the plant's (for example total riser feed including recycle used where the plant uses fresh feed, or a meter the knowledge base says is not the one to use);
- an input whose meter, by its DCS description, measures a material that cannot be part of the quantity being computed (for example a slurry meter used for a light-cycle-oil recycle ratio). A variable name that is only loosely worded is not a problem when the quantity admits that material (for example a 'gasoline' variable bound to a stabilized-gasoline product meter when computing a gasoline yield). A meter that the knowledge base lists for a quantity is correct for that quantity, whatever its DCS description says;
- an input whose tag cannot measure what its variable claims, judged from the tag's measured-variable letters (F flow, L level, T temperature, P pressure, PD/DP differential pressure, D density, A analysis, Z position) and the unit (for example a level tag in % used as a volume in m3);
- incompatible units mixed without conversion (t/d with t/h, kg/h with t/h), or a result unit that does not follow from the formula;
- a named quantity that is a set of separate quantities (for example "each product's yield") computed as one number.
Not problems: a tag that the knowledge base does not mention (unconfirmed is not wrong; report a tag only when its letters, its unit or the knowledge base contradict its use); an intermediate quantity that is computed by itself (for example a recycle flow on its way to a recycle ratio); naming or style. Leave problem empty when you see no clear problem; never write "no obvious problem but should be confirmed".

Part 3, additions (FORMULA_SUM_CHECK_V1). For each result whose formula adds two or more inputs of the same kind (for example several flows), judge from the DCS descriptions whether those inputs are "same_stream" (the same material measured twice: two meters on one line or at successive points, or a total meter together with its own branch), "different" (genuinely different streams that together make the quantity), or "unsure". Report only groups that the formula actually adds.

Return only JSON:
{"ranges":[{"id":"R1.result or R1.in1","low":number,"high":number,"unit":"the unit given","judge":true}],
 "definitions":[{"id":"R1","standard":"one line","problem":"one sentence, or empty string if none","certain":true}],
 "additions":[{"id":"R1","symbols":["C1","C2"],"relation":"same_stream|different|unsure","why":"one sentence"}]}
Set "certain" to true only when the problem is clear from the formula, units, tag letters or knowledge base alone.

