// FORMULA_SUM_CHECK_V1：四则运算求值，原样取自 Compute Derived Quantities
function __evaluate(expr, env) {
  const toks = String(expr).match(/\d+(?:\.\d+)?(?:[eE][+-]?\d+)?|[A-Za-z_Ͱ-Ͽ][A-Za-z0-9_Ͱ-Ͽ]*|[-+*/^()×÷·]|\S/g) || [];
  let i = 0;
  const peek = () => toks[i];
  const take = () => toks[i++];
  function primary() {
    const t = take();
    if (t === undefined) throw new Error('unexpected end');
    if (t === '(') { const v = sum(); if (take() !== ')') throw new Error('missing )'); return v; }
    if (t === '-') return -factor();
    if (t === '+') return factor();
    if (/^\d/.test(t)) return Number(t);
    if (Object.prototype.hasOwnProperty.call(env, t)) return env[t];
    throw new Error('unknown token ' + t);
  }
  function factor() { const b = primary(); if (peek() === '^') { take(); return Math.pow(b, factor()); } return b; }
  function product() {
    let v = factor();
    while (['*', '/', '×', '÷', '·'].includes(peek())) { const op = take(); const r = factor(); v = (op === '/' || op === '÷') ? v / r : v * r; }
    return v;
  }
  function sum() { let v = product(); while (peek() === '+' || peek() === '-') { const op = take(); const r = product(); v = op === '+' ? v + r : v - r; } return v; }
  const v = sum();
  if (i !== toks.length) throw new Error('unexpected ' + toks[i]);
  return v;
}
// COMMON_SENSE_CHECK_V1：对照模型给的范围与定义意见，把确定的疑点写进对应计算量；不改数值、不改状态。
const base = $('Prepare Common Sense Check').first().json || {};
const inp = $input.first().json || {};
const asArray = v => Array.isArray(v) ? v : [];
const asObject = v => v && typeof v === 'object' && !Array.isArray(v) ? v : {};
const { common_sense_needed, common_sense_prompt, common_sense_cases, ...out } = base;
const trace = { status: common_sense_needed ? 'unparsed' : 'not_needed', checked: asArray(common_sense_cases).length, flagged: 0 };
if (common_sense_needed) {
  const t = String(inp.output || inp.text || '').replace(/^```(?:json)?\s*|\s*```$/gi, '').trim();
  let j = null;
  try { j = JSON.parse(t); } catch (e) { const a = t.indexOf('{'), b = t.lastIndexOf('}'); try { j = JSON.parse(t.slice(a, b + 1)); } catch (e2) {} }
  if (j) {
    trace.status = 'ok';
    const rng = new Map(asArray(j.ranges).map(asObject).map(x => [String(x.id || ''), x]));
    const defs = new Map();
    for (const x of asArray(j.definitions).concat(asArray(j.definition_issues)).map(asObject)) {
      const p = String(x.problem || '').trim();
      if (!p || x.certain === false) continue;
      const k = String(x.id || '').split('.')[0];
      defs.set(k, (defs.get(k) || []).concat([p.slice(0, 300)]));
    }
    // FORMULA_SUM_CHECK_V1：公式里相加的几项被判为同一物流时，记疑点并把每一项轮流置零重算，得到「只取其一」的备选值
    const adds = new Map();
    for (const x of asArray(j.additions).map(asObject)) {
      // same_stream 与 unsure 都提示：unsure 是「从描述看不出是否同一物流」，同样给出只取其一的备选值，由回答并列呈现（不替用户择一）
      const rel = String(x.relation || '');
      if (rel !== 'same_stream' && rel !== 'unsure') continue;
      const syms = asArray(x.symbols).map(s => String(s || '').trim()).filter(Boolean);
      if (syms.length < 2) continue;
      const k = String(x.id || '').split('.')[0];
      adds.set(k, (adds.get(k) || []).concat([{ syms, rel, why: String(x.why || '').slice(0, 200) }]));
    }
    // 求值用 Compute Derived Quantities 的同一个四则运算解析器（不用 eval），见本节点开头的 __evaluate
    const evalExpr = (expr, names, vals) => {
      const env = {}; names.forEach((n, k) => { env[n] = vals[k]; });
      try { const v = __evaluate(expr, env); return Number.isFinite(v) ? v : null; } catch (e) { return null; }
    };
    const r4 = v => Number(Math.abs(v) >= 100 ? v.toFixed(2) : v.toPrecision(4));
    const M3 = 3; // 范围外 3 倍以上才算：只抓量级、单位、基准级的错
    const outside = (key, v) => {
      const g = asObject(rng.get(key));
      if (!Object.keys(g).length || g.judge === false || typeof v !== 'number' || !Number.isFinite(v)) return null;
      const lo = Number(g.low), hi = Number(g.high);
      if (!Number.isFinite(lo) || !Number.isFinite(hi)) return null;
      const L = lo > 0 ? lo / M3 : lo * M3, H = hi > 0 ? hi * M3 : hi / M3;
      return (v < L || v > H) ? '[' + lo + ', ' + hi + ']' : null;
    };
    const results = asArray(out.derived_quantity_results).map(x => ({ ...asObject(x) }));
    for (const c of asArray(common_sense_cases).map(asObject)) {
      const flags = [];
      for (const row of asArray(c.rows).map(asObject)) {
        const r = outside(c.id + '.result', row.result);
        if (r) flags.push('结果 ' + row.result + ' 超出常识范围 ' + r);
        asArray(row.inputs).forEach((v, k) => { const o = outside(c.id + '.in' + (k + 1), v); if (o) flags.push('输入 ' + (asArray(c.labels)[k] || 'in' + (k + 1)) + ' = ' + v + ' 超出常识范围 ' + o); });
      }
      const nIn = asArray(asObject(asArray(c.rows)[0]).inputs).length;
      asArray(c.constants).forEach((v, k) => { const o = outside(c.id + '.in' + (nIn + k + 1), v); if (o) flags.push('静态输入 ' + (asArray(c.labels)[nIn + k] || '') + ' = ' + v + ' 超出常识范围 ' + o); });
      for (const p of defs.get(c.id) || []) flags.push('定义：' + p);
      const alternatives = [];
      const row0 = asObject(asArray(c.rows)[0]);
      const names = asArray(c.symbols).map(String);
      const vals = asArray(row0.inputs).concat(asArray(c.constants));
      for (const g of adds.get(c.id) || []) {
        const idx = g.syms.map(s => names.indexOf(s));
        if (idx.some(i => i < 0)) continue;
        const lab = i => asArray(c.labels)[i] || names[i];
        flags.push('相加复核：' + idx.map(i => lab(i) + '（均值 ' + vals[i] + '）').join('、') +
          (g.rel === 'same_stream' ? ' 可能是同一物流的两处计量，相加会重复计入' : ' 从位号描述无法确定是否同一物流的两处计量，若是则相加会重复计入') + (g.why ? '：' + g.why : ''));
        if (names.length !== vals.length || vals.some(v => typeof v !== 'number')) continue;
        for (const i of idx) {
          const v2 = vals.slice(); v2[i] = 0;
          const r = evalExpr(String(c.expr || ''), names, v2);
          if (r != null) alternatives.push('去掉 ' + lab(i) + ' 得 ' + r4(r));
        }
      }
      const uniq = Array.from(new Set(flags)).slice(0, 5);
      if (uniq.length && results[c.di]) { results[c.di].common_sense_check = { flags: uniq, ...(alternatives.length ? { alternatives } : {}) }; trace.flagged++; }
    }
    out.derived_quantity_results = results;
  }
}
out.common_sense_check = trace;
return [{ json: out }];

// MISSING_CLAIM_CHECK_V1：判定结果整理成交修改轮的条目、追加入包的条目、补查请求，随成稿交给 Prepare Answer Verification（成稿字段原样）。
// MISSING_CLAIM_CHECK_V1 公用函数：试验台（node）与工作流代码节点共用这一份（构建时原样嵌入节点代码）。
// 回答里每处「缺 X」：在本轮全部取回资料里按检索词找候选片段（代码），交模型判是否就是这项、没有的话本轮查过没有。
const __mcA = x => Array.isArray(x) ? x : [];
const __mcO = x => x && typeof x === 'object' && !Array.isArray(x) ? x : {};
const __mcS = x => typeof x === 'string' ? x : (x == null ? '' : String(x));
const __mcClean = t => __mcS(t).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const __mcNorm = t => __mcS(t).replace(/<[^>]+>/g, '').replace(/\s+/g, '').toUpperCase();
const __mcKv = kv => { const o = __mcO(kv); const ks = Object.keys(o); return ks.length ? ' ' + ks.slice(0, 60).map(k => k + '=' + __mcS(typeof o[k] === 'object' ? JSON.stringify(o[k]) : o[k]).slice(0, 120)).join('; ') : ''; };

// 来源分层：与 Evidence Packet Builder 的 bossSourceTierV7 同一判法（1 装置专属·结构化、2 装置专属·文档、3 通识资料）。
// 通识资料（培训教材、专著、英文书）里的数不是本装置的数：可以给判定模型看，但不能据此判「资料里有」（副本 191281 把教材算例的骨架密度 2400、循环量 1823 t/h 当成了有）。
function mcTier(doc) {
  const blob = __mcS(doc);
  if (/Plant Model|装置模型|Control Graph|控制图谱|位号目录|tag_catalog|标签目录/i.test(blob)) return 1;
  if (/<厂名>|操作规程|设备台账|供货表|说明书|铭牌|P&ID|PID图|组态|联锁逻辑|DCS控制|统计表|\bYB\d{3,5}\b/i.test(blob)) return 2;
  if (/通识|English books|教材|专著|手册|大作业|培训/i.test(blob)) return 3;
  return 2;
}

// 资料条目：各单元 evidence_digest（含 normalized_result）、汇总 evidence_digest，编号与 Build Evidence Index 一致；另加静态事实。
// key 与 Build Evidence Index / Evidence Packet Builder 认条目的写法相同（正文前 400 字）。
function mcCorpus(item) {
  const it = __mcO(item), pay = __mcO(it.aggregated_payload);
  const units = __mcA(it.completed_units || pay.completed_units || it.units);
  const out = [], seen = new Set();
  const add = (loc, d) => {
    const o = __mcO(d);
    const body = __mcClean(o.content_summary || o.snippet || o.summary);
    const key = body.slice(0, 400);
    if (!key || seen.has(key)) return;
    seen.add(key);
    const doc = (o.dataset_name ? __mcClean(o.dataset_name).slice(0, 30) + ' | ' : '') + __mcClean(o.document_name).slice(0, 80) + (o.section_title ? ' > ' + __mcClean(o.section_title).slice(0, 50) : '');
    const tier = mcTier([o.document_name, o.dataset_name, o.section_title].filter(Boolean).join(' '));
