  });
  __mcA(it.evidence_digest).forEach((d, i) => add('i:d:' + i, d));
  __mcA(pay.evidence_digest).forEach((d, i) => add('p:d:' + i, d));
  __mcA(it.engineering_facts).forEach(f => { const t = JSON.stringify(f); if (t && t.length > 2) out.push({ loc: '', key: '', doc: 'engineering_facts', tier: 1, text: t.slice(0, 1500) }); });
