// 每一项：按检索词在资料条目里找，命中不同检索词越多越靠前，取前 cap 条；片段为第一处命中前后各 half 字
function mcSearch(corpus, items, packetText, cap, half) {
  cap = cap || 5; half = half || 200;
  return __mcA(items).map(it => {
    const terms = Array.from(new Set(__mcA(it.terms).concat(__mcA(it.tags)).map(t => __mcS(t).trim()).filter(t => t.length >= 2))).slice(0, 10);
    const tu = terms.map(t => t.toUpperCase());
    // 位号 / 设备号命中权重高：泛词到处都能命中，会把真正带这个位号的条目挤出前几名（189632 FRC3209）
    const tagU = new Set(__mcA(it.tags).map(t => __mcS(t).trim().toUpperCase().replace(/\.PV$/, '')).filter(t => t.length >= 2));
    const hits = [];
    for (const c of corpus) {
      const T = c.text.toUpperCase();
      const found = tu.filter(t => T.indexOf(t) >= 0);
      if (!found.length) continue;
      const tagHits = Array.from(tagU).filter(t => T.indexOf(t) >= 0).length;
      // 片段：命中词最集中的一处
      let best = -1, bestN = 0;
      for (const t of found) {
        let st = 0, n = 0;
        while (n < 20) { const i = T.indexOf(t, st); if (i < 0) break; n++; st = i + t.length;
          const w = T.slice(Math.max(0, i - half), i + half); const k = found.filter(x => w.indexOf(x) >= 0).length;
          if (k > bestN) { bestN = k; best = i; } }
      }
      const a = Math.max(0, best - half), b = Math.min(c.text.length, best + half);
      const win = c.text.slice(a, b);
      const core = __mcNorm(c.text.slice(Math.max(0, best - 30), best + 40));
      hits.push({ score: tagHits * 100 + found.length * 10 + bestN, tier: c.tier, loc: c.loc, key: c.key, doc: c.doc, text: (a > 0 ? '…' : '') + win + (b < c.text.length ? '…' : ''), core, in_packet: Boolean(core) && packetText.indexOf(core) >= 0 });
    }
    hits.sort((x, y) => y.score - x.score);
    return hits.slice(0, cap).map((h, n) => ({ n: n + 1, tier: h.tier, loc: h.loc, key: h.key, doc: h.doc, text: h.text, core: h.core, in_packet: h.in_packet }));
