  const lines = units.map(u => { const o = __mcO(u); return '#' + __mcS(o.unit_id) + ' ' + __mcS(o.tool) + ' [' + __mcS(o.execution_status) + '] ' + __mcS(o.question_part).slice(0, 120) + ' | ' + JSON.stringify(__mcO(o.params)).slice(0, 300); });
  const cc = it.coverage_check; if (cc) lines.push('coverage self-check: ' + JSON.stringify(cc).slice(0, 2000));
