function mcJudgePrompt(items, cands, callsText, answerText) {
  const blocks = __mcA(items).map((it, k) => '[Item ' + (k + 1) + '] ' + __mcS(it.item) + ' (info_type ' + __mcS(it.info_type) + '; answer says: "' + __mcS(it.quote) + '")\n' +
    (cands[k].length ? cands[k].map(c => '  snippet ' + c.n + ' [' + c.doc + ']: ' + c.text).join('\n') : '  (no snippet matched the search terms)'));
  return 'Items the answer says are not available:\n\n' + blocks.join('\n\n') + '\n\nLookups made in this run:\n' + (callsText || '(none)');
