          (cond ? ' (' + (pres === 'scoped' ? 'scope' : 'status') + ': ' + cond.slice(0, 60) + ')' : '') + '. Say what the material gives' + (pres === 'scoped' ? ' and the scope it applies to' : cond ? ' and its status' : '') + ', with its citation, instead of saying it was not retrieved.').slice(0, 300) });
