        findings.push({ claim: __mcS(it.quote).slice(0, 300), status: 'missing_unsearched', kind: 'fix', cited: [], ids: [],
          note: ('missing_unsearched: the draft says "' + __mcS(it.item).slice(0, 80) + '" is not available, but no document search in this run named ' + __ownTags(it).join('/') + '; a document search was issued ("' + q.slice(0, 60) + '"). If the new evidence has it, use it with its citation; if not, keep the statement and say which source was checked.').slice(0, 300) });
