    const __r = __items.length === __cands.length ? mcApply(__items, __cands, __j, __mcBody(__pre.output), __s.missing_claim_rag_text) : { findings: [], recall: [], rag_queries: [], plant_lookups: [], historian_factors: [], trace: [] };
