return [{ json: { ...__item, missing_claim_check: __check } }];

options.systemMessage:
You review an answer written by an industrial process Q&A system for an FCC unit. Find every place where the answer asserts that a specific piece of information is NOT available: it says the data, value, tag, elevation, range, target, limit, definition or record was not retrieved / not given / not found / missing / not in the evidence / not documented (未检索到、没有给出、证据中没有、未提供、缺少、无法获取、未找到、未记录、没有文档化的…).

Do NOT list:
- recommendations or next-step items that do not assert absence ("建议核查 X", "需要现场确认 X" without saying X is missing from the material);
- a result that could not be computed — list only the missing input that the answer names as the reason;
- statements that a value exists but is unusable, unconfirmed or of uncertain status (that is not absence);
- statements that only report how a lookup went ("searching the tag catalogue for 'X' matched nothing") unless the answer also says the information itself is unavailable;
- statements that a tag returned no samples / no data for the period when that is what the material says (still list it, the check will see the record).
List each piece of information once, even if the answer repeats it.

For each item give:
- "item": what exactly is said to be missing, as a short noun phrase naming the object (equipment / tag / period);
- "quote": the exact words of the answer that assert it, copied verbatim, at most 80 characters;
- "terms": 3 to 8 search terms specific to this item that would appear in source material if it contained this information: tag numbers, equipment numbers, the Chinese name of the quantity or device, field names. Do not use generic words that fit many items (目标值, 范围, 控制区间, 指标, 数据, 操作规程, 文档, 定义, 正文, numeric target, range). No sentences;
- "info_type": "measured" (historian values or statistics of a tag over a period), "equipment" (static data of a device or instrument: dimensions, elevations, tap positions, ranges of the transmitter), "target" (a target, control range, operating limit, alarm or interlock value, or 工艺卡片 figure of a specific quantity or tag), "document" (other things written in documents: procedures, report figures, definitions, explanations), or "unsearchable" (only field confirmation, installation details or information no data source could hold);
- "tags": tag or equipment numbers the item is about, if any (e.g. "FRC3209", "DR3110", "R1102").

Output JSON only: {"items":[{"item":"...","quote":"...","terms":["..."],"info_type":"...","tags":["..."]}]}. If there is none: {"items":[]}.

parameters.jsCode:
// MISSING_CLAIM_CHECK_V1：成稿（首稿与每轮修改稿）里每处「缺 X」，送反查前先在本轮全部取回的资料里核对。这一步只准备抽取模型的输入。
// 来由：用户 11-04「每处缺失只有两种结局：查到了用上；该查的都查了确实没有」；11-05 统计 83 次执行，资料里有却说没有的 10 处，
// 其中 189632「控制 FRC3209 为 302-350 t/h」在证据包里仍写未检索到区间，TRC3201 175～185 ℃ 取回了却没进包。
// 送检条件与 Prepare Answer Verification 相同（前三稿、本轮有检索或取数、正文不少于 200 字）。
const item = $input.first().json || {};
const __round = typeof $runIndex === 'number' ? $runIndex : 0;
const __full = String(item.output || '');
const __cut = /(^|\n)####\s/.exec(__full);
const __answer = (__cut ? __full.slice(0, __cut.index) : __full).trim();
let __epb = {};
try { __epb = $('Evidence Packet Builder').last().json || {}; } catch (e) { __epb = {}; }
const __units = Array.isArray(__epb.completed_units) ? __epb.completed_units : [];
const __retrieval = __units.some(u => { const t = String((u || {}).tool || ''); return t && t !== 'direct_response'; });
const __q = String(item.originalUserMessage || __epb.originalUserMessage || '').trim();
const __needed = Boolean(__round <= 2 && __retrieval && __answer.length >= 200);
return [{ json: { ...item, missing_claim_needed: __needed,
  missing_claim_extract_user: __needed ? ('User question:\n' + __q + '\n\nAnswer:\n' + __answer.slice(0, 14000)) : '' } }];

// MISSING_CLAIM_CHECK_V1：抽出的「缺 X」在本轮全部取回资料里按检索词找候选片段（代码），拼判定模型的输入。
// MISSING_CLAIM_CHECK_V1 公用函数：试验台（node）与工作流代码节点共用这一份（构建时原样嵌入节点代码）。
// 回答里每处「缺 X」：在本轮全部取回资料里按检索词找候选片段（代码），交模型判是否就是这项、没有的话本轮查过没有。
const __mcA = x => Array.isArray(x) ? x : [];
const __mcO = x => x && typeof x === 'object' && !Array.isArray(x) ? x : {};
const __mcS = x => typeof x === 'string' ? x : (x == null ? '' : String(x));
const __mcClean = t => __mcS(t).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const __mcNorm = t => __mcS(t).replace(/<[^>]+>/g, '').replace(/\s+/g, '').toUpperCase();
const __mcKv = kv => { const o = __mcO(kv); const ks = Object.keys(o); return ks.length ? ' ' + ks.slice(0, 60).map(k => k + '=' + __mcS(typeof o[k] === 'object' ? JSON.stringify(o[k]) : o[k]).slice(0, 120)).join('; ') : ''; };

// 来源分层：与 Evidence Packet Builder 的 bossSourceTierV7 同一判法（1 装置专属·结构化、2 装置专属·文档、3 通识资料）。
// 通识资料（培训教材、专著、英文书）里的数不是本装置的数：可以给判定模型看，但不能据此判「资料里有」（副本 191281 把教材算例的骨架密度 2400、循环量 1823 t/h 当成了有）。
function mcTier(doc) {
  const blob = __mcS(doc);
  if (/Plant Model|装置模型|Control Graph|控制图谱|位号目录|tag_catalog|标签目录/i.test(blob)) return 1;
  if (/<厂名>|操作规程|设备台账|供货表|说明书|铭牌|P&ID|PID图|组态|联锁逻辑|DCS控制|统计表|\bYB\d{3,5}\b/i.test(blob)) return 2;
  if (/通识|English books|教材|专著|手册|大作业|培训/i.test(blob)) return 3;
  return 2;
}

// 资料条目：各单元 evidence_digest（含 normalized_result）、汇总 evidence_digest，编号与 Build Evidence Index 一致；另加静态事实。
// key 与 Build Evidence Index / Evidence Packet Builder 认条目的写法相同（正文前 400 字）。
function mcCorpus(item) {
  const it = __mcO(item), pay = __mcO(it.aggregated_payload);
  const units = __mcA(it.completed_units || pay.completed_units || it.units);
  const out = [], seen = new Set();
  const add = (loc, d) => {
    const o = __mcO(d);
    const body = __mcClean(o.content_summary || o.snippet || o.summary);
    const key = body.slice(0, 400);
    if (!key || seen.has(key)) return;
    seen.add(key);
    const doc = (o.dataset_name ? __mcClean(o.dataset_name).slice(0, 30) + ' | ' : '') + __mcClean(o.document_name).slice(0, 80) + (o.section_title ? ' > ' + __mcClean(o.section_title).slice(0, 50) : '');
    const tier = mcTier([o.document_name, o.dataset_name, o.section_title].filter(Boolean).join(' '));
    out.push({ loc, key, doc: (tier === 3 ? '通识资料 | ' : '') + doc, tier, text: body + __mcKv(o.key_values) });
  };
  units.forEach((u, k) => {
    __mcA(__mcO(u).evidence_digest).forEach((d, i) => add('u:' + k + ':d:' + i, d));
    __mcA(__mcO(__mcO(u).normalized_result).evidence_digest).forEach((d, i) => add('u:' + k + ':n:' + i, d));
  });
  __mcA(it.evidence_digest).forEach((d, i) => add('i:d:' + i, d));
  __mcA(pay.evidence_digest).forEach((d, i) => add('p:d:' + i, d));
  __mcA(it.engineering_facts).forEach(f => { const t = JSON.stringify(f); if (t && t.length > 2) out.push({ loc: '', key: '', doc: 'engineering_facts', tier: 1, text: t.slice(0, 1500) }); });
  return out;
}

// 模型看到的证据包合成一段文字，用来判断片段在不在包里
function mcPacketText(packet) {
  return __mcA(packet).map(e => { const o = __mcO(e); return __mcNorm(o.document_name) + '|' + __mcNorm(o.snippet || o.content_summary) + __mcNorm(__mcKv(o.key_values)); }).join('\n');
}

// 每一项：按检索词在资料条目里找，命中不同检索词越多越靠前，取前 cap 条；片段为第一处命中前后各 half 字
function mcSearch(corpus, items, packetText, cap, half) {
  cap = cap || 5; half = half || 200;
  return __mcA(items).map(it => {
    const terms = Array.from(new Set(__mcA(it.terms).concat(__mcA(it.tags)).map(t => __mcS(t).trim()).filter(t => t.length >= 2))).slice(0, 10);
    const tu = terms.map(t => t.toUpperCase());
    // 位号 / 设备号命中权重高：泛词到处都能命中，会把真正带这个位号的条目挤出前几名（189632 FRC3209）
    const tagU = new Set(__mcA(it.tags).map(t => __mcS(t).trim().toUpperCase().replace(/\.PV$/, '')).filter(t => t.length >= 2));
    const hits = [];
    for (const c of corpus) {
      const T = c.text.toUpperCase();
      const found = tu.filter(t => T.indexOf(t) >= 0);
      if (!found.length) continue;
      const tagHits = Array.from(tagU).filter(t => T.indexOf(t) >= 0).length;
      // 片段：命中词最集中的一处
      let best = -1, bestN = 0;
      for (const t of found) {
        let st = 0, n = 0;
        while (n < 20) { const i = T.indexOf(t, st); if (i < 0) break; n++; st = i + t.length;
          const w = T.slice(Math.max(0, i - half), i + half); const k = found.filter(x => w.indexOf(x) >= 0).length;
          if (k > bestN) { bestN = k; best = i; } }
      }
      const a = Math.max(0, best - half), b = Math.min(c.text.length, best + half);
      const win = c.text.slice(a, b);
      const core = __mcNorm(c.text.slice(Math.max(0, best - 30), best + 40));
      hits.push({ score: tagHits * 100 + found.length * 10 + bestN, tier: c.tier, loc: c.loc, key: c.key, doc: c.doc, text: (a > 0 ? '…' : '') + win + (b < c.text.length ? '…' : ''), core, in_packet: Boolean(core) && packetText.indexOf(core) >= 0 });
    }
    hits.sort((x, y) => y.score - x.score);
    return hits.slice(0, cap).map((h, n) => ({ n: n + 1, tier: h.tier, loc: h.loc, key: h.key, doc: h.doc, text: h.text, core: h.core, in_packet: h.in_packet }));
  });
}

// 本轮所有文档检索的查询文字（大写），用来由代码判断「某个位号的指标有没有被按位号专门查过」
function mcRagText(item) {
  const it = __mcO(item), pay = __mcO(it.aggregated_payload);
  return __mcA(it.completed_units || pay.completed_units || it.units).map(__mcO).filter(u => __mcS(u.tool) === 'ragflow_retrieval')
    .map(u => JSON.stringify(__mcO(u.params)) + ' ' + __mcS(u.question_part)).join('\n').toUpperCase();
}

function mcCallsText(item) {
  const it = __mcO(item), pay = __mcO(it.aggregated_payload);
  const units = __mcA(it.completed_units || pay.completed_units || it.units);
  const lines = units.map(u => { const o = __mcO(u); return '#' + __mcS(o.unit_id) + ' ' + __mcS(o.tool) + ' [' + __mcS(o.execution_status) + '] ' + __mcS(o.question_part).slice(0, 120) + ' | ' + JSON.stringify(__mcO(o.params)).slice(0, 300); });
  const cc = it.coverage_check; if (cc) lines.push('coverage self-check: ' + JSON.stringify(cc).slice(0, 2000));
  return lines.join('\n');
}

function mcJudgePrompt(items, cands, callsText, answerText) {
  const blocks = __mcA(items).map((it, k) => '[Item ' + (k + 1) + '] ' + __mcS(it.item) + ' (info_type ' + __mcS(it.info_type) + '; answer says: "' + __mcS(it.quote) + '")\n' +
    (cands[k].length ? cands[k].map(c => '  snippet ' + c.n + ' [' + c.doc + ']: ' + c.text).join('\n') : '  (no snippet matched the search terms)'));
  return 'Items the answer says are not available:\n\n' + blocks.join('\n\n') + '\n\nLookups made in this run:\n' + (callsText || '(none)');
}

// 判定结果 → 交修改轮的条目、追加入包的条目、补查请求
function mcApply(items, cands, judged, answerText, ragText) {
  const __ans = __mcS(answerText).toUpperCase(), __ragU = __mcS(ragText).toUpperCase();
  const findings = [], recall = [], rag = [], ragFix = [], plant = [], hist = [], trace = [];
  let __docFix = 0;
  const __ownTags = it => __mcA(it.tags).map(x => __mcS(x).trim().toUpperCase().replace(/\.PV$/, '')).filter(x => /^[A-Z]{1,6}\d{2,5}[A-Z0-9_]*$/.test(x) && __ans.indexOf(x) >= 0);
  const J = new Map(__mcA(__mcO(judged).items).map(x => [Number(__mcO(x).i), __mcO(x)]));
  __mcA(items).forEach((it, k) => {
    const j = J.get(k + 1) || {}; const pres = __mcS(j.present);
    const c = cands[k].find(x => x.n === Number(j.snippet)) || null;
    const tr = { item: __mcS(it.item).slice(0, 120), quote: __mcS(it.quote).slice(0, 100), info_type: __mcS(it.info_type), present: pres || 'unjudged', in_packet: c ? c.in_packet : null, searched: j.searched ?? null };
    if ((pres === 'yes' || pres === 'scoped') && j.answer_correct === false && c && c.tier !== 3) {
      const cond = __mcS(j.condition).trim();
      findings.push({ claim: __mcS(it.quote).slice(0, 300), status: 'missing_but_present', kind: 'fix', cited: [], ids: [], evidence_core: __mcS(c.core).slice(0, 70),
        note: ('missing_but_present: the draft says "' + __mcS(it.item).slice(0, 80) + '" is not available, but material retrieved in this run has it: "' + __mcS(j.quote || c.text).slice(0, 120) + '" [' + c.doc.slice(0, 50) + ']' +
          (cond ? ' (' + (pres === 'scoped' ? 'scope' : 'status') + ': ' + cond.slice(0, 60) + ')' : '') + '. Say what the material gives' + (pres === 'scoped' ? ' and the scope it applies to' : cond ? ' and its status' : '') + ', with its citation, instead of saying it was not retrieved.').slice(0, 300) });
      if (!c.in_packet && c.key) recall.push({ key: c.key, loc: c.loc, need: 'missing_claim: ' + __mcS(it.item).slice(0, 120) });
      tr.action = c.in_packet ? 'fix' : 'fix+recall';
    } else if (pres === 'no' && __mcS(it.info_type) === 'target' && __ownTags(it).length && !__ownTags(it).some(x => __ragU.indexOf(x) >= 0)) {
      // 回答点名了位号的指标、限值，本轮没有哪条文档检索的查询里出现过这个位号：由代码判定「没专门查过」（不交模型判——副本 191839 模型把
      // 12 项指标都判成查过，依据是取数证据里那句「no documented numeric target/range」；191840 按位号就从 DCS 控制点统计表里查到了 TRC3218 限值）。
      // 按这一项的名称（含位号）发文档检索并成一条要改的条目；每轮至多 3 条（Coverage Retry 一次至多 4 个查询）。
      const L = __mcO(j.lookup), q = (__mcS(L.type) === 'doc' && __mcS(L.query).trim()) ? __mcS(L.query).trim() : __mcS(it.item).trim();
      if (__docFix < 3 && q) {
        __docFix++;
        ragFix.push({ need: __mcS(it.item).slice(0, 120), query: q.slice(0, 80), question_part: 'missing_claim' });
        findings.push({ claim: __mcS(it.quote).slice(0, 300), status: 'missing_unsearched', kind: 'fix', cited: [], ids: [],
          note: ('missing_unsearched: the draft says "' + __mcS(it.item).slice(0, 80) + '" is not available, but no document search in this run named ' + __ownTags(it).join('/') + '; a document search was issued ("' + q.slice(0, 60) + '"). If the new evidence has it, use it with its citation; if not, keep the statement and say which source was checked.').slice(0, 300) });
        tr.action = 'lookup:doc+fix';
      } else tr.action = 'lookup:doc_over_cap';
      tr.lookup = { type: 'doc', query: q };
    } else if (pres === 'no' && j.searched === false && j.lookup && typeof j.lookup === 'object') {
      const L = __mcO(j.lookup), ty = __mcS(L.type);
      // 历史库 / 设备资料补查的位号必须是回答里归在这一项名下的位号（抽取给的 tags），且是位号格式：模型配错位号时取回的是另一个量的数，
      // 修改轮可能当成这个量用（试验台 186827 补充量配成回答里另作下返塔流量的 FRC3205；189141 把「再生斜管密度」当位号）
      const __lt = __mcS(L.tag).trim().toUpperCase().replace(/\.PV$/, '');
      const __own = new Set(__mcA(it.tags).map(x => __mcS(x).trim().toUpperCase().replace(/\.PV$/, '')));
      if ((ty === 'historian' || ty === 'plant') && !(/^[A-Z]{1,6}\d{2,5}[A-Z0-9_]*$/.test(__lt) && __own.has(__lt) && __ans.indexOf(__lt) >= 0)) { tr.action = 'lookup_tag_not_own'; tr.lookup = L; trace.push(tr); return; }
      // 补查方式要与这一项的信息类型对得上：实测值读历史库、设备资料查装置模型库（试验台 189514「滑阀开度」被配成读 PDRA3125）
      const __it = __mcS(it.info_type);
      if ((ty === 'historian' && __it !== 'measured') || (ty === 'plant' && __it !== 'equipment')) { tr.action = 'lookup_type_mismatch'; tr.lookup = L; trace.push(tr); return; }
      if (ty === 'doc' && __mcS(L.query).trim()) {
        rag.push({ need: __mcS(it.item).slice(0, 120), query: __mcS(L.query).trim().slice(0, 80), question_part: 'missing_claim' });
      }
      else if (ty === 'plant' && /^plant_(instruments|equipment)$/.test(__mcS(L.tool)) && __mcS(L.tag).trim()) plant.push({ need: __mcS(it.item).slice(0, 120), tool: __mcS(L.tool), tag: __mcS(L.tag).trim().toUpperCase() });
      else if (ty === 'historian' && __mcS(L.tag).trim()) hist.push({ name: __mcS(L.name || it.item).slice(0, 60), source_label: __mcS(it.item).slice(0, 60), documented_tags: [__mcS(L.tag).trim().toUpperCase().replace(/\.PV$/, '') + '.PV'], unit: null, ideal_range: null, evidence_ids: [], search_context: 'missing_claim: ' + __mcS(it.quote).slice(0, 80) });
      if (!tr.action) tr.action = ty ? 'lookup:' + ty : 'none';
      tr.lookup = L;
      // 历史库读数、设备资料这两种补查（位号有效）单独成一条，触发修改轮；文档检索只随修改轮顺带查
      const __tag = __mcS(L.tag).trim().toUpperCase().replace(/\.PV$/, '');
      if ((ty === 'historian' || ty === 'plant') && /^[A-Z]{1,6}\d{2,5}[A-Z0-9_]*$/.test(__tag)) {
        findings.push({ claim: __mcS(it.quote).slice(0, 300), status: 'missing_unsearched', kind: 'fix', cited: [], ids: [],
          note: ('missing_unsearched: the draft says "' + __mcS(it.item).slice(0, 80) + '" is not available, but this run never looked it up; a lookup was issued (' + (ty === 'plant' ? 'Plant Model ' + __mcS(L.tool) : 'historian') + ' ' + __tag + '). If the new evidence has it, use it with its citation; if not, keep the statement and say which source was checked.').slice(0, 300) });
        tr.action += '+fix';
      }
    } else tr.action = 'none';
    trace.push(tr);
  });
  return { findings: findings.slice(0, 8), recall: recall.slice(0, 6), rag_queries: ragFix.concat(rag).slice(0, 3), plant_lookups: plant.slice(0, 3), historian_factors: hist.slice(0, 3), trace };
}

const __mcParse = v => {
  if (v && typeof v === 'object' && !Array.isArray(v)) return v;
  const t = String(v || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
  try { return __mcO(JSON.parse(t)); } catch (e) {}
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return __mcO(JSON.parse(t.slice(a, b + 1))); } catch (e) {} }
  return {};
};
const __mcBody = full => { const s = String(full || ''); const c = /(^|\n)####\s/.exec(s); return (c ? s.slice(0, c.index) : s).trim(); };

const __out = $input.first().json || {};
const __ex = __mcParse(__out.output ?? __out.text ?? '');
const __items = __mcA(__ex.items).map(__mcO).filter(x => __mcS(x.item).trim()).slice(0, 12);
let __base = {}, __epb = {}, __crp = {}, __pre = {};
try { __base = $('Apply Evidence Recall').last().json || {}; } catch (e) { __base = {}; }
try { __epb = $('Evidence Packet Builder').last().json || {}; } catch (e) { __epb = {}; }
try { __crp = $('Compact Result Projector').last().json || {}; } catch (e) { __crp = {}; }
try { __pre = $('Prepare Missing Claim Check').last().json || {}; } catch (e) { __pre = {}; }
const __src = { ...__base,
  completed_units: __mcA(__base.completed_units).length ? __base.completed_units : __epb.completed_units,
  engineering_facts: __mcA(__base.engineering_facts).length ? __base.engineering_facts : __epb.engineering_facts,
  coverage_check: __base.coverage_check || __epb.coverage_check };
const __answer = __mcBody(__pre.output);
let __cands = [], __prompt = '', __n = 0;
if (__items.length) {
  const __corpus = mcCorpus(__src); __n = __corpus.length;
  __cands = mcSearch(__corpus, __items, mcPacketText(__crp.evidence_packet));
  __prompt = mcJudgePrompt(__items, __cands, mcCallsText(__src), __answer);
}
return [{ json: { missing_claim_items: __items, missing_claim_cands: __cands, missing_claim_corpus: __n, missing_claim_rag_text: mcRagText(__src).slice(0, 20000),
  missing_claim_extract_parse_ok: Object.keys(__ex).length > 0,
  missing_claim_judge_needed: __items.length > 0, missing_claim_judge_user: __prompt } }];
